import React from 'react';

import { CardBrandIcon } from '../CardBrandIcon/CardBrandIcon';
import { CardNumberMasked } from '../CardNumberMasked/CardNumberMasked';
import { CardExpiryDate } from '../CardExpiryDate/CardExpiryDate';
import { CardholderName } from '../CardholderName/CardholderName';
import { DeleteCardAction } from '../DeleteCardAction/DeleteCardAction';

export type SelectPaymentCardPayload = { card_id: string };
export type DeletePaymentCardPayload = { card_id: string };
export type DeletePaymentCardCancelPayload = { card_id: string };

export type PaymentCardProps = {
  card_id: string;
  brand: string;
  last4: string;
  expiry_month: string;
  expiry_year: string;
  cardholder_name: string;
  is_selected: boolean;
  is_disabled?: boolean;
  is_expired?: boolean;
  is_delete_pending?: boolean;
  delete_error_message?: string;
  on_select: (payload: SelectPaymentCardPayload) => void;
  on_delete_confirm: (payload: DeletePaymentCardPayload) => void;
  on_delete_cancel?: (payload: DeletePaymentCardCancelPayload) => void;
  card_aria_label?: string;
};

function titleCaseBrand(brand: string): string {
  const b = (brand || '').trim().toLowerCase();
  if (b === 'visa') return 'Visa';
  if (b === 'mastercard') return 'Mastercard';
  if (b === 'amex' || b === 'american_express' || b === 'american express') return 'Amex';
  return 'Card';
}

function toIntOrNaN(value: string): number {
  const n = Number.parseInt(String(value), 10);
  return Number.isFinite(n) ? n : Number.NaN;
}

export function PaymentCard(props: PaymentCardProps) {
  const {
    card_id,
    brand,
    last4,
    expiry_month,
    expiry_year,
    cardholder_name,
    is_selected,
    is_disabled,
    is_expired,
    is_delete_pending,
    delete_error_message,
    on_select,
    on_delete_confirm,
    on_delete_cancel,
    card_aria_label
  } = props;

  const brandText = titleCaseBrand(brand);
  const mm = String(expiry_month).padStart(2, '0');
  const yy = String(expiry_year).slice(-2).padStart(2, '0');

  const computedAriaLabel = `${brandText} card ending in ${last4}, expires ${mm}/${yy}, ${cardholder_name}`;
  const ariaLabel = (card_aria_label && card_aria_label.trim().length > 0) ? card_aria_label : computedAriaLabel;

  const selectionDisabled = !!is_disabled || !!is_delete_pending;

  const onCardActivate = React.useCallback(() => {
    if (selectionDisabled) return;
    on_select({ card_id });
  }, [selectionDisabled, on_select, card_id]);

  // Provided for nested delete control to call if needed; selection is already protected
  // by stopPropagation on delete interactions, but we keep this for explicit coordination.
  const onRequestStopSelectionPropagation = React.useCallback(() => {
    // no-op
  }, []);

  const disabledAttr = !!is_disabled;

  return (
    <div
      data-payment-card-root
      data-selected={String(!!is_selected)}
      data-disabled={String(!!is_disabled)}
      data-delete-pending={String(!!is_delete_pending)}
      data-expired={String(!!is_expired)}
    >
      <button
        type="button"
        aria-pressed={is_selected}
        aria-label={ariaLabel}
        disabled={disabledAttr}
        onClick={(e) => {
          if (selectionDisabled) {
            e.preventDefault();
            return;
          }
          onCardActivate();
        }}
        // Keep explicit key handling to ensure Space triggers selection in jsdom/user-event.
        onKeyDown={(e) => {
          if (selectionDisabled) return;
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onCardActivate();
          }
        }}
        style={{
          width: '100%',
          minHeight: 44,
          textAlign: 'start',
          cursor: disabledAttr ? 'not-allowed' : 'pointer',
          padding: 12,
          borderRadius: 12,
          border: is_selected ? '2px solid currentColor' : '1px solid rgba(0,0,0,0.2)',
          background: is_selected ? 'rgba(0,0,0,0.04)' : 'white',
          display: 'grid',
          gap: 8
        }}
      >
        <div
          data-row="1"
          style={{
            display: 'grid',
            gridTemplateColumns: 'auto 1fr auto',
            alignItems: 'center',
            columnGap: 12
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <CardBrandIcon brand={brand} decorative />
          </div>

          <div
            style={{
              minWidth: 0,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap'
            }}
            title={`**** **** **** ${last4}`}
          >
            <CardNumberMasked last4={last4} />
          </div>

          <div
            style={{
              display: 'flex',
              justifyContent: 'flex-end'
            }}
            onClick={(e) => e.stopPropagation()}
            onKeyDown={(e) => e.stopPropagation()}
          >
            <DeleteCardAction
              card_id={card_id}
              last4={last4}
              is_disabled={!!selectionDisabled}
              is_deleting={!!is_delete_pending}
              delete_error_message={delete_error_message}
              on_delete_confirm={(payload: DeletePaymentCardPayload) => {
                on_delete_confirm(payload);
              }}
              on_delete_confirmation_cancel={(payload: DeletePaymentCardCancelPayload) => {
                on_delete_cancel?.(payload);
              }}
              on_request_stop_selection_propagation={onRequestStopSelectionPropagation}
            />
          </div>
        </div>

        <div
          data-row="2"
          style={{
            display: 'grid',
            gridTemplateColumns: '1fr auto',
            alignItems: 'center',
            columnGap: 12
          }}
        >
          <div
            style={{
              minWidth: 0,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap'
            }}
            title={cardholder_name}
          >
            <CardholderName cardholder_name={cardholder_name} />
          </div>

          <div style={{ justifySelf: 'end' }}>
            <CardExpiryDate
              expiry_month={toIntOrNaN(expiry_month)}
              expiry_year={toIntOrNaN(expiry_year)}
              is_expired={!!is_expired}
            />
          </div>
        </div>

        {delete_error_message ? (
          <div role="alert" style={{ color: 'rgb(176, 0, 32)', fontSize: 12 }}>
            {delete_error_message}
          </div>
        ) : null}
      </button>
    </div>
  );
}

import React from 'react';

export type CardBrandIconProps = {
  /** Card brand identifier used to choose the correct brand icon. Use "unknown" (or empty) to render the generic fallback icon. */
  brand: string;
  /** If true, hide the icon from assistive tech (aria-hidden) and do not provide alternative text; the parent component should include brand text in its own accessible label. */
  decorative?: boolean;
  /** Accessible text alternative when the icon is not decorative (e.g., "Visa"). Ignored when decorative=true. */
  alt_text?: string;
  /** Pixel size for the rendered icon (width and height). */
  size_px?: number;
};

function normalizeBrand(brand: string): 'visa' | 'mastercard' | 'amex' | 'unknown' {
  const b = (brand || '').trim().toLowerCase();
  if (b === 'visa') return 'visa';
  if (b === 'mastercard' || b === 'master card' || b === 'mc') return 'mastercard';
  if (b === 'amex' || b === 'american express' || b === 'americanexpress') return 'amex';
  return 'unknown';
}

function defaultAltText(brand: 'visa' | 'mastercard' | 'amex' | 'unknown'): string {
  switch (brand) {
    case 'visa':
      return 'Visa';
    case 'mastercard':
      return 'Mastercard';
    case 'amex':
      return 'American Express';
    default:
      return 'Card';
  }
}

type SvgProps = {
  width: number;
  height: number;
  decorative: boolean;
  alt: string;
};

function SvgWrapper({ width, height, decorative, alt, children }: React.PropsWithChildren<SvgProps>) {
  return (
    <svg
      width={width}
      height={height}
      viewBox="0 0 40 24"
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-hidden={decorative ? 'true' : undefined}
      aria-label={decorative ? undefined : alt}
      focusable="false"
    >
      {children}
    </svg>
  );
}

function VisaSvg(props: SvgProps) {
  const { width, height, decorative, alt } = props;
  return (
    <SvgWrapper width={width} height={height} decorative={decorative} alt={alt}>
      <rect x="1" y="1" width="38" height="22" rx="4" fill="#1A1F71" stroke="#0F1557" />
      <text
        x="20"
        y="16"
        textAnchor="middle"
        fontFamily="Arial, sans-serif"
        fontSize="10"
        fontWeight="700"
        fill="#FFFFFF"
      >
        VISA
      </text>
    </SvgWrapper>
  );
}

function MastercardSvg(props: SvgProps) {
  const { width, height, decorative, alt } = props;
  return (
    <SvgWrapper width={width} height={height} decorative={decorative} alt={alt}>
      <rect x="1" y="1" width="38" height="22" rx="4" fill="#FFFFFF" stroke="#D0D5DD" />
      <circle cx="17" cy="12" r="6" fill="#EB001B" />
      <circle cx="23" cy="12" r="6" fill="#F79E1B" />
      <circle cx="20" cy="12" r="6" fill="#FF5F00" opacity="0.85" />
    </SvgWrapper>
  );
}

function AmexSvg(props: SvgProps) {
  const { width, height, decorative, alt } = props;
  return (
    <SvgWrapper width={width} height={height} decorative={decorative} alt={alt}>
      <rect x="1" y="1" width="38" height="22" rx="4" fill="#2E77BC" stroke="#1E5E98" />
      <text
        x="20"
        y="16"
        textAnchor="middle"
        fontFamily="Arial, sans-serif"
        fontSize="10"
        fontWeight="700"
        fill="#FFFFFF"
      >
        AMEX
      </text>
    </SvgWrapper>
  );
}

function GenericCardSvg(props: SvgProps) {
  const { width, height, decorative, alt } = props;
  return (
    <SvgWrapper width={width} height={height} decorative={decorative} alt={alt}>
      <rect x="1" y="1" width="38" height="22" rx="4" fill="#F2F4F7" stroke="#D0D5DD" />
      <rect x="4" y="6" width="32" height="4" rx="1" fill="#98A2B3" />
      <rect x="4" y="13" width="14" height="3" rx="1" fill="#B2B7C2" />
      <rect x="20" y="13" width="16" height="3" rx="1" fill="#B2B7C2" />
    </SvgWrapper>
  );
}

export function CardBrandIcon(props: CardBrandIconProps) {
  const brand = normalizeBrand(props.brand);
  const size = typeof props.size_px === 'number' && props.size_px > 0 ? props.size_px : 24;
  const decorative = props.decorative === true;

  // For non-decorative mode, use alt_text when provided; else fall back to brand-derived label.
  const alt = decorative ? '' : (props.alt_text && props.alt_text.trim()) || defaultAltText(brand);

  const svgProps: SvgProps = {
    width: size,
    height: size,
    decorative,
    alt
  };

  switch (brand) {
    case 'visa':
      return <VisaSvg {...svgProps} />;
    case 'mastercard':
      return <MastercardSvg {...svgProps} />;
    case 'amex':
      return <AmexSvg {...svgProps} />;
    default:
      return <GenericCardSvg {...svgProps} />;
  }
}

import React from 'react';

type CardNumberMaskedProps = {
  /** Last 4 digits of the card number (e.g., "1234"). */
  last4: string;
  /** Visible mask pattern preceding last4 (e.g., "•••• •••• ••••" or "**** **** ****"). */
  mask_pattern?: string;
  /** Whether to truncate with single-line ellipsis on constrained widths. */
  truncate?: boolean;
  /** Optional tooltip text for the visible masked number (should not include full PAN). */
  title?: string;
};

const DEFAULT_MASK_PATTERN = '•••• •••• ••••';

/**
 * Masked card number display. Presentational/dumb component.
 */
export function CardNumberMasked(props: CardNumberMaskedProps) {
  const { last4, mask_pattern, truncate, title } = props;

  const mask = (mask_pattern ?? DEFAULT_MASK_PATTERN).trim();
  const safeLast4 = String(last4 ?? '').replace(/\D/g, '').slice(-4);

  const visible = mask.length > 0 ? `${mask} ${safeLast4}` : safeLast4;

  const truncationStyle: React.CSSProperties | undefined = truncate
    ? {
        whiteSpace: 'nowrap',
        overflow: 'hidden',
        textOverflow: 'ellipsis'
      }
    : undefined;

  return (
    <span
      data-testid="card-number-masked"
      data-truncate={truncate ? 'true' : undefined}
      style={truncationStyle}
      title={title}
    >
      {visible}
    </span>
  );
}

import React from 'react';

export type CardExpiryDateProps = {
  /** Expiry month as a 1–12 number. */
  expiry_month: number;
  /** Expiry year as a 2-digit (e.g., 27) or 4-digit (e.g., 2027) year number. */
  expiry_year: number;
  /** When true, render an "Expired" indicator and apply expired styling to the expiry field. */
  is_expired?: boolean;
  /** When true, apply disabled semantic/styling hook. */
  disabled?: boolean;
};

function pad2(n: number): string {
  const i = Number.isFinite(n) ? Math.trunc(n) : 0;
  return String(i).padStart(2, '0');
}

function normalizeYearToYY(year: number): string {
  const y = Number.isFinite(year) ? Math.trunc(year) : 0;
  const yy = Math.abs(y) % 100;
  return pad2(yy);
}

export function CardExpiryDate(props: CardExpiryDateProps) {
  const { expiry_month, expiry_year, is_expired = false, disabled = false } = props;

  const mm = pad2(expiry_month);
  const yy = normalizeYearToYY(expiry_year);
  const display = `${mm}/${yy}`;

  const className = [
    'CardExpiryDate',
    is_expired ? 'CardExpiryDate--expired' : null,
    disabled ? 'CardExpiryDate--disabled' : null,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <span
      className={className}
      data-expired={is_expired ? 'true' : 'false'}
      data-disabled={disabled ? 'true' : 'false'}
      aria-disabled={disabled ? 'true' : undefined}
    >
      <span className="CardExpiryDate__value">{display}</span>
      {is_expired ? (
        <span className="CardExpiryDate__badge" aria-label="Expired">
          {' '}
          Expired
        </span>
      ) : null}
    </span>
  );
}

import React from 'react';

export type CardholderNameProps = {
  /** Cardholder name text to display (will be truncated with ellipsis on constrained widths). */
  cardholder_name: string;
  /** Optional tooltip text to expose the full cardholder name when the visible value is truncated (e.g., via title attribute). */
  title?: string;
};

export function CardholderName({ cardholder_name, title }: CardholderNameProps) {
  return (
    <span
      style={{
        display: 'block',
        minWidth: 0,
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap'
      }}
      {...(title ? { title } : {})}
    >
      {cardholder_name}
    </span>
  );
}

import * as React from 'react';

export type DeletePaymentCardPayload = {
  card_id: string;
  last4: string;
};

export type DeletePaymentCardConfirmationPayload = {
  card_id: string;
  last4: string;
};

export type DeleteCardActionProps = {
  card_id: string;
  last4: string;
  is_selected?: boolean;
  is_disabled?: boolean;
  is_deleting?: boolean;
  delete_error_message?: string;
  delete_aria_label?: string;
  on_delete_confirm: (payload: DeletePaymentCardPayload) => void;
  on_delete_confirmation_open?: (payload: DeletePaymentCardConfirmationPayload) => void;
  on_delete_confirmation_cancel?: (payload: DeletePaymentCardConfirmationPayload) => void;
  on_request_stop_selection_propagation?: () => void;
};

function useStableCallback<T extends (...args: any[]) => any>(fn: T | undefined) {
  const ref = React.useRef(fn);
  React.useEffect(() => {
    ref.current = fn;
  }, [fn]);
  return React.useCallback((...args: Parameters<T>) => {
    return ref.current?.(...args);
  }, []) as T;
}

export function DeleteCardAction(props: DeleteCardActionProps) {
  const {
    card_id,
    last4,
    is_disabled,
    is_deleting,
    delete_error_message,
    delete_aria_label,
    on_delete_confirm,
    on_delete_confirmation_open,
    on_delete_confirmation_cancel,
    on_request_stop_selection_propagation
  } = props;

  const disabled = !!is_disabled || !!is_deleting;
  const [isConfirmationOpen, setIsConfirmationOpen] = React.useState(false);

  const rootRef = React.useRef<HTMLDivElement | null>(null);
  const deleteButtonRef = React.useRef<HTMLButtonElement | null>(null);

  const emitOpen = useStableCallback(on_delete_confirmation_open);
  const emitCancel = useStableCallback(on_delete_confirmation_cancel);
  const emitStopPropagation = useStableCallback(on_request_stop_selection_propagation);

  const payload = React.useMemo(() => ({ card_id, last4 }), [card_id, last4]);

  // When deletion becomes pending, ensure confirmation is closed.
  React.useEffect(() => {
    if (is_deleting && isConfirmationOpen) {
      setIsConfirmationOpen(false);
    }
  }, [is_deleting, isConfirmationOpen]);

  const closeConfirmationAndRestoreFocus = React.useCallback(
    (emit: boolean) => {
      setIsConfirmationOpen(false);
      if (emit) emitCancel(payload);
      // Focus should return to the delete button
      // (ensure it happens after DOM updates)
      queueMicrotask(() => {
        deleteButtonRef.current?.focus();
      });
    },
    [emitCancel, payload]
  );

  // Outside click closes
  React.useEffect(() => {
    if (!isConfirmationOpen) return;

    const onPointerDownCapture = (e: PointerEvent) => {
      const root = rootRef.current;
      if (!root) return;
      const target = e.target as Node | null;
      if (target && root.contains(target)) return;
      closeConfirmationAndRestoreFocus(true);
    };

    document.addEventListener('pointerdown', onPointerDownCapture, true);
    return () => {
      document.removeEventListener('pointerdown', onPointerDownCapture, true);
    };
  }, [isConfirmationOpen, closeConfirmationAndRestoreFocus]);

  // Escape closes
  React.useEffect(() => {
    if (!isConfirmationOpen) return;

    const onKeyDownCapture = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      e.preventDefault();
      e.stopPropagation();
      closeConfirmationAndRestoreFocus(true);
    };

    document.addEventListener('keydown', onKeyDownCapture, true);
    return () => {
      document.removeEventListener('keydown', onKeyDownCapture, true);
    };
  }, [isConfirmationOpen, closeConfirmationAndRestoreFocus]);

  const ariaLabel = delete_aria_label ?? `Delete card ending in ${last4}`;

  const stopSelectionPropagation = React.useCallback(
    (e: React.SyntheticEvent) => {
      e.stopPropagation();
      emitStopPropagation();
    },
    [emitStopPropagation]
  );

  const openConfirmation = React.useCallback(() => {
    if (disabled) return;
    setIsConfirmationOpen(true);
    emitOpen(payload);
  }, [disabled, emitOpen, payload]);

  const onDeleteButtonClick = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      stopSelectionPropagation(e);
      if (disabled) return;
      openConfirmation();
    },
    [disabled, openConfirmation, stopSelectionPropagation]
  );

  const onDeleteButtonKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLButtonElement>) => {
      // Ensure keyboard activation on delete doesn't bubble to parent selectable card.
      if (e.key === 'Enter' || e.key === ' ') {
        stopSelectionPropagation(e);
      }

      // Escape is no-op if confirmation isn't open.
    },
    [stopSelectionPropagation]
  );

  const onCancel = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      stopSelectionPropagation(e);
      closeConfirmationAndRestoreFocus(true);
    },
    [closeConfirmationAndRestoreFocus, stopSelectionPropagation]
  );

  const onConfirm = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      stopSelectionPropagation(e);
      if (disabled) return;
      setIsConfirmationOpen(false);
      on_delete_confirm(payload);
      // focus restoration after confirm is controlled by parent flows; keeping focus stable on delete button is OK.
      queueMicrotask(() => {
        deleteButtonRef.current?.focus();
      });
    },
    [disabled, on_delete_confirm, payload, stopSelectionPropagation]
  );

  const dialogId = `delete-confirm-${card_id}`;

  return (
    <div ref={rootRef} data-component="delete_card_action" style={{ position: 'relative', display: 'inline-flex', flexDirection: 'column', gap: 6 }}>
      <button
        ref={deleteButtonRef}
        type="button"
        aria-label={ariaLabel}
        aria-haspopup="dialog"
        aria-expanded={isConfirmationOpen ? 'true' : 'false'}
        aria-controls={isConfirmationOpen ? dialogId : undefined}
        disabled={disabled}
        onClick={onDeleteButtonClick}
        onKeyDown={onDeleteButtonKeyDown}
        style={{
          minWidth: 44,
          minHeight: 44,
          paddingInline: 10,
          paddingBlock: 8,
          borderRadius: 10,
          border: '1px solid rgba(0,0,0,0.14)',
          background: 'transparent',
          cursor: disabled ? 'not-allowed' : 'pointer',
          display: 'inline-flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}
      >
        {is_deleting ? (
          <span
            role="status"
            aria-label="Deleting"
            style={{ display: 'inline-flex', alignItems: 'center', gap: 8, fontSize: 12 }}
          >
            <span
              aria-hidden="true"
              style={{
                width: 14,
                height: 14,
                borderRadius: '50%',
                border: '2px solid rgba(0,0,0,0.25)',
                borderTopColor: 'rgba(0,0,0,0.65)',
                animation: 'dca-spin 0.8s linear infinite'
              }}
            />
          </span>
        ) : (
          // Simple icon placeholder (trash). Icon-only visual; aria-label on button.
          <svg
            aria-hidden="true"
            width="18"
            height="18"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M9 3h6l1 2h4v2H4V5h4l1-2Zm1 7h2v9h-2v-9Zm4 0h2v9h-2v-9ZM7 10h2v9H7v-9Zm-1 11h12a2 2 0 0 0 2-2V9H4v10a2 2 0 0 0 2 2Z"
              fill="currentColor"
            />
          </svg>
        )}
      </button>

      {delete_error_message ? (
        <div role="alert" style={{ color: '#B00020', fontSize: 12, lineHeight: 1.3 }}>
          {delete_error_message}
        </div>
      ) : null}

      {isConfirmationOpen && !is_deleting ? (
        <div
          id={dialogId}
          role="dialog"
          aria-label={`Confirm delete card ending in ${last4}`}
          onClick={(e) => {
            // Prevent dialog clicks from selecting parent card
            stopSelectionPropagation(e);
          }}
          style={{
            position: 'absolute',
            zIndex: 20,
            insetInlineEnd: 0,
            top: 'calc(100% + 8px)',
            width: 260,
            padding: 12,
            borderRadius: 12,
            border: '1px solid rgba(0,0,0,0.14)',
            background: '#fff',
            boxShadow: '0 8px 24px rgba(0,0,0,0.12)'
          }}
        >
          <div style={{ fontSize: 13, marginBottom: 10 }}>
            Delete card ending in <strong>{last4}</strong>?
          </div>
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <button
              type="button"
              onClick={onCancel}
              style={{
                minHeight: 36,
                paddingInline: 10,
                borderRadius: 10,
                border: '1px solid rgba(0,0,0,0.14)',
                background: 'transparent',
                cursor: 'pointer'
              }}
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={onConfirm}
              disabled={disabled}
              style={{
                minHeight: 36,
                paddingInline: 12,
                borderRadius: 10,
                border: '1px solid rgba(0,0,0,0.14)',
                background: '#111',
                color: '#fff',
                cursor: disabled ? 'not-allowed' : 'pointer'
              }}
            >
              Delete
            </button>
          </div>
        </div>
      ) : null}

      <style>{`@keyframes dca-spin { from { transform: rotate(0deg);} to { transform: rotate(360deg);} }`}</style>
    </div>
  );
}

import React from 'react';

import { CardBrandIcon } from '../CardBrandIcon/CardBrandIcon';
import { CardNumberMasked } from '../CardNumberMasked/CardNumberMasked';
import { CardExpiryDate } from '../CardExpiryDate/CardExpiryDate';
import { CardholderName } from '../CardholderName/CardholderName';
import { DeleteCardAction } from '../DeleteCardAction/DeleteCardAction';

export type SelectPaymentCardPayload = { card_id: string };
export type DeletePaymentCardPayload = { card_id: string };
export type DeletePaymentCardCancelPayload = { card_id: string };

export type PaymentCardProps = {
  card_id: string;
  brand: string;
  last4: string;
  expiry_month: string;
  expiry_year: string;
  cardholder_name: string;
  is_selected: boolean;
  is_disabled?: boolean;
  is_expired?: boolean;
  is_delete_pending?: boolean;
  delete_error_message?: string;
  on_select: (payload: SelectPaymentCardPayload) => void;
  on_delete_confirm: (payload: DeletePaymentCardPayload) => void;
  on_delete_cancel?: (payload: DeletePaymentCardCancelPayload) => void;
  card_aria_label?: string;
};

function titleCaseBrand(brand: string): string {
  const b = (brand || '').trim().toLowerCase();
  if (b === 'visa') return 'Visa';
  if (b === 'mastercard') return 'Mastercard';
  if (b === 'amex' || b === 'american_express' || b === 'american express') return 'Amex';
  return 'Card';
}

function toIntOrNaN(value: string): number {
  const n = Number.parseInt(String(value), 10);
  return Number.isFinite(n) ? n : Number.NaN;
}

export function PaymentCard(props: PaymentCardProps) {
  const {
    card_id,
    brand,
    last4,
    expiry_month,
    expiry_year,
    cardholder_name,
    is_selected,
    is_disabled,
    is_expired,
    is_delete_pending,
    delete_error_message,
    on_select,
    on_delete_confirm,
    on_delete_cancel,
    card_aria_label
  } = props;

  const brandText = titleCaseBrand(brand);
  const mm = String(expiry_month).padStart(2, '0');
  const yy = String(expiry_year).slice(-2).padStart(2, '0');

  const computedAriaLabel = `${brandText} card ending in ${last4}, expires ${mm}/${yy}, ${cardholder_name}`;
  const ariaLabel = (card_aria_label && card_aria_label.trim().length > 0) ? card_aria_label : computedAriaLabel;

  const selectionDisabled = !!is_disabled || !!is_delete_pending;

  const onCardActivate = React.useCallback(() => {
    if (selectionDisabled) return;
    on_select({ card_id });
  }, [selectionDisabled, on_select, card_id]);

  // Provided for nested delete control to call if needed; selection is already protected
  // by stopPropagation on delete interactions, but we keep this for explicit coordination.
  const onRequestStopSelectionPropagation = React.useCallback(() => {
    // no-op
  }, []);

  const disabledAttr = !!is_disabled;

  return (
    <div
      data-payment-card-root
      data-selected={String(!!is_selected)}
      data-disabled={String(!!is_disabled)}
      data-delete-pending={String(!!is_delete_pending)}
      data-expired={String(!!is_expired)}
    >
      <button
        type="button"
        aria-pressed={is_selected}
        aria-label={ariaLabel}
        disabled={disabledAttr}
        onClick={(e) => {
          if (selectionDisabled) {
            e.preventDefault();
            return;
          }
          onCardActivate();
        }}
        // Keep explicit key handling to ensure Space triggers selection in jsdom/user-event.
        onKeyDown={(e) => {
          if (selectionDisabled) return;
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onCardActivate();
          }
        }}
        style={{
          width: '100%',
          minHeight: 44,
          textAlign: 'start',
          cursor: disabledAttr ? 'not-allowed' : 'pointer',
          padding: 12,
          borderRadius: 12,
          border: is_selected ? '2px solid currentColor' : '1px solid rgba(0,0,0,0.2)',
          background: is_selected ? 'rgba(0,0,0,0.04)' : 'white',
          display: 'grid',
          gap: 8
        }}
      >
        <div
          data-row="1"
          style={{
            display: 'grid',
            gridTemplateColumns: 'auto 1fr auto',
            alignItems: 'center',
            columnGap: 12
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center' }}>
            <CardBrandIcon brand={brand} decorative />
          </div>

          <div
            style={{
              minWidth: 0,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap'
            }}
            title={`**** **** **** ${last4}`}
          >
            <CardNumberMasked last4={last4} />
          </div>

          <div
            style={{
              display: 'flex',
              justifyContent: 'flex-end'
            }}
            onClick={(e) => e.stopPropagation()}
            onKeyDown={(e) => e.stopPropagation()}
          >
            <DeleteCardAction
              card_id={card_id}
              last4={last4}
              is_disabled={!!selectionDisabled}
              is_deleting={!!is_delete_pending}
              delete_error_message={delete_error_message}
              on_delete_confirm={(payload: DeletePaymentCardPayload) => {
                on_delete_confirm(payload);
              }}
              on_delete_confirmation_cancel={(payload: DeletePaymentCardCancelPayload) => {
                on_delete_cancel?.(payload);
              }}
              on_request_stop_selection_propagation={onRequestStopSelectionPropagation}
            />
          </div>
        </div>

        <div
          data-row="2"
          style={{
            display: 'grid',
            gridTemplateColumns: '1fr auto',
            alignItems: 'center',
            columnGap: 12
          }}
        >
          <div
            style={{
              minWidth: 0,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap'
            }}
            title={cardholder_name}
          >
            <CardholderName cardholder_name={cardholder_name} />
          </div>

          <div style={{ justifySelf: 'end' }}>
            <CardExpiryDate
              expiry_month={toIntOrNaN(expiry_month)}
              expiry_year={toIntOrNaN(expiry_year)}
              is_expired={!!is_expired}
            />
          </div>
        </div>

        {delete_error_message ? (
          <div role="alert" style={{ color: 'rgb(176, 0, 32)', fontSize: 12 }}>
            {delete_error_message}
          </div>
        ) : null}
      </button>
    </div>
  );
}

import React from 'react';

export type CardBrandIconProps = {
  /** Card brand identifier used to choose the correct brand icon. Use "unknown" (or empty) to render the generic fallback icon. */
  brand: string;
  /** If true, hide the icon from assistive tech (aria-hidden) and do not provide alternative text; the parent component should include brand text in its own accessible label. */
  decorative?: boolean;
  /** Accessible text alternative when the icon is not decorative (e.g., "Visa"). Ignored when decorative=true. */
  alt_text?: string;
  /** Pixel size for the rendered icon (width and height). */
  size_px?: number;
};

function normalizeBrand(brand: string): 'visa' | 'mastercard' | 'amex' | 'unknown' {
  const b = (brand || '').trim().toLowerCase();
  if (b === 'visa') return 'visa';
  if (b === 'mastercard' || b === 'master card' || b === 'mc') return 'mastercard';
  if (b === 'amex' || b === 'american express' || b === 'americanexpress') return 'amex';
  return 'unknown';
}

function defaultAltText(brand: 'visa' | 'mastercard' | 'amex' | 'unknown'): string {
  switch (brand) {
    case 'visa':
      return 'Visa';
    case 'mastercard':
      return 'Mastercard';
    case 'amex':
      return 'American Express';
    default:
      return 'Card';
  }
}

type SvgProps = {
  width: number;
  height: number;
  decorative: boolean;
  alt: string;
};

function SvgWrapper({ width, height, decorative, alt, children }: React.PropsWithChildren<SvgProps>) {
  return (
    <svg
      width={width}
      height={height}
      viewBox="0 0 40 24"
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-hidden={decorative ? 'true' : undefined}
      aria-label={decorative ? undefined : alt}
      focusable="false"
    >
      {children}
    </svg>
  );
}

function VisaSvg(props: SvgProps) {
  const { width, height, decorative, alt } = props;
  return (
    <SvgWrapper width={width} height={height} decorative={decorative} alt={alt}>
      <rect x="1" y="1" width="38" height="22" rx="4" fill="#1A1F71" stroke="#0F1557" />
      <text
        x="20"
        y="16"
        textAnchor="middle"
        fontFamily="Arial, sans-serif"
        fontSize="10"
        fontWeight="700"
        fill="#FFFFFF"
      >
        VISA
      </text>
    </SvgWrapper>
  );
}

function MastercardSvg(props: SvgProps) {
  const { width, height, decorative, alt } = props;
  return (
    <SvgWrapper width={width} height={height} decorative={decorative} alt={alt}>
      <rect x="1" y="1" width="38" height="22" rx="4" fill="#FFFFFF" stroke="#D0D5DD" />
      <circle cx="17" cy="12" r="6" fill="#EB001B" />
      <circle cx="23" cy="12" r="6" fill="#F79E1B" />
      <circle cx="20" cy="12" r="6" fill="#FF5F00" opacity="0.85" />
    </SvgWrapper>
  );
}

function AmexSvg(props: SvgProps) {
  const { width, height, decorative, alt } = props;
  return (
    <SvgWrapper width={width} height={height} decorative={decorative} alt={alt}>
      <rect x="1" y="1" width="38" height="22" rx="4" fill="#2E77BC" stroke="#1E5E98" />
      <text
        x="20"
        y="16"
        textAnchor="middle"
        fontFamily="Arial, sans-serif"
        fontSize="10"
        fontWeight="700"
        fill="#FFFFFF"
      >
        AMEX
      </text>
    </SvgWrapper>
  );
}

function GenericCardSvg(props: SvgProps) {
  const { width, height, decorative, alt } = props;
  return (
    <SvgWrapper width={width} height={height} decorative={decorative} alt={alt}>
      <rect x="1" y="1" width="38" height="22" rx="4" fill="#F2F4F7" stroke="#D0D5DD" />
      <rect x="4" y="6" width="32" height="4" rx="1" fill="#98A2B3" />
      <rect x="4" y="13" width="14" height="3" rx="1" fill="#B2B7C2" />
      <rect x="20" y="13" width="16" height="3" rx="1" fill="#B2B7C2" />
    </SvgWrapper>
  );
}

export function CardBrandIcon(props: CardBrandIconProps) {
  const brand = normalizeBrand(props.brand);
  const size = typeof props.size_px === 'number' && props.size_px > 0 ? props.size_px : 24;
  const decorative = props.decorative === true;

  // For non-decorative mode, use alt_text when provided; else fall back to brand-derived label.
  const alt = decorative ? '' : (props.alt_text && props.alt_text.trim()) || defaultAltText(brand);

  const svgProps: SvgProps = {
    width: size,
    height: size,
    decorative,
    alt
  };

  switch (brand) {
    case 'visa':
      return <VisaSvg {...svgProps} />;
    case 'mastercard':
      return <MastercardSvg {...svgProps} />;
    case 'amex':
      return <AmexSvg {...svgProps} />;
    default:
      return <GenericCardSvg {...svgProps} />;
  }
}

import React from 'react';

type CardNumberMaskedProps = {
  /** Last 4 digits of the card number (e.g., "1234"). */
  last4: string;
  /** Visible mask pattern preceding last4 (e.g., "•••• •••• ••••" or "**** **** ****"). */
  mask_pattern?: string;
  /** Whether to truncate with single-line ellipsis on constrained widths. */
  truncate?: boolean;
  /** Optional tooltip text for the visible masked number (should not include full PAN). */
  title?: string;
};

const DEFAULT_MASK_PATTERN = '•••• •••• ••••';

/**
 * Masked card number display. Presentational/dumb component.
 */
export function CardNumberMasked(props: CardNumberMaskedProps) {
  const { last4, mask_pattern, truncate, title } = props;

  const mask = (mask_pattern ?? DEFAULT_MASK_PATTERN).trim();
  const safeLast4 = String(last4 ?? '').replace(/\D/g, '').slice(-4);

  const visible = mask.length > 0 ? `${mask} ${safeLast4}` : safeLast4;

  const truncationStyle: React.CSSProperties | undefined = truncate
    ? {
        whiteSpace: 'nowrap',
        overflow: 'hidden',
        textOverflow: 'ellipsis'
      }
    : undefined;

  return (
    <span
      data-testid="card-number-masked"
      data-truncate={truncate ? 'true' : undefined}
      style={truncationStyle}
      title={title}
    >
      {visible}
    </span>
  );
}

import React from 'react';

export type CardExpiryDateProps = {
  /** Expiry month as a 1–12 number. */
  expiry_month: number;
  /** Expiry year as a 2-digit (e.g., 27) or 4-digit (e.g., 2027) year number. */
  expiry_year: number;
  /** When true, render an "Expired" indicator and apply expired styling to the expiry field. */
  is_expired?: boolean;
  /** When true, apply disabled semantic/styling hook. */
  disabled?: boolean;
};

function pad2(n: number): string {
  const i = Number.isFinite(n) ? Math.trunc(n) : 0;
  return String(i).padStart(2, '0');
}

function normalizeYearToYY(year: number): string {
  const y = Number.isFinite(year) ? Math.trunc(year) : 0;
  const yy = Math.abs(y) % 100;
  return pad2(yy);
}

export function CardExpiryDate(props: CardExpiryDateProps) {
  const { expiry_month, expiry_year, is_expired = false, disabled = false } = props;

  const mm = pad2(expiry_month);
  const yy = normalizeYearToYY(expiry_year);
  const display = `${mm}/${yy}`;

  const className = [
    'CardExpiryDate',
    is_expired ? 'CardExpiryDate--expired' : null,
    disabled ? 'CardExpiryDate--disabled' : null,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <span
      className={className}
      data-expired={is_expired ? 'true' : 'false'}
      data-disabled={disabled ? 'true' : 'false'}
      aria-disabled={disabled ? 'true' : undefined}
    >
      <span className="CardExpiryDate__value">{display}</span>
      {is_expired ? (
        <span className="CardExpiryDate__badge" aria-label="Expired">
          {' '}
          Expired
        </span>
      ) : null}
    </span>
  );
}

import React from 'react';

export type CardholderNameProps = {
  /** Cardholder name text to display (will be truncated with ellipsis on constrained widths). */
  cardholder_name: string;
  /** Optional tooltip text to expose the full cardholder name when the visible value is truncated (e.g., via title attribute). */
  title?: string;
};

export function CardholderName({ cardholder_name, title }: CardholderNameProps) {
  return (
    <span
      style={{
        display: 'block',
        minWidth: 0,
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap'
      }}
      {...(title ? { title } : {})}
    >
      {cardholder_name}
    </span>
  );
}

import * as React from 'react';

export type DeletePaymentCardPayload = {
  card_id: string;
  last4: string;
};

export type DeletePaymentCardConfirmationPayload = {
  card_id: string;
  last4: string;
};

export type DeleteCardActionProps = {
  card_id: string;
  last4: string;
  is_selected?: boolean;
  is_disabled?: boolean;
  is_deleting?: boolean;
  delete_error_message?: string;
  delete_aria_label?: string;
  on_delete_confirm: (payload: DeletePaymentCardPayload) => void;
  on_delete_confirmation_open?: (payload: DeletePaymentCardConfirmationPayload) => void;
  on_delete_confirmation_cancel?: (payload: DeletePaymentCardConfirmationPayload) => void;
  on_request_stop_selection_propagation?: () => void;
};

function useStableCallback<T extends (...args: any[]) => any>(fn: T | undefined) {
  const ref = React.useRef(fn);
  React.useEffect(() => {
    ref.current = fn;
  }, [fn]);
  return React.useCallback((...args: Parameters<T>) => {
    return ref.current?.(...args);
  }, []) as T;
}

export function DeleteCardAction(props: DeleteCardActionProps) {
  const {
    card_id,
    last4,
    is_disabled,
    is_deleting,
    delete_error_message,
    delete_aria_label,
    on_delete_confirm,
    on_delete_confirmation_open,
    on_delete_confirmation_cancel,
    on_request_stop_selection_propagation
  } = props;

  const disabled = !!is_disabled || !!is_deleting;
  const [isConfirmationOpen, setIsConfirmationOpen] = React.useState(false);

  const rootRef = React.useRef<HTMLDivElement | null>(null);
  const deleteButtonRef = React.useRef<HTMLButtonElement | null>(null);

  const emitOpen = useStableCallback(on_delete_confirmation_open);
  const emitCancel = useStableCallback(on_delete_confirmation_cancel);
  const emitStopPropagation = useStableCallback(on_request_stop_selection_propagation);

  const payload = React.useMemo(() => ({ card_id, last4 }), [card_id, last4]);

  // When deletion becomes pending, ensure confirmation is closed.
  React.useEffect(() => {
    if (is_deleting && isConfirmationOpen) {
      setIsConfirmationOpen(false);
    }
  }, [is_deleting, isConfirmationOpen]);

  const closeConfirmationAndRestoreFocus = React.useCallback(
    (emit: boolean) => {
      setIsConfirmationOpen(false);
      if (emit) emitCancel(payload);
      // Focus should return to the delete button
      // (ensure it happens after DOM updates)
      queueMicrotask(() => {
        deleteButtonRef.current?.focus();
      });
    },
    [emitCancel, payload]
  );

  // Outside click closes
  React.useEffect(() => {
    if (!isConfirmationOpen) return;

    const onPointerDownCapture = (e: PointerEvent) => {
      const root = rootRef.current;
      if (!root) return;
      const target = e.target as Node | null;
      if (target && root.contains(target)) return;
      closeConfirmationAndRestoreFocus(true);
    };

    document.addEventListener('pointerdown', onPointerDownCapture, true);
    return () => {
      document.removeEventListener('pointerdown', onPointerDownCapture, true);
    };
  }, [isConfirmationOpen, closeConfirmationAndRestoreFocus]);

  // Escape closes
  React.useEffect(() => {
    if (!isConfirmationOpen) return;

    const onKeyDownCapture = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      e.preventDefault();
      e.stopPropagation();
      closeConfirmationAndRestoreFocus(true);
    };

    document.addEventListener('keydown', onKeyDownCapture, true);
    return () => {
      document.removeEventListener('keydown', onKeyDownCapture, true);
    };
  }, [isConfirmationOpen, closeConfirmationAndRestoreFocus]);

  const ariaLabel = delete_aria_label ?? `Delete card ending in ${last4}`;

  const stopSelectionPropagation = React.useCallback(
    (e: React.SyntheticEvent) => {
      e.stopPropagation();
      emitStopPropagation();
    },
    [emitStopPropagation]
  );

  const openConfirmation = React.useCallback(() => {
    if (disabled) return;
    setIsConfirmationOpen(true);
    emitOpen(payload);
  }, [disabled, emitOpen, payload]);

  const onDeleteButtonClick = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      stopSelectionPropagation(e);
      if (disabled) return;
      openConfirmation();
    },
    [disabled, openConfirmation, stopSelectionPropagation]
  );

  const onDeleteButtonKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLButtonElement>) => {
      // Ensure keyboard activation on delete doesn't bubble to parent selectable card.
      if (e.key === 'Enter' || e.key === ' ') {
        stopSelectionPropagation(e);
      }

      // Escape is no-op if confirmation isn't open.
    },
    [stopSelectionPropagation]
  );

  const onCancel = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      stopSelectionPropagation(e);
      closeConfirmationAndRestoreFocus(true);
    },
    [closeConfirmationAndRestoreFocus, stopSelectionPropagation]
  );

  const onConfirm = React.useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      stopSelectionPropagation(e);
      if (disabled) return;
      setIsConfirmationOpen(false);
      on_delete_confirm(payload);
      // focus restoration after confirm is controlled by parent flows; keeping focus stable on delete button is OK.
      queueMicrotask(() => {
        deleteButtonRef.current?.focus();
      });
    },
    [disabled, on_delete_confirm, payload, stopSelectionPropagation]
  );

  const dialogId = `delete-confirm-${card_id}`;

  return (
    <div ref={rootRef} data-component="delete_card_action" style={{ position: 'relative', display: 'inline-flex', flexDirection: 'column', gap: 6 }}>
      <button
        ref={deleteButtonRef}
        type="button"
        aria-label={ariaLabel}
        aria-haspopup="dialog"
        aria-expanded={isConfirmationOpen ? 'true' : 'false'}
        aria-controls={isConfirmationOpen ? dialogId : undefined}
        disabled={disabled}
        onClick={onDeleteButtonClick}
        onKeyDown={onDeleteButtonKeyDown}
        style={{
          minWidth: 44,
          minHeight: 44,
          paddingInline: 10,
          paddingBlock: 8,
          borderRadius: 10,
          border: '1px solid rgba(0,0,0,0.14)',
          background: 'transparent',
          cursor: disabled ? 'not-allowed' : 'pointer',
          display: 'inline-flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}
      >
        {is_deleting ? (
          <span
            role="status"
            aria-label="Deleting"
            style={{ display: 'inline-flex', alignItems: 'center', gap: 8, fontSize: 12 }}
          >
            <span
              aria-hidden="true"
              style={{
                width: 14,
                height: 14,
                borderRadius: '50%',
                border: '2px solid rgba(0,0,0,0.25)',
                borderTopColor: 'rgba(0,0,0,0.65)',
                animation: 'dca-spin 0.8s linear infinite'
              }}
            />
          </span>
        ) : (
          // Simple icon placeholder (trash). Icon-only visual; aria-label on button.
          <svg
            aria-hidden="true"
            width="18"
            height="18"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M9 3h6l1 2h4v2H4V5h4l1-2Zm1 7h2v9h-2v-9Zm4 0h2v9h-2v-9ZM7 10h2v9H7v-9Zm-1 11h12a2 2 0 0 0 2-2V9H4v10a2 2 0 0 0 2 2Z"
              fill="currentColor"
            />
          </svg>
        )}
      </button>

      {delete_error_message ? (
        <div role="alert" style={{ color: '#B00020', fontSize: 12, lineHeight: 1.3 }}>
          {delete_error_message}
        </div>
      ) : null}

      {isConfirmationOpen && !is_deleting ? (
        <div
          id={dialogId}
          role="dialog"
          aria-label={`Confirm delete card ending in ${last4}`}
          onClick={(e) => {
            // Prevent dialog clicks from selecting parent card
            stopSelectionPropagation(e);
          }}
          style={{
            position: 'absolute',
            zIndex: 20,
            insetInlineEnd: 0,
            top: 'calc(100% + 8px)',
            width: 260,
            padding: 12,
            borderRadius: 12,
            border: '1px solid rgba(0,0,0,0.14)',
            background: '#fff',
            boxShadow: '0 8px 24px rgba(0,0,0,0.12)'
          }}
        >
          <div style={{ fontSize: 13, marginBottom: 10 }}>
            Delete card ending in <strong>{last4}</strong>?
          </div>
          <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
            <button
              type="button"
              onClick={onCancel}
              style={{
                minHeight: 36,
                paddingInline: 10,
                borderRadius: 10,
                border: '1px solid rgba(0,0,0,0.14)',
                background: 'transparent',
                cursor: 'pointer'
              }}
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={onConfirm}
              disabled={disabled}
              style={{
                minHeight: 36,
                paddingInline: 12,
                borderRadius: 10,
                border: '1px solid rgba(0,0,0,0.14)',
                background: '#111',
                color: '#fff',
                cursor: disabled ? 'not-allowed' : 'pointer'
              }}
            >
              Delete
            </button>
          </div>
        </div>
      ) : null}

      <style>{`@keyframes dca-spin { from { transform: rotate(0deg);} to { transform: rotate(360deg);} }`}</style>
    </div>
  );
}

import React from 'react';
import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { PaymentCard } from './PaymentCard';

type CardModel = {
  card_id: string;
  brand: string;
  last4: string;
  expiry_month: string;
  expiry_year: string;
  cardholder_name: string;
  is_expired?: boolean;
};

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function makeAriaLabel(card: CardModel) {
  const brandText = card.brand && card.brand !== 'unknown'
    ? card.brand.slice(0, 1).toUpperCase() + card.brand.slice(1)
    : 'Card';
  return `${brandText} card ending in ${card.last4}, expires ${card.expiry_month}/${card.expiry_year}, ${card.cardholder_name}`;
}

function PaymentMethodsHarness(props: {
  initialCards: CardModel[];
  initialSelectedId?: string;
  listAriaLabel?: string;
}) {
  const { initialCards, initialSelectedId, listAriaLabel = 'Saved payment methods' } = props;

  const [cards, setCards] = React.useState<CardModel[]>(initialCards);
  const [selectedId, setSelectedId] = React.useState<string | null>(initialSelectedId ?? null);
  const [deletePendingById, setDeletePendingById] = React.useState<Record<string, boolean>>({});
  const [deleteErrorById, setDeleteErrorById] = React.useState<Record<string, string | undefined>>({});

  const listRef = React.useRef<HTMLDivElement | null>(null);
  const deleteQueueRef = React.useRef<
    Record<string, Array<{ promise: Promise<void>; resolve: () => void; reject: (e?: unknown) => void }>>
  >({});

  const ensureQueue = (card_id: string) => {
    if (!deleteQueueRef.current[card_id]) deleteQueueRef.current[card_id] = [];
    return deleteQueueRef.current[card_id];
  };

  const onSelect = React.useCallback((payload: { card_id: string }) => {
    setSelectedId(payload.card_id);
  }, []);

  const onDeleteCancel = React.useCallback((payload: { card_id: string }) => {
    // No-op for harness; component should already close confirmation.
    // Keep for interface completeness.
    void payload;
  }, []);

  const onDeleteConfirm = React.useCallback((payload: { card_id: string }) => {
    const { card_id } = payload;

    setDeletePendingById((prev) => ({ ...prev, [card_id]: true }));

    // Create a deferred that the test can resolve/reject to simulate async behavior.
    const d = deferred<void>();
    const queue = ensureQueue(card_id);
    queue.push({ promise: d.promise, resolve: d.resolve, reject: d.reject });

    d.promise
      .then(() => {
        // simulate brief collapse/fade delay before DOM removal
        setTimeout(() => {
          setCards((prev) => prev.filter((c) => c.card_id !== card_id));
          setDeletePendingById((prev) => {
            const next = { ...prev };
            delete next[card_id];
            return next;
          });
          setDeleteErrorById((prev) => {
            const next = { ...prev };
            delete next[card_id];
            return next;
          });

          // Focus placement: next card, else previous, else list container
          setTimeout(() => {
            const remaining = (listRef.current?.querySelectorAll('button[aria-pressed]') ?? []) as NodeListOf<HTMLButtonElement>;
            // Choose first remaining card button by DOM order (acts as "next" in this harness).
            if (remaining.length > 0) {
              remaining[0].focus();
              return;
            }
            listRef.current?.focus();
          }, 0);
        }, 180);
      })
      .catch(() => {
        setDeletePendingById((prev) => ({ ...prev, [card_id]: false }));
        setDeleteErrorById((prev) => ({ ...prev, [card_id]: 'Could not delete this card. Try again.' }));
      })
      .finally(() => {
        setDeletePendingById((prev) => {
          const isPending = prev[card_id];
          if (isPending) return prev;
          const next = { ...prev };
          delete next[card_id];
          return next;
        });
      });
  }, []);

  const api = React.useMemo(() => {
    return {
      resolveDelete(card_id: string) {
        const queue = ensureQueue(card_id);
        const item = queue.shift();
        if (!item) throw new Error(`No pending delete request for ${card_id}`);
        item.resolve();
      },
      rejectDelete(card_id: string) {
        const queue = ensureQueue(card_id);
        const item = queue.shift();
        if (!item) throw new Error(`No pending delete request for ${card_id}`);
        item.reject(new Error('delete failed'));
      }
    };
  }, []);

  // Expose harness controls to tests via a global-ish handle on the DOM node.
  // This avoids inventing additional files while keeping the test self-contained.
  (globalThis as any).__paymentMethodsHarnessApi = api;

  return (
    <div>
      <div
        ref={listRef}
        role="region"
        aria-label={listAriaLabel}
        tabIndex={-1}
        data-testid="payment-methods-list"
      >
        {cards.map((c) => (
          <PaymentCard
            key={c.card_id}
            card_id={c.card_id}
            brand={c.brand}
            last4={c.last4}
            expiry_month={c.expiry_month}
            expiry_year={c.expiry_year}
            cardholder_name={c.cardholder_name}
            is_selected={selectedId === c.card_id}
            is_expired={c.is_expired}
            is_delete_pending={!!deletePendingById[c.card_id]}
            delete_error_message={deleteErrorById[c.card_id]}
            on_select={onSelect}
            on_delete_confirm={onDeleteConfirm}
            on_delete_cancel={onDeleteCancel}
          />
        ))}
      </div>
    </div>
  );
}

function getHarnessApi(): { resolveDelete: (card_id: string) => void; rejectDelete: (card_id: string) => void } {
  const api = (globalThis as any).__paymentMethodsHarnessApi;
  if (!api) throw new Error('Harness API not found');
  return api;
}

