    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();

    // Confirm delete.
    await user.click(screen.getByRole('button', { name: /^delete$/i }));

    // Pending: selection disabled and delete disabled.
    // If PaymentCard uses a disabled button in pending, enforce it; otherwise at least ensure clicking doesn't change selection.
    expect(screen.getByRole('button', { name: cardALabel })).toHaveAttribute('aria-pressed', 'false');

    const deleteButtonAfterConfirm = screen.getByRole('button', { name: 'Delete card ending in 1111' });
