    });

    // flush the 180ms removal + focus microtask
    act(() => {
      jest.advanceTimersByTime(250);
    });

    // Card A removed
    expect(screen.queryByRole('button', { name: cardALabel })).not.toBeInTheDocument();

    // Focus moves to next card's card button (first remaining).
    const cardBButton = screen.getByRole('button', { name: makeAriaLabel(cards[1]) });
