  test('explore_states_then_select_and_delete: keyboard select + delete button focus + escape no-op + outside click cancels + reopen and delete', async () => {
    jest.useFakeTimers();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });

    const cards: CardModel[] = [
      {
        card_id: 'card_a',
