    await user.tab();
    const cardAButton = screen.getByRole('button', { name: makeAriaLabel(cards[0]) });
    expect(cardAButton).toHaveFocus();

    // Space selects it.
    await user.keyboard(' ');
    expect(cardAButton).toHaveAttribute('aria-pressed', 'true');
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();

    // Tab moves to delete inside same card.
    await user.tab();
    const deleteButton = screen.getByRole('button', { name: 'Delete card ending in 1111' });
    expect(deleteButton).toHaveFocus();

    // Escape without confirmation open: no-op.
    await user.keyboard('{Escape}');
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
    expect(deleteButton).toHaveFocus();
    expect(cardAButton).toHaveAttribute('aria-pressed', 'true');

    // Enter opens confirmation.
    await user.keyboard('{Enter}');
