    expect(screen.getByRole('button', { name: /^delete$/i })).toBeInTheDocument();

    // Click outside closes; focus returns to delete.
    await user.click(document.body);
    expect(screen.queryByRole('button', { name: /cancel/i })).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Delete card ending in 1111' })).toHaveFocus();

    // Reopen and confirm delete.
    await user.keyboard('{Enter}');
    await user.click(screen.getByRole('button', { name: /^delete$/i }));

    // Resolve and flush.
    act(() => {
      getHarnessApi().resolveDelete('card_a');
    });
    act(() => {
      jest.advanceTimersByTime(250);
    });

    // Focus should go to remaining card (unknown brand uses "Card" in label).
    const cardBButton = screen.getByRole('button', { name: makeAriaLabel(cards[1]) });
    expect(cardBButton).toHaveFocus();

    jest.useRealTimers();
  });

  test('delete_fails_then_retry_success: first delete fails -> inline error -> retry requires confirmation again -> success removes card', async () => {
    jest.useFakeTimers();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });

    const cards: CardModel[] = [
      {
        card_id: 'card_a',
        brand: 'visa',
        last4: '1111',
        expiry_month: '05',
        expiry_year: '27',
        cardholder_name: 'Jane Merchant'
      },
      {
        card_id: 'card_b',
        brand: 'mastercard',
        last4: '2222',
        expiry_month: '06',
        expiry_year: '28',
        cardholder_name: 'John Merchant'
      }
    ];

    render(<PaymentMethodsHarness initialCards={cards} initialSelectedId={null} />);

    const cardALabel = makeAriaLabel(cards[0]);

    // Open confirm and submit delete.
    await user.click(screen.getByRole('button', { name: 'Delete card ending in 1111' }));
    await user.click(screen.getByRole('button', { name: /^delete$/i }));

    // Fail it.
    act(() => {
      getHarnessApi().rejectDelete('card_a');
    });

    // Let state settle.
    await act(async () => {
      // allow promise chain to run
    });

    // Card remains and error visible.
    expect(screen.getByRole('button', { name: cardALabel })).toBeInTheDocument();
    expect(screen.getByText('Could not delete this card. Try again.')).toBeInTheDocument();

    // Controls re-enabled: delete button clickable again.
    const deleteButton = screen.getByRole('button', { name: 'Delete card ending in 1111' });
    expect(deleteButton).toBeEnabled();

    // Retry requires confirmation again.
    await user.click(deleteButton);
    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^delete$/i })).toBeInTheDocument();

    await user.click(screen.getByRole('button', { name: /^delete$/i }));

    // Succeed retry.
    act(() => {
      getHarnessApi().resolveDelete('card_a');
    });
    act(() => {
      jest.advanceTimersByTime(250);
    });

    // Card A removed; error gone with it.
    expect(screen.queryByRole('button', { name: cardALabel })).not.toBeInTheDocument();
    expect(screen.queryByText('Could not delete this card. Try again.')).not.toBeInTheDocument();

    // Focus to remaining card.
    expect(screen.getByRole('button', { name: makeAriaLabel(cards[1]) })).toHaveFocus();

    jest.useRealTimers();
  });
});

