}));

jest.mock('../DeleteCardAction/DeleteCardAction', () => ({
  DeleteCardAction: (props: any) => {
    const {
      card_id,
      last4,
      is_disabled,
      is_deleting,
      delete_error_message,
      on_delete_confirm,
      on_delete_confirmation_cancel,
      on_request_stop_selection_propagation
    } = props;

    const [open, setOpen] = React.useState(false);

    const openConfirm = (e: React.MouseEvent | React.KeyboardEvent) => {
      e.stopPropagation();
      on_request_stop_selection_propagation?.();
      if (is_disabled || is_deleting) return;
      setOpen(true);
    };

    const cancel = (e: React.MouseEvent) => {
      e.stopPropagation();
      setOpen(false);
      on_delete_confirmation_cancel?.({ card_id });
    };

    const confirm = (e: React.MouseEvent) => {
      e.stopPropagation();
      on_delete_confirm?.({ card_id });
    };

    return (
      <div>
        <button
          type="button"
          aria-label={`Delete card ending in ${last4}`}
          onClick={openConfirm}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') openConfirm(e);
          }}
          disabled={!!is_disabled || !!is_deleting}
        >
          Delete
        </button>
        {delete_error_message ? <div data-testid="delete-error">{delete_error_message}</div> : null}
        {open ? (
          <div role="dialog" aria-label={`Confirm delete card ending in ${last4}`}>
            <p>Delete card ending in {last4}?</p>
            <button type="button" onClick={cancel}>Cancel</button>
            <button type="button" onClick={confirm}>Delete</button>
          </div>
        ) : null}
      </div>
    );
  }
}));

function renderCard(overrides: Partial<React.ComponentProps<typeof PaymentCard>> = {}) {
  const props: React.ComponentProps<typeof PaymentCard> = {
    card_id: 'card_123',
    brand: 'visa',
    last4: '1234',
    expiry_month: '05',
    expiry_year: '27',
    cardholder_name: 'John Doe',
    is_selected: false,
    on_select: jest.fn(),
    on_delete_confirm: jest.fn(),
    on_delete_cancel: jest.fn(),
    ...overrides
  };

  const utils = render(<PaymentCard {...props} />);
  return { props, ...utils };
}

