    expect(screen.getByText('Could not delete this card. Try again.')).toBeInTheDocument();
  });

  test('clicking delete does not trigger card selection; confirming delete calls on_delete_confirm with card_id', async () => {
    const user = userEvent.setup();
    const on_select = jest.fn();
    const on_delete_confirm = jest.fn();

    renderCard({ on_select, on_delete_confirm });

    const deleteButton = screen.getByRole('button', { name: 'Delete card ending in 1234' });
    await user.click(deleteButton);

    // Confirm UI should appear.
    expect(screen.getByRole('dialog', { name: 'Confirm delete card ending in 1234' })).toBeInTheDocument();

    // Delete click should not select the card.
    expect(on_select).not.toHaveBeenCalled();

    await user.click(screen.getByRole('button', { name: 'Delete' }));
    expect(on_delete_confirm).toHaveBeenCalledTimes(1);
    expect(on_delete_confirm).toHaveBeenCalledWith({ card_id: 'card_123' });

    // Still should not select due to propagation stop.
    expect(on_select).not.toHaveBeenCalled();
  });

  test('cancelling delete confirmation calls on_delete_cancel with card_id (when provided) and does not select card', async () => {
    const user = userEvent.setup();
    const on_select = jest.fn();
    const on_delete_cancel = jest.fn();

    renderCard({ on_select, on_delete_cancel });

    await user.click(screen.getByRole('button', { name: 'Delete card ending in 1234' }));
    expect(screen.getByRole('dialog', { name: 'Confirm delete card ending in 1234' })).toBeInTheDocument();

    await user.click(screen.getByRole('button', { name: 'Cancel' }));

    expect(on_delete_cancel).toHaveBeenCalledTimes(1);
    expect(on_delete_cancel).toHaveBeenCalledWith({ card_id: 'card_123' });
