import { CardBrandIcon } from './CardBrandIcon';

function getRenderedIconElement(container: HTMLElement): HTMLElement {
  // Prefer an <img> if present, else fallback to first <svg>.
  const img = container.querySelector('img');
  if (img) return img as HTMLElement;
  const svg = container.querySelector('svg');
  if (svg) return svg as HTMLElement;
  throw new Error('Expected CardBrandIcon to render an <img> or <svg>.');
}

describe('CardBrandIcon', () => {
  it('renders a non-decorative icon with accessible name from alt_text when provided', () => {
    const { container } = render(
      <CardBrandIcon brand="visa" decorative={false} alt_text="Visa" />
    );

    // Non-decorative icons should be discoverable by role img.
    const imgByRole = screen.getByRole('img', { name: 'Visa' });
    expect(imgByRole).toBeInTheDocument();

    const el = getRenderedIconElement(container);
    // Must not be aria-hidden when non-decorative
    expect(el).not.toHaveAttribute('aria-hidden', 'true');
  });

  it('when decorative=true, hides from assistive tech and ignores alt_text', () => {
    const { container } = render(
      <CardBrandIcon brand="mastercard" decorative alt_text="Mastercard" />
    );

    // Decorative icon should not be exposed as role=img with an accessible name.
    expect(screen.queryByRole('img', { name: /mastercard/i })).not.toBeInTheDocument();

    const el = getRenderedIconElement(container);

    // Accept either aria-hidden=true (for SVG) or empty alt (for img). Some implementations may do both.
    const isImg = el.tagName.toLowerCase() === 'img';
    if (isImg) {
      expect(el).toHaveAttribute('alt', '');
    }
    expect(el).toHaveAttribute('aria-hidden', 'true');
  });

  it('renders a generic fallback for unknown brand', () => {
    const { container, rerender } = render(
      <CardBrandIcon brand="unknown" decorative={false} alt_text="Card" />
    );

    // Should still expose an image role when non-decorative.
    expect(screen.getByRole('img', { name: 'Card' })).toBeInTheDocument();

    const unknownMarkup = container.innerHTML;

    rerender(<CardBrandIcon brand="visa" decorative={false} alt_text="Visa" />);
    const visaMarkup = container.innerHTML;

    // Ensure rendering differs between unknown fallback and a known brand.
    expect(unknownMarkup).not.toEqual(visaMarkup);
  });

  it('treats empty brand as unknown fallback', () => {
    const { container } = render(
      <CardBrandIcon brand={''} decorative={false} alt_text="Card" />
    );

    expect(screen.getByRole('img', { name: 'Card' })).toBeInTheDocument();

    const el = getRenderedIconElement(container);
    expect(el).toBeInTheDocument();
  });

  it('applies size_px to rendered dimensions when provided', () => {
    const { container } = render(
      <CardBrandIcon brand="amex" decorative={false} alt_text="American Express" size_px={32} />
    );

    const el = getRenderedIconElement(container);

    // Implementation may use width/height attributes or inline styles.
    const widthAttr = el.getAttribute('width');
    const heightAttr = el.getAttribute('height');

    const widthStyle = (el as HTMLElement).style.width;
    const heightStyle = (el as HTMLElement).style.height;

    const attrOrStyleMatches =
      widthAttr === '32' ||
      heightAttr === '32' ||
      widthStyle === '32px' ||
      heightStyle === '32px';

    expect(attrOrStyleMatches).toBe(true);
  });
});

import React from 'react';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';

import { CardNumberMasked } from './CardNumberMasked';

describe('CardNumberMasked', () => {
  const getRoot = () => screen.getByTestId('card-number-masked');

  it('renders masked card number using default mask pattern when mask_pattern is omitted', () => {
    render(<CardNumberMasked last4="1234" />);

    const root = getRoot();
    expect(root).toHaveTextContent(/1234$/);

    // Ensure only last4 is visible as digits
    expect(root.textContent).toMatch(/\d{4}$/);
    expect(root.textContent).not.toMatch(/\d{5,}/);

    // Default mask should be present (either bullets or asterisks depending on implementation)
    // We accept either common default, but require that some mask chars appear before last4.
    expect(root.textContent).toMatch(/(\*{4}|•{4}|\u2022{4}).*1234/);
  });

  it('renders masked card number using provided mask_pattern', () => {
    render(<CardNumberMasked last4="9876" mask_pattern="**** **** ****" />);

    const root = getRoot();
    expect(root).toHaveTextContent('**** **** **** 9876');

    // Ensure only last4 is visible as digits
    expect(root.textContent).toMatch(/\d{4}$/);
    expect(root.textContent).not.toMatch(/\d{5,}/);
  });

  it('sets title attribute when provided', () => {
    render(<CardNumberMasked last4="1234" title="Card ending in 1234" />);

    expect(getRoot()).toHaveAttribute('title', 'Card ending in 1234');
  });

  it('does not set title attribute when not provided', () => {
    render(<CardNumberMasked last4="1234" />);

    expect(getRoot()).not.toHaveAttribute('title');
  });

  it('applies truncation styling/hook when truncate=true', () => {
    render(<CardNumberMasked last4="1234" truncate />);

    const root = getRoot();

    // Implementation may use className and/or inline styles; assert via common CSS signals.
    // We accept either: data attribute, class token, or style enforcing single-line ellipsis.
    const className = root.getAttribute('class') ?? '';
    const hasEllipsisStyle =
      root.style.textOverflow === 'ellipsis' ||
      root.style.overflow === 'hidden' ||
      root.style.whiteSpace === 'nowrap';

    const hasTruncateHook =
      root.getAttribute('data-truncate') === 'true' ||
      /truncate|ellipsis|singleLine/i.test(className) ||
      hasEllipsisStyle;

    expect(hasTruncateHook).toBe(true);
  });

  it('does not apply truncation styling/hook when truncate is false/undefined', () => {
    const { rerender } = render(<CardNumberMasked last4="1234" />);

    const assertNotTruncated = () => {
      const root = getRoot();
      const className = root.getAttribute('class') ?? '';

      expect(root.getAttribute('data-truncate')).not.toBe('true');
      expect(/truncate|ellipsis|singleLine/i.test(className)).toBe(false);

      // If styles are applied inline only when truncating, these should not be set.
      // (If component uses CSS classes instead, the above className assertion covers it.)
      expect(root.style.textOverflow).not.toBe('ellipsis');
      expect(root.style.whiteSpace).not.toBe('nowrap');
      expect(root.style.overflow).not.toBe('hidden');
    };

    assertNotTruncated();

    rerender(<CardNumberMasked last4="1234" truncate={false} />);
    assertNotTruncated();
  });
});

import React from 'react';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';

import { CardExpiryDate } from './CardExpiryDate';

describe('CardExpiryDate', () => {
  const renderSubject = (props: Partial<React.ComponentProps<typeof CardExpiryDate>> = {}) => {
    const allProps: React.ComponentProps<typeof CardExpiryDate> = {
      expiry_month: 5,
      expiry_year: 27,
      ...props,
    };

    return render(<CardExpiryDate {...allProps} />);
  };

  it('renders expiry as MM/YY with zero-padded month', () => {
    renderSubject({ expiry_month: 5, expiry_year: 27 });

    // Accept either "05/27" or "Exp 05/27" depending on implementation; assert the core token.
    expect(screen.getByText(/05\s*\/\s*27/)).toBeInTheDocument();
  });

  it('renders year as last two digits when a 4-digit year is provided', () => {
    renderSubject({ expiry_month: 11, expiry_year: 2027 });

    expect(screen.getByText(/11\s*\/\s*27/)).toBeInTheDocument();
  });

  it('renders an Expired indicator when is_expired is true', () => {
    renderSubject({ is_expired: true });

    // "Expired" badge/label is required by resolving-gaps decision.
    expect(screen.getByText(/expired/i)).toBeInTheDocument();
  });

  it('exposes a disabled semantic or styling hook when disabled is true', () => {
    const { container } = renderSubject({ disabled: true });

    // Support either aria-disabled on a non-form element OR a data/class hook.
    const root = container.firstElementChild as HTMLElement | null;
    expect(root).not.toBeNull();

    const hasAriaDisabled = root?.getAttribute('aria-disabled') === 'true';
    const hasDisabledAttr = (root as any)?.disabled === true || root?.hasAttribute('disabled');
    const hasDataDisabled = root?.getAttribute('data-disabled') === 'true';
    const hasDisabledClass = !!root?.className && /disabled/i.test(root.className);

    expect(hasAriaDisabled || hasDisabledAttr || hasDataDisabled || hasDisabledClass).toBe(true);
  });
});

