import React from 'react';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { DeleteCardAction } from './DeleteCardAction';

function renderSubject(
  overrideProps: Partial<React.ComponentProps<typeof DeleteCardAction>> = {}
) {
  const props: React.ComponentProps<typeof DeleteCardAction> = {
    card_id: 'card_123',
    last4: '1234',
    on_delete_confirm: jest.fn(),
    on_delete_confirmation_open: jest.fn(),
    on_delete_confirmation_cancel: jest.fn(),
    on_request_stop_selection_propagation: jest.fn(),
    ...overrideProps,
  };

  const user = userEvent.setup();
  const view = render(
    <div>
      <DeleteCardAction {...props} />
    </div>
  );

  return { user, props, ...view };
}

describe('DeleteCardAction', () => {
  test('renders a delete button with default accessible name when delete_aria_label is not provided', () => {
    renderSubject({ delete_aria_label: undefined });
    // Default name per decisions: "Delete card ending in {last4}"
    expect(
      screen.getByRole('button', { name: 'Delete card ending in 1234' })
    ).toBeInTheDocument();
  });

  test('uses delete_aria_label override when provided', () => {
    renderSubject({ delete_aria_label: 'Remove payment method 1234' });
    expect(
      screen.getByRole('button', { name: 'Remove payment method 1234' })
    ).toBeInTheDocument();
  });

  test('clicking delete button stops propagation via on_request_stop_selection_propagation and opens confirmation (emits open payload)', async () => {
    const parentOnClick = jest.fn();
    const { user, props } = renderSubject();

    // Re-render inside a clickable parent to detect bubbling.
    // Note: we must use RTL rerender to preserve same props mocks.
    // eslint-disable-next-line testing-library/no-render-in-setup
    const { rerender } = render(
      <div onClick={parentOnClick}>
        <DeleteCardAction {...props} />
      </div>
    );

    const deleteButton = screen.getByRole('button', {
      name: 'Delete card ending in 1234',
    });

    await user.click(deleteButton);

    expect(props.on_request_stop_selection_propagation).toHaveBeenCalledTimes(1);
    expect(parentOnClick).not.toHaveBeenCalled();

    // Confirmation should open and emit open payload
    expect(props.on_delete_confirmation_open).toHaveBeenCalledTimes(1);
    expect(props.on_delete_confirmation_open).toHaveBeenCalledWith({
      card_id: 'card_123',
      last4: '1234',
    });

    // Confirmation UI: Cancel + Delete, and identifier text
    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^delete$/i })).toBeInTheDocument();

    // Prompt should mention ending in 1234 (copy can vary; assert substring)
    expect(screen.getByText(/ending in\s*1234/i)).toBeInTheDocument();

    rerender(
      <div onClick={parentOnClick}>
        <DeleteCardAction {...props} />
      </div>
    );
  });

  test('confirming deletion calls on_delete_confirm with payload and blocks repeated submission when is_deleting becomes true', async () => {
    const { user, props, rerender } = renderSubject({ is_deleting: false });

    const deleteButton = screen.getByRole('button', {
      name: 'Delete card ending in 1234',
    });
    await user.click(deleteButton);

    const confirmButton = screen.getByRole('button', { name: /^delete$/i });
    await user.click(confirmButton);

    expect(props.on_delete_confirm).toHaveBeenCalledTimes(1);
    expect(props.on_delete_confirm).toHaveBeenCalledWith({
      card_id: 'card_123',
      last4: '1234',
    });

    // Simulate parent setting deleting state.
    rerender(
      <DeleteCardAction
        {...props}
        is_deleting={true}
        is_disabled={false}
      />
    );

    const deleteButtonAfter = screen.getByRole('button', {
      name: 'Delete card ending in 1234',
    });
    expect(deleteButtonAfter).toBeDisabled();

    // A progress indicator should be shown while deleting.
    // Accept either role=status/progressbar or an aria-busy marker depending on implementation.
    const progress =
      screen.queryByRole('progressbar') ||
      screen.queryByRole('status') ||
      screen.queryByLabelText(/loading|deleting|please wait/i);
    expect(progress).toBeTruthy();

    // Confirmation should not be open / re-openable while deleting.
    expect(screen.queryByRole('button', { name: /cancel/i })).not.toBeInTheDocument();

    // Trying to click again does nothing.
    await user.click(deleteButtonAfter);
    expect(props.on_delete_confirmation_open).toHaveBeenCalledTimes(1);
  });

  test('cancel closes confirmation, emits cancel payload, and returns focus to delete button', async () => {
    const { user, props } = renderSubject();

    const deleteButton = screen.getByRole('button', {
      name: 'Delete card ending in 1234',
    });
    deleteButton.focus();

    await user.click(deleteButton);

    const cancelButton = screen.getByRole('button', { name: /cancel/i });
    await user.click(cancelButton);

    expect(props.on_delete_confirmation_cancel).toHaveBeenCalledTimes(1);
    expect(props.on_delete_confirmation_cancel).toHaveBeenCalledWith({
      card_id: 'card_123',
      last4: '1234',
    });

    expect(screen.queryByRole('button', { name: /cancel/i })).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Delete card ending in 1234' })).toHaveFocus();
  });

  test('Escape closes confirmation, emits cancel payload, and returns focus to delete button', async () => {
    const { user, props } = renderSubject();

    const deleteButton = screen.getByRole('button', {
      name: 'Delete card ending in 1234',
    });
    await user.click(deleteButton);

    // Put focus inside the confirmation to ensure Escape is handled from within.
    const confirmButton = screen.getByRole('button', { name: /^delete$/i });
    confirmButton.focus();

    await user.keyboard('{Escape}');

    expect(props.on_delete_confirmation_cancel).toHaveBeenCalledTimes(1);
    expect(props.on_delete_confirmation_cancel).toHaveBeenCalledWith({
      card_id: 'card_123',
      last4: '1234',
    });

    expect(screen.queryByRole('button', { name: /cancel/i })).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Delete card ending in 1234' })).toHaveFocus();
  });

  test('clicking outside closes confirmation and emits cancel payload', async () => {
    const { user, props } = renderSubject();

    const deleteButton = screen.getByRole('button', {
      name: 'Delete card ending in 1234',
    });
    await user.click(deleteButton);

    // Ensure dialog content is present before outside click.
    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();

    // Click outside component.
    await user.click(document.body);

    expect(props.on_delete_confirmation_cancel).toHaveBeenCalledTimes(1);
    expect(props.on_delete_confirmation_cancel).toHaveBeenCalledWith({
      card_id: 'card_123',
      last4: '1234',
    });

    expect(screen.queryByRole('button', { name: /cancel/i })).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Delete card ending in 1234' })).toHaveFocus();
  });

  test('when is_disabled=true, delete button is disabled and confirmation cannot be opened', async () => {
    const { user, props } = renderSubject({ is_disabled: true });

    const deleteButton = screen.getByRole('button', {
      name: 'Delete card ending in 1234',
    });
    expect(deleteButton).toBeDisabled();

    await user.click(deleteButton);

    expect(props.on_request_stop_selection_propagation).not.toHaveBeenCalled();
    expect(props.on_delete_confirmation_open).not.toHaveBeenCalled();
    expect(screen.queryByRole('button', { name: /cancel/i })).not.toBeInTheDocument();
  });

  test('renders inline delete error message when provided (does not auto-open confirmation)', () => {
    renderSubject({ delete_error_message: 'Could not delete this card. Try again.' });

    expect(
      screen.getByText('Could not delete this card. Try again.')
    ).toBeInTheDocument();

    // Should not open confirmation implicitly
    expect(screen.queryByRole('button', { name: /cancel/i })).not.toBeInTheDocument();
  });

  test('confirmation UI contains both actions and uses accessible names for those actions', async () => {
    const { user } = renderSubject();

    await user.click(
      screen.getByRole('button', { name: 'Delete card ending in 1234' })
    );

    const cancelButton = screen.getByRole('button', { name: /cancel/i });
    const confirmButton = screen.getByRole('button', { name: /^delete$/i });

    expect(cancelButton).toBeEnabled();
    expect(confirmButton).toBeEnabled();

    // If implemented as a dialog/popover container, it should be discoverable.
    // Allow either role=dialog or a landmark; when present, ensure buttons are within it.
    const dialog = screen.queryByRole('dialog');
    if (dialog) {
      expect(within(dialog).getByRole('button', { name: /cancel/i })).toBe(cancelButton);
      expect(within(dialog).getByRole('button', { name: /^delete$/i })).toBe(confirmButton);
    }
  });
});

