{"componentCode":"payment_card","componentName":"Payment Card","coveredBehaviors":["Renders a single selectable card container as a button with composed accessible label when card_aria_label not provided","Uses card_aria_label override for the card container accessible name when provided","Reflects selected state via aria-pressed=true/false","Invokes on_select with card identifier payload on click and on keyboard activation (Enter/Space)","Does not invoke on_select when disabled or when delete is pending","Renders masked card number showing only last4 (no full PAN)","Renders expiry as MM/YY and shows an 'Expired' indicator when is_expired=true","Renders inline delete error message when delete_error_message is provided","Coordinates delete control: clicking delete does not trigger selection; confirming delete triggers on_delete_confirm with card identifier payload; cancelling triggers on_delete_cancel (when provided)"],"coveredStates":["default (unselected, enabled)","selected","disabled (is_disabled=true)","delete pending (is_delete_pending=true disables selection)","expired (is_expired=true)","delete error (delete_error_message provided)"],"files":[{"filename":"/app/generated/frontend/src/components/PaymentCard/PaymentCard.spec.tsx","content":"import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { PaymentCard } from './PaymentCard';

// Mock child components to focus unit tests on PaymentCard behavior/coordination.
jest.mock('../CardBrandIcon/CardBrandIcon', () => ({
  CardBrandIcon: ({ brand, decorative }: { brand: string; decorative?: boolean }) => (
    <div data-testid="brand-icon" data-brand={brand} data-decorative={String(!!decorative)} />
  )
}));

jest.mock('../CardNumberMasked/CardNumberMasked', () => ({
  CardNumberMasked: ({ last4 }: { last4: string }) => (
    <span data-testid="masked-number">**** **** **** {last4}</span>
  )
}));

jest.mock('../CardExpiryDate/CardExpiryDate', () => ({
  CardExpiryDate: ({ expiry_month, expiry_year, is_expired }: { expiry_month: number; expiry_year: number; is_expired?: boolean }) => (
    <span data-testid="expiry" data-expired={String(!!is_expired)}>
      {String(expiry_month).padStart(2, '0')}/{String(expiry_year).slice(-2)}
      {is_expired ? ' Expired' : ''}
    </span>
  )
}));

jest.mock('../CardholderName/CardholderName', () => ({
  CardholderName: ({ cardholder_name }: { cardholder_name: string }) => (
    <span data-testid="cardholder">{cardholder_name}</span>
  )
}));

jest.mock('../DeleteCardAction/DeleteCardAction', () => ({
  DeleteCardAction: (props: any) => {
    const {
      card_id,
      last4,
      is_disabled,
      is_deleting,
      delete_error_message,
      on_delete_confirm,
      on_delete_confirmation_cancel,
      on_request_stop_selection_propagation
    } = props;

    const [open, setOpen] = React.useState(false);

    const openConfirm = (e: React.MouseEvent | React.KeyboardEvent) => {
      e.stopPropagation();
      on_request_stop_selection_propagation?.();
      if (is_disabled || is_deleting) return;
      setOpen(true);
    };

    const cancel = (e: React.MouseEvent) => {
      e.stopPropagation();
      setOpen(false);
      on_delete_confirmation_cancel?.({ card_id });
    };

    const confirm = (e: React.MouseEvent) => {
      e.stopPropagation();
      on_delete_confirm?.({ card_id });
    };

    return (
      <div>
        <button
          type="button"
          aria-label={`Delete card ending in ${last4}`}
          onClick={openConfirm}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') openConfirm(e);
          }}
          disabled={!!is_disabled || !!is_deleting}
        >
          Delete
        </button>
        {delete_error_message ? <div data-testid="delete-error">{delete_error_message}</div> : null}
        {open ? (
          <div role="dialog" aria-label={`Confirm delete card ending in ${last4}`}>
            <p>Delete card ending in {last4}?</p>
            <button type="button" onClick={cancel}>Cancel</button>
            <button type="button" onClick={confirm}>Delete</button>
          </div>
        ) : null}
      </div>
    );
  }
}));

function renderCard(overrides: Partial<React.ComponentProps<typeof PaymentCard>> = {}) {
  const props: React.ComponentProps<typeof PaymentCard> = {
    card_id: 'card_123',
    brand: 'visa',
    last4: '1234',
    expiry_month: '05',
    expiry_year: '27',
    cardholder_name: 'John Doe',
    is_selected: false,
