{"componentDescription":"Payment card component. Shows card number (masked: **** **** **** 1234), expiry date, cardholder name, card brand icon (Visa/Mastercard/Amex). Used in merchant dashboard to display saved payment methods. User can select a card or delete it.","e2eTests":{"coveredBehaviors":["Selecting a card from a composed list updates selected state (aria-pressed) on the targeted PaymentCard and clears it from others via parent state","Delete action is a distinct nested control that does not trigger parent card selection due to stopped event propagation","Delete confirmation opens and can be cancelled without crashing; cancelling returns the UI to its prior state and keeps focus stable","Async delete pending disables both card selection and delete action until resolution","Delete success removes the PaymentCard from the DOM and moves focus to the next card in the list (or fallback as available)","Delete failure keeps the card in the DOM, re-enables controls, and shows an inline error message; retry requires confirmation again and can succeed"],"coveredComponentCodes":["payment_card","delete_card_action","card_brand_icon","card_number_masked","card_expiry_date","cardholder_name"],"coveredFlowCodes":["select_card_shortest","delete_card_with_confirmation_shortest","explore_states_then_select_and_delete","delete_fails_then_retry_success"],"coveredStates":["list: one-selected (single selection in parent state)","payment_card: unselected","payment_card: selected (aria-pressed=true)","delete_confirmation_open","delete_pending (is_delete_pending=true disables selection+delete)","delete_error (delete_error_message rendered and controls re-enabled)"],"files":[{"filename":"/app/generated/frontend/src/components/PaymentCard/PaymentCard.e2e.spec.tsx","content":"import React from 'react';
import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { PaymentCard } from './PaymentCard';

type CardModel = {
  card_id: string;
  brand: string;
  last4: string;
  expiry_month: string;
  expiry_year: string;
  cardholder_name: string;
  is_expired?: boolean;
};

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function makeAriaLabel(card: CardModel) {
  const brandText = card.brand && card.brand !== 'unknown'
    ? card.brand.slice(0, 1).toUpperCase() + card.brand.slice(1)
    : 'Card';
  return `${brandText} card ending in ${card.last4}, expires ${card.expiry_month}/${card.expiry_year}, ${card.cardholder_name}`;
}

function PaymentMethodsHarness(props: {
  initialCards: CardModel[];
  initialSelectedId?: string;
  listAriaLabel?: string;
}) {
  const { initialCards, initialSelectedId, listAriaLabel = 'Saved payment methods' } = props;

  const [cards, setCards] = React.useState<CardModel[]>(initialCards);
  const [selectedId, setSelectedId] = React.useState<string | null>(initialSelectedId ?? null);
  const [deletePendingById, setDeletePendingById] = React.useState<Record<string, boolean>>({});
  const [deleteErrorById, setDeleteErrorById] = React.useState<Record<string, string | undefined>>({});

  const listRef = React.useRef<HTMLDivElement | null>(null);
  const deleteQueueRef = React.useRef<
    Record<string, Array<{ promise: Promise<void>; resolve: () => void; reject: (e?: unknown) => void }>>
  >({});

  const ensureQueue = (card_id: string) => {
    if (!deleteQueueRef.current[card_id]) deleteQueueRef.current[card_id] = [];
    return deleteQueueRef.current[card_id];
  };

  const onSelect = React.useCallback((payload: { card_id: string }) => {
    setSelectedId(payload.card_id);
  }, []);

  const onDeleteCancel = React.useCallback((payload: { card_id: string }) => {
    // No-op for harness; component should already close confirmation.
    // Keep for interface completeness.
    void payload;
  }, []);

  const onDeleteConfirm = React.useCallback((payload: { card_id: string }) => {
    const { card_id } = payload;

    setDeletePendingById((prev) => ({ ...prev, [card_id]: true }));

    // Create a deferred that the test can resolve/reject to simulate async behavior.
    const d = deferred<void>();
    const queue = ensureQueue(card_id);
    queue.push({ promise: d.promise, resolve: d.resolve, reject: d.reject });

    d.promise
      .then(() => {
        // simulate brief collapse/fade delay before DOM removal
        setTimeout(() => {
          setCards((prev) => prev.filter((c) => c.card_id !== card_id));
          setDeletePendingById((prev) => {
            const next = { ...prev };
            delete next[card_id];
            return next;
          });
          setDeleteErrorById((prev) => {
            const next = { ...prev };
            delete next[card_id];
            return next;
          });

          // Focus placement: next card, else previous, else list container
          setTimeout(() => {
            const remaining = (listRef.current?.querySelectorAll('button[aria-pressed]') ?? []) as NodeListOf<HTMLButtonElement>;
            // Choose first remaining card button by DOM order (acts as "next" in this harness).
            if (remaining.length > 0) {
              remaining[0].focus();
              return;
            }
            listRef.current?.focus();
          }, 0);
        }, 180);
      })
      .catch(() => {
        setDeletePendingById((prev) => ({ ...prev, [card_id]: false }));
        setDeleteErrorById((prev) => ({ ...prev, [card_id]: 'Could not delete this card. Try again.' }));
      })
      .finally(() => {
        setDeletePendingById((prev) => {
          const isPending = prev[card_id];
          if (isPending) return prev;
          const next = { ...prev };
          delete next[card_id];
          return next;
        });
      });
  }, []);

  const api = React.useMemo(() => {
    return {
      resolveDelete(card_id: string) {
        const queue = ensureQueue(card_id);
        const item = queue.shift();
        if (!item) throw new Error(`No pending delete request for ${card_id}`);
        item.resolve();
      },
      rejectDelete(card_id: string) {
        const queue = ensureQueue(card_id);
        const item = queue.shift();
        if (!item) throw new Error(`No pending delete request for ${card_id}`);
        item.reject(new Error('delete failed'));
      }
    };
  }, []);

  // Expose harness controls to tests via a global-ish handle on the DOM node.
  // This avoids inventing additional files while keeping the test self-contained.
  (globalThis as any).__paymentMethodsHarnessApi = api;

  return (
    <div>
      <div
        ref={listRef}
        role="region"
        aria-label={listAriaLabel}
        tabIndex={-1}
        data-testid="payment-methods-list"
      >
        {cards.map((c) => (
          <PaymentCard
            key={c.card_id}
            card_id={c.card_id}
            brand={c.brand}
            last4={c.last4}
            expiry_month={c.expiry_month}
            expiry_year={c.expiry_year}
            cardholder_name={c.cardholder_name}
            is_selected={selectedId === c.card_id}
            is_expired={c.is_expired}
            is_delete_pending={!!deletePendingById[c.card_id]}
            delete_error_message={deleteErrorById[c.card_id]}
            on_select={onSelect}
            on_delete_confirm={onDeleteConfirm}
            on_delete_cancel={onDeleteCancel}
          />
        ))}
      </div>
    </div>
  );
}

function getHarnessApi(): { resolveDelete: (card_id: string) => void; rejectDelete: (card_id: string) => void } {
  const api = (globalThis as any).__paymentMethodsHarnessApi;
  if (!api) throw new Error('Harness API not found');
  return api;
}

describe('PaymentCard composed workflow (e2e)', () => {
  test('select_card_shortest: clicking one card selects it and unselects the other (parent state propagation)', async () => {
    const user = userEvent.setup();

    const cards: CardModel[] = [
      {
        card_id: 'card_a',
        brand: 'visa',
        last4: '1111',
        expiry_month: '05',
        expiry_year: '27',
        cardholder_name: 'Jane Merchant'
      },
      {
        card_id: 'card_b',
        brand: 'mastercard',
        last4: '2222',
        expiry_month: '06',
        expiry_year: '28',
        cardholder_name: 'John Merchant'
      }
    ];

    render(<PaymentMethodsHarness initialCards={cards} initialSelectedId={null} />);

    const cardAButton = screen.getByRole('button', { name: makeAriaLabel(cards[0]) });
    const cardBButton = screen.getByRole('button', { name: makeAriaLabel(cards[1]) });

    expect(cardAButton).toHaveAttribute('aria-pressed', 'false');
    expect(cardBButton).toHaveAttribute('aria-pressed', 'false');

    await user.click(cardAButton);
    expect(cardAButton).toHaveAttribute('aria-pressed', 'true');
    expect(cardBButton).toHaveAttribute('aria-pressed', 'false');

    await user.click(cardBButton);
    expect(cardAButton).toHaveAttribute('aria-pressed', 'false');
    expect(cardBButton).toHaveAttribute('aria-pressed', 'true');

    // Ensure selection action did not open any delete confirmation UI.
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  });

  test('delete_card_with_confirmation_shortest: confirm delete -> pending disables selection+delete -> success removes card and moves focus', async () => {
    jest.useFakeTimers();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });

    const cards: CardModel[] = [
      {
        card_id: 'card_a',
        brand: 'visa',
        last4: '1111',
        expiry_month: '05',
        expiry_year: '27',
        cardholder_name: 'Jane Merchant'
      },
      {
        card_id: 'card_b',
        brand: 'amex',
        last4: '3333',
        expiry_month: '07',
        expiry_year: '29',
        cardholder_name: 'Sam Merchant'
      }
    ];

    render(<PaymentMethodsHarness initialCards={cards} initialSelectedId={null} />);

    const cardALabel = makeAriaLabel(cards[0]);
    const cardAButton = screen.getByRole('button', { name: cardALabel });

    // Open confirmation via delete button inside card A.
    const cardAContainer = cardAButton.closest('*');
    expect(cardAContainer).toBeTruthy();

    const deleteButton = screen.getByRole('button', { name: 'Delete card ending in 1111' });
    await user.click(deleteButton);

    // Confirmation should appear.
    expect(screen.getByRole('button', { name: /^delete$/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();

    // Confirm delete.
    await user.click(screen.getByRole('button', { name: /^delete$/i }));

    // Pending: selection disabled and delete disabled.
    // If PaymentCard uses a disabled button in pending, enforce it; otherwise at least ensure clicking doesn't change selection.
    expect(screen.getByRole('button', { name: cardALabel })).toHaveAttribute('aria-pressed', 'false');

    const deleteButtonAfterConfirm = screen.getByRole('button', { name: 'Delete card ending in 1111' });
    expect(deleteButtonAfterConfirm).toBeDisabled();

    await user.click(screen.getByRole('button', { name: cardALabel }));
    expect(screen.getByRole('button', { name: cardALabel })).toHaveAttribute('aria-pressed', 'false');

    // Resolve async deletion, then allow collapse/fade to complete.
    act(() => {
      getHarnessApi().resolveDelete('card_a');
    });

    // flush the 180ms removal + focus microtask
    act(() => {
      jest.advanceTimersByTime(250);
    });

    // Card A removed
    expect(screen.queryByRole('button', { name: cardALabel })).not.toBeInTheDocument();

    // Focus moves to next card's card button (first remaining).
    const cardBButton = screen.getByRole('button', { name: makeAriaLabel(cards[1]) });
    expect(cardBButton).toHaveFocus();

    jest.useRealTimers();
  });

  test('explore_states_then_select_and_delete: keyboard select + delete button focus + escape no-op + outside click cancels + reopen and delete', async () => {
    jest.useFakeTimers();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });

    const cards: CardModel[] = [
      {
        card_id: 'card_a',
        brand: 'visa',
        last4: '1111',
        expiry_month: '05',
        expiry_year: '27',
        cardholder_name: 'Jane Merchant'
      },
      {
        card_id: 'card_b',
        brand: 'unknown',
        last4: '9999',
        expiry_month: '12',
        expiry_year: '30',
        cardholder_name: 'Fallback Brand'
      }
    ];

    render(<PaymentMethodsHarness initialCards={cards} initialSelectedId={null} />);

    // Tab to first focusable: the card container button.
    await user.tab();
    const cardAButton = screen.getByRole('button', { name: makeAriaLabel(cards[0]) });
    expect(cardAButton).toHaveFocus();

    // Space selects it.
    await user.keyboard(' ');
    expect(cardAButton).toHaveAttribute('aria-pressed', 'true');
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();

    // Tab moves to delete inside same card.
    await user.tab();
    const deleteButton = screen.getByRole('button', { name: 'Delete card ending in 1111' });
    expect(deleteButton).toHaveFocus();

    // Escape without confirmation open: no-op.
    await user.keyboard('{Escape}');
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
    expect(deleteButton).toHaveFocus();
    expect(cardAButton).toHaveAttribute('aria-pressed', 'true');

    // Enter opens confirmation.
    await user.keyboard('{Enter}');
    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^delete$/i })).toBeInTheDocument();

    // Click outside closes; focus returns to delete.
    await user.click(document.body);
    expect(screen.queryByRole('button', { name: /cancel/i })).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Delete card ending in 1111' })).toHaveFocus();

    // Reopen and confirm delete.
    await user.keyboard('{Enter}');
    await user.click(screen.getByRole('button', { name: /^delete$/i }));

    // Resolve and flush.
    act(() => {
      getHarnessApi().resolveDelete('card_a');
    });
    act(() => {
      jest.advanceTimersByTime(250);
    });

    // Focus should go to remaining card (unknown brand uses "Card" in label).
    const cardBButton = screen.getByRole('button', { name: makeAriaLabel(cards[1]) });
    expect(cardBButton).toHaveFocus();

    jest.useRealTimers();
  });

  test('delete_fails_then_retry_success: first delete fails -> inline error -> retry requires confirmation again -> success removes card', async () => {
    jest.useFakeTimers();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });

    const cards: CardModel[] = [
      {
        card_id: 'card_a',
        brand: 'visa',
        last4: '1111',
        expiry_month: '05',
        expiry_year: '27',
        cardholder_name: 'Jane Merchant'
      },
      {
        card_id: 'card_b',
        brand: 'mastercard',
        last4: '2222',
        expiry_month: '06',
        expiry_year: '28',
        cardholder_name: 'John Merchant'
      }
    ];

    render(<PaymentMethodsHarness initialCards={cards} initialSelectedId={null} />);

    const cardALabel = makeAriaLabel(cards[0]);

    // Open confirm and submit delete.
    await user.click(screen.getByRole('button', { name: 'Delete card ending in 1111' }));
    await user.click(screen.getByRole('button', { name: /^delete$/i }));

    // Fail it.
    act(() => {
      getHarnessApi().rejectDelete('card_a');
    });

    // Let state settle.
    await act(async () => {
      // allow promise chain to run
    });

    // Card remains and error visible.
    expect(screen.getByRole('button', { name: cardALabel })).toBeInTheDocument();
    expect(screen.getByText('Could not delete this card. Try again.')).toBeInTheDocument();

    // Controls re-enabled: delete button clickable again.
    const deleteButton = screen.getByRole('button', { name: 'Delete card ending in 1111' });
    expect(deleteButton).toBeEnabled();

    // Retry requires confirmation again.
    await user.click(deleteButton);
    expect(screen.getByRole('button', { name: /cancel/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^delete$/i })).toBeInTheDocument();

    await user.click(screen.getByRole('button', { name: /^delete$/i }));

    // Succeed retry.
    act(() => {
      getHarnessApi().resolveDelete('card_a');
    });
    act(() => {
      jest.advanceTimersByTime(250);
    });

    // Card A removed; error gone with it.
    expect(screen.queryByRole('button', { name: cardALabel })).not.toBeInTheDocument();
    expect(screen.queryByText('Could not delete this card. Try again.')).not.toBeInTheDocument();

    // Focus to remaining card.
    expect(screen.getByRole('button', { name: makeAriaLabel(cards[1]) })).toHaveFocus();

    jest.useRealTimers();
  });
});
