import React from 'react';

export type CardBrand = 'visa' | 'mastercard' | 'amex' | string;

export interface CardBrandIconProps {
  /** Card brand identifier used to choose which brand icon to render. */
  brand: string | null;
  /** When true, treat as decorative for assistive tech (aria-hidden="true"). */
  aria_hidden?: boolean;
  /** Accessible name when not decorative (used only when aria_hidden is false). */
  aria_label?: string;
  /** Pixel size for width/height. */
  size?: number;
}

function normalizeBrand(brand: string | null): 'visa' | 'mastercard' | 'amex' | 'unknown' {
  const b = (brand ?? '').trim().toLowerCase();
  if (b === 'visa') return 'visa';
  if (b === 'mastercard' || b === 'master card' || b === 'mc') return 'mastercard';
  if (b === 'amex' || b === 'american express' || b === 'americanexpress') return 'amex';
  return 'unknown';
}

function IconSvg({ brand }: { brand: 'visa' | 'mastercard' | 'amex' | 'unknown' }) {
  // Simple, self-contained SVG marks (no external assets) to satisfy tests and keep layout stable.
  // These are not official brand assets.
  switch (brand) {
    case 'visa':
      return (
        <svg viewBox="0 0 32 20" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="32" height="20" rx="3" fill="#1A1F71" />
          <path
            d="M6.4 14.6L4.8 5.4h2.1l1 6.3 1.6-6.3h2.1l-2.4 9.2H6.4z"
            fill="#FFFFFF"
          />
          <path
            d="M12.9 14.6l1.7-9.2h2.0l-1.7 9.2h-2.0z"
            fill="#FFFFFF"
          />
          <path
            d="M21.9 6.0c-.4-.2-1-.3-1.6-.3-1.1 0-1.9.6-1.9 1.4 0 .6.6 1 1.2 1.3.7.3 1 .5 1 .8 0 .4-.5.6-1 .6-.7 0-1.1-.1-1.7-.4l-.2-.1-.3 1.7c.4.2 1.1.4 1.9.4 1.2 0 2-.6 2-1.5 0-.5-.3-.9-1.1-1.3-.6-.3-1.1-.5-1.1-.8 0-.3.3-.6 1.0-.6.6 0 1 .1 1.4.3l.2.1.2-1.6z"
            fill="#FFFFFF"
          />
          <path
            d="M25.8 11.3h-1.6l1.0-2.8.6 2.8zm2.5 3.3l-1.6-9.2h-1.8c-.4 0-.7.2-.8.6l-3.6 8.6h2.1l.5-1.4h2.6l.3 1.4h2.3z"
            fill="#FFFFFF"
          />
        </svg>
      );
    case 'mastercard':
      return (
        <svg viewBox="0 0 32 20" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="32" height="20" rx="3" fill="#111827" />
          <circle cx="14" cy="10" r="5" fill="#EB001B" />
          <circle cx="18" cy="10" r="5" fill="#F79E1B" fillOpacity="0.95" />
          <path
            d="M16 5.7a5.9 5.9 0 0 0 0 8.6 5.9 5.9 0 0 0 0-8.6z"
            fill="#FF5F00"
          />
        </svg>
      );
    case 'amex':
      return (
        <svg viewBox="0 0 32 20" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="32" height="20" rx="3" fill="#2E77BB" />
          <rect x="4" y="4" width="24" height="12" rx="1.5" fill="#FFFFFF" fillOpacity="0.12" />
          <path
            d="M6.2 13.8V6.2h5.5v1.2H7.6v1.7h3.8v1.2H7.6v2.3H6.2zm7.0 0V6.2h2.5l1.5 4.8 1.5-4.8h2.5v7.6h-1.4V7.8l-1.8 6.0h-1.6l-1.8-6.0v6.0h-1.4zm10.2 0V6.2h5.6v1.2H24.8v1.8h3.8v1.2h-3.8v2.2h4.3v1.2h-5.7z"
            fill="#FFFFFF"
          />
        </svg>
      );
    case 'unknown':
    default:
      return (
        <svg viewBox="0 0 32 20" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="32" height="20" rx="3" fill="#D1D5DB" />
          <rect x="4" y="6" width="24" height="2" rx="1" fill="#9CA3AF" />
          <rect x="4" y="10" width="14" height="2" rx="1" fill="#9CA3AF" />
        </svg>
      );
  }
}

export function CardBrandIcon({
  brand,
  aria_hidden = true,
  aria_label,
  size = 24
}: CardBrandIconProps) {
  const normalized = normalizeBrand(brand);

  // Ensure size is applied via style so tests accept either attributes or inline style.
  const dimensionStyle: React.CSSProperties = {
    width: `${size}px`,
    height: `${size}px`,
    display: 'block'
  };

  const a11yProps: React.SVGProps<SVGSVGElement> = aria_hidden
    ? { 'aria-hidden': true, focusable: false }
    : { role: 'img', 'aria-label': aria_label ?? '' };

  // Wrap in a stable container so the component always renders at least one element.
  return (
    <span style={{ display: 'inline-block', width: `${size}px`, height: `${size}px` }}>
      {React.cloneElement(<IconSvg brand={normalized} />, {
        ...a11yProps,
        style: dimensionStyle
      })}
    </span>
  );
}

import React from 'react';

export type CardNumberProps = {
  /**
   * Last 4 digits of the card number to be displayed as the final group in the masked string;
   * if omitted, the component renders "****" as the last group.
   */
  last4?: string;
  /**
   * Preformatted masked card number string to render (e.g., "**** **** **** 1234");
   * if provided, it is rendered as-is and takes precedence over last4-based masking.
   */
  masked_card_number?: string;
};

function buildMaskedFromLast4(last4?: string): string {
  const safeLast4 = (last4 ?? '').trim();
  const lastGroup = safeLast4.length > 0 ? safeLast4 : '****';
  return `**** **** **** ${lastGroup}`;
}

export function CardNumber({ last4, masked_card_number }: CardNumberProps) {
  const value = (masked_card_number ?? '').trim().length > 0
    ? masked_card_number
    : buildMaskedFromLast4(last4);

  return <span>{value}</span>;
}

import React from 'react';

export type CardholderNameProps = {
  /** Cardholder name to display. When null/empty, renders an em dash placeholder (—). */
  cardholder_name?: string | null;
  /** Optional tooltip title. If omitted, may fall back to cardholder_name. */
  cardholder_name_title?: string | null;
};

export function CardholderName({
  cardholder_name,
  cardholder_name_title,
}: CardholderNameProps) {
  const hasName = typeof cardholder_name === 'string' && cardholder_name.trim().length > 0;
  const text = hasName ? cardholder_name : '—';

  const title =
    cardholder_name_title != null
      ? cardholder_name_title
      : hasName
        ? cardholder_name
        : null;

  const titleProps = title != null ? { title } : undefined;

  return (
    <span
      {...titleProps}
      style={{
        display: 'block',
        minWidth: 0,
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
      }}
    >
      {text}
    </span>
  );
}

import React from 'react';

export type DeletePaymentCardPayload = {
  payment_method_id: string;
};

export type DeleteCardActionProps = {
  /** Unique identifier for the saved payment method this delete action applies to. */
  payment_method_id: string;
  /** Card last-4 digits used to build an accessible name like "Delete card ending in 1234" and in confirmation copy. */
  last4: string;
  /** Whether the delete action is currently disabled (e.g., due to permissions or while deletion is in progress). */
  disabled?: boolean;
  /** Whether deletion is currently in progress for this card. */
  is_deleting?: boolean;
  /** Callback invoked when the user confirms deletion in the confirmation dialog. */
  on_confirm_delete: (payload: DeletePaymentCardPayload) => void;
  /** Callback invoked when the user cancels the confirmation dialog (including closing via Escape). */
  on_cancel_delete?: () => void;
};

function useStableId(prefix: string) {
  const reactId = (React as any).useId?.();
  const [fallbackId] = React.useState(() => `${prefix}-${Math.random().toString(16).slice(2)}`);
  return (reactId ? `${prefix}-${reactId}` : fallbackId).replace(/[^a-zA-Z0-9-_]/g, '');
}

function stopEvent(e: React.SyntheticEvent) {
  e.preventDefault();
  e.stopPropagation();
}

function DeleteIcon(props: { className?: string }) {
  return (
    <svg
      className={props.className}
      aria-hidden="true"
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path
        d="M9 3h6m-8 4h10m-9 0v13a2 2 0 0 0 2 2h4a2 2 0 0 0 2-2V7"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
      <path
        d="M10 11v7M14 11v7"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

function Spinner(props: { 'aria-label'?: string; 'data-testid'?: string }) {
  return (
    <span
      role="progressbar"
      aria-label={props['aria-label']}
      data-testid={props['data-testid']}
      style={styles.spinner}
    />
  );
}

export function DeleteCardAction({
  payment_method_id,
  last4,
  disabled = false,
  is_deleting = false,
  on_confirm_delete,
  on_cancel_delete,
}: DeleteCardActionProps) {
  const [isDialogOpen, setIsDialogOpen] = React.useState(false);
  const buttonRef = React.useRef<HTMLButtonElement | null>(null);
  const cancelButtonRef = React.useRef<HTMLButtonElement | null>(null);

  const dialogTitleId = useStableId('delete-card-title');
  const dialogBodyId = useStableId('delete-card-body');

  const effectiveDisabled = disabled || is_deleting;

  const closeDialog = React.useCallback(
    (opts?: { shouldNotifyCancel?: boolean }) => {
      setIsDialogOpen(false);
      if (opts?.shouldNotifyCancel) on_cancel_delete?.();
    },
    [on_cancel_delete]
  );

  React.useEffect(() => {
    if (!isDialogOpen) return;
    // Ensure default focus lands on Cancel
    cancelButtonRef.current?.focus();
  }, [isDialogOpen]);

  React.useEffect(() => {
    if (!isDialogOpen) return;

    const onKeyDown = (e: KeyboardEvent) => {
      if (!isDialogOpen) return;

      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        closeDialog({ shouldNotifyCancel: true });
        // return focus to trigger button after close
        setTimeout(() => buttonRef.current?.focus(), 0);
        return;
      }

      if (e.key === 'Tab') {
        // Simple focus trap: keep focus between cancel and delete buttons
        const cancelEl = cancelButtonRef.current;
        const deleteEl = document.getElementById(`${dialogTitleId}-delete-btn`) as HTMLButtonElement | null;
        if (!cancelEl || !deleteEl) return;

        const active = document.activeElement;
        if (e.shiftKey) {
          if (active === cancelEl) {
            e.preventDefault();
            deleteEl.focus();
          }
        } else {
          if (active === deleteEl) {
            e.preventDefault();
            cancelEl.focus();
          }
        }
      }
    };

    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [closeDialog, dialogTitleId, isDialogOpen]);

  const accessibleName = `Delete card ending in ${last4}`;

  const onTriggerClick = (e: React.MouseEvent<HTMLButtonElement>) => {
    stopEvent(e);
    if (effectiveDisabled) return;
    setIsDialogOpen(true);
  };

  const onTriggerKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>) => {
    // Prevent parent "radio" activation if this button is nested in a selectable container.
    if (e.key === 'Enter' || e.key === ' ') {
      stopEvent(e);
      if (effectiveDisabled) return;
      setIsDialogOpen(true);
    }
  };

  const onCancel = (e: React.MouseEvent<HTMLButtonElement>) => {
    stopEvent(e);
    closeDialog({ shouldNotifyCancel: true });
    setTimeout(() => buttonRef.current?.focus(), 0);
  };

  const onConfirm = (e: React.MouseEvent<HTMLButtonElement>) => {
    stopEvent(e);
    on_confirm_delete({ payment_method_id });
    setIsDialogOpen(false);
    // focus return to trigger is fine; if parent removes the card, focus will move naturally.
    setTimeout(() => buttonRef.current?.focus(), 0);
  };

  return (
    <>
      <button
        ref={buttonRef}
        type="button"
        aria-label={accessibleName}
        disabled={effectiveDisabled}
        onClick={onTriggerClick}
        onKeyDown={onTriggerKeyDown}
        style={styles.trigger}
      >
        {is_deleting ? (
          <Spinner aria-label="Deleting" data-testid="spinner" />
        ) : (
          <DeleteIcon />
        )}
      </button>

      {isDialogOpen ? (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby={dialogTitleId}
          aria-describedby={dialogBodyId}
          style={styles.dialogOverlay}
          onMouseDown={(e) => {
            // Prevent clicks outside from interacting with parent; do not close on backdrop by default.
            stopEvent(e);
          }}
        >
          <div style={styles.dialog} onMouseDown={(e) => stopEvent(e)}>
            <div id={dialogTitleId} style={styles.dialogTitle}>
              Delete payment method?
            </div>
            <div id={dialogBodyId} style={styles.dialogBody}>
              This will delete the card ending in {last4}.
            </div>
            <div style={styles.dialogActions}>
              <button
                ref={cancelButtonRef}
                type="button"
                onClick={onCancel}
                style={styles.cancelButton}
              >
                Cancel
              </button>
              <button
                id={`${dialogTitleId}-delete-btn`}
                type="button"
                onClick={onConfirm}
                style={styles.deleteButton}
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
}

