// Keyframes are injected once; colocated to avoid adding extra files.
const injected = { current: false };
function injectKeyframes() {
  if (injected.current) return;
  if (typeof document === 'undefined') return;
  const style = document.createElement('style');
  style.setAttribute('data-delete-card-action', '');
  style.textContent = `@keyframes dca-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`;
  document.head.appendChild(style);
  injected.current = true;
}

// Inject on module eval in browser
injectKeyframes();

