  return (
    <div>
      {/* Parent-level radiogroup wrapper per integration decision */}
      <div role="radiogroup" aria-label="Saved payment methods">
        {cards.map((card) => (
          <PaymentCard
            key={card.card_id}
            card_id={card.card_id}
            brand={card.brand}
            last4={card.last4}
            expiry_month={card.expiry_month}
            expiry_year={card.expiry_year}
            cardholder_name={card.cardholder_name}
            is_selected={selectedId === card.card_id}
            tab_index={selectedId === card.card_id ? 0 : -1}
            is_disabled={false}
            is_deleting={deletingId === card.card_id}
            delete_error_message={deleteErrorById[card.card_id]}
            on_select={onSelect}
            on_confirm_delete={onConfirmDelete}
            on_cancel_delete={onCancelDelete}
          />
        ))}
      </div>

      {/* Parent-level live region to assert announcements without depending on internal DOM structure */}
      <div aria-live="polite" aria-atomic="true" data-testid="app-live-region" style={{ position: 'absolute', left: -9999 }}>
        {liveMessage}
      </div>

      {/* Debug state for assertions */}
      <output data-testid="selected-id">{selectedId}</output>
    </div>
  );
}

function getRadioByCardId(card_id: string) {
  // The component is expected to render role="radio". Prefer scoping by containing text when possible,
  // but fall back to selecting by index when only one is present.
  const radios = screen.getAllByRole('radio');
  const match = radios.find((r) => {
    // Many implementations include the masked PAN or last4 in the label; also allow data attributes.
    const text = (r as HTMLElement).textContent ?? '';
    return text.includes(card_id);
  });
  return match ?? radios[0];
}

function getDeleteButtonForLast4(last4: string) {
  return screen.getByRole('button', { name: `Delete card ending in ${last4}` });
}

