    expect(props.on_confirm_delete).toHaveBeenCalledWith({ payment_method_id: 'pm_abc' });
  });

  test('when deleting, selection is disabled and delete action is disabled', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({ is_deleting: true });

    const radio = screen.getByRole('radio');
    expect(radio).toHaveAttribute('aria-disabled', 'true');

    const deleteBtn = screen.getByRole('button', { name: /Delete card ending in/i });
    expect(deleteBtn).toBeDisabled();

    await user.click(radio);
    radio.focus();
    await user.keyboard('{Space}');

    expect(props.on_select).not.toHaveBeenCalled();
  });

  test('renders delete error message and exposes it via an aria-live polite region', () => {
    renderSubject({ delete_error_message: 'Delete failed. Try again.' });

    expect(screen.getByText('Delete failed. Try again.')).toBeInTheDocument();

    const live = screen.getByText('Delete failed. Try again.').closest('[aria-live="polite"]');
    expect(live).toBeTruthy();
  });

  test('renders placeholders via children when optional data missing', () => {
    renderSubject({ brand: undefined, last4: undefined, expiry_month: undefined, expiry_year: undefined, cardholder_name: undefined });

    // Brand icon still renders in a neutral state (layout stability)
    expect(screen.getByTestId('brand-icon')).toBeInTheDocument();

    // Child mocks implement placeholder behaviors expected upstream.
    expect(screen.getByTestId('card-number')).toHaveTextContent('**** **** **** ****');
    expect(screen.getByTestId('expiry')).toHaveTextContent('—');
    expect(screen.getByTestId('cardholder')).toHaveTextContent('—');
  });
});

