function renderSubject(overrides: Partial<React.ComponentProps<typeof PaymentCard>> = {}) {
  const props: React.ComponentProps<typeof PaymentCard> = {
    card_id: 'pm_123',
    brand: 'visa',
    last4: '1234',
    expiry_month: '04',
    expiry_year: '27',
    cardholder_name: 'Ada Lovelace',
    is_selected: false,
    tab_index: 0,
    is_disabled: false,
    is_deleting: false,
    delete_error_message: undefined,
    on_select: jest.fn(),
    on_confirm_delete: jest.fn(),
    on_cancel_delete: jest.fn(),
    ...overrides,
  };

  const view = render(<PaymentCard {...props} />);
  return { props, ...view };
}

describe('PaymentCard', () => {
  test('renders as a radio with aria-checked and tabIndex; shows masked number, expiry, and cardholder', () => {
    renderSubject({ is_selected: true, tab_index: -1 });

    const radio = screen.getByRole('radio');
    expect(radio).toHaveAttribute('aria-checked', 'true');
    expect(radio).toHaveAttribute('tabindex', '-1');

    expect(screen.getByTestId('brand-icon')).toHaveAttribute('data-brand', 'visa');
    expect(screen.getByTestId('card-number')).toHaveTextContent('**** **** **** 1234');
    expect(screen.getByTestId('expiry')).toHaveTextContent('04/27');
    expect(screen.getByTestId('cardholder')).toHaveTextContent('Ada Lovelace');

    // Tooltip/title behavior is delegated to CardholderName; ensure it receives a usable title.
    expect(screen.getByTestId('cardholder')).toHaveAttribute('title', 'Ada Lovelace');
  });

  test('clicking card container triggers on_select with card_id payload', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({ is_selected: false });

    await user.click(screen.getByRole('radio'));

    expect(props.on_select).toHaveBeenCalledTimes(1);
    expect(props.on_select).toHaveBeenCalledWith({ card_id: 'pm_123' });
  });

  test('Space and Enter activate selection (keyboard)', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject();

    const radio = screen.getByRole('radio');
    radio.focus();

    await user.keyboard('{Space}');
    await user.keyboard('{Enter}');

    expect(props.on_select).toHaveBeenCalledTimes(2);
    expect(props.on_select).toHaveBeenNthCalledWith(1, { card_id: 'pm_123' });
    expect(props.on_select).toHaveBeenNthCalledWith(2, { card_id: 'pm_123' });
  });

  test('when disabled, sets aria-disabled and does not call on_select', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({ is_disabled: true });

    const radio = screen.getByRole('radio');
    expect(radio).toHaveAttribute('aria-disabled', 'true');

    await user.click(radio);
    radio.focus();
    await user.keyboard('{Enter}');

    expect(props.on_select).not.toHaveBeenCalled();
  });

  test('clicking delete does not select the card and calls on_confirm_delete with payment_method_id', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({ card_id: 'pm_abc', last4: '9999' });

    const deleteBtn = screen.getByRole('button', { name: 'Delete card ending in 9999' });
    await user.click(deleteBtn);

    expect(props.on_select).not.toHaveBeenCalled();
    expect(props.on_confirm_delete).toHaveBeenCalledTimes(1);
    expect(props.on_confirm_delete).toHaveBeenCalledWith({ payment_method_id: 'pm_abc' });
  });

  test('when deleting, selection is disabled and delete action is disabled', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({ is_deleting: true });

    const radio = screen.getByRole('radio');
    expect(radio).toHaveAttribute('aria-disabled', 'true');

    const deleteBtn = screen.getByRole('button', { name: /Delete card ending in/i });
    expect(deleteBtn).toBeDisabled();

    await user.click(radio);
    radio.focus();
    await user.keyboard('{Space}');

    expect(props.on_select).not.toHaveBeenCalled();
  });

  test('renders delete error message and exposes it via an aria-live polite region', () => {
    renderSubject({ delete_error_message: 'Delete failed. Try again.' });

    expect(screen.getByText('Delete failed. Try again.')).toBeInTheDocument();

    const live = screen.getByText('Delete failed. Try again.').closest('[aria-live="polite"]');
    expect(live).toBeTruthy();
  });

  test('renders placeholders via children when optional data missing', () => {
    renderSubject({ brand: undefined, last4: undefined, expiry_month: undefined, expiry_year: undefined, cardholder_name: undefined });

    // Brand icon still renders in a neutral state (layout stability)
    expect(screen.getByTestId('brand-icon')).toBeInTheDocument();

    // Child mocks implement placeholder behaviors expected upstream.
    expect(screen.getByTestId('card-number')).toHaveTextContent('**** **** **** ****');
    expect(screen.getByTestId('expiry')).toHaveTextContent('—');
    expect(screen.getByTestId('cardholder')).toHaveTextContent('—');
  });
});
