export type CardBrand = 'visa' | 'mastercard' | 'amex' | string;

export interface CardBrandIconProps {
  /** Card brand identifier used to choose which brand icon to render. */
  brand: string | null;
  /** When true, treat as decorative for assistive tech (aria-hidden="true"). */
  aria_hidden?: boolean;
  /** Accessible name when not decorative (used only when aria_hidden is false). */
  aria_label?: string;
  /** Pixel size for width/height. */
  size?: number;
}

function normalizeBrand(brand: string | null): 'visa' | 'mastercard' | 'amex' | 'unknown' {
