export type DeletePaymentCardPayload = {
  payment_method_id: string;
};

export type DeleteCardActionProps = {
  payment_method_id: string;
  last4: string;
  disabled?: boolean;
  is_deleting?: boolean;
  on_confirm_delete: (payload: DeletePaymentCardPayload) => void;
  on_cancel_delete?: () => void;
};

export function DeleteCardAction({
  payment_method_id,
  last4,
  disabled = false,
  is_deleting = false,
  on_confirm_delete,
  on_cancel_delete,
}: DeleteCardActionProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const triggerBtnRef = useRef<HTMLButtonElement | null>(null);
  const cancelBtnRef = useRef<HTMLButtonElement | null>(null);
  const dialogRef = useRef<HTMLDivElement | null>(null);

  const internalReactId = useId();
  const titleId = `delete-card-action-title-${internalReactId}`;
  const bodyId = `delete-card-action-body-${internalReactId}`;

  const isButtonDisabled = disabled || is_deleting;
  const accessibleName = useMemo(() => `Delete card ending in ${last4}`, [last4]);

  function openDialog(e: React.SyntheticEvent) {
    // Prevent parent card selection.
    e.preventDefault();
    e.stopPropagation();
    if (isButtonDisabled) return;
    setIsDialogOpen(true);
  }

  function closeDialog(reason: 'cancel' | 'confirm') {
    setIsDialogOpen(false);
    if (reason === 'cancel') {
      on_cancel_delete?.();
    }
  }

  function onConfirm(e: React.SyntheticEvent) {
    e.preventDefault();
    e.stopPropagation();
    on_confirm_delete({ payment_method_id });
    closeDialog('confirm');
  }

  function onCancel(e?: React.SyntheticEvent) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    closeDialog('cancel');
  }

  useEffect(() => {
    if (!isDialogOpen) return;

    // Default focus goes to Cancel.
    cancelBtnRef.current?.focus();

    const onKeyDown = (ev: KeyboardEvent) => {
      if (!isDialogOpen) return;

      if (ev.key === 'Escape') {
        ev.preventDefault();
        onCancel();
        return;
      }

      // Simple focus trap for Tab navigation.
      if (ev.key === 'Tab') {
        const root = dialogRef.current;
        if (!root) return;

        const focusables = Array.from(
          root.querySelectorAll<HTMLElement>(
            'button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])'
          )
        ).filter((el) => !el.hasAttribute('disabled') && el.tabIndex !== -1);

        if (focusables.length === 0) return;

        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        const active = document.activeElement as HTMLElement | null;

        if (ev.shiftKey) {
          if (!active || active === first) {
            ev.preventDefault();
            last.focus();
          }
        } else {
          if (active === last) {
            ev.preventDefault();
            first.focus();
          }
        }
      }
    };

    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [isDialogOpen]);

  useEffect(() => {
    if (isDialogOpen) return;
    // Restore focus to trigger after close.
    triggerBtnRef.current?.focus();
  }, [isDialogOpen]);

  return (
    <>
      <button
        ref={triggerBtnRef}
        type="button"
        aria-label={accessibleName}
        disabled={isButtonDisabled}
        onClick={openDialog}
        onMouseDown={(e) => {
          // Prevent mouse down from shifting focus to parent containers.
          e.stopPropagation();
        }}
        style={styles.iconButton}
      >
        {is_deleting ? (
          <Spinner ariaLabel="Deleting" />
        ) : (
          <TrashIcon />
        )}
      </button>

      {isDialogOpen ? (
        <div
          aria-hidden="false"
          style={styles.backdrop}
          onMouseDown={(e) => {
            // Prevent backdrop clicks from affecting underlying selectable card.
            e.preventDefault();
            e.stopPropagation();
          }}
        >
          <div
            ref={dialogRef}
            role="dialog"
            aria-modal="true"
            aria-labelledby={titleId}
            aria-describedby={bodyId}
            style={styles.dialog}
            onMouseDown={(e) => {
              e.stopPropagation();
            }}
          >
            <div style={styles.dialogHeader}>
              <div id={titleId} style={styles.dialogTitle}>
                Delete payment method?
              </div>
            </div>

            <div id={bodyId} style={styles.dialogBody}>
              This will remove the card ending in {last4}.
            </div>

            <div style={styles.dialogFooter}>
              <button
                ref={cancelBtnRef}
                type="button"
                onClick={onCancel}
                style={styles.cancelButton}
              >
                Cancel
              </button>
              <button type="button" onClick={onConfirm} style={styles.deleteButton}>
                Delete
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
}

function TrashIcon() {
