export function CardBrandIcon({
  brand,
  aria_hidden = true,
  aria_label,
  size = 24
}: CardBrandIconProps) {
  const normalized = normalizeBrand(brand);

  // Ensure size is applied via style so tests accept either attributes or inline style.
  const dimensionStyle: React.CSSProperties = {
    width: `${size}px`,
    height: `${size}px`,
    display: 'block'
  };

  const a11yProps: React.SVGProps<SVGSVGElement> = aria_hidden
    ? { 'aria-hidden': true, focusable: false }
    : { role: 'img', 'aria-label': aria_label ?? '' };

  // Wrap in a stable container so the component always renders at least one element.
  return (
    <span style={{ display: 'inline-block', width: `${size}px`, height: `${size}px` }}>
      {React.cloneElement(<IconSvg brand={normalized} />, {
        ...a11yProps,
        style: dimensionStyle
      })}
    </span>
  );
}
"},{"filename":"/app/generated/frontend/src/components/CardNumber/CardNumber.tsx","content":"import React from 'react';

export type CardNumberProps = {
  /**
   * Last 4 digits of the card number to be displayed as the final group in the masked string;
   * if omitted, the component renders "****" as the last group.
   */
  last4?: string;
  /**
   * Preformatted masked card number string to render (e.g., "**** **** **** 1234");
   * if provided, it is rendered as-is and takes precedence over last4-based masking.
   */
  masked_card_number?: string;
};

function buildMaskedFromLast4(last4?: string): string {
  const safeLast4 = (last4 ?? '').trim();
  const lastGroup = safeLast4.length > 0 ? safeLast4 : '****';
  return `**** **** **** ${lastGroup}`;
}

export function CardNumber({ last4, masked_card_number }: CardNumberProps) {
  const value = (masked_card_number ?? '').trim().length > 0
    ? masked_card_number
    : buildMaskedFromLast4(last4);

  return <span>{value}</span>;
}
"},{"filename":"/app/generated/frontend/src/components/CardholderName/CardholderName.tsx","content":"import React from 'react';

export type CardholderNameProps = {
  /** Cardholder name to display. When null/empty, renders an em dash placeholder (—). */
  cardholder_name?: string | null;
  /** Optional tooltip title. If omitted, may fall back to cardholder_name. */
  cardholder_name_title?: string | null;
};

export function CardholderName({
  cardholder_name,
  cardholder_name_title,
}: CardholderNameProps) {
  const hasName = typeof cardholder_name === 'string' && cardholder_name.trim().length > 0;
  const text = hasName ? cardholder_name : '—';

  const title =
    cardholder_name_title != null
      ? cardholder_name_title
      : hasName
        ? cardholder_name
        : null;

  const titleProps = title != null ? { title } : undefined;

  return (
    <span
      {...titleProps}
      style={{
        display: 'block',
        minWidth: 0,
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
      }}
    >
      {text}
    </span>
  );
}
"},{"filename":"/app/generated/frontend/src/components/DeleteCardAction/DeleteCardAction.tsx","content":"import React, { useEffect, useId, useMemo, useRef, useState } from 'react';

export type DeletePaymentCardPayload = {
  payment_method_id: string;
};

export type DeleteCardActionProps = {
  payment_method_id: string;
  last4: string;
  disabled?: boolean;
  is_deleting?: boolean;
  on_confirm_delete: (payload: DeletePaymentCardPayload) => void;
  on_cancel_delete?: () => void;
};

export function DeleteCardAction({
  payment_method_id,
  last4,
  disabled = false,
  is_deleting = false,
  on_confirm_delete,
  on_cancel_delete,
}: DeleteCardActionProps) {
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const triggerBtnRef = useRef<HTMLButtonElement | null>(null);
  const cancelBtnRef = useRef<HTMLButtonElement | null>(null);
  const dialogRef = useRef<HTMLDivElement | null>(null);

  const internalReactId = useId();
  const titleId = `delete-card-action-title-${internalReactId}`;
  const bodyId = `delete-card-action-body-${internalReactId}`;

  const isButtonDisabled = disabled || is_deleting;
  const accessibleName = useMemo(() => `Delete card ending in ${last4}`, [last4]);

  function openDialog(e: React.SyntheticEvent) {
    // Prevent parent card selection.
    e.preventDefault();
    e.stopPropagation();
    if (isButtonDisabled) return;
    setIsDialogOpen(true);
  }

  function closeDialog(reason: 'cancel' | 'confirm') {
    setIsDialogOpen(false);
    if (reason === 'cancel') {
      on_cancel_delete?.();
    }
  }

  function onConfirm(e: React.SyntheticEvent) {
    e.preventDefault();
    e.stopPropagation();
    on_confirm_delete({ payment_method_id });
    closeDialog('confirm');
  }

  function onCancel(e?: React.SyntheticEvent) {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    closeDialog('cancel');
  }

  useEffect(() => {
    if (!isDialogOpen) return;

    // Default focus goes to Cancel.
    cancelBtnRef.current?.focus();

    const onKeyDown = (ev: KeyboardEvent) => {
      if (!isDialogOpen) return;

      if (ev.key === 'Escape') {
        ev.preventDefault();
        onCancel();
        return;
      }

      // Simple focus trap for Tab navigation.
      if (ev.key === 'Tab') {
        const root = dialogRef.current;
        if (!root) return;

        const focusables = Array.from(
          root.querySelectorAll<HTMLElement>(
            'button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])'
          )
        ).filter((el) => !el.hasAttribute('disabled') && el.tabIndex !== -1);

        if (focusables.length === 0) return;

        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        const active = document.activeElement as HTMLElement | null;

        if (ev.shiftKey) {
          if (!active || active === first) {
            ev.preventDefault();
            last.focus();
          }
        } else {
          if (active === last) {
            ev.preventDefault();
            first.focus();
          }
        }
      }
    };

    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [isDialogOpen]);

  useEffect(() => {
    if (isDialogOpen) return;
    // Restore focus to trigger after close.
    triggerBtnRef.current?.focus();
  }, [isDialogOpen]);

  return (
    <>
      <button
        ref={triggerBtnRef}
        type="button"
        aria-label={accessibleName}
        disabled={isButtonDisabled}
        onClick={openDialog}
        onMouseDown={(e) => {
          // Prevent mouse down from shifting focus to parent containers.
          e.stopPropagation();
        }}
        style={styles.iconButton}
      >
        {is_deleting ? (
          <Spinner ariaLabel="Deleting" />
        ) : (
          <TrashIcon />
        )}
      </button>

      {isDialogOpen ? (
        <div
          aria-hidden="false"
          style={styles.backdrop}
          onMouseDown={(e) => {
            // Prevent backdrop clicks from affecting underlying selectable card.
            e.preventDefault();
            e.stopPropagation();
          }}
        >
          <div
            ref={dialogRef}
            role="dialog"
            aria-modal="true"
            aria-labelledby={titleId}
            aria-describedby={bodyId}
            style={styles.dialog}
            onMouseDown={(e) => {
              e.stopPropagation();
            }}
          >
            <div style={styles.dialogHeader}>
              <div id={titleId} style={styles.dialogTitle}>
                Delete payment method?
              </div>
            </div>

            <div id={bodyId} style={styles.dialogBody}>
              This will remove the card ending in {last4}.
            </div>

            <div style={styles.dialogFooter}>
              <button
                ref={cancelBtnRef}
                type="button"
                onClick={onCancel}
                style={styles.cancelButton}
              >
                Cancel
              </button>
              <button type="button" onClick={onConfirm} style={styles.deleteButton}>
                Delete
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
}

function TrashIcon() {
  return (
    <svg
      aria-hidden="true"
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      focusable="false"
    >
      <path
        d="M9 3h6m-8 4h10m-9 0l1 14h6l1-14M10 11v7m4-7v7"
        stroke="var(--color-text-secondary)"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function Spinner({ ariaLabel }: { ariaLabel: string }) {
  return (
    <span
      role="progressbar"
      aria-label={ariaLabel}
      data-testid="spinner"
      style={styles.spinner}
    />
  );
}

const styles: Record<string, React.CSSProperties> = {
  iconButton: {
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    minWidth: 44,
    minHeight: 44,
    padding: 'var(--spacing-8)',
    borderRadius: 'var(--radius-8)',
    border: `1px solid var(--color-border-subtle)`,
    background: 'var(--color-surface-default)',
    boxShadow: 'none',
    cursor: 'pointer',
  },
  backdrop: {
    position: 'fixed',
    inset: 0,
    background: 'rgba(17, 24, 39, 0.35)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 'var(--spacing-16)',
    zIndex: 1000,
  },
  dialog: {
    width: 'min(420px, 100%)',
    background: 'var(--color-surface-default)',
    border: `1px solid var(--color-border-subtle)`,
    borderRadius: 'var(--radius-12)',
    boxShadow: 'var(--shadow-sm)',
    padding: 'var(--spacing-16)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-body)',
  },
  dialogHeader: {
    marginBottom: 'var(--spacing-8)',
  },
  dialogTitle: {
    fontSize: 'var(--font-size-body)',
    fontWeight: 'var(--font-weight-medium)',
  },
  dialogBody: {
    marginBottom: 'var(--spacing-16)',
    color: 'var(--color-text-secondary)',
    fontSize: 'var(--font-size-body)',
  },
  dialogFooter: {
    display: 'flex',
    justifyContent: 'flex-end',
    gap: 'var(--spacing-8)',
  },
  cancelButton: {
    padding: 'var(--spacing-8) var(--spacing-12)',
    borderRadius: 'var(--radius-8)',
    border: `1px solid var(--color-border-subtle)`,
    background: 'var(--color-surface-muted)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-body)',
    cursor: 'pointer',
  },
  deleteButton: {
    padding: 'var(--spacing-8) var(--spacing-12)',
    borderRadius: 'var(--radius-8)',
    border: `1px solid var(--color-border-danger)`,
    background: 'var(--color-surface-default)',
    color: 'var(--color-status-danger)',
    fontSize: 'var(--font-size-body)',
    fontWeight: 'var(--font-weight-medium)',
    cursor: 'pointer',
  },
  spinner: {
    width: 18,
    height: 18,
    borderRadius: 999,
    border: '2px solid var(--color-border-subtle)',
    borderTopColor: 'var(--color-text-secondary)',
    boxSizing: 'border-box',
    display: 'inline-block',
    animation: 'deleteCardActionSpin 0.8s linear infinite',
  },
};

// Inline keyframes via stylesheet injection (kept local to this component file).
// This is minimal and avoids external CSS file dependencies.
const _styleTagId = 'delete-card-action-keyframes';
if (typeof document !== 'undefined' && !document.getElementById(_styleTagId)) {
  const style = document.createElement('style');
  style.id = _styleTagId;
  style.textContent = `@keyframes deleteCardActionSpin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }\n`;
  document.head.appendChild(style);
}
