"},{"filename":"/app/generated/frontend/src/components/PaymentCard/PaymentCard.tsx","content":"import React from 'react';

import { CardBrandIcon } from '../CardBrandIcon/CardBrandIcon';
import { CardNumber } from '../CardNumber/CardNumber';
import { ExpiryDate } from '../ExpiryDate/ExpiryDate';
import { CardholderName } from '../CardholderName/CardholderName';
import { DeleteCardAction } from '../DeleteCardAction/DeleteCardAction';

export type SelectPaymentCardPayload = { card_id: string };
export type DeletePaymentCardPayload = { payment_method_id: string };
export type CancelDeletePaymentCardPayload = { card_id: string };

export type PaymentCardProps = {
  card_id: string;
  brand?: string;
  last4?: string;
  expiry_month?: string;
  expiry_year?: string;
  cardholder_name?: string;
  is_selected: boolean;
  tab_index: number;
  is_disabled?: boolean;
  is_deleting?: boolean;
  delete_error_message?: string;
  on_select: (payload: SelectPaymentCardPayload) => void;
  on_confirm_delete: (payload: DeletePaymentCardPayload) => void;
  on_cancel_delete?: (payload: CancelDeletePaymentCardPayload) => void;
};

function brandToReadableLabel(brand?: string): string | null {
  if (!brand) return null;
  const b = brand.trim().toLowerCase();
  if (b === 'visa') return 'Visa';
  if (b === 'mastercard' || b === 'master card') return 'Mastercard';
  if (b === 'amex' || b === 'american express') return 'American Express';
  // Best-effort fallback: keep it readable.
  return brand;
}

function formatExpiryMMYY(expiry_month?: string, expiry_year?: string): string | null {
  if (!expiry_month || !expiry_year) return null;
  return `${expiry_month}/${expiry_year}`;
}

export function PaymentCard(props: PaymentCardProps) {
  const {
    card_id,
    brand,
    last4,
    expiry_month,
    expiry_year,
    cardholder_name,
    is_selected,
    tab_index,
    is_disabled = false,
    is_deleting = false,
    delete_error_message,
    on_select,
    on_confirm_delete,
    on_cancel_delete,
  } = props;

  const ariaDisabled = Boolean(is_disabled || is_deleting);

  const expiry_mm_yy = formatExpiryMMYY(expiry_month, expiry_year);
  const brandLabel = brandToReadableLabel(brand);

  const handleSelect = React.useCallback(() => {
    if (ariaDisabled) return;
    on_select({ card_id });
  }, [ariaDisabled, on_select, card_id]);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (ariaDisabled) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        on_select({ card_id });
      }
    },
    [ariaDisabled, on_select, card_id]
  );

  const handleCancelDelete = React.useCallback(() => {
    on_cancel_delete?.({ card_id });
  }, [on_cancel_delete, card_id]);

  const liveMessage = delete_error_message ? delete_error_message : '';

  return (
    <div
      role="radio"
      aria-checked={is_selected}
      aria-disabled={ariaDisabled ? 'true' : undefined}
      tabIndex={tab_index}
      className={[
        'pc_root',
        is_selected ? 'pc_selected' : '',
        ariaDisabled ? 'pc_disabled' : '',
        delete_error_message ? 'pc_hasError' : '',
      ]
        .filter(Boolean)
        .join(' ')}
      data-card-id={card_id}
      onClick={handleSelect}
      onKeyDown={handleKeyDown}
    >
      <div className="pc_layout">
        <div className="pc_left">
          <div className="pc_rowTop">
            <div className="pc_brandAndNumber">
              <CardBrandIcon brand={brand ?? null} aria_hidden={true} size={24} />
              {brandLabel ? <span className="pc_srOnly">{brandLabel}</span> : null}
              <CardNumber last4={last4} />
            </div>

            <div className="pc_actions">
              <DeleteCardAction
                payment_method_id={card_id}
                last4={last4 ?? '????'}
                disabled={ariaDisabled}
                is_deleting={is_deleting}
                on_confirm_delete={on_confirm_delete}
                on_cancel_delete={handleCancelDelete}
              />
            </div>
          </div>

          <div className="pc_rowBottom">
            <div className="pc_cardholder">
              <CardholderName
                cardholder_name={cardholder_name ?? null}
                cardholder_name_title={cardholder_name ?? null}
              />
            </div>
            <div className="pc_expiry">
              <ExpiryDate expiry_mm_yy={expiry_mm_yy} />
            </div>
          </div>
        </div>
      </div>

      {delete_error_message ? <div className="pc_error">{delete_error_message}</div> : null}

      {liveMessage ? (
        <div className="pc_srOnly" aria-live="polite" aria-atomic="true">
          {liveMessage}
        </div>
      ) : null}

      <style>{`
        .pc_root{
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border: 1px solid var(--color-border-subtle);
          border-radius: var(--radius-12);
          box-shadow: var(--shadow-sm);
          padding: var(--spacing-16);
          cursor: pointer;
          user-select: none;
          min-height: 44px;
        }

        .pc_root:hover{
          background: var(--color-surface-muted);
        }

        .pc_root:active{
          background: var(--color-surface-muted);
        }

        .pc_root:focus-visible{
          outline: 2px solid var(--color-text-primary);
          outline-offset: 2px;
        }

        .pc_selected{
          border-color: var(--color-text-primary);
          box-shadow: inset 0 0 0 2px var(--color-text-primary), var(--shadow-sm);
        }

        .pc_disabled{
          cursor: not-allowed;
          opacity: 0.7;
        }

        .pc_layout{
          display: block;
        }

        .pc_left{
          display: flex;
          flex-direction: column;
          gap: var(--spacing-12);
          min-width: 0;
        }

        .pc_rowTop{
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: var(--spacing-12);
          min-width: 0;
        }

        .pc_brandAndNumber{
          display: flex;
          align-items: center;
          gap: var(--spacing-8);
          min-width: 0;
          font-size: var(--font-size-body);
        }

        .pc_actions{
          display: flex;
          align-items: center;
          flex: 0 0 auto;
        }

        .pc_rowBottom{
          display: flex;
          align-items: baseline;
          justify-content: space-between;
          gap: var(--spacing-12);
          min-width: 0;
        }

        .pc_cardholder{
          min-width: 0;
          flex: 1 1 auto;
          color: var(--color-text-secondary);
          font-size: var(--font-size-label);
        }

        .pc_expiry{
          flex: 0 0 auto;
          color: var(--color-text-secondary);
          font-size: var(--font-size-label);
        }

        .pc_error{
          margin-top: var(--spacing-8);
          color: var(--color-status-danger);
          font-size: var(--font-size-label);
        }

        .pc_srOnly{
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }

        @media (max-width: 359px){
          .pc_rowTop{
            align-items: flex-start;
          }
        }
      `}</style>
    </div>
