import '@testing-library/jest-dom';

import { DeleteCardAction } from './DeleteCardAction';

type Props = React.ComponentProps<typeof DeleteCardAction>;

function renderSubject(overrides: Partial<Props> = {}) {
  const props: Props = {
    payment_method_id: 'pm_123',
    last4: '1234',
    on_confirm_delete: jest.fn(),
    on_cancel_delete: jest.fn(),
    ...overrides,
  };

  const user = userEvent.setup();
  const view = render(<DeleteCardAction {...props} />);
  return { ...view, user, props };
}

describe('DeleteCardAction', () => {
  it('renders an accessible icon-only delete button with label including last4', () => {
    renderSubject({ last4: '4242' });

    // Accessible name requirement: "Delete card ending in 4242"
    const btn = screen.getByRole('button', { name: 'Delete card ending in 4242' });
    expect(btn).toBeInTheDocument();
    expect(btn).toHaveAttribute('type', 'button');
  });

  it('opens confirmation dialog on click and focuses Cancel by default', async () => {
    const { user } = renderSubject({ last4: '1111' });

    await user.click(screen.getByRole('button', { name: 'Delete card ending in 1111' }));

    const dialog = screen.getByRole('dialog');
    expect(within(dialog).getByText('Delete payment method?')).toBeInTheDocument();

    // Body should reference last4
    expect(within(dialog).getByText(/1111/)).toBeInTheDocument();

    const cancel = within(dialog).getByRole('button', { name: 'Cancel' });
    expect(cancel).toHaveFocus();

    // Destructive action present
    expect(within(dialog).getByRole('button', { name: 'Delete' })).toBeInTheDocument();
  });

