  on_cancel_delete?: () => void;
};

function getLast4Safe(last4: string): string {
  const s = String(last4 ?? '').trim();
  return s.length > 0 ? s : '****';
}

export function DeleteCardAction(props: DeleteCardActionProps) {
  const {
    payment_method_id,
    last4,
    disabled = false,
    is_deleting = false,
    on_confirm_delete,
    on_cancel_delete,
  } = props;

  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const deleteButtonRef = useRef<HTMLButtonElement | null>(null);
  const cancelButtonRef = useRef<HTMLButtonElement | null>(null);

  const safeLast4 = getLast4Safe(last4);
  const ariaLabel = `Delete card ending in ${safeLast4}`;

  const titleId = useId();
  const bodyId = useId();

  const isButtonDisabled = Boolean(disabled || is_deleting);

  useEffect(() => {
    if (!isDialogOpen) return;
    // Default focus: Cancel
    cancelButtonRef.current?.focus();
  }, [isDialogOpen]);

  useEffect(() => {
    if (!isDialogOpen) return;

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        handleCancel();
        return;
      }

      // Minimal focus trap between Cancel/Delete.
      if (e.key === 'Tab') {
        const focusables = [cancelButtonRef.current].filter(Boolean) as HTMLElement[];
        const deleteBtn = document.getElementById(`${titleId}-delete-action`) as HTMLElement | null;
        if (deleteBtn) focusables.push(deleteBtn);

        if (focusables.length === 0) return;

        const current = document.activeElement as HTMLElement | null;
        const idx = current ? focusables.indexOf(current) : -1;

        e.preventDefault();
        if (e.shiftKey) {
          const next = idx <= 0 ? focusables[focusables.length - 1] : focusables[idx - 1];
          next.focus();
        } else {
          const next = idx === -1 || idx >= focusables.length - 1 ? focusables[0] : focusables[idx + 1];
          next.focus();
        }
      }
    };

    document.addEventListener('keydown', onKeyDown, true);
    return () => document.removeEventListener('keydown', onKeyDown, true);
    // titleId used for stable delete button id; safe because useId is stable for component lifetime.
  }, [isDialogOpen, titleId]);

