    // Prevent parent click/selection handlers.
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    if (isButtonDisabled) return;
    setIsDialogOpen(true);
  };

  const closeDialog = () => {
    setIsDialogOpen(false);
    // Restore focus to the triggering delete button.
    deleteButtonRef.current?.focus();
  };

