            role="dialog"
            aria-modal="true"
            aria-labelledby={titleId}
            aria-describedby={bodyId}
            className="dca_dialog"
            onMouseDown={(e) => {
              e.stopPropagation();
            }}
          >
            <h2 id={titleId} className="dca_title">
              Delete payment method?
            </h2>
            <p id={bodyId} className="dca_body">
