      <style>{`
        .dca_btn {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          min-width: 44px;
          min-height: 44px;
          padding: 0;
          border-radius: var(--radius-8);
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          color: var(--color-text-secondary);
          box-shadow: none;
          cursor: pointer;
