abled)","deleting (is_deleting)","delete error (delete_error_message present)","missing optional data (brand/expiry/cardholder/last4 omitted)"],"files":[{"filename":"/app/generated/frontend/src/components/PaymentCard/PaymentCard.spec.tsx","content":"import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { PaymentCard } from './PaymentCard';

jest.mock('../CardBrandIcon/CardBrandIcon', () => ({
  CardBrandIcon: (props: any) => (
    <div data-testid="brand-icon" data-brand={props?.brand ?? ''} />
  ),
}));

jest.mock('../CardNumber/CardNumber', () => ({
  CardNumber: (props: any) => (
    <div data-testid="card-number" data-last4={props?.last4 ?? ''}>
      {props?.masked_card_number ?? `**** **** **** ${props?.last4 ?? '****'}`}
    </div>
  ),
}));

jest.mock('../ExpiryDate/ExpiryDate', () => ({
  ExpiryDate: (props: any) => (
    <div data-testid="expiry">{props?.expiry_mm_yy ?? '—'}</div>
  ),
}));

jest.mock('../CardholderName/CardholderName', () => ({
  CardholderName: (props: any) => (
    <div
      data-testid="cardholder"
      title={props?.cardholder_name_title ?? props?.cardholder_name ?? ''}
    >
      {props?.cardholder_name ?? '—'}
    </div>
  ),
}));

jest.mock('../DeleteCardAction/DeleteCardAction', () => ({
  DeleteCardAction: (props: any) => (
    <button
      type="button"
      data-testid="delete-action"
      aria-label={`Delete card ending in ${props.last4}`}
      disabled={Boolean(props.disabled) || Boolean(props.is_deleting)}
      onClick={(e) => {
        // Ensure clicking delete does not also select the card
        e.stopPropagation();
        props.on_confirm_delete({ payment_method_id: props.payment_method_id });
      }}
    >
      Delete
    </button>
  ),
}));

function renderSubject(overrides: Partial<React.ComponentProps<typeof PaymentCard>> = {}) {
  const props: React.ComponentProps<typeof PaymentCard> = {
    card_id: 'pm_123',
    brand: 'visa',
    last4: '1234',
    expiry_month: '04',
    expiry_year: '27',
    cardholder_name: 'Ada Lovelace',
    is_selected: false,
    tab_index: 0,
    is_disabled: false,
    is_deleting: false,
    delete_error_message: undefined,
    on_select: jest.fn(),
    on_confirm_delete: jest.fn(),
    on_cancel_delete: jest.fn(),
    ...overrides,
  };

  const view = render(<PaymentCard {...props} />);
  return { props, ...view };
}

describe('PaymentCard', () => {
  test('renders as a radio with aria-checked and tabIndex; shows masked number, expiry, and cardholder', () => {
    renderSubject({ is_selected: true, tab_index: -1 });

    const radio = screen.getByRole('radio');
    expect(radio).toHaveAttribute('aria-checked', 'true');
    expect(radio).toHaveAttribute('tabindex', '-1');

    expect(screen.getByTestId('brand-icon')).toHaveAttribute('data-brand', 'visa');
    expect(screen.getByTestId('card-number')).toHaveTextContent('**** **** **** 1234');
    expect(screen.getByTestId('expiry')).toHaveTextContent('04/27');
    expect(screen.getByTestId('cardholder')).toHaveTextContent('Ada Lovelace');

    // Tooltip/title behavior is delegated to CardholderName; ensure it receives a usable title.
    expect(screen.getByTestId('cardholder')).toHaveAttribute('title', 'Ada Lovelace');
  });

  test('clicking card container triggers on_select with card_id payload', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({ is_selected: false });

    await user.click(screen.getByRole('radio'));

    expect(props.on_select).toHaveBeenCalledTimes(1);
    expect(props.on_select).toHaveBeenCalledWith({ card_id: 'pm_123' });
  });

  test('Space and Enter activate selection (keyboard)', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject();

    const radio = screen.getByRole('radio');
    radio.focus();

    await user.keyboard('{Space}');
    await user.keyboard('{Enter}');

    expect(props.on_select).toHaveBeenCalledTimes(2);
