{"componentCode":"payment_card","componentName":"Payment Card","files":[{"filename":"/app/generated/frontend/src/components/PaymentCard/PaymentCard.tsx","content":"import React from 'react';

import { CardBrandIcon } from '../CardBrandIcon/CardBrandIcon';
import { CardNumber } from '../CardNumber/CardNumber';
import { ExpiryDate } from '../ExpiryDate/ExpiryDate';
import { CardholderName } from '../CardholderName/CardholderName';
import { DeleteCardAction } from '../DeleteCardAction/DeleteCardAction';

export type SelectPaymentCardPayload = { card_id: string };
export type DeletePaymentCardPayload = { payment_method_id: string };
export type CancelDeletePaymentCardPayload = { card_id: string };

export type PaymentCardProps = {
  card_id: string;
  brand?: string;
  last4?: string;
  expiry_month?: string;
  expiry_year?: string;
  cardholder_name?: string;
  is_selected: boolean;
  tab_index: number;
  is_disabled?: boolean;
  is_deleting?: boolean;
  delete_error_message?: string;
  on_select: (payload: SelectPaymentCardPayload) => void;
  on_confirm_delete: (payload: DeletePaymentCardPayload) => void;
  on_cancel_delete?: (payload: CancelDeletePaymentCardPayload) => void;
};

function brandToSrLabel(brand?: string): string | null {
  if (!brand) return null;
  const b = brand.trim().toLowerCase();
  if (!b) return null;
  if (b === 'visa') return 'Visa';
  if (b === 'mastercard') return 'Mastercard';
  if (b === 'amex' || b === 'american_express' || b === 'american-express') return 'American Express';
  // Unknown brand: still provide something stable for AT.
  return brand;
}

function formatExpiryMmYy(expiry_month?: string, expiry_year?: string): string | null {
  if (!expiry_month || !expiry_year) return null;
  const mm = String(expiry_month).padStart(2, '0').slice(0, 2);
  const yy = String(expiry_year).padStart(2, '0').slice(0, 2);
  return `${mm}/${yy}`;
}

export function PaymentCard(props: PaymentCardProps) {
  const {
    card_id,
    brand,
    last4,
    expiry_month,
    expiry_year,
    cardholder_name,
    is_selected,
    tab_index,
    is_disabled,
    is_deleting,
    delete_error_message,
    on_select,
    on_confirm_delete,
    on_cancel_delete,
  } = props;

  const disabled = Boolean(is_disabled) || Boolean(is_deleting);
  const expiry_mm_yy = formatExpiryMmYy(expiry_month, expiry_year);
  const srBrand = brandToSrLabel(brand);

  const handleSelect = React.useCallback(() => {
    if (disabled) return;
    on_select({ card_id });
  }, [disabled, on_select, card_id]);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent) => {
      if (disabled) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        on_select({ card_id });
      }
    },
    [disabled, on_select, card_id]
  );

  const handleCancelDelete = React.useCallback(() => {
    on_cancel_delete?.({ card_id });
  }, [on_cancel_delete, card_id]);

  // Prefer provided error for announcements; do not synthesize success messages inside this component
  // because deletion/removal is parent-managed.
  const liveMessage = delete_error_message;

  return (
    <div
      role="radio"
      aria-checked={is_selected}
      aria-disabled={disabled ? 'true' : undefined}
      tabIndex={tab_index}
      onClick={handleSelect}
      onKeyDown={handleKeyDown}
      data-card-id={card_id}
      style={{
        display: 'grid',
        gridTemplateColumns: 'auto 1fr auto',
        gridTemplateAreas: 'brand number delete' + "\n" + 'brand meta delete',
