            }
          : null),
        opacity: is_disabled ? 0.7 : 1,
        minHeight: 44,
      }}
      className="PaymentCard"
    >
      {/* Decorative icon; brand meaning (if any) is provided via SR-only text */}
      <div style={{ gridArea: 'brand', display: 'flex', alignItems: 'center' }}>
        <CardBrandIcon brand={brand ?? null} aria_hidden={true} size={24} />
        {srBrand ? (
          <span
            style={{
              position: 'absolute',
              width: 1,
              height: 1,
              padding: 0,
              margin: -1,
              overflow: 'hidden',
              clip: 'rect(0, 0, 0, 0)',
              whiteSpace: 'nowrap',
              border: 0,
            }}
          >
            {srBrand}
          </span>
        ) : null}
      </div>

      <div style={{ gridArea: 'number', display: 'flex', alignItems: 'baseline', gap: 'var(--spacing-8)' }}>
        <span style={{ fontSize: 'var(--font-size-body)', fontWeight: 'var(--font-weight-medium)' }}>
          <CardNumber last4={last4} />
        </span>
        <span
          style={{
            position: 'absolute',
            width: 1,
            height: 1,
            padding: 0,
            margin: -1,
            overflow: 'hidden',
            clip: 'rect(0, 0, 0, 0)',
            whiteSpace: 'nowrap',
            border: 0,
          }}
        >
          {card_id}
        </span>
      </div>

      <div style={{ gridArea: 'delete', justifySelf: 'end' }} onClick={(e) => e.stopPropagation()}>
        <DeleteCardAction
          payment_method_id={card_id}
          last4={last4 ?? '****'}
          disabled={disabled}
          is_deleting={Boolean(is_deleting)}
          on_confirm_delete={on_confirm_delete}
          on_cancel_delete={handleCancelDelete}
        />
      </div>

      <div
        style={{
          gridArea: 'meta',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          gap: 'var(--spacing-12)',
          minWidth: 0,
          color: 'var(--color-text-secondary)',
          fontSize: 'var(--font-size-label)',
        }}
      >
        <div style={{ minWidth: 0, flex: 1 }}>
          <CardholderName
            cardholder_name={cardholder_name ? cardholder_name : null}
            cardholder_name_title={cardholder_name ? cardholder_name : null}
          />
        </div>
        <div style={{ flexShrink: 0 }}>
          <ExpiryDate expiry_mm_yy={expiry_mm_yy} />
        </div>
      </div>

      {delete_error_message ? (
        <div
          style={{
            gridColumn: '1 / -1',
            marginTop: 'var(--spacing-8)',
            color: 'var(--color-status-danger)',
            fontSize: 'var(--font-size-label)',
          }}
        >
          {delete_error_message}
        </div>
      ) : null}

      {liveMessage ? (
        <div
          aria-live="polite"
          aria-atomic="true"
          style={{
            position: 'absolute',
            width: 1,
            height: 1,
            padding: 0,
            margin: -1,
            overflow: 'hidden',
            clip: 'rect(0, 0, 0, 0)',
            whiteSpace: 'nowrap',
            border: 0,
          }}
        >
          {liveMessage}
        </div>
      ) : null}

      <style>{`
        .PaymentCard:hover {
          background: var(--color-surface-muted);
        }
        .PaymentCard:active {
          background: var(--color-surface-muted);
        }
        .PaymentCard[aria-disabled="true"]:hover {
          background: var(--color-surface-default);
        }
        .PaymentCard:focus-visible {
          outline: 2px solid var(--color-text-primary);
          outline-offset: 2px;
        }
        @media (max-width: 359px) {
          .PaymentCard {
            gridTemplateColumns: 'auto 1fr auto';
            grid-template-areas:
              "brand number delete"
              "brand meta delete";
          }
        }
      `}</style>
    </div>
  );
}
