}

function IconSvg({ brand }: { brand: 'visa' | 'mastercard' | 'amex' | 'unknown' }) {
  // Simple, self-contained SVG marks (no external assets) to satisfy tests and keep layout stable.
  // These are not official brand assets.
  switch (brand) {
    case 'visa':
      return (
        <svg viewBox="0 0 32 20" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="32" height="20" rx="3" fill="#1A1F71" />
          <path
            d="M6.4 14.6L4.8 5.4h2.1l1 6.3 1.6-6.3h2.1l-2.4 9.2H6.4z"
            fill="#FFFFFF"
          />
          <path
            d="M12.9 14.6l1.7-9.2h2.0l-1.7 9.2h-2.0z"
            fill="#FFFFFF"
          />
          <path
            d="M21.9 6.0c-.4-.2-1-.3-1.6-.3-1.1 0-1.9.6-1.9 1.4 0 .6.6 1 1.2 1.3.7.3 1 .5 1 .8 0 .4-.5.6-1 .6-.7 0-1.1-.1-1.7-.4l-.2-.1-.3 1.7c.4.2 1.1.4 1.9.4 1.2 0 2-.6 2-1.5 0-.5-.3-.9-1.1-1.3-.6-.3-1.1-.5-1.1-.8 0-.3.3-.6 1.0-.6.6 0 1 .1 1.4.3l.2.1.2-1.6z"
            fill="#FFFFFF"
          />
          <path
            d="M25.8 11.3h-1.6l1.0-2.8.6 2.8zm2.5 3.3l-1.6-9.2h-1.8c-.4 0-.7.2-.8.6l-3.6 8.6h2.1l.5-1.4h2.6l.3 1.4h2.3z"
            fill="#FFFFFF"
          />
        </svg>
      );
    case 'mastercard':
      return (
        <svg viewBox="0 0 32 20" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="32" height="20" rx="3" fill="#111827" />
          <circle cx="14" cy="10" r="5" fill="#EB001B" />
          <circle cx="18" cy="10" r="5" fill="#F79E1B" fillOpacity="0.95" />
          <path
            d="M16 5.7a5.9 5.9 0 0 0 0 8.6 5.9 5.9 0 0 0 0-8.6z"
            fill="#FF5F00"
          />
        </svg>
      );
    case 'amex':
      return (
        <svg viewBox="0 0 32 20" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="32" height="20" rx="3" fill="#2E77BB" />
          <rect x="4" y="4" width="24" height="12" rx="1.5" fill="#FFFFFF" fillOpacity="0.12" />
          <path
            d="M6.2 13.8V6.2h5.5v1.2H7.6v1.7h3.8v1.2H7.6v2.3H6.2zm7.0 0V6.2h2.5l1.5 4.8 1.5-4.8h2.5v7.6h-1.4V7.8l-1.8 6.0h-1.6l-1.8-6.0v6.0h-1.4zm10.2 0V6.2h5.6v1.2H24.8v1.8h3.8v1.2h-3.8v2.2h4.3v1.2h-5.7z"
            fill="#FFFFFF"
          />
        </svg>
      );
    case 'unknown':
    default:
      return (
        <svg viewBox="0 0 32 20" xmlns="http://www.w3.org/2000/svg">
          <rect x="0" y="0" width="32" height="20" rx="3" fill="#D1D5DB" />
          <rect x="4" y="6" width="24" height="2" rx="1" fill="#9CA3AF" />
          <rect x="4" y="10" width="14" height="2" rx="1" fill="#9CA3AF" />
        </svg>
      );
  }
}

export function CardBrandIcon({
  brand,
  aria_hidden = true,
  aria_label,
  size = 24
}: CardBrandIconProps) {
  const normalized = normalizeBrand(brand);

  // Ensure size is applied via style so tests accept either attributes or inline style.
  const dimensionStyle: React.CSSProperties = {
    width: `${size}px`,
    height: `${size}px`,
    display: 'block'
  };

  const a11yProps: React.SVGProps<SVGSVGElement> = aria_hidden
    ? { 'aria-hidden': true, focusable: false }
    : { role: 'img', 'aria-label': aria_label ?? '' };

  // Wrap in a stable container so the component always renders at least one element.
  return (
    <span style={{ display: 'inline-block', width: `${size}px`, height: `${size}px` }}>
      {React.cloneElement(<IconSvg brand={normalized} />, {
        ...a11yProps,
        style: dimensionStyle
      })}
    </span>
  );
}
"},{"filename":"/app/generated/frontend/src/components/CardNumber/CardNumber.tsx","content":"import React from 'react';

export type CardNumberProps = {
  /**
   * Last 4 digits of the card number to be displayed as the final group in the masked string;
   * if omitted, the component renders "****" as the last group.
   */
  last4?: string;
  /**
   * Preformatted masked card number string to render (e.g., "**** **** **** 1234");
   * if provided, it is rendered as-is and takes precedence over last4-based masking.
   */
  masked_card_number?: string;
};

function buildMaskedFromLast4(last4?: string): string {
  const safeLast4 = (last4 ?? '').trim();
  const lastGroup = safeLast4.length > 0 ? safeLast4 : '****';
  return `**** **** **** ${lastGroup}`;
}

export function CardNumber({ last4, masked_card_number }: CardNumberProps) {
  const value = (masked_card_number ?? '').trim().length > 0
    ? masked_card_number
    : buildMaskedFromLast4(last4);

  return <span>{value}</span>;
}
"},{"filename":"/app/generated/frontend/src/components/CardholderName/CardholderName.tsx","content":"import React from 'react';

export type CardholderNameProps = {
  /** Cardholder name to display. When null/empty, renders an em dash placeholder (—). */
  cardholder_name?: string | null;
  /** Optional tooltip title. If omitted, may fall back to cardholder_name. */
  cardholder_name_title?: string | null;
};

export function CardholderName({
  cardholder_name,
  cardholder_name_title,
}: CardholderNameProps) {
  const hasName = typeof cardholder_name === 'string' && cardholder_name.trim().length > 0;
  const text = hasName ? cardholder_name : '—';

  const title =
    cardholder_name_title != null
      ? cardholder_name_title
      : hasName
        ? cardholder_name
        : null;

  const titleProps = title != null ? { title } : undefined;

  return (
    <span
      {...titleProps}
      style={{
        display: 'block',
        minWidth: 0,
        overflow: 'hidden',
        textOverflow: 'ellipsis',
        whiteSpace: 'nowrap',
      }}
    >
      {text}
    </span>
  );
}
"},{"filename":"/app/generated/frontend/src/components/DeleteCardAction/DeleteCardAction.tsx","content":"import React, { useEffect, useId, useRef, useState } from 'react';

export type DeletePaymentCardPayload = {
  payment_method_id: string;
};

export type DeleteCardActionProps = {
  payment_method_id: string;
  last4: string;
  disabled?: boolean;
  is_deleting?: boolean;
  on_confirm_delete: (payload: DeletePaymentCardPayload) => void;
  on_cancel_delete?: () => void;
};

function getLast4Safe(last4: string): string {
  const s = String(last4 ?? '').trim();
  return s.length > 0 ? s : '****';
}

export function DeleteCardAction(props: DeleteCardActionProps) {
  const {
    payment_method_id,
    last4,
    disabled = false,
    is_deleting = false,
    on_confirm_delete,
    on_cancel_delete,
  } = props;

  const [isDialogOpen, setIsDialogOpen] = useState(false);

  const deleteButtonRef = useRef<HTMLButtonElement | null>(null);
  const cancelButtonRef = useRef<HTMLButtonElement | null>(null);

  const safeLast4 = getLast4Safe(last4);
  const ariaLabel = `Delete card ending in ${safeLast4}`;

  const titleId = useId();
  const bodyId = useId();

  const isButtonDisabled = Boolean(disabled || is_deleting);

  useEffect(() => {
    if (!isDialogOpen) return;
    // Default focus: Cancel
    cancelButtonRef.current?.focus();
  }, [isDialogOpen]);

  useEffect(() => {
    if (!isDialogOpen) return;

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        handleCancel();
        return;
      }

      // Minimal focus trap between Cancel/Delete.
      if (e.key === 'Tab') {
        const focusables = [cancelButtonRef.current].filter(Boolean) as HTMLElement[];
        const deleteBtn = document.getElementById(`${titleId}-delete-action`) as HTMLElement | null;
        if (deleteBtn) focusables.push(deleteBtn);

        if (focusables.length === 0) return;

        const current = document.activeElement as HTMLElement | null;
        const idx = current ? focusables.indexOf(current) : -1;

        e.preventDefault();
        if (e.shiftKey) {
          const next = idx <= 0 ? focusables[focusables.length - 1] : focusables[idx - 1];
          next.focus();
        } else {
          const next = idx === -1 || idx >= focusables.length - 1 ? focusables[0] : focusables[idx + 1];
          next.focus();
        }
      }
    };

    document.addEventListener('keydown', onKeyDown, true);
    return () => document.removeEventListener('keydown', onKeyDown, true);
    // titleId used for stable delete button id; safe because useId is stable for component lifetime.
  }, [isDialogOpen, titleId]);

  const openDialog = (e?: React.SyntheticEvent) => {
    // Prevent parent click/selection handlers.
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    if (isButtonDisabled) return;
    setIsDialogOpen(true);
  };

  const closeDialog = () => {
    setIsDialogOpen(false);
    // Restore focus to the triggering delete button.
    deleteButtonRef.current?.focus();
  };

  const handleCancel = () => {
    on_cancel_delete?.();
    closeDialog();
  };

  const handleConfirm = () => {
    on_confirm_delete({ payment_method_id });
    closeDialog();
  };

  return (
    <>
      <button
        ref={deleteButtonRef}
        type="button"
        aria-label={ariaLabel}
        disabled={isButtonDisabled}
        className="dca_btn"
        onClick={openDialog}
        onMouseDown={(e) => {
          // Avoid focusing a parent element on mousedown in some compositions
          e.stopPropagation();
        }}
      >
        {is_deleting ? (
          <span className="dca_spinner" role="progressbar" aria-label="Deleting" />
        ) : (
          <span className="dca_icon" aria-hidden="true">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path
                d="M9 3h6m-8 4h10m-1 0-.7 14.1A2 2 0 0 1 13.3 23h-2.6a2 2 0 0 1-2-1.9L8 7"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <path
                d="M10 11v8m4-8v8"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
              />
            </svg>
          </span>
        )}
      </button>

      {isDialogOpen ? (
        <div
          className="dca_backdrop"
          onMouseDown={(e) => {
            // Keep clicks from falling through; don't close on backdrop to keep behavior deterministic.
            e.preventDefault();
            e.stopPropagation();
          }}
        >
          <div
            role="dialog"
            aria-modal="true"
            aria-labelledby={titleId}
            aria-describedby={bodyId}
            className="dca_dialog"
            onMouseDown={(e) => {
              e.stopPropagation();
            }}
          >
            <h2 id={titleId} className="dca_title">
              Delete payment method?
            </h2>
            <p id={bodyId} className="dca_body">
              This will delete the card ending in {safeLast4}.
            </p>

            <div className="dca_actions">
              <button
                ref={cancelButtonRef}
                type="button"
                className="dca_cancel"
                onClick={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleCancel();
                }}
              >
                Cancel
              </button>
              <button
                id={`${titleId}-delete-action`}
                type="button"
                className="dca_delete"
                onClick={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  handleConfirm();
                }}
              >
                Delete
              </button>
            </div>
          </div>
        </div>
      ) : null}

      <style>{`
        .dca_btn {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          min-width: 44px;
          min-height: 44px;
          padding: 0;
          border-radius: var(--radius-8);
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          color: var(--color-text-secondary);
          box-shadow: none;
          cursor: pointer;
        }

        .dca_btn:hover:not(:disabled) {
          background: var(--color-surface-muted);
        }

        .dca_btn:active:not(:disabled) {
          background: var(--color-surface-muted);
        }

        .dca_btn:focus-visible {
          outline: 2px solid var(--color-text-primary);
          outline-offset: 2px;
        }

        .dca_btn:disabled {
          cursor: not-allowed;
          opacity: 0.6;
        }

        .dca_icon {
          display: inline-flex;
          align-items: center;
          justify-content: center;
        }

        .dca_spinner {
          width: 18px;
          height: 18px;
          border-radius: 999px;
          border: 2px solid var(--color-border-subtle);
          border-top-color: var(--color-text-secondary);
          animation: dca_spin 0.8s linear infinite;
        }

        @keyframes dca_spin {
          to { transform: rotate(360deg); }
        }

        .dca_backdrop {
          position: fixed;
          inset: 0;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: var(--spacing-16);
          background: rgba(17, 24, 39, 0.4);
          z-index: 1000;
        }

        .dca_dialog {
          width: min(420px, 100%);
          border-radius: var(--radius-12);
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          box-shadow: var(--shadow-sm);
          padding: var(--spacing-16);
          color: var(--color-text-primary);
        }

        .dca_title {
          margin: 0 0 var(--spacing-8) 0;
          font-size: var(--font-size-body);
          font-weight: var(--font-weight-medium);
        }

        .dca_body {
          margin: 0 0 var(--spacing-16) 0;
          color: var(--color-text-secondary);
          font-size: var(--font-size-body);
        }

        .dca_actions {
          display: flex;
          gap: var(--spacing-8);
          justify-content: flex-end;
        }

        .dca_cancel,
        .dca_delete {
          height: 40px;
          padding: 0 var(--spacing-12);
          border-radius: var(--radius-8);
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          font-size: var(--font-size-body);
          cursor: pointer;
        }

        .dca_cancel:hover,
        .dca_delete:hover {
          background: var(--color-surface-muted);
        }

        .dca_cancel:focus-visible,
        .dca_delete:focus-visible {
          outline: 2px solid var(--color-text-primary);
          outline-offset: 2px;
        }

        .dca_delete {
          border-color: var(--color-border-danger);
          color: var(--color-status-danger);
        }
      `}</style>
    </>
  );
}
