"},{"filename":"/app/generated/frontend/src/components/PaymentCard/PaymentCard.tsx","content":"import React from 'react';

import { CardBrandIcon } from '../CardBrandIcon/CardBrandIcon';
import { CardNumber } from '../CardNumber/CardNumber';
import { ExpiryDate } from '../ExpiryDate/ExpiryDate';
import { CardholderName } from '../CardholderName/CardholderName';
import { DeleteCardAction } from '../DeleteCardAction/DeleteCardAction';

export type SelectPaymentCardPayload = { card_id: string };
export type DeletePaymentCardPayload = { payment_method_id: string };
export type CancelDeletePaymentCardPayload = { card_id: string };

export type PaymentCardProps = {
  card_id: string;
  brand?: string;
  last4?: string;
  expiry_month?: string;
  expiry_year?: string;
  cardholder_name?: string;
  is_selected: boolean;
  tab_index: number;
  is_disabled?: boolean;
  is_deleting?: boolean;
  delete_error_message?: string;
  on_select: (payload: SelectPaymentCardPayload) => void;
  on_confirm_delete: (payload: DeletePaymentCardPayload) => void;
  on_cancel_delete?: (payload: CancelDeletePaymentCardPayload) => void;
};

function brandToSrLabel(brand?: string): string | null {
  if (!brand) return null;
  const b = brand.trim().toLowerCase();
  if (!b) return null;
  if (b === 'visa') return 'Visa';
  if (b === 'mastercard') return 'Mastercard';
  if (b === 'amex' || b === 'american_express' || b === 'american-express') return 'American Express';
  // Unknown brand: still provide something stable for AT.
  return brand;
}

function formatExpiryMmYy(expiry_month?: string, expiry_year?: string): string | null {
  if (!expiry_month || !expiry_year) return null;
  const mm = String(expiry_month).padStart(2, '0').slice(0, 2);
  const yy = String(expiry_year).padStart(2, '0').slice(0, 2);
  return `${mm}/${yy}`;
}

export function PaymentCard(props: PaymentCardProps) {
  const {
    card_id,
    brand,
    last4,
    expiry_month,
    expiry_year,
    cardholder_name,
    is_selected,
    tab_index,
    is_disabled,
    is_deleting,
    delete_error_message,
    on_select,
    on_confirm_delete,
    on_cancel_delete,
  } = props;

  const disabled = Boolean(is_disabled) || Boolean(is_deleting);
  const expiry_mm_yy = formatExpiryMmYy(expiry_month, expiry_year);
  const srBrand = brandToSrLabel(brand);

  const handleSelect = React.useCallback(() => {
    if (disabled) return;
    on_select({ card_id });
  }, [disabled, on_select, card_id]);

  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent) => {
      if (disabled) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        on_select({ card_id });
      }
    },
    [disabled, on_select, card_id]
  );

  const handleCancelDelete = React.useCallback(() => {
    on_cancel_delete?.({ card_id });
  }, [on_cancel_delete, card_id]);

  // Prefer provided error for announcements; do not synthesize success messages inside this component
  // because deletion/removal is parent-managed.
  const liveMessage = delete_error_message;

  return (
    <div
      role="radio"
      aria-checked={is_selected}
      aria-disabled={disabled ? 'true' : undefined}
      tabIndex={tab_index}
      onClick={handleSelect}
      onKeyDown={handleKeyDown}
      data-card-id={card_id}
      style={{
        display: 'grid',
        gridTemplateColumns: 'auto 1fr auto',
        gridTemplateAreas: 'brand number delete' + "\n" + 'brand meta delete',
        columnGap: 'var(--spacing-12)',
        rowGap: 'var(--spacing-4)',
        alignItems: 'center',
        padding: 'var(--spacing-16)',
        borderRadius: 'var(--radius-12)',
        border: `1px solid var(--color-border-subtle)`,
        background: 'var(--color-surface-default)',
        color: 'var(--color-text-primary)',
        boxShadow: 'var(--shadow-sm)',
        cursor: disabled ? 'not-allowed' : 'pointer',
        userSelect: 'none',
        // Selected indicator (border + inset ring)
        ...(is_selected
          ? {
              boxShadow: `inset 0 0 0 2px var(--color-text-primary), var(--shadow-sm)`,
            }
          : null),
        opacity: is_disabled ? 0.7 : 1,
        minHeight: 44,
      }}
      className="PaymentCard"
    >
      {/* Decorative icon; brand meaning (if any) is provided via SR-only text */}
      <div style={{ gridArea: 'brand', display: 'flex', alignItems: 'center' }}>
        <CardBrandIcon brand={brand ?? null} aria_hidden={true} size={24} />
        {srBrand ? (
          <span
            style={{
              position: 'absolute',
              width: 1,
              height: 1,
              padding: 0,
              margin: -1,
              overflow: 'hidden',
              clip: 'rect(0, 0, 0, 0)',
              whiteSpace: 'nowrap',
              border: 0,
            }}
          >
            {srBrand}
          </span>
        ) : null}
      </div>

      <div style={{ gridArea: 'number', display: 'flex', alignItems: 'baseline', gap: 'var(--spacing-8)' }}>
        <span style={{ fontSize: 'var(--font-size-body)', fontWeight: 'var(--font-weight-medium)' }}>
          <CardNumber last4={last4} />
        </span>
        <span
          style={{
            position: 'absolute',
            width: 1,
            height: 1,
            padding: 0,
            margin: -1,
            overflow: 'hidden',
            clip: 'rect(0, 0, 0, 0)',
            whiteSpace: 'nowrap',
            border: 0,
          }}
        >
          {card_id}
        </span>
      </div>

      <div style={{ gridArea: 'delete', justifySelf: 'end' }} onClick={(e) => e.stopPropagation()}>
        <DeleteCardAction
          payment_method_id={card_id}
          last4={last4 ?? '****'}
          disabled={disabled}
          is_deleting={Boolean(is_deleting)}
          on_confirm_delete={on_confirm_delete}
          on_cancel_delete={handleCancelDelete}
        />
      </div>

      <div
        style={{
          gridArea: 'meta',
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          gap: 'var(--spacing-12)',
          minWidth: 0,
          color: 'var(--color-text-secondary)',
          fontSize: 'var(--font-size-label)',
        }}
      >
        <div style={{ minWidth: 0, flex: 1 }}>
          <CardholderName
            cardholder_name={cardholder_name ? cardholder_name : null}
            cardholder_name_title={cardholder_name ? cardholder_name : null}
          />
        </div>
        <div style={{ flexShrink: 0 }}>
          <ExpiryDate expiry_mm_yy={expiry_mm_yy} />
        </div>
      </div>

      {delete_error_message ? (
        <div
          style={{
            gridColumn: '1 / -1',
            marginTop: 'var(--spacing-8)',
            color: 'var(--color-status-danger)',
            fontSize: 'var(--font-size-label)',
          }}
        >
          {delete_error_message}
        </div>
      ) : null}

      {liveMessage ? (
        <div
          aria-live="polite"
          aria-atomic="true"
          style={{
            position: 'absolute',
            width: 1,
            height: 1,
            padding: 0,
            margin: -1,
            overflow: 'hidden',
            clip: 'rect(0, 0, 0, 0)',
            whiteSpace: 'nowrap',
            border: 0,
          }}
        >
          {liveMessage}
        </div>
      ) : null}

      <style>{`
        .PaymentCard:hover {
          background: var(--color-surface-muted);
        }
        .PaymentCard:active {
          background: var(--color-surface-muted);
        }
        .PaymentCard[aria-disabled="true"]:hover {
          background: var(--color-surface-default);
        }
        .PaymentCard:focus-visible {
          outline: 2px solid var(--color-text-primary);
          outline-offset: 2px;
        }
        @media (max-width: 359px) {
          .PaymentCard {
            gridTemplateColumns: 'auto 1fr auto';
            grid-template-areas:
              "brand number delete"
              "brand meta delete";
          }
        }
      `}</style>
