import { render, screen, within, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { PaymentCard } from './PaymentCard';

type CardModel = {
  card_id: string;
  brand?: string;
  last4?: string;
  expiry_month?: string;
  expiry_year?: string;
  cardholder_name?: string;
};

type DeleteOutcome = 'success' | 'fail-once-then-success';

function PaymentMethodsFixture(props: { initialCards: CardModel[]; deleteOutcome: DeleteOutcome }) {
  const { initialCards, deleteOutcome } = props;

  const [cards, setCards] = React.useState<CardModel[]>(initialCards);
  const [selectedId, setSelectedId] = React.useState<string>(initialCards[0]?.card_id ?? '');
  const [deletingId, setDeletingId] = React.useState<string | null>(null);
  const [deleteErrorById, setDeleteErrorById] = React.useState<Record<string, string | undefined>>({});
  const [liveMessage, setLiveMessage] = React.useState<string>('');
  const deleteAttemptCount = React.useRef<Record<string, number>>({});

  const onSelect = (payload: any) => {
    setSelectedId(payload.card_id);
  };

  const onConfirmDelete = async (payload: any) => {
    const id = payload.payment_method_id;

    setLiveMessage('');
    setDeleteErrorById((prev) => ({ ...prev, [id]: undefined }));
    setDeletingId(id);

    deleteAttemptCount.current[id] = (deleteAttemptCount.current[id] ?? 0) + 1;
    const attempt = deleteAttemptCount.current[id];

    // Simulate async network.
    await new Promise((r) => setTimeout(r, 10));

    const shouldFail = deleteOutcome === 'fail-once-then-success' && attempt === 1;

    if (shouldFail) {
      setDeletingId(null);
      setDeleteErrorById((prev) => ({ ...prev, [id]: 'Delete failed. Try again.' }));
      setLiveMessage('Delete failed. Try again.');
      return;
    }

    setCards((prev) => prev.filter((c) => c.card_id !== id));
    setDeletingId(null);
    setLiveMessage('Card deleted');

    // If the deleted card was selected, select the first remaining card (parent responsibility).
    setSelectedId((prevSelected) => {
      if (prevSelected !== id) return prevSelected;
      const remaining = cards.filter((c) => c.card_id !== id);
      return remaining[0]?.card_id ?? '';
    });
  };

  const onCancelDelete = (_payload: any) => {
    // No-op; the test suite asserts no selection side-effects and focus restoration.
  };

  return (
    <div>
      {/* Parent-level radiogroup wrapper per integration decision */}
      <div role="radiogroup" aria-label="Saved payment methods">
        {cards.map((card) => (
          <PaymentCard
            key={card.card_id}
            card_id={card.card_id}
            brand={card.brand}
            last4={card.last4}
            expiry_month={card.expiry_month}
            expiry_year={card.expiry_year}
            cardholder_name={card.cardholder_name}
            is_selected={selectedId === card.card_id}
            tab_index={selectedId === card.card_id ? 0 : -1}
            is_disabled={false}
            is_deleting={deletingId === card.card_id}
            delete_error_message={deleteErrorById[card.card_id]}
            on_select={onSelect}
            on_confirm_delete={onConfirmDelete}
            on_cancel_delete={onCancelDelete}
          />
        ))}
      </div>

      {/* Parent-level live region to assert announcements without depending on internal DOM structure */}
      <div aria-live="polite" aria-atomic="true" data-testid="app-live-region" style={{ position: 'absolute', left: -9999 }}>
        {liveMessage}
      </div>

      {/* Debug state for assertions */}
      <output data-testid="selected-id">{selectedId}</output>
    </div>
  );
}

function getRadioByCardId(card_id: string) {
  // The component is expected to render role="radio". Prefer scoping by containing text when possible,
  // but fall back to selecting by index when only one is present.
  const radios = screen.getAllByRole('radio');
  const match = radios.find((r) => {
    // Many implementations include the masked PAN or last4 in the label; also allow data attributes.
    const text = (r as HTMLElement).textContent ?? '';
    return text.includes(card_id);
  });
  return match ?? radios[0];
}

function getDeleteButtonForLast4(last4: string) {
  return screen.getByRole('button', { name: `Delete card ending in ${last4}` });
}

describe('PaymentCard composed workflow (integration e2e-ish)', () => {
  test('select_card_shortest: click card selects it and updates roving tabindex in parent radiogroup', async () => {
    const user = userEvent.setup();

    render(
      <PaymentMethodsFixture
        deleteOutcome="success"
        initialCards={[
          {
            card_id: 'pm_1',
            brand: 'visa',
            last4: '1111',
            expiry_month: '04',
            expiry_year: '27',
            cardholder_name: 'Ada Lovelace',
          },
          {
            card_id: 'pm_2',
            brand: 'mastercard',
            last4: '2222',
            expiry_month: '12',
            expiry_year: '29',
            cardholder_name: 'Grace Hopper',
          },
        ]}
      />
    );

    const radios = screen.getAllByRole('radio');
    expect(radios).toHaveLength(2);

    // Initially first is selected/tabbable.
    expect(radios[0]).toHaveAttribute('aria-checked', 'true');
    expect(radios[0]).toHaveAttribute('tabindex', '0');
    expect(radios[1]).toHaveAttribute('aria-checked', 'false');
    expect(radios[1]).toHaveAttribute('tabindex', '-1');
    expect(screen.getByTestId('selected-id')).toHaveTextContent('pm_1');

    // Click the second card container to select it.
    await user.click(radios[1]);

    await waitFor(() => expect(screen.getByTestId('selected-id')).toHaveTextContent('pm_2'));

    const updated = screen.getAllByRole('radio');
    expect(updated[0]).toHaveAttribute('aria-checked', 'false');
    expect(updated[0]).toHaveAttribute('tabindex', '-1');
    expect(updated[1]).toHaveAttribute('aria-checked', 'true');
    expect(updated[1]).toHaveAttribute('tabindex', '0');
  });

  test('delete_card_cancel_then_select_exploratory: keyboard open delete dialog, cancel (focus returns), then select card via Space', async () => {
    const user = userEvent.setup();

    render(
      <PaymentMethodsFixture
        deleteOutcome="success"
        initialCards={[
          {
            card_id: 'pm_1',
            brand: 'visa',
            last4: '1234',
            expiry_month: '04',
            expiry_year: '27',
            cardholder_name: 'A very very very long cardholder name that should truncate',
          },
          {
            card_id: 'pm_2',
            brand: 'amex',
            last4: '9876',
            expiry_month: '09',
            expiry_year: '28',
            cardholder_name: 'Grace Hopper',
          },
        ]}
      />
    );

    const deleteBtn = getDeleteButtonForLast4('9876');

    // Tab to delete button (focus-visible expected; we assert focus only).
    await user.tab();
    await user.tab();
    await user.tab();
    // Ensure we can focus the delete button directly.
    deleteBtn.focus();
    expect(deleteBtn).toHaveFocus();

    // Activate delete via keyboard; must not select the card as side-effect.
    await user.keyboard('{Enter}');

    const dialog = await screen.findByRole('dialog');
    expect(within(dialog).getByText('Delete payment method?')).toBeInTheDocument();

    const cancel = within(dialog).getByRole('button', { name: 'Cancel' });
    expect(cancel).toHaveFocus();

    // Cancel via Escape.
    await user.keyboard('{Escape}');

    await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
    expect(deleteBtn).toHaveFocus();

    // Ensure card wasn't selected as a side-effect of opening delete.
    expect(screen.getByTestId('selected-id')).toHaveTextContent('pm_1');

