{"componentCode":"payment_card","componentName":"Payment Card","files":[{"filename":"/app/generated/frontend/src/components/PaymentCard/PaymentCard.tsx","content":"import React from 'react';

import { CardBrandIcon } from '../CardBrandIcon/CardBrandIcon';
import { CardNumber } from '../CardNumber/CardNumber';
import { ExpiryDate } from '../ExpiryDate/ExpiryDate';
import { CardholderName } from '../CardholderName/CardholderName';
import { DeleteCardAction } from '../DeleteCardAction/DeleteCardAction';

type SelectPaymentCardPayload = { card_id: string };
type DeletePaymentCardPayload = { payment_method_id: string };
type CancelDeletePaymentCardPayload = { card_id: string };

export type PaymentCardProps = {
  card_id: string;
  brand?: string;
  last4?: string;
  expiry_month?: string;
  expiry_year?: string;
  cardholder_name?: string;
  is_selected: boolean;
  tab_index: number;
  is_disabled?: boolean;
  is_deleting?: boolean;
  delete_error_message?: string;
  on_select: (payload: SelectPaymentCardPayload) => void;
  on_confirm_delete: (payload: DeletePaymentCardPayload) => void;
  on_cancel_delete?: (payload: CancelDeletePaymentCardPayload) => void;
};

function brandToSpokenLabel(brand?: string): string | null {
  if (!brand) return null;
  const v = brand.trim().toLowerCase();
  if (!v) return null;
  if (v === 'visa') return 'Visa';
  if (v === 'mastercard' || v === 'master card') return 'Mastercard';
  if (v === 'amex' || v === 'american express') return 'American Express';
  // Fallback: speak the raw brand token.
  return brand;
}

function formatExpiryMmYy(expiry_month?: string, expiry_year?: string): string | null {
  if (!expiry_month || !expiry_year) return null;
  const mm = String(expiry_month).padStart(2, '0').slice(0, 2);
  const yy = String(expiry_year).padStart(2, '0').slice(-2);
  // Minimal validation: ensure digits, else let child show placeholder.
  if (!/^[0-9]{2}$/.test(mm) || !/^[0-9]{2}$/.test(yy)) return null;
  return `${mm}/${yy}`;
}

export function PaymentCard(props: PaymentCardProps) {
  const {
    card_id,
    brand,
    last4,
    expiry_month,
    expiry_year,
    cardholder_name,
    is_selected,
    tab_index,
    is_disabled = false,
    is_deleting = false,
    delete_error_message,
    on_select,
    on_confirm_delete,
    on_cancel_delete,
  } = props;

  const isInteractionDisabled = Boolean(is_disabled) || Boolean(is_deleting);

  const handleSelect = React.useCallback(() => {
    if (isInteractionDisabled) return;
    on_select({ card_id });
  }, [isInteractionDisabled, on_select, card_id]);

  const onKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLElement>) => {
      if (isInteractionDisabled) return;

      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        handleSelect();
      }
    },
    [isInteractionDisabled, handleSelect]
  );

  const expiry_mm_yy = formatExpiryMmYy(expiry_month, expiry_year);
  const cardholderName = cardholder_name && cardholder_name.trim().length > 0 ? cardholder_name : null;
  const brandLabel = brandToSpokenLabel(brand);

  const handleConfirmDelete = React.useCallback(
    (payload: DeletePaymentCardPayload) => {
      // Ensure delete never selects the card via bubbling.
      on_confirm_delete(payload);
    },
    [on_confirm_delete]
  );

  const handleCancelDelete = React.useCallback(() => {
    on_cancel_delete?.({ card_id });
  }, [on_cancel_delete, card_id]);

  return (
    <div
      role="radio"
      aria-checked={is_selected}
      aria-disabled={isInteractionDisabled ? 'true' : undefined}
      tabIndex={tab_index}
      className={[
        'pc-root',
        is_selected ? 'pc-selected' : '',
        isInteractionDisabled ? 'pc-disabled' : '',
      ]
        .filter(Boolean)
        .join(' ')}
      onClick={(e) => {
        // If click originated from nested controls, they should stopPropagation;
        // this is a final guard.
        if (isInteractionDisabled) return;
        if ((e.target as HTMLElement | null)?.closest?.('button,[role="button"],[role="dialog"],a,input,select,textarea')) {
          return;
        }
        handleSelect();
      }}
      onKeyDown={onKeyDown}
      data-card-id={card_id}
    >
      <div className="pc-grid" aria-label={`Payment method ${card_id}`}>
        <div className="pc-left">
          <CardBrandIcon brand={brand ?? null} aria_hidden={true} size={24} />
          {/* Provide brand meaning to screen readers without relying on the decorative icon */}
          {brandLabel ? <span className="pc-srOnly">{brandLabel}</span> : null}

          <div className="pc-number">
            <CardNumber last4={last4} />
          </div>
        </div>

        <div className="pc-right">
          <DeleteCardAction
            payment_method_id={card_id}
            last4={last4 ?? '????'}
            disabled={isInteractionDisabled}
            is_deleting={is_deleting}
            on_confirm_delete={handleConfirmDelete}
            on_cancel_delete={handleCancelDelete}
          />
        </div>

        <div className="pc-bottomLeft">
          <CardholderName cardholder_name={cardholderName} cardholder_name_title={cardholderName} />
        </div>

        <div className="pc-bottomRight">
          <ExpiryDate expiry_mm_yy={expiry_mm_yy} />
        </div>
      </div>

      {delete_error_message ? (
        <div className="pc-errorWrap">
          <div aria-live="polite" aria-atomic="true" className="pc-error">
            {delete_error_message}
          </div>
        </div>
      ) : null}

      <style>{`
        .pc-root {
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border: 1px solid var(--color-border-subtle);
          border-radius: var(--radius-12);
          box-shadow: var(--shadow-sm);
          padding: var(--spacing-16);
          min-height: 44px;
          cursor: pointer;
          user-select: none;
        }

        .pc-grid {
          display: grid;
          grid-template-columns: 1fr auto;
          grid-template-rows: auto auto;
          column-gap: var(--spacing-12);
          row-gap: var(--spacing-8);
          align-items: center;
        }

        .pc-left {
          display: flex;
          align-items: center;
          gap: var(--spacing-12);
          min-width: 0;
        }

        .pc-number {
          font-size: var(--font-size-body);
          color: var(--color-text-primary);
          min-width: 0;
        }

        .pc-right {
          justify-self: end;
        }

        .pc-bottomLeft {
          grid-column: 1 / 2;
          min-width: 0;
          color: var(--color-text-secondary);
          font-size: var(--font-size-label);
        }

        .pc-bottomRight {
          grid-column: 2 / 3;
          justify-self: end;
          color: var(--color-text-secondary);
          font-size: var(--font-size-label);
          font-weight: var(--font-weight-medium);
          white-space: nowrap;
        }

        .pc-selected {
          /* Distinct border + 2px inset ring */
          box-shadow: inset 0 0 0 2px var(--color-text-primary), var(--shadow-sm);
        }

        .pc-root:hover {
          background: var(--color-surface-muted);
        }

        .pc-root:active {
          background: var(--color-surface-muted);
        }

        .pc-root:focus-visible {
          outline: 2px solid var(--color-text-primary);
          outline-offset: 2px;
        }

        .pc-disabled {
          cursor: not-allowed;
        }

        .pc-disabled:hover,
        .pc-disabled:active {
          background: var(--color-surface-default);
        }

        .pc-errorWrap {
          margin-top: var(--spacing-8);
        }

        .pc-error {
          color: var(--color-status-danger);
          font-size: var(--font-size-label);
        }

        .pc-srOnly {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }

        @media (max-width: 359px) {
          .pc-grid {
            grid-template-columns: 1fr auto;
            grid-template-rows: auto auto;
          }
          .pc-left {
            grid-column: 1 / 2;
            grid-row: 1;
          }
          .pc-right {
            grid-column: 2 / 3;
            grid-row: 1;
          }
          .pc-bottomLeft {
            grid-column: 1 / 2;
            grid-row: 2;
          }
          .pc-bottomRight {
            grid-column: 2 / 3;
            grid-row: 2;
          }
        }
      `}</style>
    </div>
  );
}
