import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';

import { CardBrandIcon } from './CardBrandIcon';

function getRenderedElement(container: HTMLElement): HTMLElement {
  // Prefer an actual <img> if used by the implementation, otherwise fall back to first element child.
  const img = container.querySelector('img');
  if (img) return img as unknown as HTMLElement;

  const svg = container.querySelector('svg');
  if (svg) return svg as unknown as HTMLElement;

  const first = container.firstElementChild;
  if (!first) {
    throw new Error('CardBrandIcon rendered no DOM element');
  }
  return first as HTMLElement;
}

describe('CardBrandIcon', () => {
  it('renders without crashing for a known brand (visa)', () => {
    const { container } = render(<CardBrandIcon brand="visa" />);
    expect(container).not.toBeEmptyDOMElement();

    // Should render some element representing the icon.
    const el = getRenderedElement(container);
    expect(el).toBeInTheDocument();
  });

  it('renders a neutral/empty state for brand=null (should not break layout)', () => {
    const { container } = render(<CardBrandIcon brand={null} />);
    expect(container).not.toBeEmptyDOMElement();

    // Layout-stability check: still renders an element even when no brand.
    const el = getRenderedElement(container);
    expect(el).toBeInTheDocument();
  });

  it('renders a neutral/empty state for an unknown brand value', () => {
    const { container } = render(<CardBrandIcon brand="diners" />);
    expect(container).not.toBeEmptyDOMElement();

    const el = getRenderedElement(container);
    expect(el).toBeInTheDocument();
  });

  it('is decorative when aria_hidden=true (aria-hidden=true and not discoverable by role=img)', () => {
    const { container } = render(
      <CardBrandIcon brand="visa" aria_hidden={true} aria_label="Visa" />
    );

    const el = getRenderedElement(container);
    expect(el).toHaveAttribute('aria-hidden', 'true');

    // If the implementation uses <img alt="">, it won't show up as role=img name.
    // If it uses <svg>, role may be absent; either way, it should not be findable as an accessible image.
    expect(screen.queryByRole('img', { name: /visa/i })).toBeNull();

    // For <img>, ensure alt is empty when decorative.
    if (el.tagName.toLowerCase() === 'img') {
      expect(el).toHaveAttribute('alt', '');
    }
  });

  it('exposes an accessible name when aria_hidden is false and aria_label is provided', () => {
    render(<CardBrandIcon brand="visa" aria_hidden={false} aria_label="Visa" />);

    // The icon should be exposed as an image with an accessible name.
    // This covers common implementations: <img alt="Visa"> or <svg role="img" aria-label="Visa">.
    const img = screen.getByRole('img', { name: 'Visa' });
    expect(img).toBeInTheDocument();
    expect(img).not.toHaveAttribute('aria-hidden', 'true');
  });

  it('applies size to width/height (via attributes or inline style)', () => {
    const { container } = render(<CardBrandIcon brand="visa" size={32} />);
    const el = getRenderedElement(container);

    // Accept either attributes (width/height) or inline style width/height.
    const hasWidthAttr = el.getAttribute('width') === '32';
    const hasHeightAttr = el.getAttribute('height') === '32';
    const style = (el as HTMLElement).style;
    const hasWidthStyle = style?.width === '32px';
    const hasHeightStyle = style?.height === '32px';

    expect(hasWidthAttr || hasWidthStyle).toBe(true);
    expect(hasHeightAttr || hasHeightStyle).toBe(true);
  });
});
