import React from 'react';

type Props = {
  /** Card brand identifier used to choose the correct brand icon asset. */
  brand: string;
  /** Whether the icon should be hidden from assistive technology. Defaults to true (decorative). */
  aria_hidden?: boolean;
  /** Accessible label for the icon when aria_hidden is false. */
  aria_label?: string;
  /** Rendered icon size in pixels. Defaults to 24. */
  size_px?: number;
};

const DEFAULT_SIZE_PX = 24;

type BrandKey = 'visa' | 'mastercard' | 'amex' | 'unknown';

function normalizeBrand(brand: string): BrandKey {
  const b = (brand || '').trim().toLowerCase();
  if (b === 'visa') return 'visa';
  if (b === 'mastercard' || b === 'master card') return 'mastercard';
  if (b === 'amex' || b === 'american express') return 'amex';
  return 'unknown';
}

function brandTestId(brand: BrandKey): string {
  switch (brand) {
    case 'visa':
      return 'card-brand-icon-visa';
    case 'mastercard':
      return 'card-brand-icon-mastercard';
    case 'amex':
      return 'card-brand-icon-amex';
    default:
      return 'card-brand-icon-unknown';
  }
}

export function CardBrandIcon({ brand, aria_hidden, aria_label, size_px }: Props) {
  const size = typeof size_px === 'number' && Number.isFinite(size_px) ? size_px : DEFAULT_SIZE_PX;
  const resolvedBrand = normalizeBrand(brand);

  // Decorative by default.
  const isAriaHidden = aria_hidden !== undefined ? aria_hidden : true;

  // If not hidden, expose semantic image role with an accessible name.
  const accessibleLabel = !isAriaHidden ? aria_label : undefined;

  return (
    <svg
      data-testid={brandTestId(resolvedBrand)}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      xmlns="http://www.w3.org/2000/svg"
      role={!isAriaHidden ? 'img' : undefined}
      aria-hidden={isAriaHidden ? 'true' : undefined}
      aria-label={accessibleLabel}
      focusable="false"
      style={{ width: `${size}px`, height: `${size}px`, display: 'block' }}
    >
      {resolvedBrand === 'visa' && (
        <>
          <rect x="2" y="5" width="20" height="14" rx="3" fill="#1A1F71" />
          <path d="M7 16L9 8H10.7L8.7 16H7Z" fill="#ffffff" />
          <path d="M11.4 16L12.7 8H14.1L12.8 16H11.4Z" fill="#ffffff" />
          <path
