  aria_hidden?: boolean;
  /** Accessible label for the icon when aria_hidden is false. */
  aria_label?: string;
  /** Rendered icon size in pixels. Defaults to 24. */
  size_px?: number;
};

const DEFAULT_SIZE_PX = 24;

type BrandKey = 'visa' | 'mastercard' | 'amex' | 'unknown';

function normalizeBrand(brand: string): BrandKey {
  const b = (brand || '').trim().toLowerCase();
  if (b === 'visa') return 'visa';
  if (b === 'mastercard' || b === 'master card') return 'mastercard';
  if (b === 'amex' || b === 'american express') return 'amex';
  return 'unknown';
}

function brandTestId(brand: BrandKey): string {
  switch (brand) {
    case 'visa':
      return 'card-brand-icon-visa';
    case 'mastercard':
      return 'card-brand-icon-mastercard';
    case 'amex':
      return 'card-brand-icon-amex';
    default:
      return 'card-brand-icon-unknown';
  }
}

