import React from 'react';

type RequestDeletePaymentCardPayload = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
};

type ConfirmDeletePaymentCardPayload = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
};

type CancelDeletePaymentCardPayload = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
};

type RetryDeletePaymentCardPayload = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
};

export type DeleteCardActionProps = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
  can_delete: boolean;
  disabled_reason?: string;
  is_deleting: boolean;
  on_request_delete: (payload: RequestDeletePaymentCardPayload) => void;
  on_confirm_delete: (payload: ConfirmDeletePaymentCardPayload) => void;
  on_cancel_delete: (payload: CancelDeletePaymentCardPayload) => void;
  on_retry_delete?: (payload: RetryDeletePaymentCardPayload) => void;
};

export function DeleteCardAction(props: DeleteCardActionProps) {
  const {
    payment_method_id,
    last4,
    card_brand,
    can_delete,
    disabled_reason,
    is_deleting,
    on_request_delete
  } = props;

  const disabled = !can_delete || is_deleting;
  const accessibleName = `Delete card ending in ${last4}`;

  const handleClick: React.MouseEventHandler<HTMLButtonElement> = (e) => {
    // Prevent parent selectable container from also handling click
    e.stopPropagation();

    if (disabled) return;

    on_request_delete({ payment_method_id, last4, card_brand });
  };

  const handleMouseDown: React.MouseEventHandler<HTMLButtonElement> = (e) => {
    // Also stop early propagation paths in some parent implementations
    e.stopPropagation();
  };

  const handleKeyDown: React.KeyboardEventHandler<HTMLButtonElement> = (e) => {
    // Avoid bubbling key events to parent (e.g., radio-card Space/Enter handlers)
    e.stopPropagation();
  };

  return (
    <button
      type="button"
      aria-label={accessibleName}
      disabled={disabled}
      title={!can_delete && disabled_reason ? disabled_reason : undefined}
      onClick={handleClick}
      onMouseDown={handleMouseDown}
      onKeyDown={handleKeyDown}
    >
      {is_deleting ? 'Deleting…' : 'Delete'}
    </button>
  );
}

import React from 'react';

import { CardBrandIcon } from '../CardBrandIcon/CardBrandIcon';
import { CardDetails } from '../CardDetails/CardDetails';
import { DeleteCardAction } from '../DeleteCardAction/DeleteCardAction';

type SelectPaymentCardPayload = { payment_method_id: string };
type DeletePaymentCardPayload = { payment_method_id: string };

export type PaymentCardProps = {
  payment_method_id: string;
  card_brand: string;
  last4: string;
  expiry_month: string;
  expiry_year: string;
  cardholder_name: string;
  selected: boolean;
  selectable?: boolean;
  delete_enabled?: boolean;
  dense?: boolean;
  deleting?: boolean;
  delete_error_message?: string;
  on_select: (payload: SelectPaymentCardPayload) => void;
  on_delete: (payload: DeletePaymentCardPayload) => void;
};

function normalizeExpiryMMYY(expiry_month: string, expiry_year: string): string {
  const monthNum = Number.parseInt(String(expiry_month), 10);
  const mm = Number.isFinite(monthNum) && monthNum > 0 ? String(monthNum).padStart(2, '0') : String(expiry_month).padStart(2, '0');

  const y = String(expiry_year);
  const yy = y.length === 4 ? y.slice(-2) : y.padStart(2, '0').slice(-2);
  return `${mm}/${yy}`;
}

function normalizeBrandForCopy(brand: string): string {
  const v = (brand || '').toLowerCase();
  if (v === 'visa') return 'Visa';
  if (v === 'mastercard') return 'Mastercard';
  if (v === 'amex') return 'Amex';
  return 'Card';
}

export function PaymentCard(props: PaymentCardProps) {
  const {
    payment_method_id,
    card_brand,
    last4,
    expiry_month,
    expiry_year,
    cardholder_name,
    selected,
    selectable = true,
    delete_enabled = true,
    dense = false,
    deleting = false,
    delete_error_message,
    on_select,
    on_delete
  } = props;

  const expiry = React.useMemo(() => normalizeExpiryMMYY(expiry_month, expiry_year), [expiry_month, expiry_year]);
  const masked = React.useMemo(() => `•••• •••• •••• ${last4}`, [last4]);
  const maskedNumberAriaLabel = React.useMemo(() => `Card ending in ${last4}`, [last4]);

  const canSelect = !!selectable;

  const onCardSelect = React.useCallback(() => {
    if (!canSelect) return;
    on_select({ payment_method_id });
  }, [canSelect, on_select, payment_method_id]);

  const onCardKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLElement>) => {
      if (!canSelect) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        on_select({ payment_method_id });
      }
    },
    [canSelect, on_select, payment_method_id]
  );

  const brandForCopy = normalizeBrandForCopy(card_brand);

  const disabledReason = "You don’t have permission to delete this card";

  return (
    <div
      role="radio"
      aria-checked={selected}
      aria-busy={deleting || undefined}
      tabIndex={canSelect ? 0 : -1}
      data-payment-method-id={payment_method_id}
      className={[
        'pc_root',
        selected ? 'pc_selected' : '',
        !canSelect ? 'pc_notSelectable' : '',
        dense ? 'pc_dense' : ''
      ]
        .filter(Boolean)
        .join(' ')}
      onClick={onCardSelect}
      onKeyDown={onCardKeyDown}
    >
      <div className="pc_inner">
        <div className="pc_brand">
          <CardBrandIcon brand={card_brand} aria_hidden={true} size_px={24} />
        </div>

        <div className="pc_details">
          <CardDetails
            masked_card_number={masked}
            last4={last4}
            expiry_date={expiry}
            cardholder_name={cardholder_name}
            masked_number_aria_label={maskedNumberAriaLabel}
            enable_overflow_rules={true}
          />

          {delete_error_message ? (
            <div className="pc_error" role="alert">
              <div className="pc_errorRow">
                <span className="pc_errorText">{delete_error_message}</span>
                {/* Retry affordance required by flow; keep outside DeleteCardAction mock contract. */}
                <button
                  type="button"
                  className="pc_retry"
                  aria-label={`Retry delete for card ending in ${last4}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    on_delete({ payment_method_id });
                  }}
                  disabled={deleting}
                >
                  Retry
                </button>
              </div>
            </div>
          ) : null}
        </div>

        <div
          className="pc_delete"
          onClickCapture={(e) => {
            // prevent_select_on_delete: ensure events within delete affordance never select the card
            e.stopPropagation();
          }}
          onKeyDownCapture={(e) => {
            e.stopPropagation();
          }}
        >
          <DeleteCardAction
            payment_method_id={payment_method_id}
            last4={last4}
            card_brand={brandForCopy}
            can_delete={!!delete_enabled}
            disabled_reason={disabledReason}
            is_deleting={!!deleting}
            on_request_delete={() => {
              /* Confirmation modal is hosted by parent page (see e2e bridge). */
            }}
            on_confirm_delete={({ payment_method_id: pmid }: { payment_method_id: string }) => {
              on_delete({ payment_method_id: pmid });
            }}
            on_cancel_delete={() => {
              /* Parent hosts modal; no-op here. */
            }}
            on_retry_delete={({ payment_method_id: pmid }: { payment_method_id: string }) => {
              on_delete({ payment_method_id: pmid });
            }}
          />
        </div>
      </div>

      <style>{`
        .pc_root{
          width: 100%;
          box-sizing: border-box;
          display: block;
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border: 1px solid var(--color-border-subtle);
          border-radius: var(--radius-12);
          box-shadow: var(--shadow-sm);
          padding: var(--spacing-16);
          cursor: pointer;
          user-select: none;
        }

        .pc_dense{
          padding: var(--spacing-12);
        }

        .pc_root:hover{
          background: var(--color-surface-muted);
        }

        .pc_root:active{
          transform: scale(0.99);
        }

        .pc_root:focus-visible{
          outline: 2px solid var(--color-border-subtle);
          outline-offset: 2px;
        }

        .pc_notSelectable{
          cursor: default;
        }

        .pc_notSelectable:active{
          transform: none;
        }

        .pc_selected{
          border: 2px solid var(--color-text-primary);
          background: var(--color-surface-muted);
        }

        .pc_inner{
          display: flex;
          align-items: center;
          gap: var(--spacing-12);
          min-width: 0;
        }

        .pc_brand{
          flex: 0 0 auto;
          display: flex;
          align-items: center;
        }

        .pc_details{
          flex: 1 1 auto;
          min-width: 0;
        }

        .pc_delete{
          flex: 0 0 auto;
          display: flex;
          align-items: center;
          margin-left: var(--spacing-8);
        }

        .pc_error{
          margin-top: var(--spacing-8);
          color: var(--color-status-danger);
          font-size: var(--font-size-body);
        }

        .pc_errorRow{
          display: flex;
          gap: var(--spacing-8);
          align-items: baseline;
          justify-content: space-between;
        }

        .pc_errorText{
          min-width: 0;
        }

        .pc_retry{
          flex: 0 0 auto;
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border-radius: var(--radius-8);
          padding: var(--spacing-8);
          font-size: var(--font-size-label);
          font-weight: var(--font-weight-medium);
          cursor: pointer;
        }

        .pc_retry:hover{
          background: var(--color-surface-muted);
        }

        .pc_retry:focus-visible{
          outline: 2px solid var(--color-border-subtle);
          outline-offset: 2px;
        }

        .pc_retry:disabled{
          cursor: default;
          opacity: 0.7;
        }
      `}</style>
    </div>
  );
}

import React from 'react';
import '@testing-library/jest-dom';
import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

import { PaymentCard } from './PaymentCard';

type CardModel = {
  payment_method_id: string;
  card_brand: string;
  last4: string;
  expiry_month: string;
  expiry_year: string;
  cardholder_name: string;
  selectable?: boolean;
  delete_enabled?: boolean;
};

type DeleteOutcome = 'success' | 'error';

function normalizeBrandForCopy(card_brand: string): string {
  const v = (card_brand || '').toLowerCase();
  if (v === 'visa') return 'Visa';
  if (v === 'mastercard') return 'Mastercard';
  if (v === 'amex') return 'Amex';
  return 'Card';
}

function getRadioByPaymentMethodId(pmId: string): HTMLElement {
  const radios = screen.getAllByRole('radio');
  const match = radios.find((r) => r.getAttribute('data-payment-method-id') === pmId);
  if (match) return match;

  // Fallback if implementation does not include data attribute:
  // assume each card exposes an accessible string with last4; tests using this fallback are more brittle.
  throw new Error(
    `Unable to locate payment_card radio for payment_method_id=${pmId}. ` +
      `Expected a role=radio element with data-payment-method-id attribute.`
  );
}

function getDeleteButtonForLast4(last4: string): HTMLButtonElement {
  return screen.getByRole('button', { name: new RegExp(`delete.*ending in\\s*${last4}`, 'i') }) as HTMLButtonElement;
}

function getAllTabbablesInOrder(container: HTMLElement): HTMLElement[] {
  const sel = [
    'button:not([disabled])',
    '[href]',
    'input:not([disabled])',
    'select:not([disabled])',
    'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])'
  ].join(',');

  const nodes = Array.from(container.querySelectorAll(sel)) as HTMLElement[];
  return nodes.filter((el) => {
    // Basic visibility filter
    const style = window.getComputedStyle(el);
    return style.visibility !== 'hidden' && style.display !== 'none';
  });
}

function TestPaymentMethodsList(props: {
  initialCards: CardModel[];
  initialSelectedId?: string;
  disabledReason?: string;
  deletePlanById?: Record<string, DeleteOutcome[]>; // each confirm/retry consumes one outcome
}) {
  const {
    initialCards,
    initialSelectedId,
    disabledReason = "You don’t have permission to delete this card",
    deletePlanById = {}
  } = props;

  const [cards, setCards] = React.useState<CardModel[]>(initialCards);
  const [selectedId, setSelectedId] = React.useState<string | undefined>(initialSelectedId);

  const [modal, setModal] = React.useState<
    | null
    | {
        payment_method_id: string;
        last4: string;
        card_brand: string;
      }
  >(null);

  const [deletingId, setDeletingId] = React.useState<string | null>(null);
  const [deleteErrorById, setDeleteErrorById] = React.useState<Record<string, string>>({});

  const planIndexRef = React.useRef<Record<string, number>>({});

  const beginDelete = React.useCallback((payment_method_id: string) => {
    setDeletingId(payment_method_id);

    // simulate async request
    setTimeout(() => {
      const idx = planIndexRef.current[payment_method_id] ?? 0;
      const plan = deletePlanById[payment_method_id] ?? ['success'];
      const outcome = plan[Math.min(idx, plan.length - 1)] ?? 'success';
      planIndexRef.current[payment_method_id] = idx + 1;

      if (outcome === 'success') {
        setCards((prev) => prev.filter((c) => c.payment_method_id !== payment_method_id));
        setDeleteErrorById((prev) => {
          const next = { ...prev };
          delete next[payment_method_id];
          return next;
        });
        setModal(null);
        setDeletingId(null);

        // If deleted card was selected, clear selection.
        setSelectedId((prev) => (prev === payment_method_id ? undefined : prev));
      } else {
        setDeletingId(null);
        setModal(null);
        setDeleteErrorById((prev) => ({
          ...prev,
          [payment_method_id]: "Couldn’t delete this payment method. Try again."
        }));
      }
    }, 20);
  }, [deletePlanById]);

  return (
    <div>
      <h1>Saved payment methods</h1>

      {/* Render list of PaymentCard components */}
      <div aria-label="Saved payment methods list">
        {cards.map((c) => (
          <div key={c.payment_method_id} style={{ marginBottom: 12 }}>
            <PaymentCard
              payment_method_id={c.payment_method_id}
              card_brand={c.card_brand}
              last4={c.last4}
              expiry_month={c.expiry_month}
              expiry_year={c.expiry_year}
              cardholder_name={c.cardholder_name}
              selected={selectedId === c.payment_method_id}
              selectable={c.selectable}
              delete_enabled={c.delete_enabled}
              deleting={deletingId === c.payment_method_id}
              delete_error_message={deleteErrorById[c.payment_method_id]}
              on_select={({ payment_method_id }) => setSelectedId(payment_method_id)}
              on_delete={({ payment_method_id }) => beginDelete(payment_method_id)}
            />
          </div>
        ))}
      </div>

      {/* Confirmation modal per resolving-gaps decision */}
      {modal ? (
        <div role="dialog" aria-modal="true" aria-label="Delete payment method?">
          <h2>Delete payment method?</h2>
          <p>
            This will remove {normalizeBrandForCopy(modal.card_brand)} card ending in {modal.last4} from your saved payment
            methods.
          </p>
          <div>
            <button
              type="button"
              onClick={() => beginDelete(modal.payment_method_id)}
            >
              Delete
            </button>
            <button
              type="button"
              onClick={() => {
                setModal(null);
                // Focus return is handled by parent in real app; best-effort here.
                const btn = getDeleteButtonForLast4(modal.last4);
                btn?.focus();
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      ) : null}

      {/* Glue layer: capture DeleteCardAction's request/confirm/cancel/retry via DOM event hooks.
          The generated PaymentCard is expected to wire DeleteCardAction internally; we don't mock child components.
          Instead, we open the modal when the user activates the delete button in the card.

          We implement this by listening for click on buttons with the expected accessible name, and mapping them back
          to a card using last4 present in the name.
      */}
      <DeleteFlowBridge
        cards={cards}
        disabledReason={disabledReason}
        onOpenModal={(m) => setModal(m)}
        onRetry={(payment_method_id) => beginDelete(payment_method_id)}
        onSetDisabledTitle={() => {
          // no-op; exists for clarity
        }}
      />
    </div>
  );
}

function DeleteFlowBridge(props: {
  cards: CardModel[];
  disabledReason: string;
  onOpenModal: (m: { payment_method_id: string; last4: string; card_brand: string }) => void;
  onRetry: (payment_method_id: string) => void;
  onSetDisabledTitle: () => void;
}) {
  const { cards, onOpenModal, onRetry } = props;

  React.useEffect(() => {
    const handler = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target) return;

      // Identify delete button click by accessible name pattern.
      if (target instanceof HTMLButtonElement) {
        const name = target.getAttribute('aria-label') || target.textContent || '';

        const m = name.match(/ending in\s*(\d{4})/i);
        const last4 = m?.[1];
        if (!last4) return;

        // If this is a Retry affordance within the card, trigger retry.
        if (/retry/i.test(name) || /retry/i.test(target.textContent || '')) {
          const card = cards.find((c) => c.last4 === last4);
          if (!card) return;
          onRetry(card.payment_method_id);
          return;
        }

        // If this is the delete activation button, open modal. We do not open modal for disabled buttons.
        if (/delete/i.test(name)) {
          const card = cards.find((c) => c.last4 === last4);
          if (!card) return;
          if (target.disabled) return;
          onOpenModal({ payment_method_id: card.payment_method_id, last4: card.last4, card_brand: card.card_brand });
        }
      }
    };

    document.addEventListener('click', handler, true);
    return () => document.removeEventListener('click', handler, true);
  }, [cards, onOpenModal, onRetry]);

  return null;
}

describe('PaymentCard composed workflow (e2e)', () => {
  test('select_card_click_shortest: click card selects it (radio semantics) and does not trigger deletion UI', async () => {
    const user = userEvent.setup();

    render(
      <TestPaymentMethodsList
        initialCards={[
          {
            payment_method_id: 'pm_a',
            card_brand: 'visa',
            last4: '1111',
            expiry_month: '3',
            expiry_year: '2026',
            cardholder_name: 'Ada Lovelace',
            delete_enabled: true
          },
          {
            payment_method_id: 'pm_b',
            card_brand: 'mastercard',
            last4: '2222',
            expiry_month: '11',
            expiry_year: '27',
            cardholder_name: 'Grace Hopper',
            delete_enabled: true
          }
        ]}
        initialSelectedId={'pm_a'}
      />
    );

    const radios = screen.getAllByRole('radio');
    expect(radios).toHaveLength(2);

    const cardA = getRadioByPaymentMethodId('pm_a');
    const cardB = getRadioByPaymentMethodId('pm_b');

    expect(cardA).toHaveAttribute('aria-checked', 'true');
    expect(cardB).toHaveAttribute('aria-checked', 'false');

    await user.click(cardB);

    expect(cardA).toHaveAttribute('aria-checked', 'false');
    expect(cardB).toHaveAttribute('aria-checked', 'true');

    expect(screen.queryByRole('dialog', { name: /delete payment method\?/i })).not.toBeInTheDocument();
  });

  test('explore_card_accessibility_and_responsive_then_select: tab order card then delete; shift+tab and space selects', async () => {
    const user = userEvent.setup();

    const { container } = render(
      <div style={{ width: 320 }}>
        <TestPaymentMethodsList
          initialCards={[
            {
              payment_method_id: 'pm_x',
              card_brand: 'visa',
              last4: '3333',
              expiry_month: '9',
              expiry_year: '2028',
              cardholder_name: 'A very very long cardholder name that should truncate',
              delete_enabled: true
            }
          ]}
          initialSelectedId={undefined}
        />
      </div>
    );

    // Ensure we can find the two expected tab stops within the card: radio then delete.
    const tabbables = getAllTabbablesInOrder(container);
    const firstRadio = screen.getByRole('radio');
    const deleteBtn = getDeleteButtonForLast4('3333');

    // The first tabbable in the rendered UI should be the radio card (per decision).
    expect(tabbables[0]).toBe(firstRadio);

    await user.tab();
    expect(firstRadio).toHaveFocus();
    expect(firstRadio).toHaveAttribute('role', 'radio');

    // Masked number SR strategy is implemented in CardDetails; we validate presence of the label on some element.
    // This is an integration check that card_details is present and contains the aria-label.
    expect(container.querySelector('[aria-label="Card ending in 3333"]')).toBeTruthy();

    await user.tab();
    expect(deleteBtn).toHaveFocus();

    await user.tab({ shift: true });
    expect(firstRadio).toHaveFocus();

    await user.keyboard(' ');
    expect(firstRadio).toHaveAttribute('aria-checked', 'true');
  });

  test('delete_card_confirm_shortest: delete -> confirm -> busy -> removed from list', async () => {
    const user = userEvent.setup();

    render(
      <TestPaymentMethodsList
        initialCards={[
          {
            payment_method_id: 'pm_del',
            card_brand: 'mastercard',
            last4: '4444',
            expiry_month: '12',
            expiry_year: '2030',
            cardholder_name: 'Merchant Admin',
            delete_enabled: true
          },
          {
            payment_method_id: 'pm_keep',
            card_brand: 'visa',
            last4: '5555',
            expiry_month: '1',
            expiry_year: '29',
            cardholder_name: 'Second Card',
            delete_enabled: true
          }
        ]}
        initialSelectedId={'pm_keep'}
        deletePlanById={{ pm_del: ['success'] }}
      />
    );

    const cardToDelete = getRadioByPaymentMethodId('pm_del');
    const otherCard = getRadioByPaymentMethodId('pm_keep');
    expect(otherCard).toHaveAttribute('aria-checked', 'true');

    const deleteBtn = getDeleteButtonForLast4('4444');
    await user.click(deleteBtn);

    // Must not select the card when delete is activated.
    expect(otherCard).toHaveAttribute('aria-checked', 'true');
    expect(cardToDelete).toHaveAttribute('aria-checked', 'false');

    const dialog = screen.getByRole('dialog', { name: /delete payment method\?/i });
    expect(within(dialog).getByText(/delete payment method\?/i)).toBeInTheDocument();
    expect(within(dialog).getByText(/remove\s+Mastercard\s+card\s+ending\s+in\s+4444/i)).toBeInTheDocument();

    await user.click(within(dialog).getByRole('button', { name: /^delete$/i }));

    // Busy state while request is pending.
    expect(getRadioByPaymentMethodId('pm_del')).toHaveAttribute('aria-busy', 'true');

    await act(async () => {
      await new Promise((r) => setTimeout(r, 30));
    });

    // Removed from list and dialog closed.
    expect(screen.queryByRole('dialog', { name: /delete payment method\?/i })).not.toBeInTheDocument();

    const remainingRadios = screen.getAllByRole('radio');
    expect(remainingRadios).toHaveLength(1);
    expect(() => getRadioByPaymentMethodId('pm_del')).toThrow();

    // Remaining card still exists.
    expect(getRadioByPaymentMethodId('pm_keep')).toBeInTheDocument();
  });

  test('delete_attempt_disabled_unhappy: disabled delete blocks modal; user can still select card', async () => {
    const user = userEvent.setup();

    render(
      <TestPaymentMethodsList
        initialCards={[
          {
            payment_method_id: 'pm_locked',
            card_brand: 'visa',
            last4: '6666',
            expiry_month: '2',
            expiry_year: '27',
            cardholder_name: 'Locked Card',
            delete_enabled: false
          }
        ]}
        initialSelectedId={undefined}
        disabledReason={"You don’t have permission to delete this card"}
      />
    );

    const deleteBtn = getDeleteButtonForLast4('6666');
    expect(deleteBtn).toBeDisabled();

    // Explanation available via title/tooltip per decision.
    const title = deleteBtn.getAttribute('title') || '';
    expect(title).toMatch(/permission|delete/i);

    await user.click(deleteBtn);
    expect(screen.queryByRole('dialog', { name: /delete payment method\?/i })).not.toBeInTheDocument();

    const card = getRadioByPaymentMethodId('pm_locked');
    await user.click(card);
    expect(card).toHaveAttribute('aria-checked', 'true');
  });

  test('delete_confirm_then_api_error_retry_unhappy: failure shows alert and allows retry to success', async () => {
    const user = userEvent.setup();

    render(
      <TestPaymentMethodsList
        initialCards={[
          {
            payment_method_id: 'pm_err',
            card_brand: 'unknown',
            last4: '7777',
            expiry_month: '10',
            expiry_year: '2029',
            cardholder_name: 'Fallback Brand',
            delete_enabled: true
          }
        ]}
        deletePlanById={{ pm_err: ['error', 'success'] }}
      />
    );

    const deleteBtn = getDeleteButtonForLast4('7777');
    await user.click(deleteBtn);

    const dialog = screen.getByRole('dialog', { name: /delete payment method\?/i });
    // Unknown brand should fall back to generic "Card" descriptor.
    expect(within(dialog).getByText(/remove\s+Card\s+card\s+ending\s+in\s+7777/i)).toBeInTheDocument();

    await user.click(within(dialog).getByRole('button', { name: /^delete$/i }));

    // Busy while request pending.
    expect(getRadioByPaymentMethodId('pm_err')).toHaveAttribute('aria-busy', 'true');

    await act(async () => {
      await new Promise((r) => setTimeout(r, 30));
    });

    // Error shown inline and announced via role=alert.
    const alert = screen.getByRole('alert');
    expect(alert).toHaveTextContent("Couldn’t delete this payment method. Try again.");

    // Retry via inline affordance (expected by flow). We look for a button named Retry ending in 7777;
    // if implementation labels it differently, prefer a button with text "Retry" within the card.
    const retryBtn =
      screen.queryByRole('button', { name: /retry.*7777/i }) ||
      screen.queryByRole('button', { name: /^retry$/i }) ||
      (() => {
        const cardRoot = getRadioByPaymentMethodId('pm_err');
        const wrapper = cardRoot.parentElement ?? cardRoot;
        const btn = within(wrapper).queryByRole('button', { name: /retry/i });
        return btn;
      })();

    if (!retryBtn) {
      throw new Error('Expected a Retry affordance (button) to be rendered after deletion failure.');
    }

    await user.click(retryBtn);

    expect(getRadioByPaymentMethodId('pm_err')).toHaveAttribute('aria-busy', 'true');

    await act(async () => {
      await new Promise((r) => setTimeout(r, 30));
    });

    // Card removed.
    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
    expect(screen.queryAllByRole('radio')).toHaveLength(0);
  });
});

import React from 'react';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';
import { CardBrandIcon } from './CardBrandIcon';

function getRenderedGraphicElement(container: HTMLElement): HTMLElement {
  // Prefer semantic img, then svg, then anything with a test id if present.
  const img = container.querySelector('img');
  if (img) return img as HTMLElement;

  const svg = container.querySelector('svg');
  if (svg) return svg as HTMLElement;

  const testIdEl = container.querySelector('[data-testid]');
  if (testIdEl) return testIdEl as HTMLElement;

  throw new Error('Unable to find a rendered icon element (img/svg/[data-testid]).');
}

function expectSizeApplied(el: HTMLElement, sizePx: number) {
  // Implementation may use width/height attributes or styles.
  const widthAttr = el.getAttribute('width');
  const heightAttr = el.getAttribute('height');

  const widthStyle = (el as HTMLElement).style?.width;
  const heightStyle = (el as HTMLElement).style?.height;

  const expected = String(sizePx);
  const expectedPx = `${sizePx}px`;

  const matches =
    widthAttr === expected ||
    widthAttr === expectedPx ||
    heightAttr === expected ||
    heightAttr === expectedPx ||
    widthStyle === expected ||
    widthStyle === expectedPx ||
    heightStyle === expected ||
    heightStyle === expectedPx;

  expect(matches).toBe(true);
}

describe('CardBrandIcon', () => {
  it('defaults to decorative icon behavior (aria-hidden=true) when aria_hidden is omitted', () => {
    const { container } = render(<CardBrandIcon brand="visa" />);

    const graphic = getRenderedGraphicElement(container);

    // Decorative default per a11y decision.
    expect(graphic).toHaveAttribute('aria-hidden', 'true');

    // If the implementation uses role="img" when not hidden, ensure it is not exposed as an accessible image.
    // This assertion is tolerant: either no role=img exists, or if it does exist, it is aria-hidden.
    const exposedImg = screen.queryByRole('img');
    if (exposedImg) {
      expect(exposedImg).toHaveAttribute('aria-hidden', 'true');
    }
  });

  it('when aria_hidden=false and aria_label is provided, exposes an accessible name', () => {
    render(<CardBrandIcon brand="visa" aria_hidden={false} aria_label="Visa" />);

    // Expect an accessible graphic with name.
    // Works if implemented as <img alt="Visa" ...> or <svg role="img" aria-label="Visa">.
    expect(screen.getByRole('img', { name: 'Visa' })).toBeInTheDocument();
  });

  it('applies default size (24px) when size_px is omitted', () => {
    const { container } = render(<CardBrandIcon brand="mastercard" />);
    const graphic = getRenderedGraphicElement(container);

    expectSizeApplied(graphic, 24);
  });

  it('applies custom size_px to the icon dimensions', () => {
    const { container } = render(<CardBrandIcon brand="amex" size_px={32} />);
    const graphic = getRenderedGraphicElement(container);

    expectSizeApplied(graphic, 32);
  });

  it('renders a fallback icon for unknown brand', () => {
    const { container } = render(<CardBrandIcon brand="unknown" />);
    const graphic = getRenderedGraphicElement(container);

    // Ensure something is rendered.
    expect(graphic).toBeInTheDocument();

    // Heuristic: fallback should not advertise a known brand in src/alt/label.
    const src = graphic.getAttribute('src') || '';
    const ariaLabel = graphic.getAttribute('aria-label') || '';
    const alt = graphic.getAttribute('alt') || '';
    const combined = `${src} ${ariaLabel} ${alt}`.toLowerCase();

    expect(combined.includes('visa')).toBe(false);
    expect(combined.includes('mastercard')).toBe(false);
    expect(combined.includes('amex')).toBe(false);
  });

  it('treats unsupported brand values as fallback (generic icon)', () => {
    const { container } = render(<CardBrandIcon brand="diners" />);
    const graphic = getRenderedGraphicElement(container);

    expect(graphic).toBeInTheDocument();

    const src = graphic.getAttribute('src') || '';
    const ariaLabel = graphic.getAttribute('aria-label') || '';
    const alt = graphic.getAttribute('alt') || '';
    const combined = `${src} ${ariaLabel} ${alt}`.toLowerCase();

    expect(combined.includes('diners')).toBe(false);
  });
});

