describe('DeleteCardAction', () => {
  test('renders a button with accessible name including last4', () => {
    setup({ last4: '4242' });

    // Per a11y decision: unique accessible name like "Delete card ending in 4242" (icon-only or augmented label)
    const btn = screen.getByRole('button', { name: /delete.*ending in 4242/i });
