import React from 'react';

export type CardDetailsProps = {
  /** Masked card number text to render (e.g., "•••• •••• •••• 1234" or "**** **** **** 1234"). */
  masked_card_number: string;
  /** Last 4 digits used for accessible text (e.g., "1234"). */
  last4: string;
  /** Expiry date display string, expected in MM/YY format (e.g., "04/27"). */
  expiry_date: string;
  /** Cardholder name to display (single-line with ellipsis on overflow). */
  cardholder_name: string;
  /** Optional accessible label override for the masked number (defaults to "Card ending in {last4}"). */
  masked_number_aria_label?: string;
  /** Whether to apply overflow rules (title on cardholder name, no wrapping). */
  enable_overflow_rules?: boolean;
};

export function CardDetails(props: CardDetailsProps) {
  const {
    masked_card_number,
    last4,
    expiry_date,
    cardholder_name,
    masked_number_aria_label,
    enable_overflow_rules,
  } = props;

  const maskedNumberAriaLabel = masked_number_aria_label ?? `Card ending in ${last4}`;

  return (
    <div style={styles.root}>
      <div style={styles.rowTop}>
        {/*
          aria-label provides a screen-reader-friendly announcement so mask characters
          are not read out.
        */}
        <span aria-label={maskedNumberAriaLabel} style={enable_overflow_rules ? styles.noWrapEllipsis : styles.noWrap}>
          {masked_card_number}
        </span>

        <span style={styles.expiry}>{expiry_date}</span>
      </div>

      <div>
        <span
          style={enable_overflow_rules ? styles.noWrapEllipsisSecondary : styles.secondary}
          title={enable_overflow_rules ? cardholder_name : undefined}
        >
          {cardholder_name}
        </span>
      </div>
    </div>
  );
}

