import React from 'react';

type RequestDeletePaymentCardPayload = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
};

type ConfirmDeletePaymentCardPayload = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
};

type CancelDeletePaymentCardPayload = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
};

type RetryDeletePaymentCardPayload = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
};

export type DeleteCardActionProps = {
  payment_method_id: string;
  last4: string;
  card_brand: string;
  can_delete: boolean;
  disabled_reason?: string;
  is_deleting: boolean;
  on_request_delete: (payload: RequestDeletePaymentCardPayload) => void;
  on_confirm_delete: (payload: ConfirmDeletePaymentCardPayload) => void;
  on_cancel_delete: (payload: CancelDeletePaymentCardPayload) => void;
  on_retry_delete?: (payload: RetryDeletePaymentCardPayload) => void;
};

export function DeleteCardAction(props: DeleteCardActionProps) {
  const {
    payment_method_id,
    last4,
    card_brand,
    can_delete,
    disabled_reason,
    is_deleting,
    on_request_delete
  } = props;

  const disabled = !can_delete || is_deleting;
  const accessibleName = `Delete card ending in ${last4}`;

  const handleClick: React.MouseEventHandler<HTMLButtonElement> = (e) => {
    // Prevent parent selectable container from also handling click
    e.stopPropagation();

    if (disabled) return;

    on_request_delete({ payment_method_id, last4, card_brand });
  };

  const handleMouseDown: React.MouseEventHandler<HTMLButtonElement> = (e) => {
    // Also stop early propagation paths in some parent implementations
    e.stopPropagation();
  };

  const handleKeyDown: React.KeyboardEventHandler<HTMLButtonElement> = (e) => {
    // Avoid bubbling key events to parent (e.g., radio-card Space/Enter handlers)
    e.stopPropagation();
  };

  return (
    <button
      type="button"
      aria-label={accessibleName}
      disabled={disabled}
      title={!can_delete && disabled_reason ? disabled_reason : undefined}
      onClick={handleClick}
      onMouseDown={handleMouseDown}
      onKeyDown={handleKeyDown}
    >
      {is_deleting ? 'Deleting…' : 'Delete'}
    </button>
  );
}

import React from 'react';

import { CardBrandIcon } from '../CardBrandIcon/CardBrandIcon';
import { CardDetails } from '../CardDetails/CardDetails';
import { DeleteCardAction } from '../DeleteCardAction/DeleteCardAction';

type SelectPaymentCardPayload = { payment_method_id: string };
type DeletePaymentCardPayload = { payment_method_id: string };

export type PaymentCardProps = {
  payment_method_id: string;
  card_brand: string;
  last4: string;
  expiry_month: string;
  expiry_year: string;
  cardholder_name: string;
  selected: boolean;
  selectable?: boolean;
  delete_enabled?: boolean;
  dense?: boolean;
  deleting?: boolean;
  delete_error_message?: string;
  on_select: (payload: SelectPaymentCardPayload) => void;
  on_delete: (payload: DeletePaymentCardPayload) => void;
};

function normalizeExpiryMMYY(expiry_month: string, expiry_year: string): string {
  const monthNum = Number.parseInt(String(expiry_month), 10);
  const mm = Number.isFinite(monthNum) && monthNum > 0 ? String(monthNum).padStart(2, '0') : String(expiry_month).padStart(2, '0');

  const y = String(expiry_year);
  const yy = y.length === 4 ? y.slice(-2) : y.padStart(2, '0').slice(-2);
  return `${mm}/${yy}`;
}

function normalizeBrandForCopy(brand: string): string {
  const v = (brand || '').toLowerCase();
  if (v === 'visa') return 'Visa';
  if (v === 'mastercard') return 'Mastercard';
  if (v === 'amex') return 'Amex';
  return 'Card';
}

export function PaymentCard(props: PaymentCardProps) {
  const {
    payment_method_id,
    card_brand,
    last4,
    expiry_month,
    expiry_year,
    cardholder_name,
    selected,
    selectable = true,
    delete_enabled = true,
    dense = false,
    deleting = false,
    delete_error_message,
    on_select,
    on_delete
  } = props;

  const expiry = React.useMemo(() => normalizeExpiryMMYY(expiry_month, expiry_year), [expiry_month, expiry_year]);
  const masked = React.useMemo(() => `•••• •••• •••• ${last4}`, [last4]);
  const maskedNumberAriaLabel = React.useMemo(() => `Card ending in ${last4}`, [last4]);

  const canSelect = !!selectable;

  const onCardSelect = React.useCallback(() => {
    if (!canSelect) return;
    on_select({ payment_method_id });
  }, [canSelect, on_select, payment_method_id]);

  const onCardKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLElement>) => {
      if (!canSelect) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        on_select({ payment_method_id });
      }
    },
    [canSelect, on_select, payment_method_id]
  );

  const brandForCopy = normalizeBrandForCopy(card_brand);

  const disabledReason = "You don’t have permission to delete this card";

  return (
    <div
      role="radio"
      aria-checked={selected}
      aria-busy={deleting || undefined}
      tabIndex={canSelect ? 0 : -1}
      data-payment-method-id={payment_method_id}
      className={[
        'pc_root',
        selected ? 'pc_selected' : '',
        !canSelect ? 'pc_notSelectable' : '',
        dense ? 'pc_dense' : ''
      ]
        .filter(Boolean)
        .join(' ')}
      onClick={onCardSelect}
      onKeyDown={onCardKeyDown}
    >
      <div className="pc_inner">
        <div className="pc_brand">
          <CardBrandIcon brand={card_brand} aria_hidden={true} size_px={24} />
        </div>

        <div className="pc_details">
          <CardDetails
            masked_card_number={masked}
            last4={last4}
            expiry_date={expiry}
            cardholder_name={cardholder_name}
            masked_number_aria_label={maskedNumberAriaLabel}
            enable_overflow_rules={true}
          />

          {delete_error_message ? (
            <div className="pc_error" role="alert">
              <div className="pc_errorRow">
                <span className="pc_errorText">{delete_error_message}</span>
                {/* Retry affordance required by flow; keep outside DeleteCardAction mock contract. */}
                <button
                  type="button"
                  className="pc_retry"
                  aria-label={`Retry delete for card ending in ${last4}`}
                  onClick={(e) => {
                    e.stopPropagation();
                    on_delete({ payment_method_id });
                  }}
                  disabled={deleting}
                >
                  Retry
                </button>
              </div>
            </div>
          ) : null}
        </div>

        <div
          className="pc_delete"
          onClickCapture={(e) => {
            // prevent_select_on_delete: ensure events within delete affordance never select the card
            e.stopPropagation();
          }}
          onKeyDownCapture={(e) => {
            e.stopPropagation();
          }}
        >
          <DeleteCardAction
            payment_method_id={payment_method_id}
            last4={last4}
            card_brand={brandForCopy}
            can_delete={!!delete_enabled}
            disabled_reason={disabledReason}
            is_deleting={!!deleting}
            on_request_delete={() => {
              /* Confirmation modal is hosted by parent page (see e2e bridge). */
            }}
            on_confirm_delete={({ payment_method_id: pmid }: { payment_method_id: string }) => {
              on_delete({ payment_method_id: pmid });
            }}
            on_cancel_delete={() => {
              /* Parent hosts modal; no-op here. */
            }}
            on_retry_delete={({ payment_method_id: pmid }: { payment_method_id: string }) => {
              on_delete({ payment_method_id: pmid });
            }}
          />
        </div>
      </div>

      <style>{`
        .pc_root{
          width: 100%;
          box-sizing: border-box;
          display: block;
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border: 1px solid var(--color-border-subtle);
          border-radius: var(--radius-12);
          box-shadow: var(--shadow-sm);
          padding: var(--spacing-16);
          cursor: pointer;
          user-select: none;
        }

        .pc_dense{
          padding: var(--spacing-12);
        }

        .pc_root:hover{
          background: var(--color-surface-muted);
        }

        .pc_root:active{
          transform: scale(0.99);
        }

        .pc_root:focus-visible{
          outline: 2px solid var(--color-border-subtle);
          outline-offset: 2px;
        }

        .pc_notSelectable{
          cursor: default;
        }

        .pc_notSelectable:active{
          transform: none;
        }

        .pc_selected{
          border: 2px solid var(--color-text-primary);
          background: var(--color-surface-muted);
        }

        .pc_inner{
          display: flex;
          align-items: center;
          gap: var(--spacing-12);
          min-width: 0;
        }

        .pc_brand{
          flex: 0 0 auto;
          display: flex;
          align-items: center;
        }

        .pc_details{
          flex: 1 1 auto;
          min-width: 0;
        }

        .pc_delete{
          flex: 0 0 auto;
          display: flex;
          align-items: center;
          margin-left: var(--spacing-8);
        }

        .pc_error{
          margin-top: var(--spacing-8);
          color: var(--color-status-danger);
          font-size: var(--font-size-body);
        }

        .pc_errorRow{
          display: flex;
          gap: var(--spacing-8);
          align-items: baseline;
          justify-content: space-between;
        }

        .pc_errorText{
          min-width: 0;
        }

        .pc_retry{
          flex: 0 0 auto;
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border-radius: var(--radius-8);
          padding: var(--spacing-8);
          font-size: var(--font-size-label);
          font-weight: var(--font-weight-medium);
          cursor: pointer;
        }

        .pc_retry:hover{
          background: var(--color-surface-muted);
        }

        .pc_retry:focus-visible{
          outline: 2px solid var(--color-border-subtle);
          outline-offset: 2px;
        }

        .pc_retry:disabled{
          cursor: default;
          opacity: 0.7;
        }
      `}</style>
    </div>
  );
}

