import { CardDetails } from './CardDetails';

describe('CardDetails', () => {
  const baseProps = {
    masked_card_number: '•••• •••• •••• 1234',
    last4: '1234',
    expiry_date: '04/27',
    cardholder_name: 'Jane Merchant',
  };

  it('renders the provided masked card number, expiry date, and cardholder name', () => {
    render(<CardDetails {...baseProps} />);

    expect(screen.getByText('•••• •••• •••• 1234')).toBeInTheDocument();
    expect(screen.getByText('04/27')).toBeInTheDocument();
    expect(screen.getByText('Jane Merchant')).toBeInTheDocument();
  });

