    const { container } = render(<CardDetails {...baseProps} />);

    // We don't assume a specific element/role for the masked number; we assert the aria-label exists somewhere.
    const el = container.querySelector('[aria-label="Card ending in 1234"]');
    expect(el).toBeTruthy();
  });

  it('uses masked_number_aria_label when provided', () => {
    const { container } = render(
      <CardDetails {...baseProps} masked_number_aria_label="Payment card ending in 1234" />
    );

    expect(container.querySelector('[aria-label="Payment card ending in 1234"]')).toBeTruthy();
    expect(container.querySelector('[aria-label="Card ending in 1234"]')).toBeFalsy();
  });

  it('when enable_overflow_rules is true, sets title on cardholder name to the full value', () => {
    render(<CardDetails {...baseProps} enable_overflow_rules={true} />);

    const nameEl = screen.getByText('Jane Merchant');
    expect(nameEl).toHaveAttribute('title', 'Jane Merchant');
  });

  it('when enable_overflow_rules is false/undefined, does not set title on cardholder name', () => {
    const { rerender } = render(<CardDetails {...baseProps} />);
    expect(screen.getByText('Jane Merchant')).not.toHaveAttribute('title');

    rerender(<CardDetails {...baseProps} enable_overflow_rules={false} />);
    expect(screen.getByText('Jane Merchant')).not.toHaveAttribute('title');
  });
});
"}]}

