{"componentCode":"delete_card_action","componentName":"Delete Card Action","coveredBehaviors":["Renders a native button with an accessible name including last4 ("Delete card ending in {last4}")","When can_delete=false, button is disabled, shows disabled_reason as title/tooltip, and does not invoke on_request_delete","When can_delete=true, clicking the button invokes on_request_delete with payment_method_id, last4, and card_brand","When is_deleting=true, button is disabled to prevent interactions (request/confirm/cancel)","Stops click event propagation to prevent parent card selection when delete is activated"],"coveredStates":["Enabled (can_delete=true, is_deleting=false)","Disabled (can_delete=false)","Deleting/in-progress (is_deleting=true)"],"files":[{"filename":"/app/generated/frontend/src/components/DeleteCardAction/DeleteCardAction.spec.tsx","content":"import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { DeleteCardAction } from './DeleteCardAction';

function setup(overrides: Partial<React.ComponentProps<typeof DeleteCardAction>> = {}) {
  const props: React.ComponentProps<typeof DeleteCardAction> = {
    payment_method_id: 'pm_123',
    last4: '1234',
    card_brand: 'Visa',
    can_delete: true,
    disabled_reason: "You don’t have permission to delete this card",
    is_deleting: false,
    on_request_delete: jest.fn(),
    on_confirm_delete: jest.fn(),
    on_cancel_delete: jest.fn(),
    on_retry_delete: jest.fn(),
    ...overrides
  };

  const user = userEvent.setup();
  const view = render(<DeleteCardAction {...props} />);
  return { ...view, user, props };
}

describe('DeleteCardAction', () => {
  test('renders a button with accessible name including last4', () => {
    setup({ last4: '4242' });

    // Per a11y decision: unique accessible name like "Delete card ending in 4242" (icon-only or augmented label)
    const btn = screen.getByRole('button', { name: /delete.*ending in 4242/i });
    expect(btn).toBeInTheDocument();
  });

  test('when can_delete=false, button is disabled and carries disabled_reason as title; clicking does not request delete', async () => {
    const { user, props } = setup({ can_delete: false, is_deleting: false, disabled_reason: 'Not allowed' });

    const btn = screen.getByRole('button', { name: /delete.*ending in 1234/i });
    expect(btn).toBeDisabled();

    // Tooltip/title availability decision
    expect(btn).toHaveAttribute('title', 'Not allowed');

    await user.click(btn);
    expect(props.on_request_delete).not.toHaveBeenCalled();
  });

  test('when enabled, clicking requests delete with payload containing payment_method_id, last4, and card_brand', async () => {
    const { user, props } = setup({
      payment_method_id: 'pm_999',
      last4: '0005',
      card_brand: 'Card',
      can_delete: true,
      is_deleting: false
    });

    const btn = screen.getByRole('button', { name: /delete.*ending in 0005/i });
    await user.click(btn);

    expect(props.on_request_delete).toHaveBeenCalledTimes(1);
    expect(props.on_request_delete).toHaveBeenCalledWith(
      expect.objectContaining({
        payment_method_id: 'pm_999',
        last4: '0005',
        card_brand: 'Card'
      })
    );
  });

  test('when is_deleting=true, button is disabled and does not invoke callbacks on click', async () => {
    const { user, props } = setup({ is_deleting: true, can_delete: true });

    const btn = screen.getByRole('button', { name: /delete/i });
    expect(btn).toBeDisabled();

    await user.click(btn);
    expect(props.on_request_delete).not.toHaveBeenCalled();
    expect(props.on_confirm_delete).not.toHaveBeenCalled();
    expect(props.on_cancel_delete).not.toHaveBeenCalled();
  });

  test('stops click propagation so parent container onClick is not triggered', async () => {
    const user = userEvent.setup();
    const parentOnClick = jest.fn();

    render(
      <div onClick={parentOnClick} data-testid="parent">
        <DeleteCardAction
          payment_method_id="pm_1"
          last4="1234"
          card_brand="Visa"
          can_delete={true}
          is_deleting={false}
          on_request_delete={jest.fn()}
          on_confirm_delete={jest.fn()}
          on_cancel_delete={jest.fn()}
        />
      </div>
    );

    const btn = screen.getByRole('button', { name: /delete.*ending in 1234/i });
    await user.click(btn);

    expect(parentOnClick).not.toHaveBeenCalled();
  });

  test('stops propagation on native click event (bubbles) as well', () => {
    const parentOnClick = jest.fn();

    render(
      <div onClick={parentOnClick}>
        <DeleteCardAction
          payment_method_id="pm_1"
          last4="1234"
          card_brand="Visa"
          can_delete={true}
          is_deleting={false}
          on_request_delete={jest.fn()}
          on_confirm_delete={jest.fn()}
          on_cancel_delete={jest.fn()}
        />
      </div>
    );

    const btn = screen.getByRole('button', { name: /delete.*ending in 1234/i });

    // Ensure bubbling click does not reach parent
    fireEvent.click(btn);
    expect(parentOnClick).not.toHaveBeenCalled();
  });
});
"}]}

