import '@testing-library/jest-dom';
import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

import { PaymentCard } from './PaymentCard';

type CardModel = {
  payment_method_id: string;
  card_brand: string;
  last4: string;
  expiry_month: string;
  expiry_year: string;
  cardholder_name: string;
  selectable?: boolean;
  delete_enabled?: boolean;
};

type DeleteOutcome = 'success' | 'error';

function normalizeBrandForCopy(card_brand: string): string {
  const v = (card_brand || '').toLowerCase();
  if (v === 'visa') return 'Visa';
  if (v === 'mastercard') return 'Mastercard';
  if (v === 'amex') return 'Amex';
  return 'Card';
}

function getRadioByPaymentMethodId(pmId: string): HTMLElement {
  const radios = screen.getAllByRole('radio');
  const match = radios.find((r) => r.getAttribute('data-payment-method-id') === pmId);
  if (match) return match;

  // Fallback if implementation does not include data attribute:
  // assume each card exposes an accessible string with last4; tests using this fallback are more brittle.
  throw new Error(
    `Unable to locate payment_card radio for payment_method_id=${pmId}. ` +
      `Expected a role=radio element with data-payment-method-id attribute.`
  );
}

function getDeleteButtonForLast4(last4: string): HTMLButtonElement {
  return screen.getByRole('button', { name: new RegExp(`delete.*ending in\\s*${last4}`, 'i') }) as HTMLButtonElement;
}

function getAllTabbablesInOrder(container: HTMLElement): HTMLElement[] {
  const sel = [
    'button:not([disabled])',
    '[href]',
    'input:not([disabled])',
    'select:not([disabled])',
    'textarea:not([disabled])',
    '[tabindex]:not([tabindex="-1"])'
  ].join(',');

  const nodes = Array.from(container.querySelectorAll(sel)) as HTMLElement[];
  return nodes.filter((el) => {
    // Basic visibility filter
    const style = window.getComputedStyle(el);
    return style.visibility !== 'hidden' && style.display !== 'none';
  });
}

function TestPaymentMethodsList(props: {
  initialCards: CardModel[];
  initialSelectedId?: string;
  disabledReason?: string;
  deletePlanById?: Record<string, DeleteOutcome[]>; // each confirm/retry consumes one outcome
}) {
  const {
    initialCards,
    initialSelectedId,
    disabledReason = "You don’t have permission to delete this card",
    deletePlanById = {}
  } = props;

  const [cards, setCards] = React.useState<CardModel[]>(initialCards);
  const [selectedId, setSelectedId] = React.useState<string | undefined>(initialSelectedId);

  const [modal, setModal] = React.useState<
    | null
    | {
        payment_method_id: string;
        last4: string;
        card_brand: string;
      }
  >(null);

  const [deletingId, setDeletingId] = React.useState<string | null>(null);
  const [deleteErrorById, setDeleteErrorById] = React.useState<Record<string, string>>({});

  const planIndexRef = React.useRef<Record<string, number>>({});

  const beginDelete = React.useCallback((payment_method_id: string) => {
    setDeletingId(payment_method_id);

    // simulate async request
    setTimeout(() => {
      const idx = planIndexRef.current[payment_method_id] ?? 0;
      const plan = deletePlanById[payment_method_id] ?? ['success'];
      const outcome = plan[Math.min(idx, plan.length - 1)] ?? 'success';
      planIndexRef.current[payment_method_id] = idx + 1;

      if (outcome === 'success') {
        setCards((prev) => prev.filter((c) => c.payment_method_id !== payment_method_id));
        setDeleteErrorById((prev) => {
          const next = { ...prev };
          delete next[payment_method_id];
          return next;
        });
        setModal(null);
        setDeletingId(null);

        // If deleted card was selected, clear selection.
        setSelectedId((prev) => (prev === payment_method_id ? undefined : prev));
      } else {
        setDeletingId(null);
        setModal(null);
        setDeleteErrorById((prev) => ({
          ...prev,
          [payment_method_id]: "Couldn’t delete this payment method. Try again."
        }));
      }
    }, 20);
  }, [deletePlanById]);

  return (
    <div>
      <h1>Saved payment methods</h1>

      {/* Render list of PaymentCard components */}
      <div aria-label="Saved payment methods list">
        {cards.map((c) => (
          <div key={c.payment_method_id} style={{ marginBottom: 12 }}>
            <PaymentCard
              payment_method_id={c.payment_method_id}
              card_brand={c.card_brand}
              last4={c.last4}
              expiry_month={c.expiry_month}
              expiry_year={c.expiry_year}
              cardholder_name={c.cardholder_name}
              selected={selectedId === c.payment_method_id}
              selectable={c.selectable}
              delete_enabled={c.delete_enabled}
              deleting={deletingId === c.payment_method_id}
              delete_error_message={deleteErrorById[c.payment_method_id]}
              on_select={({ payment_method_id }) => setSelectedId(payment_method_id)}
              on_delete={({ payment_method_id }) => beginDelete(payment_method_id)}
            />
          </div>
        ))}
      </div>

      {/* Confirmation modal per resolving-gaps decision */}
      {modal ? (
        <div role="dialog" aria-modal="true" aria-label="Delete payment method?">
          <h2>Delete payment method?</h2>
          <p>
            This will remove {normalizeBrandForCopy(modal.card_brand)} card ending in {modal.last4} from your saved payment
            methods.
          </p>
          <div>
            <button
              type="button"
              onClick={() => beginDelete(modal.payment_method_id)}
            >
              Delete
            </button>
            <button
              type="button"
              onClick={() => {
                setModal(null);
                // Focus return is handled by parent in real app; best-effort here.
                const btn = getDeleteButtonForLast4(modal.last4);
                btn?.focus();
              }}
            >
              Cancel
            </button>
          </div>
        </div>
      ) : null}

      {/* Glue layer: capture DeleteCardAction's request/confirm/cancel/retry via DOM event hooks.
          The generated PaymentCard is expected to wire DeleteCardAction internally; we don't mock child components.
          Instead, we open the modal when the user activates the delete button in the card.

          We implement this by listening for click on buttons with the expected accessible name, and mapping them back
          to a card using last4 present in the name.
      */}
      <DeleteFlowBridge
        cards={cards}
        disabledReason={disabledReason}
        onOpenModal={(m) => setModal(m)}
        onRetry={(payment_method_id) => beginDelete(payment_method_id)}
        onSetDisabledTitle={() => {
          // no-op; exists for clarity
        }}
      />
    </div>
  );
}

function DeleteFlowBridge(props: {
  cards: CardModel[];
  disabledReason: string;
  onOpenModal: (m: { payment_method_id: string; last4: string; card_brand: string }) => void;
  onRetry: (payment_method_id: string) => void;
  onSetDisabledTitle: () => void;
}) {
  const { cards, onOpenModal, onRetry } = props;

  React.useEffect(() => {
    const handler = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      if (!target) return;

      // Identify delete button click by accessible name pattern.
      if (target instanceof HTMLButtonElement) {
        const name = target.getAttribute('aria-label') || target.textContent || '';

        const m = name.match(/ending in\s*(\d{4})/i);
        const last4 = m?.[1];
        if (!last4) return;

        // If this is a Retry affordance within the card, trigger retry.
        if (/retry/i.test(name) || /retry/i.test(target.textContent || '')) {
          const card = cards.find((c) => c.last4 === last4);
          if (!card) return;
          onRetry(card.payment_method_id);
          return;
        }

        // If this is the delete activation button, open modal. We do not open modal for disabled buttons.
        if (/delete/i.test(name)) {
          const card = cards.find((c) => c.last4 === last4);
          if (!card) return;
          if (target.disabled) return;
          onOpenModal({ payment_method_id: card.payment_method_id, last4: card.last4, card_brand: card.card_brand });
        }
      }
    };

    document.addEventListener('click', handler, true);
    return () => document.removeEventListener('click', handler, true);
  }, [cards, onOpenModal, onRetry]);

  return null;
}

describe('PaymentCard composed workflow (e2e)', () => {
  test('select_card_click_shortest: click card selects it (radio semantics) and does not trigger deletion UI', async () => {
    const user = userEvent.setup();

    render(
      <TestPaymentMethodsList
        initialCards={[
          {
            payment_method_id: 'pm_a',
            card_brand: 'visa',
            last4: '1111',
            expiry_month: '3',
            expiry_year: '2026',
            cardholder_name: 'Ada Lovelace',
            delete_enabled: true
          },
          {
            payment_method_id: 'pm_b',
            card_brand: 'mastercard',
            last4: '2222',
            expiry_month: '11',
            expiry_year: '27',
            cardholder_name: 'Grace Hopper',
            delete_enabled: true
          }
        ]}
        initialSelectedId={'pm_a'}
      />
    );

    const radios = screen.getAllByRole('radio');
    expect(radios).toHaveLength(2);

    const cardA = getRadioByPaymentMethodId('pm_a');
    const cardB = getRadioByPaymentMethodId('pm_b');

    expect(cardA).toHaveAttribute('aria-checked', 'true');
    expect(cardB).toHaveAttribute('aria-checked', 'false');

    await user.click(cardB);

    expect(cardA).toHaveAttribute('aria-checked', 'false');
    expect(cardB).toHaveAttribute('aria-checked', 'true');

    expect(screen.queryByRole('dialog', { name: /delete payment method\?/i })).not.toBeInTheDocument();
  });

  test('explore_card_accessibility_and_responsive_then_select: tab order card then delete; shift+tab and space selects', async () => {
    const user = userEvent.setup();

    const { container } = render(
      <div style={{ width: 320 }}>
        <TestPaymentMethodsList
          initialCards={[
            {
              payment_method_id: 'pm_x',
              card_brand: 'visa',
              last4: '3333',
              expiry_month: '9',
              expiry_year: '2028',
              cardholder_name: 'A very very long cardholder name that should truncate',
              delete_enabled: true
            }
          ]}
          initialSelectedId={undefined}
        />
      </div>
    );

    // Ensure we can find the two expected tab stops within the card: radio then delete.
    const tabbables = getAllTabbablesInOrder(container);
    const firstRadio = screen.getByRole('radio');
    const deleteBtn = getDeleteButtonForLast4('3333');

    // The first tabbable in the rendered UI should be the radio card (per decision).
    expect(tabbables[0]).toBe(firstRadio);

    await user.tab();
    expect(firstRadio).toHaveFocus();
    expect(firstRadio).toHaveAttribute('role', 'radio');

    // Masked number SR strategy is implemented in CardDetails; we validate presence of the label on some element.
    // This is an integration check that card_details is present and contains the aria-label.
    expect(container.querySelector('[aria-label="Card ending in 3333"]')).toBeTruthy();

    await user.tab();
    expect(deleteBtn).toHaveFocus();

    await user.tab({ shift: true });
    expect(firstRadio).toHaveFocus();

    await user.keyboard(' ');
    expect(firstRadio).toHaveAttribute('aria-checked', 'true');
  });

  test('delete_card_confirm_shortest: delete -> confirm -> busy -> removed from list', async () => {
    const user = userEvent.setup();

    render(
      <TestPaymentMethodsList
        initialCards={[
          {
            payment_method_id: 'pm_del',
            card_brand: 'mastercard',
            last4: '4444',
            expiry_month: '12',
            expiry_year: '2030',
            cardholder_name: 'Merchant Admin',
            delete_enabled: true
          },
          {
            payment_method_id: 'pm_keep',
