  test('delete_confirm_then_api_error_retry_unhappy: failure shows alert and allows retry to success', async () => {
    const user = userEvent.setup();

    render(
      <TestPaymentMethodsList
        initialCards={[
          {
            payment_method_id: 'pm_err',
            card_brand: 'unknown',
            last4: '7777',
            expiry_month: '10',
