    );

    const deleteBtn = getDeleteButtonForLast4('7777');
    await user.click(deleteBtn);

    const dialog = screen.getByRole('dialog', { name: /delete payment method\?/i });
    // Unknown brand should fall back to generic "Card" descriptor.
    expect(within(dialog).getByText(/remove\s+Card\s+card\s+ending\s+in\s+7777/i)).toBeInTheDocument();

