import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { PaymentCard } from './PaymentCard';

jest.mock('../CardBrandIcon/CardBrandIcon', () => {
  return {
    CardBrandIcon: (props: any) => (
      <div
        data-testid="card-brand-icon"
        data-brand={props.brand}
        data-aria-hidden={String(props.aria_hidden)}
        data-aria-label={props.aria_label ?? ''}
        data-size={String(props.size_px ?? '')}
      />
    )
  };
});

jest.mock('../CardDetails/CardDetails', () => {
  return {
    CardDetails: (props: any) => (
      <div
        data-testid="card-details"
        data-masked={props.masked_card_number}
        data-last4={props.last4}
        data-expiry={props.expiry_date}
        data-name={props.cardholder_name}
        data-masked-aria={props.masked_number_aria_label ?? ''}
        data-overflow={String(!!props.enable_overflow_rules)}
      />
    )
  };
});

// Mock DeleteCardAction to:
// - expose a "Delete" button
// - stop propagation to ensure clicking it does not select the card
// - provide buttons to simulate confirm and retry callbacks
jest.mock('../DeleteCardAction/DeleteCardAction', () => {
  return {
    DeleteCardAction: (props: any) => {
      const disabled = !props.can_delete || !!props.is_deleting;
      return (
        <div data-testid="delete-card-action">
          <button
            type="button"
            data-testid="delete-button"
            disabled={disabled}
            title={props.disabled_reason}
            aria-label={`Delete card ending in ${props.last4}`}
            onClick={(e) => {
              e.stopPropagation();
              if (!disabled) props.on_request_delete({ payment_method_id: props.payment_method_id });
            }}
          >
            Delete
          </button>
          <button
            type="button"
            data-testid="confirm-delete"
            onClick={(e) => {
              e.stopPropagation();
              props.on_confirm_delete({ payment_method_id: props.payment_method_id });
            }}
          >
            Confirm
          </button>
          <button
            type="button"
            data-testid="retry-delete"
            onClick={(e) => {
              e.stopPropagation();
              props.on_retry_delete?.({ payment_method_id: props.payment_method_id });
            }}
          >
            Retry
          </button>
        </div>
      );
    }
  };
});

describe('PaymentCard', () => {
  const baseProps = {
    payment_method_id: 'pm_123',
    card_brand: 'visa',
    last4: '1234',
    expiry_month: '3',
    expiry_year: '2026',
    cardholder_name: 'Ada Lovelace',
    selected: false,
    on_select: jest.fn(),
    on_delete: jest.fn()
  };

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders with role="radio" and aria-checked reflecting selected state', () => {
    const { rerender } = render(<PaymentCard {...baseProps} selected={false} />);

    const radio = screen.getByRole('radio');
    expect(radio).toHaveAttribute('aria-checked', 'false');

    rerender(<PaymentCard {...baseProps} selected={true} />);
    expect(screen.getByRole('radio')).toHaveAttribute('aria-checked', 'true');
  });

  it('is focusable when selectable (default) and selects via click, emitting payment_method_id', async () => {
    const user = userEvent.setup();
    render(<PaymentCard {...baseProps} />);

    const radio = screen.getByRole('radio');
    expect(radio).toHaveAttribute('tabindex', '0');

    await user.click(radio);
    expect(baseProps.on_select).toHaveBeenCalledTimes(1);
    expect(baseProps.on_select).toHaveBeenCalledWith({ payment_method_id: 'pm_123' });
  });

  it('selects via keyboard Enter and Space when focus is on the card', async () => {
    const user = userEvent.setup();
    render(<PaymentCard {...baseProps} />);

    const radio = screen.getByRole('radio');
    radio.focus();
    expect(radio).toHaveFocus();

    await user.keyboard('{Enter}');
    await user.keyboard(' ');

    expect(baseProps.on_select).toHaveBeenCalledTimes(2);
    expect(baseProps.on_select).toHaveBeenNthCalledWith(1, { payment_method_id: 'pm_123' });
    expect(baseProps.on_select).toHaveBeenNthCalledWith(2, { payment_method_id: 'pm_123' });
  });

  it('when selectable=false, is not focusable and does not emit selection on click/keyboard', async () => {
    const user = userEvent.setup();
    render(<PaymentCard {...baseProps} selectable={false} />);

    const radio = screen.getByRole('radio');

    // Not focusable
    expect(radio.getAttribute('tabindex')).not.toBe('0');

    await user.click(radio);

    // Try to focus and activate anyway
    radio.focus();
    await user.keyboard('{Enter}');
    await user.keyboard(' ');

    expect(baseProps.on_select).not.toHaveBeenCalled();
  });

  it('passes brand to CardBrandIcon and renders it decorative by default', () => {
    render(<PaymentCard {...baseProps} card_brand="mastercard" />);

    const icon = screen.getByTestId('card-brand-icon');
    expect(icon).toHaveAttribute('data-brand', 'mastercard');

    // The a11y decision: brand icon treated as decorative by default.
    // We verify aria_hidden was passed as true (stringified).
    expect(icon).toHaveAttribute('data-aria-hidden', 'true');
  });

  it('formats expiry as MM/YY and passes masked card number + details to CardDetails', () => {
    render(
      <PaymentCard
        {...baseProps}
        expiry_month="3"
        expiry_year="2026"
        last4="4242"
        cardholder_name="Grace Hopper"
      />
    );

    const details = screen.getByTestId('card-details');

    // Expect month padded to 2 digits; year normalized to 2 digits.
    expect(details).toHaveAttribute('data-expiry', '03/26');

    // Masking rule: visible masked number uses last4
    const masked = details.getAttribute('data-masked') ?? '';
    expect(masked).toContain('4242');

    expect(details).toHaveAttribute('data-last4', '4242');
    expect(details).toHaveAttribute('data-name', 'Grace Hopper');

    // Screen-reader strategy for masked number: label includes last4
    const srLabel = details.getAttribute('data-masked-aria') ?? '';
    expect(srLabel).toContain('4242');
  });

  it('sets aria-busy on the card container when deleting=true', () => {
    render(<PaymentCard {...baseProps} deleting={true} />);

    const radio = screen.getByRole('radio');
    expect(radio).toHaveAttribute('aria-busy', 'true');
  });

  it('renders inline deletion error message with role="alert" when delete_error_message is provided', () => {
    render(
      <PaymentCard
        {...baseProps}
        delete_error_message="Couldn’t delete this payment method. Try again."
      />
    );

    const alert = screen.getByRole('alert');
    expect(alert).toHaveTextContent("Couldn’t delete this payment method. Try again.");
  });

  it('wires deletion: confirming delete triggers on_delete with payment_method_id', async () => {
    const user = userEvent.setup();
    render(<PaymentCard {...baseProps} />);

    await user.click(screen.getByTestId('confirm-delete'));

    expect(baseProps.on_delete).toHaveBeenCalledTimes(1);
    expect(baseProps.on_delete).toHaveBeenCalledWith({ payment_method_id: 'pm_123' });
  });

  it('wires deletion retry: clicking Retry triggers on_delete with payment_method_id', async () => {
    const user = userEvent.setup();
    render(<PaymentCard {...baseProps} delete_error_message="Error" />);

    await user.click(screen.getByTestId('retry-delete'));

    expect(baseProps.on_delete).toHaveBeenCalledTimes(1);
    expect(baseProps.on_delete).toHaveBeenCalledWith({ payment_method_id: 'pm_123' });
  });

  it('prevents select-on-delete collision: clicking delete button does not trigger on_select', async () => {
    const user = userEvent.setup();
    render(<PaymentCard {...baseProps} />);

    await user.click(screen.getByTestId('delete-button'));

    expect(baseProps.on_select).not.toHaveBeenCalled();
  });

  it('forwards delete_enabled=false to DeleteCardAction as disabled with a disabled_reason/title', () => {
    render(
      <PaymentCard
        {...baseProps}
        delete_enabled={false}
      />
    );

    const deleteBtn = screen.getByTestId('delete-button') as HTMLButtonElement;
    expect(deleteBtn.disabled).toBe(true);

    // We can only assert title is present if PaymentCard passes a default reason.
    // If not implemented, this assertion can be adjusted.
    expect(deleteBtn.getAttribute('title') ?? '').toMatch(/permission|delete/i);
  });
});
