// Mock DeleteCardAction to:
// - expose a "Delete" button
// - stop propagation to ensure clicking it does not select the card
// - provide buttons to simulate confirm and retry callbacks
jest.mock('../DeleteCardAction/DeleteCardAction', () => {
  return {
    DeleteCardAction: (props: any) => {
      const disabled = !props.can_delete || !!props.is_deleting;
      return (
        <div data-testid="delete-card-action">
          <button
            type="button"
            data-testid="delete-button"
            disabled={disabled}
            title={props.disabled_reason}
            aria-label={`Delete card ending in ${props.last4}`}
            onClick={(e) => {
              e.stopPropagation();
              if (!disabled) props.on_request_delete({ payment_method_id: props.payment_method_id });
            }}
          >
            Delete
          </button>
          <button
            type="button"
            data-testid="confirm-delete"
            onClick={(e) => {
