import React, { useEffect, useId, useMemo, useRef } from 'react';
import { DocumentUpload } from '../DocumentUpload/DocumentUpload';

export type KycDocumentUploadItem = {
  id: string;
  file_name?: string;
  status?: 'empty' | 'selected' | 'uploading' | 'success' | 'failure' | 'removed';
  [key: string]: any;
};

export type KycUploadError = {
  code: string;
  message: string;
  [key: string]: any;
};

export type DocumentUploadStepProps = {
  step_title: string;
  is_active: boolean;
  is_busy?: boolean;

  documents: KycDocumentUploadItem[];
  accepted_mime_types: string[];
  max_file_size_bytes: number;
  max_file_count: number;

  is_step_valid: boolean;
  blocking_error?: string;
  upload_errors?: KycUploadError[];
  instructions_text: string;

  on_add_files: (files: File[], source: 'picker' | 'drop') => void;
  on_remove_file: (document_id: string) => void;
  on_retry_upload?: (document_id: string) => void;
  on_step_validity_change?: (is_valid: boolean) => void;
};

export function DocumentUploadStep(props: DocumentUploadStepProps) {
  const {
    step_title,
    is_active,
    is_busy = false,
    documents,
    accepted_mime_types,
    max_file_size_bytes,
    max_file_count,
    is_step_valid,
    blocking_error,
    upload_errors,
    instructions_text,
    on_add_files,
    on_remove_file,
    on_retry_upload,
    on_step_validity_change
  } = props;

  const reactId = useId();
  const instructionsId = `document-upload-instructions-${reactId}`;
  const blockingErrorId = `document-upload-blocking-error-${reactId}`;

  const prevValidityRef = useRef<boolean | null>(null);
  useEffect(() => {
    if (!on_step_validity_change) return;
    if (prevValidityRef.current === null) {
      prevValidityRef.current = is_step_valid;
      return;
    }
    if (prevValidityRef.current !== is_step_valid) {
      prevValidityRef.current = is_step_valid;
      on_step_validity_change(is_step_valid);
    }
  }, [is_step_valid, on_step_validity_change]);

  const disabled = is_active && is_busy;

  const describedBy = useMemo(() => {
    const ids = [instructionsId];
    if (!is_step_valid && blocking_error) ids.push(blockingErrorId);
    return ids.join(' ');
  }, [instructionsId, is_step_valid, blocking_error, blockingErrorId]);

  // Keep minimal but deterministic mapping for a11y + tests.
  const isInvalid = !is_step_valid;

  // Presentational drag state / aria-live are owned by DocumentUpload; step does not compute it.
  const drag_state = 'idle';
  const aria_live_message = undefined;

  // Label isn't in the interface, but the test mock expects it to exist (can be undefined).
  const label = 'Upload documents';

  // Step container should only be aria-busy when both active and busy.
  const stepContainerProps: React.HTMLAttributes<HTMLDivElement> = {};
  if (is_active && is_busy) stepContainerProps['aria-busy'] = 'true';

  return (
    <div {...stepContainerProps} style={{ display: is_active ? 'block' : 'none' }}>
      <h2 tabIndex={-1}>{step_title}</h2>

      <div id={instructionsId} style={{ fontSize: 'var(--font-size-body)', color: 'var(--color-text-secondary)' }}>
        {instructions_text}
      </div>

      {!is_step_valid && blocking_error ? (
        <div
          id={blockingErrorId}
          role="alert"
          style={{
            marginTop: 'var(--spacing-8)',
            color: 'var(--color-status-danger)',
            fontSize: 'var(--font-size-body)'
          }}
        >
          {blocking_error}
        </div>
      ) : null}

      <div style={{ marginTop: 'var(--spacing-12)' }}>
        <DocumentUpload
          files={documents as any}
          accepted_mime_types={accepted_mime_types}
          max_file_size_bytes={max_file_size_bytes}
          max_files={max_file_count}
          instructions_id={describedBy}
          label={label}
          drag_state={drag_state}
          aria_live_message={aria_live_message}
          errors={upload_errors}
          is_invalid={isInvalid}
          disabled={disabled}
          on_add_files={(payload: { files: File[]; source: 'picker' | 'drop' }) => {
            on_add_files(payload.files, payload.source);
          }}
          on_remove_file={(payload: { document_id: string }) => {
            on_remove_file(payload.document_id);
          }}
          on_retry_file={(payload: { document_id: string }) => {
            on_retry_upload?.(payload.document_id);
          }}
        />
      </div>
    </div>
  );
}

import React from 'react';

export type KycStepIndicatorStep = {
  id: string;
  label: string;
};

export type KycStepIndicatorStepClickPayload = {
  step_index: number;
  step: KycStepIndicatorStep;
};

export type KycStepIndicatorProps = {
  steps: KycStepIndicatorStep[];
  active_step_index: number;
  max_completed_step_index: number;
  aria_label?: string;
  variant?: 'condensed' | 'full';
  on_step_click?: (payload: KycStepIndicatorStepClickPayload) => void;
};

export function KycStepIndicator({
  steps,
  active_step_index,
  max_completed_step_index,
  aria_label,
  variant = 'full',
  on_step_click
}: KycStepIndicatorProps) {
  const label = aria_label ?? 'KYC steps';

  const safeActiveIndex = Math.min(Math.max(active_step_index, 0), Math.max(steps.length - 1, 0));
  const activeStep = steps[safeActiveIndex];

  const handleStepClick = (step: KycStepIndicatorStep, step_index: number) => {
    const isFuture = step_index > max_completed_step_index;
    if (isFuture) return;
    on_step_click?.({ step_index, step });
  };

  if (variant === 'condensed') {
    const total = steps.length;
    const currentDisplay = total > 0 ? `${safeActiveIndex + 1}/${total}` : '0/0';

    return (
      <div style={styles.condensedRoot}>
        <div style={styles.condensedProgress} aria-hidden="true">
          {currentDisplay}
        </div>
        <div style={styles.condensedName}>{activeStep?.label ?? ''}</div>
      </div>
    );
  }

  return (
    <nav aria-label={label}>
      <ol aria-label={label} style={styles.list}>
        {steps.map((step, idx) => {
          const isActive = idx === active_step_index;
          const isFuture = idx > max_completed_step_index;

          return (
            <li key={step.id} style={styles.item}>
              <button
                type="button"
                style={{
                  ...styles.button,
                  ...(isActive ? styles.buttonActive : undefined),
                  ...(isFuture ? styles.buttonDisabled : undefined)
                }}
                aria-current={isActive ? 'step' : undefined}
                aria-disabled={isFuture ? 'true' : undefined}
                onClick={() => handleStepClick(step, idx)}
              >
                {step.label}
              </button>
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

