import React from 'react';

import { KycStepIndicator } from '../KycStepIndicator/KycStepIndicator';
import { PersonalInfoStep } from '../PersonalInfoStep/PersonalInfoStep';
import { DocumentUploadStep } from '../DocumentUploadStep/DocumentUploadStep';
import { SelfieStep } from '../SelfieStep/SelfieStep';
import { WizardNavigation } from '../WizardNavigation/WizardNavigation';
import { VerificationStatus } from '../VerificationStatus/VerificationStatus';

export type KycWizardStep = 'personal_info' | 'document_upload' | 'selfie' | 'status';

export type KycStepChangePayload = {
  direction?: 'next' | 'back';
  source?: 'navigation' | 'step_indicator';
  from_step: KycWizardStep;
  to_step: KycWizardStep;
};

export type KycNextPayload = { step: KycWizardStep };
export type KycBackPayload = { step: KycWizardStep };
export type KycBlockingErrorPayload = {
  step: KycWizardStep;
  reason: string;
};

export type DocumentUploadState = {
  documents: Array<{ id: string; filename: string; status: 'selected' | 'uploading' | 'success' | 'failure' }>;
  accepted_mime_types: string[];
  max_file_size_bytes: number;
  max_file_count: number;
  is_step_valid: boolean;
  blocking_error?: string;
  upload_errors?: Array<{ id: string; message: string }>;
  instructions_text: string;
  drag_state?: 'idle' | 'drag-over-accept' | 'drag-over-reject';
  aria_live_message?: string;
};

export type VerificationStatusState = {
  is_loading: boolean;
  has_error: boolean;
  status: 'pending_review' | 'approved' | 'rejected' | any;
};

export type KycVerificationWizardProps = {
  initial_step?: KycWizardStep;
  current_step?: KycWizardStep;

  is_personal_info_valid: boolean;
  document_upload_state: DocumentUploadState;
  is_selfie_valid: boolean;

  is_submitting: boolean;
  completed_steps: KycWizardStep[];

  verification_status_state: VerificationStatusState;

  on_step_change: (payload: KycStepChangePayload) => void;
  on_next: (payload: KycNextPayload) => void;
  on_back: (payload: KycBackPayload) => void;
  on_blocking_error?: (payload: KycBlockingErrorPayload) => void;
  on_retry_status_fetch?: () => void;
};

const STEPS: Array<{ id: Exclude<KycWizardStep, 'status'>; label: string }> = [
  { id: 'personal_info', label: 'Personal info' },
  { id: 'document_upload', label: 'Document upload' },
  { id: 'selfie', label: 'Selfie' }
];

function getStepIndex(step: KycWizardStep): number {
  const idx = STEPS.findIndex((s) => s.id === step);
  if (idx >= 0) return idx;
  if (step === 'status') return STEPS.length;
  return 0;
}

function getMaxCompletedIndex(completed_steps: KycWizardStep[]): number {
  const idxs = completed_steps
    .map((s) => getStepIndex(s))
    .filter((i) => Number.isFinite(i) && i >= 0 && i < STEPS.length);
  return idxs.length ? Math.max(...idxs) : -1;
}

function getNextStep(step: KycWizardStep): KycWizardStep {
  if (step === 'personal_info') return 'document_upload';
  if (step === 'document_upload') return 'selfie';
  if (step === 'selfie') return 'status';
  return 'status';
}

function getPrevStep(step: KycWizardStep): KycWizardStep {
  if (step === 'document_upload') return 'personal_info';
  if (step === 'selfie') return 'document_upload';
  if (step === 'status') return 'selfie';
  return 'personal_info';
}

function isStepBlockingInvalid(
  step: KycWizardStep,
  props: Pick<KycVerificationWizardProps, 'is_personal_info_valid' | 'document_upload_state' | 'is_selfie_valid'>
): { is_invalid: boolean; reason: string } {
  if (step === 'personal_info') {
    return { is_invalid: !props.is_personal_info_valid, reason: 'personal_info_invalid' };
  }
  if (step === 'document_upload') {
    return { is_invalid: !props.document_upload_state?.is_step_valid, reason: 'documents_required' };
  }
  if (step === 'selfie') {
    return { is_invalid: !props.is_selfie_valid, reason: 'selfie_required' };
  }
  return { is_invalid: false, reason: 'ok' };
}

function getIndicatorVariant(): 'condensed' | 'full' {
  if (typeof window === 'undefined') return 'full';
  return window.innerWidth < 360 ? 'condensed' : 'full';
}

export function KycVerificationWizard(props: KycVerificationWizardProps) {
  const isControlled = props.current_step !== undefined;
  const [uncontrolledStep, setUncontrolledStep] = React.useState<KycWizardStep>(() => props.initial_step ?? 'personal_info');

  const activeStep: KycWizardStep = (isControlled ? props.current_step : uncontrolledStep) ?? 'personal_info';

  const active_step_index = Math.min(getStepIndex(activeStep), STEPS.length - 1);
  const max_completed_step_index = getMaxCompletedIndex(props.completed_steps);

  const can_go_back = activeStep !== 'personal_info' && activeStep !== 'status' ? true : activeStep === 'status' ? true : false;

  const { is_invalid: is_current_step_invalid } = isStepBlockingInvalid(activeStep, props);

  const can_go_next = activeStep === 'status' ? false : !is_current_step_invalid;

  const requestStepChange = React.useCallback(
    (payload: KycStepChangePayload) => {
      props.on_step_change(payload);
      if (!isControlled) {
        setUncontrolledStep(payload.to_step);
      }
    },
    [isControlled, props]
  );

  const handleStepClick = React.useCallback(
    (payload: { step_index: number }) => {
      if (props.is_submitting) return;

      const idx = payload?.step_index;
      if (typeof idx !== 'number') return;
      const to = STEPS[idx]?.id;
      if (!to) return;

      const allowed = to === activeStep || props.completed_steps.includes(to);
      if (!allowed) return;

      requestStepChange({ source: 'step_indicator', from_step: activeStep, to_step: to });
    },
    [activeStep, props.completed_steps, props.is_submitting, requestStepChange]
  );

  const handleNext = React.useCallback(() => {
    if (props.is_submitting) return;
    if (activeStep === 'status') return;

    const validity = isStepBlockingInvalid(activeStep, props);
    if (validity.is_invalid) {
      props.on_blocking_error?.({ step: activeStep, reason: validity.reason });
      return;
    }

    props.on_next({ step: activeStep });

    const to_step = getNextStep(activeStep);
    requestStepChange({ direction: 'next', source: 'navigation', from_step: activeStep, to_step });
  }, [activeStep, props, requestStepChange]);

  const handleBack = React.useCallback(() => {
    if (props.is_submitting) return;

    // On step 1, back is not allowed
    if (activeStep === 'personal_info') return;

    props.on_back({ step: activeStep });

    const to_step = getPrevStep(activeStep);
    requestStepChange({ direction: 'back', source: 'navigation', from_step: activeStep, to_step });
  }, [activeStep, props, requestStepChange]);

  const indicatorVariant = getIndicatorVariant();

  const personalHeadingId = 'kyc-step-personal-info-heading';
  const selfieHeadingId = 'kyc-step-selfie-heading';

  return (
    <div
      style={{
        background: 'var(--color-surface-default)',
        color: 'var(--color-text-primary)',
        padding: 'var(--spacing-16)',
        maxWidth: '720px',
        margin: '0 auto'
      }}
    >
      <div style={{ marginBottom: 'var(--spacing-16)' }}>
        <KycStepIndicator
          steps={STEPS}
          active_step_index={active_step_index}
          max_completed_step_index={max_completed_step_index}
          aria_label="KYC steps"
          variant={indicatorVariant}
          on_step_click={handleStepClick}
        />
      </div>

      <div>
        <PersonalInfoStep
          is_active={activeStep === 'personal_info'}
          step_title="Personal info"
          step_heading_id={personalHeadingId}
          is_confirmed={props.is_personal_info_valid}
          has_error={false}
          on_confirm_change={() => {
            // Wizard does not own personal info state; presentational contract only.
          }}
        />

        <DocumentUploadStep
          step_title="Document upload"
          is_active={activeStep === 'document_upload'}
          is_busy={!!props.is_submitting}
          documents={props.document_upload_state.documents}
          accepted_mime_types={props.document_upload_state.accepted_mime_types}
          max_file_size_bytes={props.document_upload_state.max_file_size_bytes}
          max_file_count={props.document_upload_state.max_file_count}
          is_step_valid={props.document_upload_state.is_step_valid}
          blocking_error={props.document_upload_state.blocking_error}
          upload_errors={props.document_upload_state.upload_errors}
          instructions_text={props.document_upload_state.instructions_text}
          on_add_files={() => {
            // State lifted to parent; the e2e harness owns the on_add_files via DocumentUploadStep implementation.
          }}
          on_remove_file={() => {
            // Lifted.
          }}
        />

        <SelfieStep
          is_active={activeStep === 'selfie'}
          is_busy={!!props.is_submitting}
          step_heading="Selfie"
          step_heading_id={selfieHeadingId}
          upload_instructions="Upload a clear selfie (JPG or PNG, max 10MB)."
          upload_instructions_id="kyc-selfie-instructions"
          accepted_mime_types={['image/jpeg', 'image/png']}
          max_file_size_bytes={10 * 1024 * 1024}
          selfie_file={null}
          selfie_preview_url={null}
          error_message={null}
          is_invalid={!props.is_selfie_valid && activeStep === 'selfie'}
          on_select_selfie_file={() => {
            // Lifted.
          }}
          on_remove_selfie_file={() => {
            // Lifted.
          }}
          on_request_replace={() => {
            // Lifted.
          }}
        />

        {activeStep === 'status' ? (
          <div style={{ marginTop: 'var(--spacing-16)' }}>
            <VerificationStatus
              aria_label="Verification status"
              status={props.verification_status_state.status}
              is_loading={props.verification_status_state.is_loading}
              has_error={props.verification_status_state.has_error}
              on_retry={() => {
                props.on_retry_status_fetch?.();
              }}
            />
          </div>
        ) : null}
      </div>

      <div style={{ marginTop: 'var(--spacing-16)' }}>
        <WizardNavigation
          current_step_index={active_step_index}
          total_steps={STEPS.length}
          can_go_back={activeStep !== 'personal_info'}
          can_go_next={can_go_next}
          is_submitting={props.is_submitting}
          back_label="Back"
          next_label="Next"
          on_back={handleBack}
          on_next={handleNext}
        />
      </div>
    </div>
  );
}

import React from 'react';

export type NextButtonProps = {
  /** Visible label for the button (e.g., "Next"). */
  label: string;
  /** Whether the button is disabled. Maps to native disabled and aria-disabled. */
  disabled?: boolean;
  /** Whether the button is in a loading state; loading forces non-interactive. */
  loading?: boolean;
  /** Handler invoked when the user activates the button (click/keyboard). */
  on_next: () => void;
};

export function NextButton({ label, disabled = false, loading = false, on_next }: NextButtonProps) {
  const isDisabled = Boolean(disabled || loading);

  const handleClick: React.MouseEventHandler<HTMLButtonElement> = (e) => {
    if (isDisabled) {
      e.preventDefault();
      return;
    }
    on_next();
  };

  return (
    <button
      type="button"
      onClick={handleClick}
      disabled={isDisabled}
      aria-disabled={isDisabled ? 'true' : 'false'}
    >
      {label}
    </button>
  );
}

import React, { useEffect, useId, useMemo, useRef } from 'react';

export type PersonalInfoStepProps = {
  /** Whether this step is currently active (displayed) in the wizard. */
  is_active: boolean;
  /** Step title rendered as the <h2>. */
  step_title: string;
  /** Stable id attribute for the step heading element. */
  step_heading_id: string;
  /** Current value of the required confirmation checkbox. */
  is_confirmed: boolean;
  /** Whether the step is currently blocked by a validation error. */
  has_error: boolean;
  /** Inline error message for the confirmation checkbox when has_error is true. */
  error_message?: string;
  /** Id for the inline error message element to link via aria-describedby. */
  error_message_id?: string;
  /** Fired when the user toggles the confirmation checkbox. */
  on_confirm_change: (checked: boolean) => void;
  /** Optional focus request contract for parent-managed deterministic focus. */
  on_request_focus_invalid?: () => void;
};

export function PersonalInfoStep(props: PersonalInfoStepProps) {
  const {
    is_active,
    step_title,
    step_heading_id,
    is_confirmed,
    has_error,
    error_message,
    error_message_id,
    on_confirm_change,
    on_request_focus_invalid,
  } = props;

  const reactId = useId();
  const fallbackErrorId = useMemo(
    () => error_message_id ?? `personal-info-confirm-error-${reactId}`,
    [error_message_id, reactId]
  );

  const checkboxRef = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    if (has_error && on_request_focus_invalid) {
      on_request_focus_invalid();
    }
  }, [has_error, on_request_focus_invalid]);

  // Keep described-by minimal and deterministic for tests.
  const ariaDescribedBy = has_error && error_message ? fallbackErrorId : undefined;

  return (
    <section
      aria-hidden={!is_active}
      data-active={is_active ? 'true' : 'false'}
      style={{
        background: 'var(--color-surface-default)',
        color: 'var(--color-text-primary)',
        padding: 'var(--spacing-16)',
        border: `1px solid var(--color-border-subtle)`,
        borderRadius: 'var(--radius-12)',
        boxShadow: 'var(--shadow-sm)',
      }}
    >
      <h2
        id={step_heading_id}
        tabIndex={-1}
        style={{
          margin: 0,
          marginBottom: 'var(--spacing-12)',
          fontSize: 'var(--font-size-body)',
          fontWeight: 'var(--font-weight-medium)',
        }}
      >
        {step_title}
      </h2>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--spacing-8)' }}>
        <label
          style={{
            display: 'flex',
            alignItems: 'flex-start',
            gap: 'var(--spacing-8)',
            fontSize: 'var(--font-size-body)',
            color: 'var(--color-text-primary)',
          }}
        >
          <input
            ref={checkboxRef}
            type="checkbox"
            checked={is_confirmed}
            onChange={(e) => on_confirm_change(e.currentTarget.checked)}
            aria-invalid={has_error ? 'true' : undefined}
            aria-describedby={ariaDescribedBy}
          />
          <span>I confirm the above information is correct</span>
        </label>

        {has_error && error_message ? (
          <div
            id={fallbackErrorId}
            role="alert"
            style={{
              fontSize: 'var(--font-size-label)',
              color: 'var(--color-status-danger)',
            }}
          >
            {error_message}
          </div>
        ) : null}
      </div>
    </section>
  );
}

import React, { useId, useMemo, useRef } from 'react';

type Props = {
  is_active: boolean;
  is_busy: boolean;
  step_heading: string;
  step_heading_id: string;
  upload_instructions: string;
  upload_instructions_id: string;
  accepted_mime_types: string[];
  max_file_size_bytes: number;
  selfie_file: File | null;
  selfie_preview_url: string | null;
  error_message?: string | null;
  error_message_id?: string;
  is_invalid: boolean;
  on_select_selfie_file: (file: File) => void;
  on_remove_selfie_file: () => void;
  on_request_replace: () => void;
};

export function SelfieStep(props: Props) {
  const {
    is_active,
    is_busy,
    step_heading,
    step_heading_id,
    upload_instructions,
    upload_instructions_id,
    accepted_mime_types,
    max_file_size_bytes, // present for parent validation; not enforced here (dumb component)
    selfie_file,
    selfie_preview_url,
    error_message,
    error_message_id,
    is_invalid,
    on_select_selfie_file,
    on_remove_selfie_file,
    on_request_replace
  } = props;

  const internalId = useId();
  const inputId = `selfie-file-input-${internalId}`;
  const fileInputRef = useRef<HTMLInputElement | null>(null);

  const describedBy = useMemo(() => {
    const ids: string[] = [];
    if (upload_instructions_id) ids.push(upload_instructions_id);
    if (is_invalid && error_message && error_message_id) ids.push(error_message_id);
    return ids.join(' ');
  }, [upload_instructions_id, is_invalid, error_message, error_message_id]);

  const acceptAttr = useMemo(() => accepted_mime_types.join(','), [accepted_mime_types]);

  const handleFileChange: React.ChangeEventHandler<HTMLInputElement> = (e) => {
    if (is_busy) return;
    const file = e.currentTarget.files?.[0];
    if (!file) return;
    on_select_selfie_file(file);
    // Allow selecting the same file again.
    e.currentTarget.value = '';
  };

  const handleReplaceClick = () => {
    if (is_busy) return;
    on_request_replace();
    // Provide a sensible default in case parent doesn't implement programmatic click.
    fileInputRef.current?.click();
  };

  const handleRemoveClick = () => {
    if (is_busy) return;
    on_remove_selfie_file();
  };

  const showPreview = Boolean(selfie_file && selfie_preview_url);

  return (
    <section
      aria-labelledby={step_heading_id}
      aria-busy={is_busy ? 'true' : undefined}
      data-active={is_active ? 'true' : 'false'}
      style={styles.container}
    >
      <h2 id={step_heading_id} tabIndex={-1} style={styles.heading}>
        {step_heading}
      </h2>

      <p id={upload_instructions_id} style={styles.instructions}>
        {upload_instructions}
      </p>

      {is_invalid && error_message ? (
        <p id={error_message_id} style={styles.errorText}>
          {error_message}
        </p>
      ) : null}

      <div style={styles.card}>
        <div style={styles.controlsRow}>
          <label htmlFor={inputId} style={styles.uploadLabel}>
            Upload selfie
          </label>

          <input
            ref={fileInputRef}
            id={inputId}
            type="file"
            accept={acceptAttr}
            aria-describedby={describedBy || undefined}
            aria-invalid={is_invalid && error_message ? 'true' : undefined}
            disabled={is_busy}
            onChange={handleFileChange}
            style={styles.fileInput}
          />
        </div>

        {showPreview ? (
          <div style={styles.previewArea}>
            <img
              src={selfie_preview_url as string}
              alt="Selected selfie preview"
              style={styles.previewImage}
            />

            <div style={styles.actions}>
              <button
                type="button"
                onClick={handleReplaceClick}
                disabled={is_busy}
                style={styles.secondaryButton}
              >
                Replace
              </button>
              <button
                type="button"
                onClick={handleRemoveClick}
                disabled={is_busy}
                style={styles.dangerButton}
              >
                Remove
              </button>
            </div>
          </div>
        ) : (
          <div style={styles.emptyState}>
            <p style={styles.emptyTitle}>No selfie selected</p>
            <p style={styles.emptyMeta}>
              {accepted_mime_types.includes('image/jpeg') || accepted_mime_types.includes('image/png')
                ? `Choose a JPG or PNG image (max ${(max_file_size_bytes / (1024 * 1024)).toFixed(0)}MB).`
                : `Choose an image file.`}
            </p>
          </div>
        )}
      </div>
    </section>
  );
}

