describe('DocumentUploadStep', () => {
  test('renders the step heading as an h2 focus target with tabIndex=-1', () => {
    render(<DocumentUploadStep {...baseProps({ step_title: 'Document upload' })} />);

    const heading = screen.getByRole('heading', { level: 2, name: 'Document upload' });
    expect(heading).toBeInTheDocument();
    expect(heading).toHaveAttribute('tabindex', '-1');
  });

  test('sets aria-busy=true on the step container only when active and busy', () => {
    const { rerender } = render(
      <DocumentUploadStep {...baseProps({ is_active: true, is_busy: true })} />
    );

    // Find a reasonably stable container via heading parent chain.
    const heading = screen.getByRole('heading', { level: 2, name: 'Upload documents' });
    const container = heading.closest('[aria-busy]') ?? heading.parentElement;
    expect(container).toHaveAttribute('aria-busy', 'true');

    rerender(<DocumentUploadStep {...baseProps({ is_active: true, is_busy: false })} />);
    const heading2 = screen.getByRole('heading', { level: 2, name: 'Upload documents' });
    const container2 = heading2.closest('[aria-busy]');
    if (container2) {
      expect(container2).not.toHaveAttribute('aria-busy', 'true');
    }

    rerender(<DocumentUploadStep {...baseProps({ is_active: false, is_busy: true })} />);
    const heading3 = screen.getByRole('heading', { level: 2, name: 'Upload documents' });
    const container3 = heading3.closest('[aria-busy]');
    if (container3) {
      expect(container3).not.toHaveAttribute('aria-busy', 'true');
    }
  });

  test('passes configuration props through to DocumentUpload', () => {
    render(
      <DocumentUploadStep
        {...baseProps({
          documents: [
            // shape is owned by step; test only that list is forwarded as files
            { id: 'doc_1', file_name: 'passport.pdf', status: 'success' } as any
          ],
          max_file_count: 3,
          max_file_size_bytes: 123,
          accepted_mime_types: ['application/pdf'],
          instructions_text: 'Accepted formats: PDF. Max size: 123 bytes. Up to 3 files.',
          upload_errors: [{ code: 'too_large', message: 'Too large' }] as any,
          is_busy: true
        })}
      />
    );

    const propsJson = screen.getByTestId('du-props').textContent;
    expect(propsJson).toContain('"accepted_mime_types"');
    expect(propsJson).toContain('application/pdf');
    expect(propsJson).toContain('"max_file_size_bytes": 123');
    expect(propsJson).toContain('"max_files": 3');
