import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { DocumentUpload } from './DocumentUpload';

function makeFile(name: string, type: string, sizeBytes = 1024) {
  const blob = new Blob([new Uint8Array(sizeBytes)], { type });
  return new File([blob], name, { type, lastModified: 1710000000000 });
}

describe('DocumentUpload', () => {
  const baseProps = {
    files: [],
    instructions_id: 'doc-upload-instructions',
    drag_state: 'idle' as any,
    on_add_files: jest.fn(),
    on_remove_file: jest.fn(),
    on_retry_file: jest.fn(),
    on_drag_state_change: jest.fn()
  };

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('wires instructions_id to both dropzone and file input via aria-describedby', () => {
    render(
      <DocumentUpload
        {...baseProps}
        aria_live_message={undefined}
      />
    );

    const input = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    expect(input).toHaveAttribute('aria-describedby', expect.stringContaining('doc-upload-instructions'));

    // Dropzone is expected to be focusable per decisions.
    const dropzone = screen.getByTestId('document-upload-dropzone');
    expect(dropzone).toHaveAttribute('aria-describedby', expect.stringContaining('doc-upload-instructions'));
  });

  it('renders aria-live polite region message when aria_live_message is provided', () => {
    render(
      <DocumentUpload
        {...baseProps}
        aria_live_message="Files will be added"
      />
    );

    const live = screen.getByTestId('document-upload-aria-live');
    expect(live).toHaveAttribute('aria-live', 'polite');
    expect(live).toHaveTextContent('Files will be added');
  });

  it('sets aria-invalid on controls when is_invalid is true and appends error summary ids to aria-describedby when errors are present', () => {
    render(
      <DocumentUpload
        {...baseProps}
        is_invalid
        errors={[{ id: 'e1', message: 'Unsupported file type' } as any, { id: 'e2', message: 'Too large' } as any]}
      />
    );

    const input = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    expect(input).toHaveAttribute('aria-invalid', 'true');
    expect(input.getAttribute('aria-describedby') || '').toEqual(expect.stringContaining('doc-upload-instructions'));

    const errorSummary = screen.getByTestId('document-upload-error-summary');
    expect(errorSummary).toBeInTheDocument();
    expect(errorSummary).toHaveTextContent('Unsupported file type');
    expect(errorSummary).toHaveTextContent('Too large');

    const describedBy = input.getAttribute('aria-describedby') || '';
    // Expect that error summary is referenced (implementation may reference wrapper id).
    expect(describedBy).toEqual(expect.stringMatching(/doc-upload-instructions/));
  });

  it('calls on_add_files({files, source:"picker"}) when selecting files in the input', () => {
    render(<DocumentUpload {...baseProps} />);

    const input = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' }) as HTMLInputElement;
    const f1 = makeFile('passport.pdf', 'application/pdf');
    const f2 = makeFile('id.png', 'image/png');

    fireEvent.change(input, { target: { files: [f1, f2] } });

    expect(baseProps.on_add_files).toHaveBeenCalledTimes(1);
    expect(baseProps.on_add_files).toHaveBeenCalledWith({ files: [f1, f2], source: 'picker' });
  });

  it('calls on_drag_state_change for drag interactions when provided and enabled', () => {
    render(<DocumentUpload {...baseProps} />);

    const dropzone = screen.getByTestId('document-upload-dropzone');

    fireEvent.dragEnter(dropzone);
    fireEvent.dragOver(dropzone);
    fireEvent.dragLeave(dropzone);

    expect(baseProps.on_drag_state_change).toHaveBeenCalled();
  });

  it('calls on_add_files({files, source:"drop"}) on drop with dataTransfer files', () => {
    render(<DocumentUpload {...baseProps} />);

    const dropzone = screen.getByTestId('document-upload-dropzone');
    const f1 = makeFile('id_front.png', 'image/png');

    fireEvent.drop(dropzone, {
      dataTransfer: {
        files: [f1]
      }
    });

    expect(baseProps.on_add_files).toHaveBeenCalledTimes(1);
    expect(baseProps.on_add_files).toHaveBeenCalledWith({ files: [f1], source: 'drop' });
  });

  it('supports keyboard: Enter/Space on dropzone triggers file input click when enabled', async () => {
    const user = userEvent.setup();
    render(<DocumentUpload {...baseProps} />);

    const input = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    const clickSpy = jest.spyOn(input, 'click');

    const dropzone = screen.getByTestId('document-upload-dropzone');
    dropzone.focus();

    await user.keyboard('{Enter}');
    await user.keyboard(' ');

    expect(clickSpy).toHaveBeenCalled();
  });

  it('when disabled, blocks picker, drop, keyboard trigger, drag_state_change, and remove/retry actions', async () => {
    const user = userEvent.setup();

    render(
      <DocumentUpload
        {...baseProps}
        disabled
        files={[{ document_id: 'd1', filename: 'x.pdf', status: 'failure' } as any]}
      />
    );

    const input = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' }) as HTMLInputElement;
    const inputClickSpy = jest.spyOn(input, 'click');

    const f1 = makeFile('passport.pdf', 'application/pdf');
    fireEvent.change(input, { target: { files: [f1] } });

    const dropzone = screen.getByTestId('document-upload-dropzone');
    fireEvent.drop(dropzone, { dataTransfer: { files: [f1] } });

    dropzone.focus();
    await user.keyboard('{Enter}');

    fireEvent.dragEnter(dropzone);

    // Remove / Retry buttons should be present but disabled or no-op.
    const removeBtn = screen.getByRole('button', { name: /remove/i });
    const retryBtn = screen.getByRole('button', { name: /retry/i });

    await user.click(removeBtn);
    await user.click(retryBtn);

    expect(baseProps.on_add_files).not.toHaveBeenCalled();
    expect(baseProps.on_drag_state_change).not.toHaveBeenCalled();
    expect(baseProps.on_remove_file).not.toHaveBeenCalled();
    expect(baseProps.on_retry_file).not.toHaveBeenCalled();

    expect(inputClickSpy).not.toHaveBeenCalled();
  });

  it('renders file items and wires Remove and Retry callbacks with document_id payloads', async () => {
    const user = userEvent.setup();

    render(
      <DocumentUpload
        {...baseProps}
        files={[
          { document_id: 'doc-ok', filename: 'passport.pdf', status: 'success' } as any,
          { document_id: 'doc-fail', filename: 'id.png', status: 'failure' } as any
        ]}
      />
    );

    expect(screen.getByText('passport.pdf')).toBeInTheDocument();
    expect(screen.getByText('id.png')).toBeInTheDocument();

    const removeButtons = screen.getAllByRole('button', { name: /remove/i });
    // Remove failed file to ensure payload mapping for a non-first item too
    await user.click(removeButtons[1]);
    expect(baseProps.on_remove_file).toHaveBeenCalledWith({ document_id: 'doc-fail' });

    const retryBtn = screen.getByRole('button', { name: /retry/i });
    await user.click(retryBtn);
    expect(baseProps.on_retry_file).toHaveBeenCalledWith({ document_id: 'doc-fail' });
  });
});

import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { SelfieStep } from './SelfieStep';

function makeFile(name: string, type: string, sizeBytes = 1234) {
  // jsdom File doesn't reliably set size from content length; size isn't needed for this component.
  return new File([new Array(sizeBytes).fill('a').join('')], name, { type, lastModified: 1710000000000 });
}

const baseProps = {
  is_active: true,
  is_busy: false,
  step_heading: 'Selfie',
  step_heading_id: 'selfie-heading',
  upload_instructions: 'Accepted formats: JPG, PNG. Max size: 10MB.',
  upload_instructions_id: 'selfie-instructions',
  accepted_mime_types: ['image/jpeg', 'image/png'],
  max_file_size_bytes: 10 * 1024 * 1024,
  selfie_file: null as File | null,
  selfie_preview_url: null as string | null,
  error_message: null as string | null,
  error_message_id: 'selfie-error',
  is_invalid: false,
  on_select_selfie_file: jest.fn(),
  on_remove_selfie_file: jest.fn(),
  on_request_replace: jest.fn()
};

describe('SelfieStep', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders the heading with the provided id and tabIndex=-1, and wires aria-labelledby on the step region/container', () => {
    const { container } = render(<SelfieStep {...baseProps} />);

    const heading = screen.getByRole('heading', { level: 2, name: 'Selfie' });
    expect(heading).toHaveAttribute('id', 'selfie-heading');
    expect(heading).toHaveAttribute('tabindex', '-1');

    // Prefer a labelled region if present; otherwise fall back to a top-level container.
    const labelledRegion = container.querySelector('[aria-labelledby="selfie-heading"]');
    expect(labelledRegion).toBeTruthy();
  });

  it('renders instructions with the provided id and references them via aria-describedby from the file input', () => {
    render(<SelfieStep {...baseProps} />);

    const instructions = screen.getByText(baseProps.upload_instructions);
    expect(instructions).toHaveAttribute('id', 'selfie-instructions');

    const fileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    expect(fileInput).toHaveAttribute('aria-describedby');
    const describedBy = fileInput.getAttribute('aria-describedby') || '';
    expect(describedBy.split(/\s+/)).toContain('selfie-instructions');
  });

  it('sets accept attribute based on accepted_mime_types and calls on_select_selfie_file on file selection', async () => {
    const user = userEvent.setup();
    render(<SelfieStep {...baseProps} />);

    const fileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });

    // Accept attribute should include provided MIME types (order may vary, check containment).
    const accept = fileInput.getAttribute('accept') || '';
    expect(accept).toEqual(expect.stringContaining('image/jpeg'));
    expect(accept).toEqual(expect.stringContaining('image/png'));

    const selfie = makeFile('selfie.jpg', 'image/jpeg');
    await user.upload(fileInput, selfie);

    expect(baseProps.on_select_selfie_file).toHaveBeenCalledTimes(1);
    expect(baseProps.on_select_selfie_file).toHaveBeenCalledWith(selfie);
  });

  it('when selfie is selected, renders preview image and exposes Replace/Remove actions that call callbacks', async () => {
    const user = userEvent.setup();

    render(
      <SelfieStep
        {...baseProps}
        selfie_file={makeFile('selfie.png', 'image/png')}
        selfie_preview_url="blob:preview-url"
      />
    );

    const img = screen.getByRole('img');
    expect(img).toHaveAttribute('src', 'blob:preview-url');

    const removeBtn = screen.getByRole('button', { name: /remove/i });
    const replaceBtn = screen.getByRole('button', { name: /replace/i });

    await user.click(replaceBtn);
    expect(baseProps.on_request_replace).toHaveBeenCalledTimes(1);

    await user.click(removeBtn);
    expect(baseProps.on_remove_selfie_file).toHaveBeenCalledTimes(1);
  });

  it('when invalid with an error message, marks the file input aria-invalid and includes error_message_id in aria-describedby, and renders the error text', () => {
    render(
      <SelfieStep
        {...baseProps}
        is_invalid={true}
        error_message="Selfie is required"
        error_message_id="selfie-error"
      />
    );

    const fileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    expect(fileInput).toHaveAttribute('aria-invalid', 'true');

    const describedBy = fileInput.getAttribute('aria-describedby') || '';
    const ids = describedBy.split(/\s+/).filter(Boolean);
    expect(ids).toContain('selfie-instructions');
    expect(ids).toContain('selfie-error');

    const error = screen.getByText('Selfie is required');
    expect(error).toHaveAttribute('id', 'selfie-error');
  });

  it('when busy, sets aria-busy on the step container and disables interactive controls', async () => {
    const user = userEvent.setup();

    const { container } = render(
      <SelfieStep
        {...baseProps}
        is_busy={true}
        selfie_file={makeFile('selfie.png', 'image/png')}
        selfie_preview_url="blob:preview-url"
      />
    );

    const busyContainer = container.querySelector('[aria-busy="true"]');
    expect(busyContainer).toBeTruthy();

    const fileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    expect(fileInput).toBeDisabled();

    const removeBtn = screen.getByRole('button', { name: /remove/i });
    const replaceBtn = screen.getByRole('button', { name: /replace/i });
    expect(removeBtn).toBeDisabled();
    expect(replaceBtn).toBeDisabled();

    await user.click(replaceBtn);
    await user.click(removeBtn);
    expect(baseProps.on_request_replace).not.toHaveBeenCalled();
    expect(baseProps.on_remove_selfie_file).not.toHaveBeenCalled();
  });

  it('renders in inactive state without crashing (is_active=false)', () => {
    render(<SelfieStep {...baseProps} is_active={false} />);

    // Still renders heading/instructions; visibility behavior is owned by parent layout.
    expect(screen.getByRole('heading', { level: 2, name: 'Selfie' })).toBeInTheDocument();
    expect(screen.getByText(baseProps.upload_instructions)).toBeInTheDocument();
  });
});

