    render(<NextButton label="Next" loading={true} on_next={onNext} />);

    const btn = screen.getByRole('button', { name: 'Next' });

    // Loading should prevent interaction; enforce the safest behavior
    expect(btn).toBeDisabled();
    expect(btn).toHaveAttribute('aria-disabled', 'true');

    await user.click(btn);
    expect(onNext).not.toHaveBeenCalled();
  });

  it('supports keyboard activation via Enter when enabled', async () => {
    const user = userEvent.setup();
    const onNext = jest.fn();

    render(<NextButton label="Next" on_next={onNext} />);

    const btn = screen.getByRole('button', { name: 'Next' });
    btn.focus();
    expect(btn).toHaveFocus();

    await user.keyboard('{Enter}');
    expect(onNext).toHaveBeenCalledTimes(1);
  });

  it('supports keyboard activation via Space when enabled', async () => {
    const user = userEvent.setup();
    const onNext = jest.fn();

    render(<NextButton label="Next" on_next={onNext} />);

    const btn = screen.getByRole('button', { name: 'Next' });
    btn.focus();
    expect(btn).toHaveFocus();

    await user.keyboard(' ');
    expect(onNext).toHaveBeenCalledTimes(1);
  });
});

import React from 'react';
