    const user = userEvent.setup();
    const onRetry = jest.fn();

    render(
      <VerificationStatus
        is_loading={false}
        has_error={true}
        status={null}
        on_retry={onRetry}
      />
    );

    expect(screen.getByText(/unable to load status/i)).toBeInTheDocument();

    const retryButton = screen.getByRole('button', { name: /retry/i });
    await user.click(retryButton);

    expect(onRetry).toHaveBeenCalledTimes(1);
  });

  it('does not crash if Retry is clicked without on_retry', async () => {
    const user = userEvent.setup();

    render(
      <VerificationStatus
        is_loading={false}
        has_error={true}
        status={null}
      />
    );

    const retryButton = screen.getByRole('button', { name: /retry/i });
    await user.click(retryButton);

    // No expectation other than not throwing; button exists and is clickable.
    expect(screen.getByText(/unable to load status/i)).toBeInTheDocument();
  });

  it('applies aria_label to the status region when provided', () => {
    render(
      <VerificationStatus
        is_loading={false}
