import React from 'react';

export type KycVerificationStatus = 'pending_review' | 'approved' | 'rejected' | (string & {});

export interface VerificationStatusProps {
  /**
   * Verification status value to render. Use "pending_review", "approved", or "rejected";
   * any other non-null value should render the "Status unavailable" fallback.
   */
  status?: KycVerificationStatus | null;
  /** Whether the status is currently being fetched; when true, render the loading UI (takes precedence). */
  is_loading: boolean;
  /** Whether the latest status fetch failed; when true, render the error UI (when not loading). */
  has_error: boolean;
  /** Callback invoked when the user clicks the Retry button in the error state to re-fetch status. */
  on_retry?: () => void;
  /** Accessible label for the overall status region (used for screen readers). */
  aria_label?: string;
}

function getResolvedStatus(status: KycVerificationStatus | null | undefined): 'pending_review' | 'approved' | 'rejected' | 'unknown' {
  if (status === 'pending_review' || status === 'approved' || status === 'rejected') return status;
  if (status == null) return 'unknown';
  return 'unknown';
}

function getStatusPresentation(resolved: 'pending_review' | 'approved' | 'rejected' | 'unknown') {
  switch (resolved) {
    case 'pending_review':
      return {
        title: 'Pending review',
        icon: '⏳',
        colorVar: 'var(--color-status-warning)'
      };
    case 'approved':
      return {
        title: 'Approved',
        icon: '✓',
        colorVar: 'var(--color-status-success)'
      };
    case 'rejected':
      return {
        title: 'Rejected',
        icon: '⚠',
        colorVar: 'var(--color-status-danger)'
      };
    default:
      return {
        title: 'Status unavailable',
        icon: '•',
        colorVar: 'var(--color-text-secondary)'
      };
  }
}

export function VerificationStatus(props: VerificationStatusProps) {
  const { status = null, is_loading, has_error, on_retry, aria_label } = props;

  const baseStyle: React.CSSProperties = {
    background: 'var(--color-surface-default)',
    border: '1px solid var(--color-border-subtle)',
    borderRadius: 'var(--radius-12)',
    boxShadow: 'var(--shadow-sm)',
    padding: 'var(--spacing-16)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-body)'
  };

  const headingStyle: React.CSSProperties = {
    margin: 0,
    fontWeight: 600
  };

  const subtleTextStyle: React.CSSProperties = {
    marginTop: 'var(--spacing-8)',
    color: 'var(--color-text-secondary)',
    fontSize: 'var(--font-size-body)'
  };

  // Loading takes precedence over error/status per unit tests.
  if (is_loading) {
    return (
      <section aria-label={aria_label} style={baseStyle}>
        <p style={{ margin: 0, color: 'var(--color-text-secondary)' }}>Loading status...</p>
      </section>
    );
  }

  if (has_error) {
    return (
      <section aria-label={aria_label} style={baseStyle}>
        <p style={{ margin: 0, color: 'var(--color-text-primary)' }}>Unable to load status</p>
        <div style={{ marginTop: 'var(--spacing-12)' }}>
          <button
            type="button"
            onClick={() => {
              on_retry?.();
            }}
            style={{
              minHeight: 44,
              padding: 'var(--spacing-8) var(--spacing-12)',
              borderRadius: 'var(--radius-8)',
              border: '1px solid var(--color-border-subtle)',
              background: 'var(--color-surface-muted)',
              color: 'var(--color-text-primary)',
              fontWeight: 600,
              cursor: 'pointer'
            }}
          >
            Retry
          </button>
        </div>
      </section>
    );
  }

  const resolved = getResolvedStatus(status);
  const presentation = getStatusPresentation(resolved);

  return (
    <section aria-label={aria_label} style={baseStyle}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--spacing-8)' }}>
        <span aria-hidden="true" style={{ color: presentation.colorVar, fontSize: 18, lineHeight: 1 }}>
          {presentation.icon}
        </span>
        <h3 style={headingStyle}>{presentation.title}</h3>
      </div>
      {resolved === 'pending_review' && (
        <p style={subtleTextStyle}>We’re reviewing your submission. This usually takes a short time.</p>
      )}
      {resolved === 'approved' && <p style={subtleTextStyle}>Your identity has been verified.</p>}
      {resolved === 'rejected' && <p style={subtleTextStyle}>Your verification was not approved. Please review and try again.</p>}
    </section>
  );
}

import React from 'react';
import { BackButton } from '../BackButton/BackButton';
import { NextButton } from '../NextButton/NextButton';
import styles from './WizardNavigation.module.css';

export type WizardNavigationProps = {
  current_step_index: number;
  total_steps: number;
  can_go_back: boolean;
  can_go_next: boolean;
  is_submitting: boolean;
  back_label?: string;
  next_label?: string;
  on_back: () => void;
  on_next: () => void;
};

export function WizardNavigation(props: WizardNavigationProps) {
  const {
    current_step_index,
    total_steps,
    can_go_back,
    can_go_next,
    is_submitting,
    back_label,
    next_label,
    on_back,
    on_next,
  } = props;

  const isLastStep = current_step_index === total_steps - 1;

  const backText = back_label ?? 'Back';
  const nextText = next_label ?? 'Next';

  const backDisabled = is_submitting || !can_go_back;
  const nextDisabled = is_submitting || !can_go_next;

  return (
    <nav className={styles.root} aria-label="Wizard navigation">
      <div className={styles.inner}>
        <div className={styles.back}>
          <BackButton
            label={backText}
            disabled={backDisabled}
            on_press={() => {
              if (backDisabled) return;
              on_back();
            }}
          />
        </div>

        <div className={styles.next}>
          {!isLastStep ? (
            <NextButton
              label={nextText}
              disabled={nextDisabled}
              loading={is_submitting}
              on_next={() => {
                if (nextDisabled) return;
                on_next();
              }}
            />
          ) : null}
        </div>
      </div>
    </nav>
  );
}

.root {
  position: sticky;
  bottom: 0;
  background: var(--color-surface-default);
  border-top: 1px solid var(--color-border-subtle);
  padding: var(--spacing-16);
}

.inner {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-8);
}

.back,
.next {
  width: 100%;
}

.back :global(button),
.next :global(button) {
  width: 100%;
  min-height: 44px;
}

@media (min-width: 768px) {
  .root {
    position: static;
    border-top: none;
    padding: 0;
  }

  .inner {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: var(--spacing-16);
  }

  .back,
  .next {
    width: auto;
  }

  .back :global(button),
  .next :global(button) {
    width: auto;
  }
}

