    const user = userEvent.setup();
    const on_remove_file = jest.fn();

    render(<DocumentUploadStep {...baseProps({ on_remove_file })} />);

    await user.click(screen.getByRole('button', { name: 'remove-doc_1' }));
    expect(on_remove_file).toHaveBeenCalledTimes(1);
    expect(on_remove_file).toHaveBeenCalledWith('doc_1');
  });

  test('maps retry action from DocumentUpload to on_retry_upload(document_id) when provided', async () => {
    const user = userEvent.setup();
    const on_retry_upload = jest.fn();

    render(<DocumentUploadStep {...baseProps({ on_retry_upload })} />);

    await user.click(screen.getByRole('button', { name: 'retry-doc_2' }));
    expect(on_retry_upload).toHaveBeenCalledTimes(1);
    expect(on_retry_upload).toHaveBeenCalledWith('doc_2');
  });

  test('does not throw if on_retry_upload is not provided and retry is activated', async () => {
    const user = userEvent.setup();

    render(<DocumentUploadStep {...baseProps({ on_retry_upload: undefined })} />);

    await expect(user.click(screen.getByRole('button', { name: 'retry-doc_2' }))).resolves.toBeUndefined();
  });

  test('renders blocking error and marks upload control invalid when is_step_valid=false', () => {
    render(
      <DocumentUploadStep
        {...baseProps({
          is_step_valid: false,
          blocking_error: 'Please upload at least one document.'
        })}
      />
    );

    expect(screen.getByText('Please upload at least one document.')).toBeInTheDocument();

    const propsJson = screen.getByTestId('du-props').textContent;
    expect(propsJson).toContain('"is_invalid": true');
  });

  test('calls on_step_validity_change when is_step_valid changes across rerenders', () => {
    const on_step_validity_change = jest.fn();

    const { rerender } = render(
      <DocumentUploadStep
        {...baseProps({
          is_step_valid: false,
          on_step_validity_change
        })}
      />
    );

    // Some implementations may call on mount; we only assert the transition call.
    rerender(
      <DocumentUploadStep
        {...baseProps({
          is_step_valid: true,
          on_step_validity_change
        })}
      />
    );

    expect(on_step_validity_change).toHaveBeenCalled();
    // Ensure at least one call includes the new validity
    expect(on_step_validity_change.mock.calls.map((c) => c[0])).toContain(true);
  });
});
"}]}

