{"componentCode":"selfie_step","componentName":"Selfie step","coveredBehaviors":["Renders step heading as an <h2> with the provided id and tabIndex=-1 (focus target on step entry).","Sets step container aria-labelledby to the step heading id.","Renders upload instructions with the provided id and references it via aria-describedby from the file input/control.","Applies accepted MIME types to the file input accept attribute.","Invokes on_select_selfie_file with the selected File when user picks a file.","When selfie_file and selfie_preview_url are provided, renders an image preview and exposes Remove and Replace actions.","Invokes on_remove_selfie_file when Remove is activated.","Invokes on_request_replace when Replace is activated.","When is_invalid is true and error_message is present, sets aria-invalid=true and includes error_message_id in aria-describedby; renders the error text.","When is_busy is true, marks the step container aria-busy=true and disables interactive controls (file input and actions)."],"coveredStates":["Active step (is_active=true)","Inactive step (is_active=false)","Not busy (is_busy=false)","Busy/disabled (is_busy=true)","No selfie selected (selfie_file=null, selfie_preview_url=null)","Selfie selected with preview","Invalid with error message","Valid/no error message"],"files":[{"filename":"/app/generated/frontend/src/components/SelfieStep/SelfieStep.spec.tsx","content":"import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { SelfieStep } from './SelfieStep';

function makeFile(name: string, type: string, sizeBytes = 1234) {
  // jsdom File doesn't reliably set size from content length; size isn't needed for this component.
  return new File([new Array(sizeBytes).fill('a').join('')], name, { type, lastModified: 1710000000000 });
}

const baseProps = {
  is_active: true,
  is_busy: false,
  step_heading: 'Selfie',
  step_heading_id: 'selfie-heading',
  upload_instructions: 'Accepted formats: JPG, PNG. Max size: 10MB.',
  upload_instructions_id: 'selfie-instructions',
  accepted_mime_types: ['image/jpeg', 'image/png'],
  max_file_size_bytes: 10 * 1024 * 1024,
  selfie_file: null as File | null,
  selfie_preview_url: null as string | null,
  error_message: null as string | null,
  error_message_id: 'selfie-error',
  is_invalid: false,
  on_select_selfie_file: jest.fn(),
  on_remove_selfie_file: jest.fn(),
  on_request_replace: jest.fn()
};

describe('SelfieStep', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders the heading with the provided id and tabIndex=-1, and wires aria-labelledby on the step region/container', () => {
    const { container } = render(<SelfieStep {...baseProps} />);

    const heading = screen.getByRole('heading', { level: 2, name: 'Selfie' });
    expect(heading).toHaveAttribute('id', 'selfie-heading');
    expect(heading).toHaveAttribute('tabindex', '-1');

    // Prefer a labelled region if present; otherwise fall back to a top-level container.
    const labelledRegion = container.querySelector('[aria-labelledby="selfie-heading"]');
    expect(labelledRegion).toBeTruthy();
  });

  it('renders instructions with the provided id and references them via aria-describedby from the file input', () => {
    render(<SelfieStep {...baseProps} />);

    const instructions = screen.getByText(baseProps.upload_instructions);
    expect(instructions).toHaveAttribute('id', 'selfie-instructions');

    const fileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    expect(fileInput).toHaveAttribute('aria-describedby');
    const describedBy = fileInput.getAttribute('aria-describedby') || '';
    expect(describedBy.split(/\s+/)).toContain('selfie-instructions');
  });

  it('sets accept attribute based on accepted_mime_types and calls on_select_selfie_file on file selection', async () => {
    const user = userEvent.setup();
    render(<SelfieStep {...baseProps} />);

    const fileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });

    // Accept attribute should include provided MIME types (order may vary, check containment).
    const accept = fileInput.getAttribute('accept') || '';
    expect(accept).toEqual(expect.stringContaining('image/jpeg'));
    expect(accept).toEqual(expect.stringContaining('image/png'));

    const selfie = makeFile('selfie.jpg', 'image/jpeg');
    await user.upload(fileInput, selfie);

    expect(baseProps.on_select_selfie_file).toHaveBeenCalledTimes(1);
    expect(baseProps.on_select_selfie_file).toHaveBeenCalledWith(selfie);
  });

  it('when selfie is selected, renders preview image and exposes Replace/Remove actions that call callbacks', async () => {
    const user = userEvent.setup();

    render(
      <SelfieStep
        {...baseProps}
        selfie_file={makeFile('selfie.png', 'image/png')}
        selfie_preview_url="blob:preview-url"
      />
    );

    const img = screen.getByRole('img');
    expect(img).toHaveAttribute('src', 'blob:preview-url');

    const removeBtn = screen.getByRole('button', { name: /remove/i });
    const replaceBtn = screen.getByRole('button', { name: /replace/i });

    await user.click(replaceBtn);
    expect(baseProps.on_request_replace).toHaveBeenCalledTimes(1);

    await user.click(removeBtn);
    expect(baseProps.on_remove_selfie_file).toHaveBeenCalledTimes(1);
  });

  it('when invalid with an error message, marks the file input aria-invalid and includes error_message_id in aria-describedby, and renders the error text', () => {
    render(
      <SelfieStep
        {...baseProps}
        is_invalid={true}
        error_message="Selfie is required"
        error_message_id="selfie-error"
      />
    );

    const fileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    expect(fileInput).toHaveAttribute('aria-invalid', 'true');

    const describedBy = fileInput.getAttribute('aria-describedby') || '';
    const ids = describedBy.split(/\s+/).filter(Boolean);
    expect(ids).toContain('selfie-instructions');
    expect(ids).toContain('selfie-error');

    const error = screen.getByText('Selfie is required');
    expect(error).toHaveAttribute('id', 'selfie-error');
  });

  it('when busy, sets aria-busy on the step container and disables interactive controls', async () => {
    const user = userEvent.setup();

    const { container } = render(
      <SelfieStep
        {...baseProps}
        is_busy={true}
        selfie_file={makeFile('selfie.png', 'image/png')}
        selfie_preview_url="blob:preview-url"
      />
    );

    const busyContainer = container.querySelector('[aria-busy="true"]');
    expect(busyContainer).toBeTruthy();

    const fileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    expect(fileInput).toBeDisabled();

    const removeBtn = screen.getByRole('button', { name: /remove/i });
    const replaceBtn = screen.getByRole('button', { name: /replace/i });
    expect(removeBtn).toBeDisabled();
    expect(replaceBtn).toBeDisabled();

    await user.click(replaceBtn);
    await user.click(removeBtn);
    expect(baseProps.on_request_replace).not.toHaveBeenCalled();
    expect(baseProps.on_remove_selfie_file).not.toHaveBeenCalled();
  });

  it('renders in inactive state without crashing (is_active=false)', () => {
    render(<SelfieStep {...baseProps} is_active={false} />);

    // Still renders heading/instructions; visibility behavior is owned by parent layout.
    expect(screen.getByRole('heading', { level: 2, name: 'Selfie' })).toBeInTheDocument();
    expect(screen.getByText(baseProps.upload_instructions)).toBeInTheDocument();
  });
});
"}]}

