describe('WizardNavigation', () => {
  const baseProps = {
    current_step_index: 0,
    total_steps: 3,
    can_go_back: true,
    can_go_next: true,
    is_submitting: false,
    on_back: jest.fn(),
    on_next: jest.fn(),
  };

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders Back and Next with default labels when overrides are not provided', () => {
    render(<WizardNavigation {...baseProps} />);

    expect(screen.getByRole('button', { name: 'Back' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Next' })).toBeInTheDocument();
  });

  it('uses label overrides when provided', () => {
    render(
      <WizardNavigation
        {...baseProps}
        back_label="Previous"
        next_label="Continue"
      />
    );

    expect(screen.getByRole('button', { name: 'Previous' })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Continue' })).toBeInTheDocument();
  });

  it('disables Back when can_go_back is false', async () => {
    const user = userEvent.setup();
    render(<WizardNavigation {...baseProps} can_go_back={false} />);

    const back = screen.getByRole('button', { name: 'Back' });
    expect(back).toBeDisabled();

    await user.click(back);
    expect(baseProps.on_back).not.toHaveBeenCalled();
  });

  it('disables Next when can_go_next is false', async () => {
    const user = userEvent.setup();
    render(<WizardNavigation {...baseProps} can_go_next={false} />);

    const next = screen.getByRole('button', { name: 'Next' });
    expect(next).toBeDisabled();

    await user.click(next);
    expect(baseProps.on_next).not.toHaveBeenCalled();
  });

  it('when is_submitting is true, disables both buttons and renders Next as loading', () => {
    render(<WizardNavigation {...baseProps} is_submitting={true} />);

    const back = screen.getByRole('button', { name: 'Back' });
    const next = screen.getByRole('button', { name: 'Next' });

    expect(back).toBeDisabled();
    expect(next).toBeDisabled();
    expect(next).toHaveAttribute('aria-busy', 'true');
    expect(next).toHaveTextContent('Next (loading)');
  });

  it('invokes on_back when Back is activated while enabled', async () => {
    const user = userEvent.setup();
    render(<WizardNavigation {...baseProps} />);

    await user.click(screen.getByRole('button', { name: 'Back' }));
    expect(baseProps.on_back).toHaveBeenCalledTimes(1);
  });

  it('invokes on_next when Next is activated while enabled', async () => {
    const user = userEvent.setup();
    render(<WizardNavigation {...baseProps} />);

    await user.click(screen.getByRole('button', { name: 'Next' }));
    expect(baseProps.on_next).toHaveBeenCalledTimes(1);
  });

  it('does not render Next on the last step (current_step_index === total_steps - 1)', () => {
    render(
      <WizardNavigation
        {...baseProps}
        current_step_index={2}
        total_steps={3}
      />
    );

    expect(screen.getByRole('button', { name: 'Back' })).toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Next' })).not.toBeInTheDocument();
  });
});
"}]}

