function renderWizard(overrideProps: Partial<React.ComponentProps<typeof KycVerificationWizard>> = {}) {
  const props: React.ComponentProps<typeof KycVerificationWizard> = {
    is_personal_info_valid: false,
    document_upload_state: {
      documents: [],
      accepted_mime_types: ['application/pdf', 'image/jpeg', 'image/png'],
      max_file_size_bytes: 10 * 1024 * 1024,
      max_file_count: 3,
      is_step_valid: false,
      instructions_text: 'Accepted formats: PDF, JPG, PNG. Max size: 10MB. Up to 3 files.'
    } as any,
    is_selfie_valid: false,
    is_submitting: false,
    completed_steps: [],
    verification_status_state: { is_loading: false, has_error: false, status: null } as any,
    on_step_change: jest.fn(),
    on_next: jest.fn(),
    on_back: jest.fn(),
    on_blocking_error: jest.fn(),
    on_retry_status_fetch: jest.fn(),
    ...overrideProps
  };

  return {
    ...render(<KycVerificationWizard {...props} />),
    props
  };
}

describe('KycVerificationWizard', () => {
  test('defaults to personal info step when uncontrolled (no initial_step/current_step)', () => {
    renderWizard();

    expect(screen.getByTestId('personal-step')).toBeInTheDocument();
    expect(screen.getByTestId('personal-active')).toHaveTextContent('true');

    expect(screen.getByTestId('active-index')).toHaveTextContent('0');
    expect(screen.getByTestId('max-completed-index')).toHaveTextContent('-1');

    expect(screen.getByTestId('back')).toBeDisabled();
    expect(screen.getByTestId('next')).toBeDisabled();
  });

  test('clicking Next on invalid personal info emits blocking error and does not call on_next/on_step_change', async () => {
    const user = userEvent.setup();
    const { props } = renderWizard({
      is_personal_info_valid: false,
      current_step: 'personal_info' as any
    });

    await user.click(screen.getByTestId('next'));

    expect(props.on_blocking_error).toHaveBeenCalledTimes(1);
    expect(props.on_next).not.toHaveBeenCalled();
    expect(props.on_step_change).not.toHaveBeenCalled();
  });

  test('clicking Next on valid personal info calls on_next and requests step change forward', async () => {
    const user = userEvent.setup();
    const { props } = renderWizard({
      is_personal_info_valid: true,
      current_step: 'personal_info' as any
    });

    await user.click(screen.getByTestId('next'));

    expect(props.on_next).toHaveBeenCalledTimes(1);
    expect(props.on_step_change).toHaveBeenCalledTimes(1);

    const payload = (props.on_step_change as jest.Mock).mock.calls[0][0];
    expect(payload).toEqual(expect.objectContaining({
      direction: 'next'
    }));
  });

  test('step indicator: does not allow jumping forward to an incomplete step (ignores click)', async () => {
    const user = userEvent.setup();
    const { props } = renderWizard({
      current_step: 'personal_info' as any,
      completed_steps: []
    });

    await user.click(screen.getByTestId('step-btn-1'));

    expect(props.on_step_change).not.toHaveBeenCalled();
  });

  test('step indicator: allows navigation to completed step (calls on_step_change)', async () => {
    const user = userEvent.setup();
    const { props } = renderWizard({
      current_step: 'document_upload' as any,
      completed_steps: ['personal_info'] as any,
      is_personal_info_valid: true
    });

    expect(screen.getByTestId('active-index')).toHaveTextContent('1');
    expect(screen.getByTestId('max-completed-index')).toHaveTextContent('0');

    await user.click(screen.getByTestId('step-btn-0'));

    expect(props.on_step_change).toHaveBeenCalledTimes(1);
    const payload = (props.on_step_change as jest.Mock).mock.calls[0][0];
    expect(payload).toEqual(expect.objectContaining({
      source: 'step_indicator',
      to_step: 'personal_info'
    }));
  });

  test('Back/Next are disabled while is_submitting=true and do not emit actions', async () => {
    const user = userEvent.setup();
    const { props } = renderWizard({
      current_step: 'document_upload' as any,
      completed_steps: ['personal_info'] as any,
      is_submitting: true,
      document_upload_state: {
        documents: [{ id: 'd1', filename: 'passport.pdf', status: 'success' }],
        accepted_mime_types: ['application/pdf', 'image/jpeg', 'image/png'],
        max_file_size_bytes: 10 * 1024 * 1024,
        max_file_count: 3,
        is_step_valid: true,
        instructions_text: 'Accepted formats: PDF, JPG, PNG. Max size: 10MB. Up to 3 files.'
      } as any
    });

    expect(screen.getByTestId('back')).toBeDisabled();
    expect(screen.getByTestId('next')).toBeDisabled();

    await user.click(screen.getByTestId('back'));
    await user.click(screen.getByTestId('next'));

    expect(props.on_back).not.toHaveBeenCalled();
    expect(props.on_next).not.toHaveBeenCalled();
    expect(props.on_step_change).not.toHaveBeenCalled();
  });

  test('status view: clicking Retry calls on_retry_status_fetch', async () => {
    const user = userEvent.setup();
    const { props } = renderWizard({
      current_step: 'status' as any,
      verification_status_state: { is_loading: false, has_error: true, status: null } as any
    });

    expect(screen.getByTestId('status')).toBeInTheDocument();
    expect(screen.getByTestId('status-error')).toHaveTextContent('true');

    await user.click(screen.getByTestId('status-retry'));
