describe('KycVerificationWizard composed e2e', () => {
  test('shortest happy path: complete all steps and reach Pending review status', async () => {
    const user = userEvent.setup();

    render(
      <WizardHarness
        onBlockingError={jest.fn()}
        onNext={jest.fn()}
        onBack={jest.fn()}
        onStepChange={jest.fn()}
      />
    );

    // Step 1 visible
    expect(screen.getByText(/personal info/i)).toBeInTheDocument();

    // Step indicator semantics: active step has aria-current
    const stepsList = screen.getByRole('list', { name: /kyc steps/i });
    const personalStepBtn = within(stepsList).getByRole('button', { name: /personal info/i });
    expect(personalStepBtn).toHaveAttribute('aria-current', 'step');

    // Back disabled on step 1
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();

    // Confirm personal info
    const confirm = screen.getByRole('checkbox', { name: /i confirm the above information is correct/i });
    await user.click(confirm);

    // Next to step 2
    await user.click(screen.getByRole('button', { name: /^next$/i }));
    expect(screen.getByRole('heading', { level: 2, name: /document upload/i })).toBeInTheDocument();

    // Pick a valid PDF document using the file picker
    const docFileInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    await user.upload(docFileInput, makeFile('passport.pdf', 'application/pdf', 2048));

    // Next to step 3
    await user.click(screen.getByRole('button', { name: /^next$/i }));
    expect(screen.getByRole('heading', { level: 2, name: /selfie/i })).toBeInTheDocument();

    // Upload a valid selfie
    const selfieInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    await user.upload(selfieInput, makeFile('selfie.jpg', 'image/jpeg', 2048));

    // Submit to status view (loading appears)
    await user.click(screen.getByRole('button', { name: /^next$/i }));

    // Status should enter loading state
    expect(screen.getByText(/loading status/i)).toBeInTheDocument();

    // Simulate fetch completion to Pending review via harness hidden control
    await act(async () => {
      screen.getByRole('button', { name: 'statusPending' }).click();
    });

    expect(screen.getByText(/pending review/i)).toBeInTheDocument();
  });

  test('exploratory happy path: mobile condensed indicator, back, step click to completed, remove doc, replace selfie, reach Approved', async () => {
    const user = userEvent.setup();
    const onStepChange = jest.fn();

    render(
      <WizardHarness
        initialIsMobileCondensed
        onStepChange={onStepChange}
      />
    );

    // Attempt jump forward to step 2 while on step 1 should be blocked
    const stepsList = screen.getByRole('list', { name: /kyc steps/i });
    const documentStepBtn = within(stepsList).getByRole('button', { name: /document upload/i });
    expect(documentStepBtn).toHaveAttribute('aria-disabled', 'true');
    await user.click(documentStepBtn);
    expect(screen.getByRole('heading', { level: 2, name: /personal info/i })).toBeInTheDocument();

    // Complete step 1
    await user.click(screen.getByRole('checkbox', { name: /i confirm the above information is correct/i }));
    await user.click(screen.getByRole('button', { name: /^next$/i }));

    // Drag/drop two valid files
    const dropzone = screen.getByTestId('document-upload-dropzone');
    const f1 = makeFile('id_front.png', 'image/png', 2048, 1710000001001);
    const f2 = makeFile('id_back.png', 'image/png', 2048, 1710000001002);

    // Drag over accept -> aria-live polite message
    fireEvent.dragEnter(dropzone, { dataTransfer: { files: [f1, f2] } });
    const live = screen.getByTestId('document-upload-aria-live');
    expect(live).toHaveTextContent(/files will be added/i);

    fireEvent.drop(dropzone, { dataTransfer: { files: [f1, f2] } });

    // Back to step 1
    await user.click(screen.getByRole('button', { name: /back/i }));
    expect(screen.getByRole('heading', { level: 2, name: /personal info/i })).toBeInTheDocument();

    // Step indicator navigate to completed step 2
    const documentStepBtn2 = within(screen.getByRole('list', { name: /kyc steps/i })).getByRole('button', { name: /document upload/i });
    // After completion, it must be enabled for navigation
    expect(documentStepBtn2).not.toHaveAttribute('aria-disabled', 'true');
    await user.click(documentStepBtn2);
    expect(onStepChange).toHaveBeenCalledWith(expect.objectContaining({ source: 'step_indicator', to_step: 'document_upload' }));
    expect(screen.getByRole('heading', { level: 2, name: /document upload/i })).toBeInTheDocument();

    // Remove one document and ensure still can proceed (at least one remains)
    const removeButtons = screen.getAllByRole('button', { name: /remove/i });
    await user.click(removeButtons[0]);

    await user.click(screen.getByRole('button', { name: /^next$/i }));
    expect(screen.getByRole('heading', { level: 2, name: /selfie/i })).toBeInTheDocument();

    // Upload selfie then Replace with another
    const selfieInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    await user.upload(selfieInput, makeFile('selfie1.png', 'image/png', 1024, 1710000002001));

    const replaceBtn = screen.getByRole('button', { name: /replace/i });
    await user.click(replaceBtn);
    await user.upload(selfieInput, makeFile('selfie2.jpg', 'image/jpeg', 1024, 1710000002002));

    await user.click(screen.getByRole('button', { name: /^next$/i }));
    expect(screen.getByText(/loading status/i)).toBeInTheDocument();

    await act(async () => {
      screen.getByRole('button', { name: 'statusApproved' }).click();
    });

    expect(screen.getByText(/approved/i)).toBeInTheDocument();
  });

  test('unhappy invalid document upload and recovery: mixed invalid drop, duplicate/max count errors, Next blocked, keyboard open picker, proceed, status error retry and unknown fallback', async () => {
    const user = userEvent.setup();
    const onBlockingError = jest.fn();
    const onRetryStatusFetch = jest.fn();

    render(
      <WizardHarness
        onBlockingError={onBlockingError}
        onRetryStatusFetch={onRetryStatusFetch}
      />
    );

    // Step 1 -> confirm -> Next
    await user.click(screen.getByRole('checkbox', { name: /i confirm the above information is correct/i }));
    await user.click(screen.getByRole('button', { name: /^next$/i }));

    // Drop mixed valid+invalid; should announce reject message and show error summary
    const dropzone = screen.getByTestId('document-upload-dropzone');
    const ok = makeFile('id.png', 'image/png', 1024, 1710000003001);
    const badType = makeFile('statement.docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 1024, 1710000003002);
    const tooLarge = makeFile('large_scan.pdf', 'application/pdf', 10 * 1024 * 1024 + 1, 1710000003003);

    fireEvent.dragOver(dropzone, { dataTransfer: { files: [ok, badType, tooLarge] } });
    expect(screen.getByTestId('document-upload-aria-live')).toHaveTextContent(/some files are not supported/i);

    fireEvent.drop(dropzone, { dataTransfer: { files: [ok, badType, tooLarge] } });
    const summary = screen.getByTestId('document-upload-error-summary');
    expect(summary).toHaveTextContent(/unsupported file type/i);
    expect(summary).toHaveTextContent(/file too large/i);

    // Duplicate file via picker should show duplicate error and not add
    const input = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    await user.upload(input, makeFile('id.png', 'image/png', 1024, 1710000003001));
    expect(screen.getByTestId('document-upload-error-summary')).toHaveTextContent(/duplicate/i);

    // Exceed max file count
    await user.upload(input, [
      makeFile('a.png', 'image/png', 1024, 1710000003010),
      makeFile('b.png', 'image/png', 1024, 1710000003011),
      makeFile('c.png', 'image/png', 1024, 1710000003012),
      makeFile('d.png', 'image/png', 1024, 1710000003013)
    ] as any);
    expect(screen.getByTestId('document-upload-error-summary')).toHaveTextContent(/max 3 files/i);

    // Force blocking state by removing all docs, then try Next; must not crash and must guide recovery
    const removeButtons = screen.queryAllByRole('button', { name: /remove/i });
    for (const btn of removeButtons) {
      await user.click(btn);
    }

    await user.click(screen.getByRole('button', { name: /^next$/i }));
    expect(onBlockingError).toHaveBeenCalled();

    // Should surface blocking error message somewhere in step (DocumentUploadStep contract)
    expect(screen.getByText(/please upload at least one document/i)).toBeInTheDocument();

    // Keyboard: focus dropzone then Enter should open picker (input click)
    dropzone.focus();
    expect(dropzone).toHaveFocus();

    const clickSpy = jest.spyOn(input as HTMLInputElement, 'click');
    await user.keyboard('{Enter}');
    expect(clickSpy).toHaveBeenCalled();

    // Select a valid PDF to recover
    await user.upload(input, makeFile('passport.pdf', 'application/pdf', 2048, 1710000004000));

    // Proceed to selfie
    await user.click(screen.getByRole('button', { name: /^next$/i }));
    expect(screen.getByRole('heading', { level: 2, name: /selfie/i })).toBeInTheDocument();

    // Selfie upload + submit
    const selfieInput = screen.getByLabelText(/upload/i, { selector: 'input[type="file"]' });
    await user.upload(selfieInput, makeFile('selfie.jpg', 'image/jpeg', 2048, 1710000005000));
    await user.click(screen.getByRole('button', { name: /^next$/i }));

    // Status error once, retry -> loading again
    await act(async () => {
      screen.getByRole('button', { name: 'statusError' }).click();
    });
    expect(screen.getByText(/unable to load status/i)).toBeInTheDocument();

    await user.click(screen.getByRole('button', { name: /retry/i }));
    expect(onRetryStatusFetch).toHaveBeenCalledTimes(1);
    expect(screen.getByText(/loading status/i)).toBeInTheDocument();

    // Unknown status fallback
    await act(async () => {
      screen.getByRole('button', { name: 'statusUnknown' }).click();
    });
    expect(screen.getByText(/status unavailable/i)).toBeInTheDocument();
  });
});
