import { DocumentUpload } from '../DocumentUpload/DocumentUpload';

export type KycDocumentUploadItem = {
  id: string;
  file_name?: string;
  status?: 'empty' | 'selected' | 'uploading' | 'success' | 'failure' | string;
  [key: string]: any;
};

export type KycUploadError = {
  code: string;
  message: string;
  [key: string]: any;
};

export type DocumentUploadStepProps = {
  step_title: string;
  is_active: boolean;
  is_busy?: boolean;
  documents: KycDocumentUploadItem[];
  accepted_mime_types: string[];
  max_file_size_bytes: number;
  max_file_count: number;
  is_step_valid: boolean;
  blocking_error?: string;
  upload_errors?: KycUploadError[];
  instructions_text: string;
  on_add_files: (files: File[], source: 'picker' | 'drop') => void;
  on_remove_file: (document_id: string) => void;
  on_retry_upload?: (document_id: string) => void;
  on_step_validity_change?: (is_valid: boolean) => void;
};

export function DocumentUploadStep(props: DocumentUploadStepProps) {
  const {
    step_title,
    is_active,
    is_busy = false,
    documents,
    accepted_mime_types,
    max_file_size_bytes,
    max_file_count,
    is_step_valid,
    blocking_error,
    upload_errors,
    on_add_files,
    on_remove_file,
    on_retry_upload,
    on_step_validity_change
  } = props;

  const reactId = useId();
  const instructionsId = `document-upload-instructions-${reactId}`;
  const blockingErrorId = `document-upload-blocking-error-${reactId}`;

  const disabled = Boolean(is_active && is_busy);

  const isInvalid = Boolean(!is_step_valid && blocking_error);

  const describedByIds = useMemo(() => {
    const ids: string[] = [instructionsId];
    if (isInvalid) ids.push(blockingErrorId);
    return ids.join(' ');
  }, [instructionsId, isInvalid, blockingErrorId]);

  const prevValidityRef = useRef<boolean | undefined>(undefined);
  useEffect(() => {
    if (!on_step_validity_change) return;

    const prev = prevValidityRef.current;
    if (prev === undefined) {
      prevValidityRef.current = is_step_valid;
      return;
    }

    if (prev !== is_step_valid) {
      prevValidityRef.current = is_step_valid;
      on_step_validity_change(is_step_valid);
    }
  }, [is_step_valid, on_step_validity_change]);

  return (
    <section
      aria-busy={is_active && is_busy ? 'true' : undefined}
      aria-hidden={is_active ? undefined : 'true'}
    >
      <h2 tabIndex={-1}>{step_title}</h2>

      <p id={instructionsId}>{props.instructions_text}</p>

      {!is_step_valid && blocking_error ? (
        <div
          id={blockingErrorId}
          role="alert"
          style={{
            marginTop: 'var(--spacing-8)',
            padding: 'var(--spacing-12)',
            borderRadius: 'var(--radius-8)',
            border: `1px solid var(--color-border-danger)`,
            color: 'var(--color-text-primary)',
            background: 'var(--color-surface-default)'
          }}
        >
          {blocking_error}
        </div>
      ) : null}

      <div style={{ marginTop: 'var(--spacing-12)' }}>
        <DocumentUpload
          label="Upload documents"
          files={documents as any}
          accepted_mime_types={accepted_mime_types}
          max_file_size_bytes={max_file_size_bytes}
          max_files={max_file_count}
          instructions_id={describedByIds}
          errors={upload_errors as any}
          is_invalid={isInvalid}
          disabled={disabled}
          drag_state="idle"
          aria_live_message={undefined}
          on_add_files={({ files, source }: { files: File[]; source: 'picker' | 'drop' }) => {
            on_add_files(files, source);
          }}
          on_remove_file={({ document_id }: { document_id: string }) => {
            on_remove_file(document_id);
          }}
          on_retry_file={({ document_id }: { document_id: string }) => {
            on_retry_upload?.(document_id);
          }}
        />
      </div>
    </section>
  );
}
