{"componentCode":"document_upload","componentName":"Document upload","files":[{"filename":"/app/generated/frontend/src/components/DocumentUpload/DocumentUpload.tsx","content":"import React, { useId, useMemo, useRef } from 'react';

type DocumentDropzoneDragState = 'idle' | 'drag-over-accept' | 'drag-over-reject';

type DocumentUploadFileStatus = 'selected' | 'uploading' | 'success' | 'failure';

type DocumentUploadFileItem = {
  document_id: string;
  filename: string;
  status: DocumentUploadFileStatus;
  error_message?: string;
};

type DocumentUploadErrorItem = {
  id: string;
  message: string;
};

type AddDocumentFilesPayload = {
  files: File[];
  source: 'picker' | 'drop';
};

type RemoveDocumentFilePayload = { document_id: string };

type RetryDocumentFilePayload = { document_id: string };

type DocumentDragStateChangePayload = {
  type: 'dragEnter' | 'dragOver' | 'dragLeave' | 'drop';
  files?: File[];
};

export type DocumentUploadProps = {
  files: DocumentUploadFileItem[];
  disabled?: boolean;
  max_files?: number;
  max_file_size_bytes?: number;
  accepted_mime_types?: string[];
  instructions_id: string;
  label?: string;
  drag_state: DocumentDropzoneDragState;
  aria_live_message?: string;
  errors?: DocumentUploadErrorItem[];
  is_invalid?: boolean;
  on_add_files: (payload: AddDocumentFilesPayload) => void;
  on_remove_file: (payload: RemoveDocumentFilePayload) => void;
  on_retry_file: (payload: RetryDocumentFilePayload) => void;
  on_drag_state_change?: (payload: DocumentDragStateChangePayload) => void;
};

export function DocumentUpload(props: DocumentUploadProps) {
  const {
    files,
    disabled = false,
    max_files = 3,
    max_file_size_bytes = 10 * 1024 * 1024,
    accepted_mime_types = ['application/pdf', 'image/jpeg', 'image/png'],
    instructions_id,
    label = 'Upload documents',
    drag_state,
    aria_live_message,
    errors,
    is_invalid,
    on_add_files,
    on_remove_file,
    on_retry_file,
    on_drag_state_change
  } = props;

  const reactId = useId();
  const inputRef = useRef<HTMLInputElement | null>(null);

  const errorSummaryId = useMemo(() => `document-upload-error-summary-${reactId}`, [reactId]);

  const describedBy = useMemo(() => {
    const ids: string[] = [];
    if (instructions_id) ids.push(instructions_id);
    if (errors && errors.length > 0) ids.push(errorSummaryId);
    return ids.join(' ');
  }, [instructions_id, errors, errorSummaryId]);

  const acceptAttr = useMemo(() => {
    // Input accept supports mime types.
    return accepted_mime_types.join(',');
  }, [accepted_mime_types]);

  const dragStyle: React.CSSProperties = useMemo(() => {
    const base: React.CSSProperties = {
      border: `1px dashed var(--color-border-subtle)`,
      background: `var(--color-surface-muted)`,
      borderRadius: `var(--radius-12)`,
      padding: `var(--spacing-16)`,
      minHeight: 120,
      boxShadow: `var(--shadow-sm)`,
      color: `var(--color-text-primary)`,
      outline: 'none'
    };

    if (drag_state === 'drag-over-accept') {
      return {
        ...base,
        border: `1px dashed var(--color-status-success)`
      };
    }

    if (drag_state === 'drag-over-reject') {
      return {
        ...base,
        border: `1px dashed var(--color-border-danger)`
      };
    }

    return base;
  }, [drag_state]);

  const buttonBaseStyle: React.CSSProperties = {
    height: 44,
    padding: `0 var(--spacing-12)`,
    borderRadius: `var(--radius-8)`,
    border: `1px solid var(--color-border-subtle)`,
    background: `var(--color-surface-default)`,
    color: `var(--color-text-primary)`,
    fontSize: `var(--font-size-body)`,
    fontWeight: `var(--font-weight-medium)`,
    cursor: 'pointer'
  };

  const smallButtonStyle: React.CSSProperties = {
    ...buttonBaseStyle,
    height: 36,
    padding: `0 var(--spacing-8)`,
    fontSize: `var(--font-size-label)`
  };

  const handleOpenPicker = () => {
    if (disabled) return;
    inputRef.current?.click();
  };

  const handleInputChange: React.ChangeEventHandler<HTMLInputElement> = (e) => {
