    if (isDisabled) {
      e.preventDefault();
      return;
    }
    on_next();
  };

  return (
    <button
      type="button"
      onClick={handleClick}
      disabled={isDisabled}
      aria-disabled={isDisabled ? 'true' : 'false'}
    >
      {label}
    </button>
  );
}
