        <button type="button" onClick={() => setState((s) => ({ ...s, is_confirmed: false }))}>unconfirm</button>
        <button type="button" onClick={() => {
          const f = makeFile('passport.pdf', 'application/pdf', 1024);
          void onAddDocFiles([f], 'picker');
        }}>addDocValid</button>
        <button type="button" onClick={() => {
          const f = makeFile('id_front.png', 'image/png', 1024, 1710000000001);
          const f2 = makeFile('id_back.png', 'image/png', 1024, 1710000000002);
