        }}>dropDocsValid</button>
        <button type="button" onClick={() => {
          const ok = makeFile('id.png', 'image/png', 1024, 1710000000003);
          const badType = makeFile('statement.docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 1024, 1710000000004);
          const tooLarge = makeFile('large_scan.pdf', 'application/pdf', maxBytes + 1, 1710000000005);
