import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { KycVerificationWizard } from './KycVerificationWizard';

jest.mock('../KycStepIndicator/KycStepIndicator', () => {
  return {
    KycStepIndicator: (props: any) => {
      const { steps, active_step_index, max_completed_step_index, on_step_click } = props;
      return (
        <div data-testid="step-indicator">
          <div data-testid="active-index">{active_step_index}</div>
          <div data-testid="max-completed-index">{max_completed_step_index}</div>
          <div>
            {steps?.map((s: any, idx: number) => {
              const disabled = idx > max_completed_step_index;
              return (
                <button
                  key={s?.id ?? s?.code ?? s?.label ?? idx}
                  type="button"
                  data-testid={`step-btn-${idx}`}
                  aria-disabled={disabled ? 'true' : 'false'}
                  aria-current={idx === active_step_index ? 'step' : undefined}
                  onClick={() => on_step_click?.({ step_index: idx })}
                >
                  {s?.label ?? s?.name ?? String(idx)}
                </button>
              );
            })}
          </div>
        </div>
      );
    }
  };
});

jest.mock('../WizardNavigation/WizardNavigation', () => {
  return {
    WizardNavigation: (props: any) => {
      const { can_go_back, can_go_next, is_submitting, on_back, on_next, back_label, next_label } = props;
      return (
        <div data-testid="wizard-nav">
          <button
            type="button"
            data-testid="back"
            disabled={!can_go_back || is_submitting}
            aria-disabled={!can_go_back || is_submitting ? 'true' : 'false'}
            onClick={() => on_back?.()}
          >
            {back_label ?? 'Back'}
          </button>
          <button
            type="button"
            data-testid="next"
            disabled={!can_go_next || is_submitting}
            aria-disabled={!can_go_next || is_submitting ? 'true' : 'false'}
            onClick={() => on_next?.()}
          >
            {next_label ?? 'Next'}
          </button>
        </div>
      );
    }
  };
});

jest.mock('../PersonalInfoStep/PersonalInfoStep', () => {
  return {
    PersonalInfoStep: (props: any) => {
      return (
        <section data-testid="personal-step">
          <h2 id={props.step_heading_id} tabIndex={-1}>
            {props.step_title}
          </h2>
          <div data-testid="personal-active">{String(props.is_active)}</div>
          <div data-testid="personal-confirmed">{String(props.is_confirmed)}</div>
          <div data-testid="personal-error">{String(props.has_error)}</div>
