      );
    }
  };
});

jest.mock('../DocumentUploadStep/DocumentUploadStep', () => {
  return {
    DocumentUploadStep: (props: any) => {
      return (
        <section data-testid="document-step" aria-busy={props.is_active && props.is_busy ? 'true' : 'false'}>
          <h2 tabIndex={-1}>{props.step_title}</h2>
          <div data-testid="document-active">{String(props.is_active)}</div>
