{"componentCode":"document_upload","componentName":"Document upload","files":[{"filename":"/app/generated/frontend/src/components/DocumentUpload/DocumentUpload.tsx","content":"import React, { useCallback, useId, useMemo, useRef } from 'react';
import styles from './DocumentUpload.module.css';

export type DocumentDropzoneDragState = 'idle' | 'drag-over-accept' | 'drag-over-reject';

export type DocumentUploadFileStatus =
  | 'selected'
  | 'uploading'
  | 'success'
  | 'failure';

export type DocumentUploadFileItem = {
  document_id: string;
  filename: string;
  status: DocumentUploadFileStatus;
  progress?: number;
  error_message?: string;
};

export type DocumentUploadErrorItem = {
  id: string;
  message: string;
};

export type AddDocumentFilesPayload = {
  files: File[];
  source: 'picker' | 'drop';
};

export type RemoveDocumentFilePayload = {
  document_id: string;
};

export type RetryDocumentFilePayload = {
  document_id: string;
};

export type DocumentDragStateChangePayload = {
  event: 'dragEnter' | 'dragOver' | 'dragLeave' | 'drop';
};

export type DocumentUploadProps = {
  files: DocumentUploadFileItem[];
  disabled?: boolean;
  max_files?: number;
  max_file_size_bytes?: number;
  accepted_mime_types?: string[];
  instructions_id: string;
  label?: string;
  drag_state: DocumentDropzoneDragState;
  aria_live_message?: string;
  errors?: DocumentUploadErrorItem[];
  is_invalid?: boolean;
  on_add_files: (payload: AddDocumentFilesPayload) => void;
  on_remove_file: (payload: RemoveDocumentFilePayload) => void;
  on_retry_file: (payload: RetryDocumentFilePayload) => void;
  on_drag_state_change?: (payload: DocumentDragStateChangePayload) => void;
};

export function DocumentUpload(props: DocumentUploadProps) {
  const {
    files,
    disabled = false,
    instructions_id,
    label,
    drag_state,
    aria_live_message,
    errors,
    is_invalid,
    on_add_files,
    on_remove_file,
    on_retry_file,
    on_drag_state_change
  } = props;

  const inputRef = useRef<HTMLInputElement | null>(null);
  const reactId = useId();
  const inputId = `document-upload-input-${reactId}`;

  const errorSummaryId = useMemo(() => {
    if (!errors || errors.length === 0) return undefined;
    return `document-upload-error-summary-${reactId}`;
  }, [errors, reactId]);

  const describedBy = useMemo(() => {
    const ids: string[] = [];
    if (instructions_id) ids.push(instructions_id);
    if (errorSummaryId) ids.push(errorSummaryId);
    return ids.join(' ');
  }, [instructions_id, errorSummaryId]);

  const triggerPicker = useCallback(() => {
    if (disabled) return;
    inputRef.current?.click();
  }, [disabled]);

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled) return;
      const list = e.target.files;
      if (!list || list.length === 0) return;
      const nextFiles = Array.from(list);
      on_add_files({ files: nextFiles, source: 'picker' });
      // Allow re-selecting the same file(s) to trigger onChange again.
      e.target.value = '';
    },
    [disabled, on_add_files]
  );

  const handleDrop = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      if (disabled) return;

      on_drag_state_change?.({ event: 'drop' });

      const list = e.dataTransfer?.files;
      if (!list || list.length === 0) return;
      on_add_files({ files: Array.from(list), source: 'drop' });
    },
    [disabled, on_add_files, on_drag_state_change]
  );

  const handleDragEnter = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      if (disabled) return;
      on_drag_state_change?.({ event: 'dragEnter' });
    },
    [disabled, on_drag_state_change]
  );

  const handleDragOver = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      if (disabled) return;
      on_drag_state_change?.({ event: 'dragOver' });
    },
    [disabled, on_drag_state_change]
  );

  const handleDragLeave = useCallback(
    (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      if (disabled) return;
      on_drag_state_change?.({ event: 'dragLeave' });
    },
    [disabled, on_drag_state_change]
  );

  const handleDropzoneKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (disabled) return;
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        triggerPicker();
      }
    },
    [disabled, triggerPicker]
  );

  const acceptAttr = useMemo(() => {
    // Parent validates; this is primarily for picker UX.
    return 'application/pdf,image/jpeg,image/png';
  }, []);

  const dropzoneClassName = useMemo(() => {
    const classes = [styles.dropzone];
    if (drag_state === 'drag-over-accept') classes.push(styles.dragAccept);
    if (drag_state === 'drag-over-reject') classes.push(styles.dragReject);
    if (disabled) classes.push(styles.disabled);
    if (is_invalid) classes.push(styles.invalid);
    return classes.join(' ');
  }, [drag_state, disabled, is_invalid]);

  const controlAriaInvalid = is_invalid ? 'true' : undefined;

  return (
    <div className={styles.root}>
      <div
        data-testid="document-upload-aria-live"
        className={styles.srOnly}
        aria-live="polite"
      >
        {aria_live_message || ''}
      </div>

      <div className={styles.header}>
        <div className={styles.labelRow}>
          <label className={styles.label} htmlFor={inputId}>
            {label || 'Upload documents'}
          </label>
        </div>
      </div>

      <input
        ref={inputRef}
        id={inputId}
        className={styles.fileInput}
        type="file"
        multiple
        accept={acceptAttr}
        aria-describedby={describedBy}
        aria-invalid={controlAriaInvalid}
        disabled={disabled}
        onChange={handleInputChange}
      />

      <div
        data-testid="document-upload-dropzone"
        className={dropzoneClassName}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled ? 'true' : undefined}
        aria-describedby={describedBy}
        aria-invalid={controlAriaInvalid}
        onClick={triggerPicker}
        onKeyDown={handleDropzoneKeyDown}
        onDragEnter={handleDragEnter}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
      >
        <div className={styles.dropzoneInner}>
          <div className={styles.dropzoneTitle}>Drag and drop files here</div>
          <div className={styles.dropzoneSubtitle}>or choose files</div>
          <button
            type="button"
            className={styles.chooseButton}
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              triggerPicker();
            }}
            disabled={disabled}
          >
            Choose files
          </button>
        </div>
      </div>

      {errors && errors.length > 0 ? (
        <div
          data-testid="document-upload-error-summary"
          id={errorSummaryId}
          className={styles.errorSummary}
        >
          <ul className={styles.errorList}>
            {errors.map((err) => (
              <li key={err.id} id={err.id} className={styles.errorItem}>
                {err.message}
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      <div className={styles.fileList} aria-label="Selected documents">
        {files.length === 0 ? (
          <div className={styles.empty}>No files selected.</div>
        ) : (
          <ul className={styles.list}>
            {files.map((f) => {
              const isFailure = f.status === 'failure';
              const statusText =
                f.status === 'uploading'
                  ? 'Uploading'
                  : f.status === 'success'
                    ? 'Uploaded'
                    : f.status === 'failure'
                      ? 'Failed'
                      : 'Selected';

              return (
                <li key={f.document_id} className={styles.listItem}>
