import React from 'react';

export type KycVerificationStatus = 'pending_review' | 'approved' | 'rejected';

export interface VerificationStatusProps {
  /** Current verification status to display. */
  status: KycVerificationStatus;
  /** Optional rejection reason text to display when status is rejected; if omitted, render a fallback reason message. */
  rejection_reason?: string | null;
  /** Whether to show the "Start over" action when status is rejected. */
  show_start_over?: boolean;
  /** Callback invoked when the user activates the "Start over" action. */
  on_start_over?: () => void;
  /** Accessible label text for screen readers announcing the status. If not provided, derived from status. */
  sr_status_label?: string;
}

const getStatusLabel = (status: KycVerificationStatus): string => {
  switch (status) {
    case 'pending_review':
      return 'Pending review';
    case 'approved':
      return 'Approved';
    case 'rejected':
      return 'Rejected';
    default: {
      // Exhaustiveness safeguard
      const _never: never = status;
      return String(_never);
    }
  }
};

const getStatusIcon = (status: KycVerificationStatus): string => {
  // Simple text icons to avoid adding extra deps; also ensures non-color indicator.
  switch (status) {
    case 'pending_review':
      return '⏳';
    case 'approved':
      return '✓';
    case 'rejected':
      return '✕';
    default: {
      const _never: never = status;
      return String(_never);
    }
  }
};

const getStatusColorToken = (status: KycVerificationStatus): string => {
  switch (status) {
    case 'pending_review':
      return 'var(--color-status-warning)';
    case 'approved':
      return 'var(--color-status-success)';
    case 'rejected':
      return 'var(--color-status-danger)';
    default: {
      const _never: never = status;
      return String(_never);
    }
  }
};

export const VerificationStatus: React.FC<VerificationStatusProps> = ({
  status,
  rejection_reason,
  show_start_over = false,
  on_start_over,
  sr_status_label
}) => {
  const statusLabel = getStatusLabel(status);
  const derivedSr = `Verification status: ${statusLabel}`;
  const srLabel = sr_status_label ?? derivedSr;

  const isRejected = status === 'rejected';
  const reasonText = isRejected
    ? `Reason: ${rejection_reason && rejection_reason.trim().length > 0 ? rejection_reason : 'Not provided'}`
    : null;

  return (
    <section
      aria-label="Verification status"
      style={{
        background: 'var(--color-surface-default)',
        border: '1px solid var(--color-border-subtle)',
        borderRadius: 'var(--radius-12)',
        boxShadow: 'var(--shadow-sm)',
        padding: 'var(--spacing-16)',
        color: 'var(--color-text-primary)',
        fontSize: 'var(--font-size-body)'
      }}
    >
      {/* Ensure tests can find SR label either via aria-label or text. */}
      <div aria-label={srLabel} style={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(1px, 1px, 1px, 1px)', whiteSpace: 'nowrap' }}>
        {srLabel}
      </div>

      <div style={{ display: 'flex', gap: 'var(--spacing-12)', alignItems: 'center' }}>
        <span
          aria-hidden="true"
          style={{
            display: 'inline-flex',
            width: 32,
            height: 32,
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: 'var(--radius-8)',
            background: 'var(--color-surface-muted)',
            border: `1px solid var(--color-border-subtle)`,
            color: getStatusColorToken(status),
            fontWeight: 'var(--font-weight-medium)'
          }}
        >
          {getStatusIcon(status)}
        </span>

        <div style={{ minWidth: 0 }}>
          <div
            style={{
              fontSize: 'var(--font-size-body)',
              fontWeight: 'var(--font-weight-medium)',
              lineHeight: 1.2
            }}
          >
            {statusLabel}
          </div>
          <div style={{ marginTop: 'var(--spacing-4)', color: 'var(--color-text-secondary)', fontSize: 'var(--font-size-label)' }}>
            {status === 'pending_review'
              ? 'Your submission is being reviewed.'
              : status === 'approved'
                ? 'Your identity has been verified.'
                : 'Your submission was rejected.'}
          </div>
        </div>
      </div>

      {isRejected && (
        <div style={{ marginTop: 'var(--spacing-16)' }}>
          <div style={{ color: 'var(--color-text-primary)', fontSize: 'var(--font-size-body)' }}>{reasonText}</div>

          {show_start_over && (
            <div style={{ marginTop: 'var(--spacing-16)' }}>
              <button
                type="button"
                onClick={() => on_start_over?.()}
                style={{
                  appearance: 'none',
                  border: '1px solid var(--color-border-subtle)',
                  borderRadius: 'var(--radius-8)',
                  background: 'var(--color-surface-muted)',
                  color: 'var(--color-text-primary)',
                  padding: 'var(--spacing-12) var(--spacing-16)',
                  fontSize: 'var(--font-size-body)',
                  fontWeight: 'var(--font-weight-medium)',
                  cursor: 'pointer'
                }}
              >
                Start over
              </button>
            </div>
          )}
        </div>
      )}
    </section>
  );
};

