  /** Whether the button should present a loading state (used alongside a loading label). */
  loading?: boolean;
  /** Callback fired when the user activates the button (click/keyboard). */
  on_press: () => void;
};

export function WizardNextButton({
  label,
  disabled,
  loading = false,
  on_press
}: WizardNextButtonProps) {
  // Native <button> handles Enter/Space activation semantics.
  // When disabled, it won't fire click events.
  return (
    <button
      type="button"
      className={styles.button}
      disabled={disabled}
      aria-busy={loading ? true : undefined}
      onClick={() => {
        if (disabled) return;
        on_press();
      }}
    >
      {label}
    </button>
  );
}

