import React from 'react';
import { render, screen, within, act, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import KycVerificationWizard from './KycVerificationWizard';

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function createFile(name: string, mime: string, sizeBytes: number) {
  const blob = new Blob([new Uint8Array(Math.max(sizeBytes, 1)).fill(1)], { type: mime });
  return new File([blob], name, { type: mime });
}

async function fillPersonalInfo(user: ReturnType<typeof userEvent.setup>) {
  await user.clear(screen.getByLabelText(/legal first name/i));
  await user.type(screen.getByLabelText(/legal first name/i), 'Ada');
  await user.clear(screen.getByLabelText(/legal last name/i));
  await user.type(screen.getByLabelText(/legal last name/i), 'Lovelace');
  await user.clear(screen.getByLabelText(/date of birth/i));
  await user.type(screen.getByLabelText(/date of birth/i), '1815-12-10');
}

describe('KycVerificationWizard (composed e2e)', () => {
  test('kyc_shortest_happy_submit_pending: completes 3 steps and shows Pending review status on success', async () => {
    const user = userEvent.setup();
    const submit = deferred<any>();
    const onSubmit = jest.fn(() => submit.promise);

    render(<KycVerificationWizard on_submit_kyc={onSubmit} />);

    // Step 1 default: Back disabled; indicator current; aria-live region ready.
    expect(screen.getByRole('heading', { level: 2, name: /personal info/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();

    const stepsNav = screen.getByRole('navigation', { name: /kyc steps/i });
    const stepItems = within(stepsNav).getAllByRole('listitem');
    expect(stepItems[0]).toHaveAttribute('aria-current', 'step');

    const live = screen.getByRole('status');
    expect(live).toHaveAttribute('aria-live', 'polite');

    // Step 1 valid
    await fillPersonalInfo(user);
    const next1 = screen.getByRole('button', { name: /^next$/i });
    expect(next1).toBeEnabled();

    // Next -> Step 2; focus management + announcement
    await user.click(next1);
    const docHeading = await screen.findByRole('heading', { level: 2, name: /document upload/i });
    expect(docHeading).toHaveFocus();
    expect(screen.getByRole('status')).toHaveTextContent(/step 2 of 3: document upload/i);

    // Add a valid document via file picker input
    // The DocumentUploadStep decision includes a hidden <input type=file> (multiple) triggered by a button.
    const docFileInput = document.querySelector('input[type="file"][multiple]') as HTMLInputElement | null;
    expect(docFileInput).not.toBeNull();

    const validPdf = createFile('passport.pdf', 'application/pdf', 1024);
    await user.upload(docFileInput!, validPdf);

    // While uploading, Next should be disabled and show "Uploading…".
    // Allow either exact label on the button or presence of text on the button.
    const uploadingNext = await screen.findByRole('button', { name: /uploading/i });
    expect(uploadingNext).toBeDisabled();

    // Wait for upload completion by observing Next returns to normal and enabled.
    const next2 = await screen.findByRole('button', { name: /^next$/i });
    expect(next2).toBeEnabled();

    // Next -> Step 3
    await user.click(next2);
    const selfieHeading = await screen.findByRole('heading', { level: 2, name: /selfie/i });
    expect(selfieHeading).toHaveFocus();
    expect(screen.getByRole('status')).toHaveTextContent(/step 3 of 3: selfie/i);

    // Upload selfie
    const selfieInput = document.querySelector('input[type="file"]:not([multiple])') as HTMLInputElement | null;
    expect(selfieInput).not.toBeNull();
    const selfieFile = createFile('selfie.png', 'image/png', 2048);
    await user.upload(selfieInput!, selfieFile);

    const next3 = screen.getByRole('button', { name: /^next$/i });
    expect(next3).toBeEnabled();

    // Submit -> Submitting… and nav disabled
    await user.click(next3);
    expect(onSubmit).toHaveBeenCalledTimes(1);
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /submitting/i })).toBeDisabled();

    await act(async () => {
      submit.resolve({ status: 'pending_review' });
      await submit.promise;
    });

    // Status view
    expect(await screen.findByRole('heading', { name: /verification status/i })).toBeInTheDocument();
    // SR label per decision can be aria-label or visible text; prefer label query.
    expect(
      screen.queryByLabelText(/verification status:\s*pending review/i) ??
        screen.getByText(/verification status:\s*pending review/i)
    ).toBeTruthy();
    expect(screen.getByText(/pending review/i)).toBeInTheDocument();
  });

  test('kyc_exploratory_happy_review_and_retry_then_submit: invalid Step 1 blocks, doc upload drag-drop + remove + retry, camera unavailable fallback, back/next preserves state, submit fails then retry succeeds', async () => {
    const user = userEvent.setup();

    const firstSubmit = deferred<any>();
    const retrySubmit = deferred<any>();
    const onSubmit = jest.fn(() => firstSubmit.promise);
    const onRetry = jest.fn(() => retrySubmit.promise);

    // Simulate small screen for responsive rules (where used)
    // (JSDOM may not trigger CSS, but we keep the intent and ensure no crashes.)
    Object.defineProperty(window, 'innerWidth', { value: 375, writable: true });
    fireEvent(window, new Event('resize'));

    render(<KycVerificationWizard on_submit_kyc={onSubmit} on_retry_submit={onRetry} />);

    // Attempt Next with invalid personal info: should not navigate; should show inline errors and focus first invalid.
    const next = screen.getByRole('button', { name: /^next$/i });
    expect(next).toBeDisabled();

    // Force a "Next attempt" via keyboard on the Next button is not possible when disabled;
    // Instead, trigger blur validation then ensure gating still prevents progression.
    // (Wizard decision: validate on blur and on Next click; disabled gating is the primary block.)
    screen.getByLabelText(/legal first name/i).focus();
    await user.tab();

    // After blur, errors should be discoverable; first invalid field is still first name.
    const firstName = screen.getByLabelText(/legal first name/i);
    expect(firstName).toHaveAttribute('aria-invalid', 'true');
    expect(firstName.getAttribute('aria-describedby') || '').not.toEqual('');

    // Fix personal info then Next.
    await fillPersonalInfo(user);
    const nextEnabled = screen.getByRole('button', { name: /^next$/i });
    expect(nextEnabled).toBeEnabled();
    await user.click(nextEnabled);

    const docHeading = await screen.findByRole('heading', { level: 2, name: /document upload/i });
    expect(docHeading).toHaveFocus();

    // Drag-and-drop two valid files onto drop zone button.
    const dropZone = screen.getByRole('button', { name: /upload documents/i });

    const f1 = createFile('id.pdf', 'application/pdf', 2000);
    const f2 = createFile('license.jpg', 'image/jpeg', 3000);
    const dataTransfer = { files: [f1, f2], items: [] } as unknown as DataTransfer;
    fireEvent.drop(dropZone, { dataTransfer });

    // While uploading, Next disabled and labeled Uploading…
    expect(await screen.findByRole('button', { name: /uploading/i })).toBeDisabled();

    // Remove one file (any remove button) to test list interaction + parent recalculation.
    const removeButtons = await screen.findAllByRole('button', { name: /remove/i });
    expect(removeButtons.length).toBeGreaterThan(0);
    await user.click(removeButtons[0]);

    // Simulate an upload failure and retry: expect an Upload failed row and Retry button appears.
    // The component may surface retry after internal state; we look for it.
    const retryBtn = await screen.findByRole('button', { name: /retry/i });
    await user.click(retryBtn);

    // Eventually Next enabled again after success
    const nextAfterDocs = await screen.findByRole('button', { name: /^next$/i });
    expect(nextAfterDocs).toBeEnabled();
    await user.click(nextAfterDocs);

    const selfieHeading = await screen.findByRole('heading', { level: 2, name: /selfie/i });
    expect(selfieHeading).toHaveFocus();

    // Attempt camera, but expect fallback message and upload mode when camera unavailable.
    const useCamera = screen.queryByRole('radio', { name: /use camera/i }) ?? screen.queryByRole('button', { name: /use camera/i });
    expect(useCamera).toBeTruthy();
    if (useCamera) {
      await user.click(useCamera);
    }

    expect(await screen.findByText(/camera unavailable\. upload a selfie instead\./i)).toBeInTheDocument();

    // Upload selfie, then Back to docs, then Next back to selfie; ensure selfie still present.
    const selfieInput = document.querySelector('input[type="file"]:not([multiple])') as HTMLInputElement | null;
    expect(selfieInput).not.toBeNull();
    await user.upload(selfieInput!, createFile('selfie.jpeg', 'image/jpeg', 2048));

    // Preview should appear
    expect(await screen.findByRole('img', { name: /selfie preview/i })).toBeInTheDocument();

    await user.click(screen.getByRole('button', { name: /back/i }));
    expect(await screen.findByRole('heading', { level: 2, name: /document upload/i })).toHaveFocus();

    await user.click(screen.getByRole('button', { name: /^next$/i }));
    expect(await screen.findByRole('heading', { level: 2, name: /selfie/i })).toHaveFocus();
    expect(await screen.findByRole('img', { name: /selfie preview/i })).toBeInTheDocument();

    // Submit: fail first, show alert, then retry succeeds.
    await user.click(screen.getByRole('button', { name: /^next$/i }));

    await act(async () => {
      firstSubmit.reject(new Error('transient'));
      try {
        await firstSubmit.promise;
      } catch {
        // ignore
      }
    });

    const alert = await screen.findByRole('alert');
    expect(alert).toHaveTextContent(/something went wrong\. please try again\./i);

    const retry = within(alert).getByRole('button', { name: /retry/i });
    await user.click(retry);
    expect(onRetry).toHaveBeenCalledTimes(1);

    await act(async () => {
      retrySubmit.resolve({ status: 'pending_review' });
      await retrySubmit.promise;
    });

    expect(await screen.findByRole('heading', { name: /verification status/i })).toBeInTheDocument();
    expect(
      screen.queryByLabelText(/verification status:\s*pending review/i) ??
        screen.getByText(/verification status:\s*pending review/i)
    ).toBeTruthy();
  });

  test('kyc_unhappy_invalid_document_type_and_size_then_recover: rejects invalid docs (type + oversize), blocks Next until valid upload succeeds, then proceeds to Step 3', async () => {
    const user = userEvent.setup();
    render(<KycVerificationWizard on_submit_kyc={async () => ({ status: 'pending_review' } as any)} />);

    // Step 1 -> Step 2
    await fillPersonalInfo(user);
    await user.click(screen.getByRole('button', { name: /^next$/i }));
    expect(await screen.findByRole('heading', { level: 2, name: /document upload/i })).toBeInTheDocument();

    const fileInput = document.querySelector('input[type="file"][multiple]') as HTMLInputElement | null;
    expect(fileInput).not.toBeNull();

    // Unsupported type (e.g., .docx)
    const docx = createFile('bad.docx', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 1500);
    await user.upload(fileInput!, docx);

    const alert1 = await screen.findByRole('alert');
    expect(alert1).toBeInTheDocument();

    // Next should remain disabled because step invalid.
    // It may be disabled with label Next.
    const next = screen.getByRole('button', { name: /^next$/i });
    expect(next).toBeDisabled();

    // Oversize supported type (>10MB)
    const oversizePdf = createFile('huge.pdf', 'application/pdf', 10 * 1024 * 1024 + 1);
    await user.upload(fileInput!, oversizePdf);
    expect(await screen.findByRole('alert')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^next$/i })).toBeDisabled();

    // Valid file
    const okPng = createFile('ok.png', 'image/png', 5000);
    await user.upload(fileInput!, okPng);

    // While uploading
    expect(await screen.findByRole('button', { name: /uploading/i })).toBeDisabled();

    // After upload success, Next enabled and proceeds to Step 3
    const nextEnabled = await screen.findByRole('button', { name: /^next$/i });
    expect(nextEnabled).toBeEnabled();
    await user.click(nextEnabled);

    const selfieHeading = await screen.findByRole('heading', { level: 2, name: /selfie/i });
    expect(selfieHeading).toHaveFocus();
    expect(screen.getByRole('status')).toHaveTextContent(/step 3 of 3: selfie/i);
  });
});

import React from 'react';
import { render, screen, within } from '@testing-library/react';
import '@testing-library/jest-dom';

import { KycStepIndicator } from './KycStepIndicator';

describe('KycStepIndicator', () => {
  const steps = ['Personal info', 'Document upload', 'Selfie'];

  it('renders a nav with default aria-label and an ordered list of non-interactive step labels', () => {
    const { container } = render(
      <KycStepIndicator steps={steps} current_step_index={0} total_steps={3} />
    );

    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    // Ensure list semantics are present and ordered list is used
    const list = container.querySelector('nav ol');
    expect(list).toBeInTheDocument();

    // Labels are rendered as text
    for (const step of steps) {
      expect(within(nav).getByText(step)).toBeInTheDocument();
    }

    // Non-interactive: no buttons/links for step labels
    expect(within(nav).queryAllByRole('button')).toHaveLength(0);
    expect(within(nav).queryAllByRole('link')).toHaveLength(0);
  });

  it('marks only the current step with aria-current="step" and shows helper text for Step 1 of 3', () => {
    render(<KycStepIndicator steps={steps} current_step_index={0} total_steps={3} />);

    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    const current = nav.querySelector('[aria-current="step"]');
    expect(current).toBeInTheDocument();
    expect(current).toHaveTextContent('Personal info');

    // Only one aria-current=step
    expect(nav.querySelectorAll('[aria-current="step"]').length).toBe(1);

    // Visible progress helper text
    expect(screen.getByText(/step\s*1\s*of\s*3/i)).toBeInTheDocument();
  });

  it('updates aria-current when current_step_index changes (Step 2 of 3)', () => {
    render(<KycStepIndicator steps={steps} current_step_index={1} total_steps={3} />);

    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    const current = nav.querySelector('[aria-current="step"]');
    expect(current).toBeInTheDocument();
    expect(current).toHaveTextContent('Document upload');
    expect(nav.querySelectorAll('[aria-current="step"]').length).toBe(1);

    expect(screen.getByText(/step\s*2\s*of\s*3/i)).toBeInTheDocument();
  });

  it('uses provided aria_label for the navigation landmark', () => {
    render(
      <KycStepIndicator
        steps={steps}
        current_step_index={2}
        total_steps={3}
        aria_label="Onboarding steps"
      />
    );

    expect(screen.getByRole('navigation', { name: /onboarding steps/i })).toBeInTheDocument();
    expect(screen.getByText(/step\s*3\s*of\s*3/i)).toBeInTheDocument();

    const nav = screen.getByRole('navigation', { name: /onboarding steps/i });
    const current = nav.querySelector('[aria-current="step"]');
    expect(current).toBeInTheDocument();
    expect(current).toHaveTextContent('Selfie');
  });
});

import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { PersonalInfoStep } from './PersonalInfoStep';

type Values = {
  legal_first_name: string;
  legal_last_name: string;
  date_of_birth: string;
};

type Errors = Partial<Record<keyof Values, string>>;

describe('PersonalInfoStep', () => {
  const baseValues: Values = {
    legal_first_name: 'Jane',
    legal_last_name: 'Doe',
    date_of_birth: '1990-01-01'
  };

  const renderStep = (overrides?: Partial<React.ComponentProps<typeof PersonalInfoStep>>) => {
    const props: React.ComponentProps<typeof PersonalInfoStep> = {
      values: baseValues as any,
      errors: {} as any,
      show_validation: false,
      is_disabled: false,
      on_change: jest.fn(),
      on_blur: jest.fn(),
      ...overrides
    };

    const view = render(<PersonalInfoStep {...props} />);
    return { props, ...view };
  };

  it('renders the required fields with controlled values', () => {
    renderStep();

    const firstName = screen.getByLabelText(/legal first name/i) as HTMLInputElement;
    const lastName = screen.getByLabelText(/legal last name/i) as HTMLInputElement;
    const dob = screen.getByLabelText(/date of birth/i) as HTMLInputElement;

    expect(firstName).toBeInTheDocument();
    expect(lastName).toBeInTheDocument();
    expect(dob).toBeInTheDocument();

    expect(firstName.value).toBe(baseValues.legal_first_name);
    expect(lastName.value).toBe(baseValues.legal_last_name);
    expect(dob.value).toBe(baseValues.date_of_birth);
  });

  it('calls on_change with a payload when a field changes', async () => {
    const user = userEvent.setup();
    const { props } = renderStep({
      values: { ...baseValues, legal_first_name: '' } as any
    });

    const firstName = screen.getByLabelText(/legal first name/i) as HTMLInputElement;
    await user.type(firstName, 'A');

    expect(props.on_change).toHaveBeenCalled();

    // Expect shape: { field_name, value }
    const lastCall = (props.on_change as jest.Mock).mock.calls[(props.on_change as jest.Mock).mock.calls.length - 1][0];
    expect(lastCall).toEqual(
      expect.objectContaining({
        field_name: expect.any(String),
        value: expect.any(String)
      })
    );

    // And expect it targets the correct field.
    expect(lastCall.field_name).toBe('legal_first_name');
  });

  it('calls on_blur with the field name when provided', async () => {
    const user = userEvent.setup();
    const on_blur = jest.fn();
    renderStep({ on_blur });

    const lastName = screen.getByLabelText(/legal last name/i);
    await user.click(lastName);
    await user.tab();

    expect(on_blur).toHaveBeenCalledWith('legal_last_name');
  });

  it('does not crash if on_blur is not provided', async () => {
    const user = userEvent.setup();
    renderStep({ on_blur: undefined });

    const dob = screen.getByLabelText(/date of birth/i);
    await user.click(dob);
    await user.tab();

    // No assertion needed beyond no throw; ensure input still exists.
    expect(dob).toBeInTheDocument();
  });

  it('when show_validation is true, renders inline errors and associates them via aria-describedby + aria-invalid', () => {
    const errors: Errors = {
      legal_first_name: 'First name is required',
      date_of_birth: 'Date of birth is required'
    };

    renderStep({
      show_validation: true,
      errors: errors as any,
      values: { ...baseValues, legal_first_name: '', date_of_birth: '' } as any
    });

    const firstName = screen.getByLabelText(/legal first name/i);
    const dob = screen.getByLabelText(/date of birth/i);

    const firstNameErr = screen.getByText('First name is required');
    const dobErr = screen.getByText('Date of birth is required');

    expect(firstNameErr).toBeInTheDocument();
    expect(dobErr).toBeInTheDocument();

    expect(firstName).toHaveAttribute('aria-invalid', 'true');
    expect(dob).toHaveAttribute('aria-invalid', 'true');

    const firstNameDescribedBy = firstName.getAttribute('aria-describedby') || '';
    const dobDescribedBy = dob.getAttribute('aria-describedby') || '';

    // The described-by should reference the rendered error element ids.
    expect(firstNameDescribedBy.length).toBeGreaterThan(0);
    expect(dobDescribedBy.length).toBeGreaterThan(0);

    // Verify that the DOM element referenced by the id contains the error text.
    // (Supports components that set describedby to a single id.)
    const firstId = firstNameDescribedBy.split(/\s+/)[0];
    const dobId = dobDescribedBy.split(/\s+/)[0];

    const firstDescEl = document.getElementById(firstId);
    const dobDescEl = document.getElementById(dobId);

    expect(firstDescEl).not.toBeNull();
    expect(dobDescEl).not.toBeNull();

    expect(firstDescEl).toHaveTextContent('First name is required');
    expect(dobDescEl).toHaveTextContent('Date of birth is required');
  });

  it('when show_validation is false, does not show inline errors or aria-invalid even if errors are provided', () => {
    renderStep({
      show_validation: false,
      errors: { legal_last_name: 'Last name is required' } as any,
      values: { ...baseValues, legal_last_name: '' } as any
    });

    const lastName = screen.getByLabelText(/legal last name/i);
    expect(screen.queryByText('Last name is required')).not.toBeInTheDocument();
    expect(lastName).not.toHaveAttribute('aria-invalid', 'true');
  });

  it('disables all inputs when is_disabled is true', () => {
    renderStep({ is_disabled: true });

    expect(screen.getByLabelText(/legal first name/i)).toBeDisabled();
    expect(screen.getByLabelText(/legal last name/i)).toBeDisabled();
    expect(screen.getByLabelText(/date of birth/i)).toBeDisabled();
  });
});

import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { SelfieStep } from './SelfieStep';

type SelfieMode = 'camera' | 'upload';

function createFile(name: string, type: string, sizeBytes = 1024) {
  const blob = new Blob([new Uint8Array(sizeBytes).fill(1)], { type });
  return new File([blob], name, { type });
}

function renderSelfieStep(overrides: Partial<React.ComponentProps<typeof SelfieStep>> = {}) {
  const props: React.ComponentProps<typeof SelfieStep> = {
    mode: 'upload' as SelfieMode,
    selfie_file: null,
    selfie_preview_url: null,
    camera_unavailable_message: null,
    is_valid: false,
    show_validation_errors: false,
    validation_error_message: null,
    accepted_file_types: ['.jpg', '.jpeg', '.png'],
    max_file_size_bytes: 10 * 1024 * 1024,
    is_disabled: false,
    on_mode_change: jest.fn(),
    on_upload_file: jest.fn(),
    on_remove_selfie: jest.fn(),
    on_capture_selfie: jest.fn(),
    on_retake_selfie: jest.fn(),
    on_camera_unavailable: jest.fn(),
    ...overrides
  };

  return {
    user: userEvent.setup(),
    props,
    ...render(<SelfieStep {...props} />)
  };
}

describe('SelfieStep', () => {
  test('renders mode selection and calls on_mode_change when switching modes', async () => {
    const { user, props } = renderSelfieStep({ mode: 'upload' as SelfieMode });

    // Prefer accessible radios if present; otherwise fall back to buttons by name.
    const cameraOption =
      screen.queryByRole('radio', { name: /use camera/i }) ??
      screen.queryByRole('button', { name: /use camera/i });
    const uploadOption =
      screen.queryByRole('radio', { name: /upload a photo/i }) ??
      screen.queryByRole('button', { name: /upload a photo/i });

    expect(cameraOption).toBeTruthy();
    expect(uploadOption).toBeTruthy();

    if (cameraOption) {
      await user.click(cameraOption);
      expect(props.on_mode_change).toHaveBeenCalledWith('camera');
    }
  });

  test('upload mode: file input uses accept derived from accepted_file_types and selecting a file calls on_upload_file', async () => {
    const { user, props } = renderSelfieStep({
      mode: 'upload' as SelfieMode,
      accepted_file_types: ['.jpg', '.jpeg', '.png']
    });

    const fileInput = screen.getByLabelText(/upload a photo/i, { selector: 'input[type="file"]' });
    expect(fileInput).toHaveAttribute('accept', expect.stringContaining('.jpg'));
    expect(fileInput).toHaveAttribute('accept', expect.stringContaining('.jpeg'));
    expect(fileInput).toHaveAttribute('accept', expect.stringContaining('.png'));

    const file = createFile('selfie.jpg', 'image/jpeg');
    await user.upload(fileInput, file);

    expect(props.on_upload_file).toHaveBeenCalledTimes(1);
    expect(props.on_upload_file).toHaveBeenCalledWith(file);
  });

  test('when selfie_preview_url is provided, renders preview image and Remove calls on_remove_selfie', async () => {
    const { user, props } = renderSelfieStep({
      mode: 'upload' as SelfieMode,
      selfie_file: createFile('selfie.png', 'image/png'),
      selfie_preview_url: 'data:image/png;base64,AAAA'
    });

    const img = screen.getByRole('img', { name: /selfie preview/i });
    expect(img).toHaveAttribute('src', 'data:image/png;base64,AAAA');

    const removeBtn = screen.getByRole('button', { name: /remove/i });
    await user.click(removeBtn);
    expect(props.on_remove_selfie).toHaveBeenCalledTimes(1);
  });

  test('when show_validation_errors is true, renders validation_error_message and associates it to upload control via aria-describedby', async () => {
    renderSelfieStep({
      mode: 'upload' as SelfieMode,
      show_validation_errors: true,
      validation_error_message: 'Please provide a selfie.'
    });

    const alert = screen.getByText(/please provide a selfie\./i);
    expect(alert).toBeInTheDocument();

    const fileInput = screen.getByLabelText(/upload a photo/i, { selector: 'input[type="file"]' });
    const describedBy = fileInput.getAttribute('aria-describedby');
    expect(describedBy).toBeTruthy();

    if (describedBy) {
      const ids = describedBy.split(/\s+/).filter(Boolean);
      const describedEls = ids
        .map((id) => document.getElementById(id))
        .filter(Boolean) as HTMLElement[];

      expect(describedEls.length).toBeGreaterThan(0);
      expect(describedEls.some((el) => /please provide a selfie\./i.test(el.textContent ?? ''))).toBe(true);
    }
  });

  test('camera mode: renders Capture/Retake and triggers callbacks', async () => {
    const { user, props } = renderSelfieStep({
      mode: 'camera' as SelfieMode,
      selfie_preview_url: null
    });

    const captureBtn = screen.getByRole('button', { name: /capture/i });
    await user.click(captureBtn);

    expect(props.on_capture_selfie).toHaveBeenCalledTimes(1);
    expect(typeof props.on_capture_selfie.mock.calls[0][0]).toBe('string');

    const retakeBtn = screen.getByRole('button', { name: /retake/i });
    await user.click(retakeBtn);
    expect(props.on_retake_selfie).toHaveBeenCalledTimes(1);
  });

  test('disabled state: prevents interactions and disables controls', async () => {
    const { user, props } = renderSelfieStep({
      is_disabled: true,
      mode: 'upload' as SelfieMode,
      show_validation_errors: true,
      validation_error_message: 'Please provide a selfie.'
    });

    const fileInput = screen.getByLabelText(/upload a photo/i, { selector: 'input[type="file"]' });
    expect(fileInput).toBeDisabled();

    const file = createFile('selfie.jpg', 'image/jpeg');
    await user.upload(fileInput, file);
    expect(props.on_upload_file).not.toHaveBeenCalled();

    const cameraOption =
      screen.queryByRole('radio', { name: /use camera/i }) ??
      screen.queryByRole('button', { name: /use camera/i });

    if (cameraOption) {
      expect(cameraOption).toBeDisabled();
      await user.click(cameraOption);
      expect(props.on_mode_change).not.toHaveBeenCalled();
    }
  });
});

import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

import { WizardBackButton } from './WizardBackButton';

describe('WizardBackButton', () => {
  it('renders a button with the provided label', () => {
    const onBack = jest.fn();
    render(<WizardBackButton label="Back" disabled={false} on_back={onBack} />);

    expect(screen.getByRole('button', { name: 'Back' })).toBeInTheDocument();
  });

  it('calls on_back on click when enabled', async () => {
    const user = userEvent.setup();
    const onBack = jest.fn();

    render(<WizardBackButton label="Back" disabled={false} on_back={onBack} />);

    await user.click(screen.getByRole('button', { name: 'Back' }));
    expect(onBack).toHaveBeenCalledTimes(1);
  });

  it('calls on_back on Enter/Space when enabled and focused', async () => {
    const user = userEvent.setup();
    const onBack = jest.fn();

    render(<WizardBackButton label="Back" disabled={false} on_back={onBack} />);

    const btn = screen.getByRole('button', { name: 'Back' });
    btn.focus();
    expect(btn).toHaveFocus();

    await user.keyboard('{Enter}');
    await user.keyboard(' ');

    expect(onBack).toHaveBeenCalledTimes(2);
  });

  it('is disabled with the native disabled attribute when disabled=true', () => {
    const onBack = jest.fn();

    render(<WizardBackButton label="Back" disabled={true} on_back={onBack} />);

    const btn = screen.getByRole('button', { name: 'Back' });
    expect(btn).toBeDisabled();
  });

  it('does not call on_back when disabled (click and keyboard)', async () => {
    const user = userEvent.setup();
    const onBack = jest.fn();

    render(<WizardBackButton label="Back" disabled={true} on_back={onBack} />);

    const btn = screen.getByRole('button', { name: 'Back' });
    expect(btn).toBeDisabled();

    await user.click(btn);

    // userEvent will not fire key events on a disabled button; still assert no calls.
    btn.focus();
    await user.keyboard('{Enter}');
    await user.keyboard(' ');

    expect(onBack).not.toHaveBeenCalled();
  });
});

