import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { VerificationStatus } from './VerificationStatus';

type Status = 'pending_review' | 'approved' | 'rejected';

describe('VerificationStatus', () => {
  const renderComponent = (props: Partial<React.ComponentProps<typeof VerificationStatus>> & { status: Status }) => {
    return render(
      <VerificationStatus
        status={props.status as any}
        rejection_reason={props.rejection_reason as any}
        show_start_over={props.show_start_over as any}
        on_start_over={props.on_start_over as any}
        sr_status_label={props.sr_status_label as any}
      />
    );
  };

  it('renders Pending review status and derives an SR label when sr_status_label is not provided', () => {
    renderComponent({ status: 'pending_review' });

    // Visible status text (non-color indicator requirement implies explicit text exists)
    expect(screen.getByText(/pending review/i)).toBeInTheDocument();

    // SR label: allow either aria-label on a status element or an explicit text node.
    // Match the decision copy: "Verification status: Pending review"
    const sr =
      screen.queryByLabelText(/verification status:\s*pending review/i) ??
      screen.queryByText(/verification status:\s*pending review/i);
    expect(sr).toBeTruthy();
  });

  it('renders Approved status', () => {
    renderComponent({ status: 'approved' });
    expect(screen.getByText(/approved/i)).toBeInTheDocument();

    const sr =
      screen.queryByLabelText(/verification status:\s*approved/i) ??
      screen.queryByText(/verification status:\s*approved/i);
    expect(sr).toBeTruthy();
  });

  it('renders Rejected status with provided rejection reason', () => {
    renderComponent({ status: 'rejected', rejection_reason: 'Blurry document photo' });

    expect(screen.getByText(/rejected/i)).toBeInTheDocument();
    expect(screen.getByText(/reason/i)).toBeInTheDocument();
    expect(screen.getByText(/blurry document photo/i)).toBeInTheDocument();

    const sr =
      screen.queryByLabelText(/verification status:\s*rejected/i) ??
      screen.queryByText(/verification status:\s*rejected/i);
    expect(sr).toBeTruthy();
  });

  it('renders Rejected status with fallback reason when rejection_reason is missing', () => {
    renderComponent({ status: 'rejected' });

    expect(screen.getByText(/rejected/i)).toBeInTheDocument();
    // Fallback per decisions
    expect(screen.getByText(/reason:\s*not provided/i)).toBeInTheDocument();
  });

  it('uses provided sr_status_label when passed', () => {
    renderComponent({
      status: 'pending_review',
      sr_status_label: 'Verification status: Waiting for compliance review'
    });

    const sr =
      screen.queryByLabelText(/verification status:\s*waiting for compliance review/i) ??
      screen.queryByText(/verification status:\s*waiting for compliance review/i);
    expect(sr).toBeTruthy();
  });

  it('does not render Start over action by default', () => {
    const onStartOver = jest.fn();
    renderComponent({ status: 'rejected', on_start_over: onStartOver });

    expect(screen.queryByRole('button', { name: /start over/i })).not.toBeInTheDocument();
  });

  it('renders Start over when show_start_over is true and calls on_start_over on activation', async () => {
    const user = userEvent.setup();
    const onStartOver = jest.fn();

    renderComponent({
      status: 'rejected',
      show_start_over: true,
      on_start_over: onStartOver
    });

    const btn = screen.getByRole('button', { name: /start over/i });
    await user.click(btn);

    expect(onStartOver).toHaveBeenCalledTimes(1);
  });
});

