function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (reason?: any) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

describe('KycVerificationWizard', () => {
  test('defaults to Step 1 with Back disabled; indicator marks current step; aria-live region exists', () => {
    render(<KycVerificationWizard on_submit_kyc={async () => ({ status: 'pending_review' } as any)} />);

    // Step 1 heading rendered and focusable target exists.
    expect(screen.getByRole('heading', { level: 2, name: /personal info/i })).toBeInTheDocument();

    // Back disabled on first step.
    const back = screen.getByRole('button', { name: /back/i });
    expect(back).toBeDisabled();

    // Step indicator current step.
    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    const items = within(nav).getAllByRole('listitem');
    expect(items[0]).toHaveAttribute('aria-current', 'step');

    // Helper text "Step X of 3" visible (from step indicator decision).
    expect(within(nav).getByText(/step 1 of 3/i)).toBeInTheDocument();

    // aria-live polite region should exist; text may be empty initially.
    expect(screen.getByRole('status')).toHaveAttribute('aria-live', 'polite');
  });

  test('Next navigates to Step 2, updates aria-live announcement, and moves focus to Step 2 heading', async () => {
    const user = userEvent.setup();
    render(<KycVerificationWizard on_submit_kyc={async () => ({ status: 'pending_review' } as any)} />);

    // Make step 1 valid via filling required fields.
    await user.type(screen.getByLabelText(/legal first name/i), 'Ada');
    await user.type(screen.getByLabelText(/legal last name/i), 'Lovelace');
    await user.type(screen.getByLabelText(/date of birth/i), '1815-12-10');

    const next = screen.getByRole('button', { name: /^next$/i });
    expect(next).toBeEnabled();

    await user.click(next);

    const h2 = await screen.findByRole('heading', { level: 2, name: /document upload/i });
    expect(h2).toHaveFocus();

    // aria-live announces step change
    expect(screen.getByRole('status')).toHaveTextContent(/step 2 of 3: document upload/i);

    // indicator updated
    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    const items = within(nav).getAllByRole('listitem');
    expect(items[1]).toHaveAttribute('aria-current', 'step');
  });

  test('Back from Step 2 returns to Step 1 and moves focus to Step 1 heading', async () => {
    const user = userEvent.setup();
    render(<KycVerificationWizard on_submit_kyc={async () => ({ status: 'pending_review' } as any)} />);

    await user.type(screen.getByLabelText(/legal first name/i), 'Ada');
    await user.type(screen.getByLabelText(/legal last name/i), 'Lovelace');
    await user.type(screen.getByLabelText(/date of birth/i), '1815-12-10');
    await user.click(screen.getByRole('button', { name: /^next$/i }));

    await user.click(screen.getByRole('button', { name: /back/i }));

    const h2 = await screen.findByRole('heading', { level: 2, name: /personal info/i });
    expect(h2).toHaveFocus();
    expect(screen.getByRole('status')).toHaveTextContent(/step 1 of 3: personal info/i);
  });

  test('final submit: disables navigation and shows "Submitting…"; on success renders verification status Pending review', async () => {
    const user = userEvent.setup();
    const submit = deferred<any>();
    const onSubmit = jest.fn(() => submit.promise);

    render(<KycVerificationWizard on_submit_kyc={onSubmit} />);

    // Step 1 valid -> Step 2
    await user.type(screen.getByLabelText(/legal first name/i), 'Ada');
    await user.type(screen.getByLabelText(/legal last name/i), 'Lovelace');
    await user.type(screen.getByLabelText(/date of birth/i), '1815-12-10');
    await user.click(screen.getByRole('button', { name: /^next$/i }));

    // Step 2: assume wizard can proceed after internal upload; here we just proceed.
    await user.click(screen.getByRole('button', { name: /^next$/i }));

    // Step 3: provide selfie to make valid
    await user.click(screen.getByRole('button', { name: /choose selfie file/i }));

    const next = screen.getByRole('button', { name: /^next$/i });
    expect(next).toBeEnabled();

    await user.click(next);

    // During submit
    expect(onSubmit).toHaveBeenCalledTimes(1);
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /submitting/i })).toBeDisabled();

    await act(async () => {
      submit.resolve({ status: 'pending_review' });
      await submit.promise;
    });

    expect(await screen.findByRole('heading', { name: /verification status/i })).toBeInTheDocument();
    expect(screen.getByLabelText(/verification status: pending review/i)).toBeInTheDocument();
    expect(screen.getByText(/status: pending_review/i)).toBeInTheDocument();
  });

  test('submit failure shows global error banner (role=alert) and Retry calls on_retry_submit then transitions to status on success', async () => {
    const user = userEvent.setup();

    const firstAttempt = deferred<any>();
    const retryAttempt = deferred<any>();

    const onSubmit = jest.fn(() => firstAttempt.promise);
    const onRetry = jest.fn(() => retryAttempt.promise);

    render(<KycVerificationWizard on_submit_kyc={onSubmit} on_retry_submit={onRetry} />);

    // Step 1 valid -> Step 2 -> Step 3
    await user.type(screen.getByLabelText(/legal first name/i), 'Ada');
    await user.type(screen.getByLabelText(/legal last name/i), 'Lovelace');
    await user.type(screen.getByLabelText(/date of birth/i), '1815-12-10');
    await user.click(screen.getByRole('button', { name: /^next$/i }));
    await user.click(screen.getByRole('button', { name: /^next$/i }));
    await user.click(screen.getByRole('button', { name: /choose selfie file/i }));

    await user.click(screen.getByRole('button', { name: /^next$/i }));

    await act(async () => {
      firstAttempt.reject(new Error('network'));
      try {
        await firstAttempt.promise;
      } catch {
        // swallow
      }
    });

    const alert = await screen.findByRole('alert');
    expect(alert).toHaveTextContent(/something went wrong\. please try again\./i);

    const retryBtn = within(alert).getByRole('button', { name: /retry/i });
    await user.click(retryBtn);
    expect(onRetry).toHaveBeenCalledTimes(1);

    await act(async () => {
      retryAttempt.resolve({ status: 'pending_review' });
      await retryAttempt.promise;
    });

    expect(await screen.findByRole('heading', { name: /verification status/i })).toBeInTheDocument();
    expect(screen.getByText(/status: pending_review/i)).toBeInTheDocument();
  });

  test('when initial_verification_status is provided, bypasses steps and renders status view', () => {
    render(
      <KycVerificationWizard
        initial_verification_status={'approved' as any}
        on_submit_kyc={async () => ({ status: 'pending_review' } as any)}
      />
    );

    expect(screen.getByRole('heading', { name: /verification status/i })).toBeInTheDocument();
    expect(screen.getByText(/status: approved/i)).toBeInTheDocument();

    // Ensure wizard steps are not shown.
    expect(screen.queryByRole('heading', { level: 2, name: /personal info/i })).not.toBeInTheDocument();
  });

  test('rejected initial status shows fallback reason and Start over resets to Step 1', async () => {
    const user = userEvent.setup();
    render(
      <KycVerificationWizard
        initial_verification_status={'rejected' as any}
        on_submit_kyc={async () => ({ status: 'pending_review' } as any)}
      />
    );

    expect(screen.getByText(/status: rejected/i)).toBeInTheDocument();
    expect(screen.getByText(/reason: not provided/i)).toBeInTheDocument();

    const startOver = screen.getByRole('button', { name: /start over/i });
    await user.click(startOver);

    const h2 = await screen.findByRole('heading', { level: 2, name: /personal info/i });
    expect(h2).toBeInTheDocument();

    const back = screen.getByRole('button', { name: /back/i });
    expect(back).toBeDisabled();

    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    const items = within(nav).getAllByRole('listitem');
    expect(items[0]).toHaveAttribute('aria-current', 'step');
  });
});

