{"componentCode":"kyc_step_indicator","componentName":"Step indicator","coveredBehaviors":["Renders a <nav> wrapping the step list with aria-label derived from aria_label prop (or defaults to "KYC steps")","Renders steps as a non-interactive ordered list (<ol>) with each step label present as text","Marks only the current step item with aria-current="step" based on current_step_index","Renders visible helper/progress text "Step X of N" where X is 1-based current_step_index+1 and N is total_steps"],"coveredStates":["Current step = first step (index 0)","Current step = middle step (index 1)","Custom aria_label provided"],"files":[{"filename":"/app/generated/frontend/src/components/KycStepIndicator/KycStepIndicator.spec.tsx","content":"import React from 'react';
import { render, screen, within } from '@testing-library/react';
import '@testing-library/jest-dom';

import { KycStepIndicator } from './KycStepIndicator';

describe('KycStepIndicator', () => {
  const steps = ['Personal info', 'Document upload', 'Selfie'];

  it('renders a nav with default aria-label and an ordered list of non-interactive step labels', () => {
    const { container } = render(
      <KycStepIndicator steps={steps} current_step_index={0} total_steps={3} />
    );

    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    // Ensure list semantics are present and ordered list is used
    const list = container.querySelector('nav ol');
    expect(list).toBeInTheDocument();

    // Labels are rendered as text
    for (const step of steps) {
      expect(within(nav).getByText(step)).toBeInTheDocument();
    }

    // Non-interactive: no buttons/links for step labels
    expect(within(nav).queryAllByRole('button')).toHaveLength(0);
    expect(within(nav).queryAllByRole('link')).toHaveLength(0);
  });

  it('marks only the current step with aria-current="step" and shows helper text for Step 1 of 3', () => {
    render(<KycStepIndicator steps={steps} current_step_index={0} total_steps={3} />);

    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    const current = nav.querySelector('[aria-current="step"]');
    expect(current).toBeInTheDocument();
    expect(current).toHaveTextContent('Personal info');

    // Only one aria-current=step
    expect(nav.querySelectorAll('[aria-current="step"]').length).toBe(1);

    // Visible progress helper text
    expect(screen.getByText(/step\s*1\s*of\s*3/i)).toBeInTheDocument();
  });

  it('updates aria-current when current_step_index changes (Step 2 of 3)', () => {
    render(<KycStepIndicator steps={steps} current_step_index={1} total_steps={3} />);

    const nav = screen.getByRole('navigation', { name: /kyc steps/i });
    const current = nav.querySelector('[aria-current="step"]');
    expect(current).toBeInTheDocument();
    expect(current).toHaveTextContent('Document upload');
    expect(nav.querySelectorAll('[aria-current="step"]').length).toBe(1);

    expect(screen.getByText(/step\s*2\s*of\s*3/i)).toBeInTheDocument();
  });

  it('uses provided aria_label for the navigation landmark', () => {
    render(
      <KycStepIndicator
        steps={steps}
        current_step_index={2}
        total_steps={3}
        aria_label="Onboarding steps"
      />
    );

    expect(screen.getByRole('navigation', { name: /onboarding steps/i })).toBeInTheDocument();
    expect(screen.getByText(/step\s*3\s*of\s*3/i)).toBeInTheDocument();

    const nav = screen.getByRole('navigation', { name: /onboarding steps/i });
    const current = nav.querySelector('[aria-current="step"]');
    expect(current).toBeInTheDocument();
    expect(current).toHaveTextContent('Selfie');
  });
});
"}]}

