{"componentCode":"personal_info_step","componentName":"Personal info step","coveredBehaviors":["Renders the three required controlled inputs (Legal first name, Legal last name, Date of birth) with values from props","Calls on_change with field_name and value when a field changes","Calls on_blur with the field name when an input is blurred (when on_blur is provided)","When show_validation is true and a field has an error, renders inline error text and associates it to the input via aria-describedby; marks the input aria-invalid=true","When show_validation is false, does not render inline error messaging / aria-invalid even if errors are provided","When is_disabled is true, disables all inputs"],"coveredStates":["Default rendering (no validation UI)","Validation visible with per-field errors","Disabled inputs"],"files":[{"filename":"/app/generated/frontend/src/components/PersonalInfoStep/PersonalInfoStep.spec.tsx","content":"import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { PersonalInfoStep } from './PersonalInfoStep';

type Values = {
  legal_first_name: string;
  legal_last_name: string;
  date_of_birth: string;
};

type Errors = Partial<Record<keyof Values, string>>;

describe('PersonalInfoStep', () => {
  const baseValues: Values = {
    legal_first_name: 'Jane',
    legal_last_name: 'Doe',
    date_of_birth: '1990-01-01'
  };

  const renderStep = (overrides?: Partial<React.ComponentProps<typeof PersonalInfoStep>>) => {
    const props: React.ComponentProps<typeof PersonalInfoStep> = {
      values: baseValues as any,
      errors: {} as any,
      show_validation: false,
      is_disabled: false,
      on_change: jest.fn(),
      on_blur: jest.fn(),
      ...overrides
    };

    const view = render(<PersonalInfoStep {...props} />);
    return { props, ...view };
  };

  it('renders the required fields with controlled values', () => {
    renderStep();

    const firstName = screen.getByLabelText(/legal first name/i) as HTMLInputElement;
    const lastName = screen.getByLabelText(/legal last name/i) as HTMLInputElement;
    const dob = screen.getByLabelText(/date of birth/i) as HTMLInputElement;

    expect(firstName).toBeInTheDocument();
    expect(lastName).toBeInTheDocument();
    expect(dob).toBeInTheDocument();

    expect(firstName.value).toBe(baseValues.legal_first_name);
    expect(lastName.value).toBe(baseValues.legal_last_name);
    expect(dob.value).toBe(baseValues.date_of_birth);
  });

  it('calls on_change with a payload when a field changes', async () => {
    const user = userEvent.setup();
    const { props } = renderStep({
      values: { ...baseValues, legal_first_name: '' } as any
    });

    const firstName = screen.getByLabelText(/legal first name/i) as HTMLInputElement;
    await user.type(firstName, 'A');

    expect(props.on_change).toHaveBeenCalled();

    // Expect shape: { field_name, value }
    const lastCall = (props.on_change as jest.Mock).mock.calls[(props.on_change as jest.Mock).mock.calls.length - 1][0];
    expect(lastCall).toEqual(
      expect.objectContaining({
        field_name: expect.any(String),
        value: expect.any(String)
      })
    );

    // And expect it targets the correct field.
    expect(lastCall.field_name).toBe('legal_first_name');
  });

  it('calls on_blur with the field name when provided', async () => {
    const user = userEvent.setup();
    const on_blur = jest.fn();
    renderStep({ on_blur });

    const lastName = screen.getByLabelText(/legal last name/i);
    await user.click(lastName);
    await user.tab();

    expect(on_blur).toHaveBeenCalledWith('legal_last_name');
  });

  it('does not crash if on_blur is not provided', async () => {
    const user = userEvent.setup();
    renderStep({ on_blur: undefined });

    const dob = screen.getByLabelText(/date of birth/i);
    await user.click(dob);
    await user.tab();

    // No assertion needed beyond no throw; ensure input still exists.
    expect(dob).toBeInTheDocument();
  });

  it('when show_validation is true, renders inline errors and associates them via aria-describedby + aria-invalid', () => {
    const errors: Errors = {
      legal_first_name: 'First name is required',
      date_of_birth: 'Date of birth is required'
    };

    renderStep({
      show_validation: true,
      errors: errors as any,
      values: { ...baseValues, legal_first_name: '', date_of_birth: '' } as any
    });

    const firstName = screen.getByLabelText(/legal first name/i);
    const dob = screen.getByLabelText(/date of birth/i);

    const firstNameErr = screen.getByText('First name is required');
    const dobErr = screen.getByText('Date of birth is required');

    expect(firstNameErr).toBeInTheDocument();
    expect(dobErr).toBeInTheDocument();

    expect(firstName).toHaveAttribute('aria-invalid', 'true');
    expect(dob).toHaveAttribute('aria-invalid', 'true');

    const firstNameDescribedBy = firstName.getAttribute('aria-describedby') || '';
    const dobDescribedBy = dob.getAttribute('aria-describedby') || '';

    // The described-by should reference the rendered error element ids.
    expect(firstNameDescribedBy.length).toBeGreaterThan(0);
    expect(dobDescribedBy.length).toBeGreaterThan(0);

    // Verify that the DOM element referenced by the id contains the error text.
    // (Supports components that set describedby to a single id.)
    const firstId = firstNameDescribedBy.split(/\s+/)[0];
    const dobId = dobDescribedBy.split(/\s+/)[0];

    const firstDescEl = document.getElementById(firstId);
    const dobDescEl = document.getElementById(dobId);

    expect(firstDescEl).not.toBeNull();
    expect(dobDescEl).not.toBeNull();

    expect(firstDescEl).toHaveTextContent('First name is required');
    expect(dobDescEl).toHaveTextContent('Date of birth is required');
  });

  it('when show_validation is false, does not show inline errors or aria-invalid even if errors are provided', () => {
    renderStep({
      show_validation: false,
      errors: { legal_last_name: 'Last name is required' } as any,
      values: { ...baseValues, legal_last_name: '' } as any
    });

    const lastName = screen.getByLabelText(/legal last name/i);
    expect(screen.queryByText('Last name is required')).not.toBeInTheDocument();
    expect(lastName).not.toHaveAttribute('aria-invalid', 'true');
  });

  it('disables all inputs when is_disabled is true', () => {
    renderStep({ is_disabled: true });

    expect(screen.getByLabelText(/legal first name/i)).toBeDisabled();
    expect(screen.getByLabelText(/legal last name/i)).toBeDisabled();
    expect(screen.getByLabelText(/date of birth/i)).toBeDisabled();
  });
});
"}]}

