    renderStep();

    const firstName = screen.getByLabelText(/legal first name/i) as HTMLInputElement;
    const lastName = screen.getByLabelText(/legal last name/i) as HTMLInputElement;
    const dob = screen.getByLabelText(/date of birth/i) as HTMLInputElement;

