    expect(lastName).toBeInTheDocument();
    expect(dob).toBeInTheDocument();

    expect(firstName.value).toBe(baseValues.legal_first_name);
    expect(lastName.value).toBe(baseValues.legal_last_name);
    expect(dob.value).toBe(baseValues.date_of_birth);
  });

  it('calls on_change with a payload when a field changes', async () => {
    const user = userEvent.setup();
    const { props } = renderStep({
      values: { ...baseValues, legal_first_name: '' } as any
    });

    const firstName = screen.getByLabelText(/legal first name/i) as HTMLInputElement;
    await user.type(firstName, 'A');

    expect(props.on_change).toHaveBeenCalled();

    // Expect shape: { field_name, value }
    const lastCall = (props.on_change as jest.Mock).mock.calls[(props.on_change as jest.Mock).mock.calls.length - 1][0];
    expect(lastCall).toEqual(
      expect.objectContaining({
        field_name: expect.any(String),
        value: expect.any(String)
      })
    );

    // And expect it targets the correct field.
    expect(lastCall.field_name).toBe('legal_first_name');
  });

  it('calls on_blur with the field name when provided', async () => {
    const user = userEvent.setup();
    const on_blur = jest.fn();
    renderStep({ on_blur });

    const lastName = screen.getByLabelText(/legal last name/i);
    await user.click(lastName);
    await user.tab();

    expect(on_blur).toHaveBeenCalledWith('legal_last_name');
  });

  it('does not crash if on_blur is not provided', async () => {
