import { SelfieStep } from './SelfieStep';

type SelfieMode = 'camera' | 'upload';

function createFile(name: string, type: string, sizeBytes = 1024) {
  const blob = new Blob([new Uint8Array(sizeBytes).fill(1)], { type });
  return new File([blob], name, { type });
}

function renderSelfieStep(overrides: Partial<React.ComponentProps<typeof SelfieStep>> = {}) {
  const props: React.ComponentProps<typeof SelfieStep> = {
    mode: 'upload' as SelfieMode,
    selfie_file: null,
    selfie_preview_url: null,
    camera_unavailable_message: null,
    is_valid: false,
    show_validation_errors: false,
    validation_error_message: null,
    accepted_file_types: ['.jpg', '.jpeg', '.png'],
    max_file_size_bytes: 10 * 1024 * 1024,
    is_disabled: false,
    on_mode_change: jest.fn(),
    on_upload_file: jest.fn(),
    on_remove_selfie: jest.fn(),
    on_capture_selfie: jest.fn(),
    on_retake_selfie: jest.fn(),
    on_camera_unavailable: jest.fn(),
    ...overrides
  };

  return {
    user: userEvent.setup(),
    props,
    ...render(<SelfieStep {...props} />)
  };
}

describe('SelfieStep', () => {
  test('renders mode selection and calls on_mode_change when switching modes', async () => {
    const { user, props } = renderSelfieStep({ mode: 'upload' as SelfieMode });

    // Prefer accessible radios if present; otherwise fall back to buttons by name.
    const cameraOption =
      screen.queryByRole('radio', { name: /use camera/i }) ??
      screen.queryByRole('button', { name: /use camera/i });
    const uploadOption =
      screen.queryByRole('radio', { name: /upload a photo/i }) ??
      screen.queryByRole('button', { name: /upload a photo/i });

    expect(cameraOption).toBeTruthy();
    expect(uploadOption).toBeTruthy();

    if (cameraOption) {
      await user.click(cameraOption);
      expect(props.on_mode_change).toHaveBeenCalledWith('camera');
    }
  });

  test('upload mode: file input uses accept derived from accepted_file_types and selecting a file calls on_upload_file', async () => {
    const { user, props } = renderSelfieStep({
      mode: 'upload' as SelfieMode,
      accepted_file_types: ['.jpg', '.jpeg', '.png']
    });

    const fileInput = screen.getByLabelText(/upload a photo/i, { selector: 'input[type="file"]' });
    expect(fileInput).toHaveAttribute('accept', expect.stringContaining('.jpg'));
    expect(fileInput).toHaveAttribute('accept', expect.stringContaining('.jpeg'));
    expect(fileInput).toHaveAttribute('accept', expect.stringContaining('.png'));

    const file = createFile('selfie.jpg', 'image/jpeg');
    await user.upload(fileInput, file);

    expect(props.on_upload_file).toHaveBeenCalledTimes(1);
    expect(props.on_upload_file).toHaveBeenCalledWith(file);
  });

  test('when selfie_preview_url is provided, renders preview image and Remove calls on_remove_selfie', async () => {
    const { user, props } = renderSelfieStep({
      mode: 'upload' as SelfieMode,
      selfie_file: createFile('selfie.png', 'image/png'),
      selfie_preview_url: 'data:image/png;base64,AAAA'
    });

    const img = screen.getByRole('img', { name: /selfie preview/i });
    expect(img).toHaveAttribute('src', 'data:image/png;base64,AAAA');

    const removeBtn = screen.getByRole('button', { name: /remove/i });
    await user.click(removeBtn);
    expect(props.on_remove_selfie).toHaveBeenCalledTimes(1);
  });

  test('when show_validation_errors is true, renders validation_error_message and associates it to upload control via aria-describedby', async () => {
    renderSelfieStep({
      mode: 'upload' as SelfieMode,
      show_validation_errors: true,
      validation_error_message: 'Please provide a selfie.'
    });

    const alert = screen.getByText(/please provide a selfie\./i);
    expect(alert).toBeInTheDocument();

    const fileInput = screen.getByLabelText(/upload a photo/i, { selector: 'input[type="file"]' });
    const describedBy = fileInput.getAttribute('aria-describedby');
    expect(describedBy).toBeTruthy();

    if (describedBy) {
      const ids = describedBy.split(/\s+/).filter(Boolean);
      const describedEls = ids
        .map((id) => document.getElementById(id))
        .filter(Boolean) as HTMLElement[];

      expect(describedEls.length).toBeGreaterThan(0);
      expect(describedEls.some((el) => /please provide a selfie\./i.test(el.textContent ?? ''))).toBe(true);
    }
  });

  test('camera mode: renders Capture/Retake and triggers callbacks', async () => {
    const { user, props } = renderSelfieStep({
      mode: 'camera' as SelfieMode,
      selfie_preview_url: null
    });

    const captureBtn = screen.getByRole('button', { name: /capture/i });
    await user.click(captureBtn);

    expect(props.on_capture_selfie).toHaveBeenCalledTimes(1);
    expect(typeof props.on_capture_selfie.mock.calls[0][0]).toBe('string');

    const retakeBtn = screen.getByRole('button', { name: /retake/i });
    await user.click(retakeBtn);
    expect(props.on_retake_selfie).toHaveBeenCalledTimes(1);
  });

  test('disabled state: prevents interactions and disables controls', async () => {
    const { user, props } = renderSelfieStep({
      is_disabled: true,
      mode: 'upload' as SelfieMode,
      show_validation_errors: true,
      validation_error_message: 'Please provide a selfie.'
    });

    const fileInput = screen.getByLabelText(/upload a photo/i, { selector: 'input[type="file"]' });
    expect(fileInput).toBeDisabled();

    const file = createFile('selfie.jpg', 'image/jpeg');
    await user.upload(fileInput, file);
    expect(props.on_upload_file).not.toHaveBeenCalled();

    const cameraOption =
      screen.queryByRole('radio', { name: /use camera/i }) ??
      screen.queryByRole('button', { name: /use camera/i });

    if (cameraOption) {
      expect(cameraOption).toBeDisabled();
      await user.click(cameraOption);
      expect(props.on_mode_change).not.toHaveBeenCalled();
    }
  });
});
"}]}

