      screen.queryByText(/verification status:\s*rejected/i);
    expect(sr).toBeTruthy();
  });

  it('renders Rejected status with fallback reason when rejection_reason is missing', () => {
    renderComponent({ status: 'rejected' });

    expect(screen.getByText(/rejected/i)).toBeInTheDocument();
    // Fallback per decisions
