steps.outputJson:
{"coveredBehaviors":["Wizard renders Step 1 by default with Back disabled and step indicator aria-current="step"","Step changes via Next/Back propagate across child components: step indicator updates, aria-live announces, focus moves to step <h2>","Per-step validation gates Next and prevents invalid navigation with accessible inline errors and focus-to-first-invalid behavior","Document upload step integrates file picker and drag-and-drop; while uploading, Next is disabled and label shows "Uploading…"; successful upload enables progression","Document upload validation rejects unsupported type and oversize files, shows role="alert" error summary, and blocks progression until recovery","Selfie step integrates mode switching; camera unavailable triggers fallback message and upload mode; uploading selfie enables final submit","Final submission disables navigation and shows "Submitting…"; on success shows Verification status Pending review with SR label","On submission failure, global error banner role="alert" provides Retry that calls on_retry_submit and recovers to success"],"coveredComponentCodes":["kyc_verification_wizard","kyc_step_indicator","personal_info_step","document_upload_step","selfie_step","wizard_back_button","wizard_next_button","verification_status"],"coveredFlowCodes":["kyc_shortest_happy_submit_pending","kyc_exploratory_happy_review_and_retry_then_submit","kyc_unhappy_invalid_document_type_and_size_then_recover"],"coveredStates":["Step 1: Personal info (initial/default)","Step 2: Document upload","Step 3: Selfie","Document upload: uploading (Next disabled, "Uploading…")","Document upload: validation error (role="alert")","Selfie: camera unavailable fallback to upload","Submitting (Next shows "Submitting…", navigation disabled)","Global submit error banner with Retry","Verification status: pending_review"],"files":[{"filename":"/app/generated/frontend/src/components/KycVerificationWizard/KycVerificationWizard.e2e.spec.tsx","content":"import React from 'react';
import { render, screen, within, act, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import KycVerificationWizard from './KycVerificationWizard';

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

function createFile(name: string, mime: string, sizeBytes: number) {
  const blob = new Blob([new Uint8Array(Math.max(sizeBytes, 1)).fill(1)], { type: mime });
  return new File([blob], name, { type: mime });
}

async function fillPersonalInfo(user: ReturnType<typeof userEvent.setup>) {
  await user.clear(screen.getByLabelText(/legal first name/i));
  await user.type(screen.getByLabelText(/legal first name/i), 'Ada');
  await user.clear(screen.getByLabelText(/legal last name/i));
  await user.type(screen.getByLabelText(/legal last name/i), 'Lovelace');
  await user.clear(screen.getByLabelText(/date of birth/i));
  await user.type(screen.getByLabelText(/date of birth/i), '1815-12-10');
}

describe('KycVerificationWizard (composed e2e)', () => {
  test('kyc_shortest_happy_submit_pending: completes 3 steps and shows Pending review status on success', async () => {
    const user = userEvent.setup();
    const submit = deferred<any>();
    const onSubmit = jest.fn(() => submit.promise);

    render(<KycVerificationWizard on_submit_kyc={onSubmit} />);

    // Step 1 default: Back disabled; indicator current; aria-live region ready.
    expect(screen.getByRole('heading', { level: 2, name: /personal info/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();

    const stepsNav = screen.getByRole('navigation', { name: /kyc steps/i });
    const stepItems = within(stepsNav).getAllByRole('listitem');
    expect(stepItems[0]).toHaveAttribute('aria-current', 'step');

    const live = screen.getByRole('status');
    expect(live).toHaveAttribute('aria-live', 'polite');

    // Step 1 valid
    await fillPersonalInfo(user);
    const next1 = screen.getByRole('button', { name: /^next$/i });
    expect(next1).toBeEnabled();

    // Next -> Step 2; focus management + announcement
    await user.click(next1);
    const docHeading = await screen.findByRole('heading', { level: 2, name: /document upload/i });
    expect(docHeading).toHaveFocus();
    expect(screen.getByRole('status')).toHaveTextContent(/step 2 of 3: document upload/i);

    // Add a valid document via file picker input
    // The DocumentUploadStep decision includes a hidden <input type=file> (multiple) triggered by a button.
    const docFileInput = document.querySelector('input[type="file"][multiple]') as HTMLInputElement | null;
    expect(docFileInput).not.toBeNull();

    const validPdf = createFile('passport.pdf', 'application/pdf', 1024);
    await user.upload(docFileInput!, validPdf);

    // While uploading, Next should be disabled and show "Uploading…".
    // Allow either exact label on the button or presence of text on the button.
    const uploadingNext = await screen.findByRole('button', { name: /uploading/i });
    expect(uploadingNext).toBeDisabled();

    // Wait for upload completion by observing Next returns to normal and enabled.
    const next2 = await screen.findByRole('button', { name: /^next$/i });
    expect(next2).toBeEnabled();

    // Next -> Step 3
    await user.click(next2);
    const selfieHeading = await screen.findByRole('heading', { level: 2, name: /selfie/i });
    expect(selfieHeading).toHaveFocus();
    expect(screen.getByRole('status')).toHaveTextContent(/step 3 of 3: selfie/i);

    // Upload selfie
    const selfieInput = document.querySelector('input[type="file"]:not([multiple])') as HTMLInputElement | null;
    expect(selfieInput).not.toBeNull();
    const selfieFile = createFile('selfie.png', 'image/png', 2048);
    await user.upload(selfieInput!, selfieFile);

    const next3 = screen.getByRole('button', { name: /^next$/i });
    expect(next3).toBeEnabled();

    // Submit -> Submitting… and nav disabled
    await user.click(next3);
    expect(onSubmit).toHaveBeenCalledTimes(1);
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /submitting/i })).toBeDisabled();

    await act(async () => {
      submit.resolve({ status: 'pending_review' });
      await submit.promise;
    });

    // Status view
    expect(await screen.findByRole('heading', { name: /verification status/i })).toBeInTheDocument();
    // SR label per decision can be aria-label or visible text; prefer label query.
    expect(
      screen.queryByLabelText(/verification status:\s*pending review/i) ??
        screen.getByText(/verification status:\s*pending review/i)
    ).toBeTruthy();
    expect(screen.getByText(/pending review/i)).toBeInTheDocument();
  });

  test('kyc_exploratory_happy_review_and_retry_then_submit: invalid Step 1 blocks, doc upload drag-drop + remove + retry, camera unavailable fallback, back/next preserves state, submit fails then retry succeeds', async () => {
    const user = userEvent.setup();

    const firstSubmit = deferred<any>();
    const retrySubmit = deferred<any>();
    const onSubmit = jest.fn(() => firstSubmit.promise);
    const onRetry = jest.fn(() => retrySubmit.promise);

    // Simulate small screen for responsive rules (where used)
    // (JSDOM may not trigger CSS, but we keep the intent and ensure no crashes.)
    Object.defineProperty(window, 'innerWidth', { value: 375, writable: true });
    fireEvent(window, new Event('resize'));

    render(<KycVerificationWizard on_submit_kyc={onSubmit} on_retry_submit={onRetry} />);

    // Attempt Next with invalid personal info: should not navigate; should show inline errors and focus first invalid.
    const next = screen.getByRole('button', { name: /^next$/i });
    expect(next).toBeDisabled();

    // Force a "Next attempt" via keyboard on the Next button is not possible when disabled;
    // Instead, trigger blur validation then ensure gating still prevents progression.
    // (Wizard decision: validate on blur and on Next click; disabled gating is the primary block.)
    screen.getByLabelText(/legal first name/i).focus();
    await user.tab();

    // After blur, errors should be discoverable; first invalid field is still first name.
    const firstName = screen.getByLabelText(/legal first name/i);
    expect(firstName).toHaveAttribute('aria-invalid', 'true');
    expect(firstName.getAttribute('aria-describedby') || '').not.toEqual('');

    // Fix personal info then Next.
    await fillPersonalInfo(user);
    const nextEnabled = screen.getByRole('button', { name: /^next$/i });
    expect(nextEnabled).toBeEnabled();
    await user.click(nextEnabled);

    const docHeading = await screen.findByRole('heading', { level: 2, name: /document upload/i });
    expect(docHeading).toHaveFocus();

    // Drag-and-drop two valid files onto drop zone button.
    const dropZone = screen.getByRole('button', { name: /upload documents/i });

    const f1 = createFile('id.pdf', 'application/pdf', 2000);
