export interface KycStepIndicatorProps {
  /** Ordered list of wizard step labels to render in the indicator (display-only, non-interactive). */
  steps: string[];
  /** Zero-based index of the currently active step; the corresponding item is marked with aria-current="step". */
  current_step_index: number;
  /** Total number of steps, used for helper text such as "Step X of 3" (should match steps.length). */
  total_steps: number;
  /** Accessible label for the <nav> wrapping the step list (e.g., "KYC steps"). */
  aria_label?: string;
}

export function KycStepIndicator({
  steps,
  current_step_index,
  total_steps,
  aria_label,
}: KycStepIndicatorProps) {
  const safeTotal = Number.isFinite(total_steps) && total_steps > 0 ? total_steps : steps.length;
  const safeCurrentIndex =
    Number.isFinite(current_step_index) && current_step_index >= 0
      ? Math.min(current_step_index, Math.max(0, steps.length - 1))
      : 0;

  const currentStepNumber = safeCurrentIndex + 1;

  return (
    <nav aria-label={aria_label ?? 'KYC steps'} style={styles.nav}>
      <div style={styles.helperText}>{`Step ${currentStepNumber} of ${safeTotal}`}</div>
      <ol style={styles.list}>
        {steps.map((label, idx) => {
          const isCurrent = idx === safeCurrentIndex;
          return (
            <li key={`${label}-${idx}`} style={styles.listItem} aria-current={isCurrent ? 'step' : undefined}>
              <span style={isCurrent ? styles.stepLabelCurrent : styles.stepLabel}>{label}</span>
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

