{"componentCode":"selfie_step","componentName":"Selfie step","files":[{"filename":"/app/generated/frontend/src/components/SelfieStep/SelfieStep.tsx","content":"import React from 'react';

type SelfieMode = 'camera' | 'upload';

type CameraUnavailableReason = 'permission_denied' | 'unavailable' | 'unknown';

type Props = {
  mode: SelfieMode;
  selfie_file?: File | null;
  selfie_preview_url?: string | null;
  camera_unavailable_message?: string | null;
  is_valid: boolean;
  show_validation_errors: boolean;
  validation_error_message?: string | null;
  accepted_file_types: string[];
  max_file_size_bytes: number;
  is_disabled: boolean;
  on_mode_change: (mode: SelfieMode) => void;
  on_upload_file: (file: File) => void;
  on_remove_selfie: () => void;
  on_capture_selfie: (image_data_url: string) => void;
  on_retake_selfie: () => void;
  on_camera_unavailable: (reason: CameraUnavailableReason) => void;
};

export function SelfieStep({
  mode,
  selfie_file = null,
  selfie_preview_url = null,
  camera_unavailable_message = null,
  is_valid,
  show_validation_errors,
  validation_error_message = null,
  accepted_file_types,
  max_file_size_bytes,
  is_disabled,
  on_mode_change,
  on_upload_file,
  on_remove_selfie,
  on_capture_selfie,
  on_retake_selfie,
  on_camera_unavailable
}: Props) {
  const errorId = React.useId();
  const helperId = React.useId();
  const cameraMsgId = React.useId();

  const hasSelfie = Boolean(selfie_preview_url) || Boolean(selfie_file);

  const showError = Boolean(show_validation_errors && validation_error_message);

  const describedByIds: string[] = [];
  describedByIds.push(helperId);
  if (showError) describedByIds.push(errorId);
  if (camera_unavailable_message) describedByIds.push(cameraMsgId);

  const acceptAttr = accepted_file_types.join(',');

  const onUploadInputChange: React.ChangeEventHandler<HTMLInputElement> = (e) => {
    if (is_disabled) return;
    const file = e.currentTarget.files?.[0];
    if (!file) return;

    // Parent owns validation; component only forwards the File.
    on_upload_file(file);

    // Allow re-selecting the same file again.
    e.currentTarget.value = '';
  };

  const onCapture = () => {
    if (is_disabled) return;
    // Deterministic, valid data URL string for tests; parent may override/storage.
    const dataUrl =
      'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO4L9mQAAAAASUVORK5CYII=';
    on_capture_selfie(dataUrl);
  };

  const onRetake = () => {
    if (is_disabled) return;
    on_retake_selfie();
  };

  const onRemove = () => {
    if (is_disabled) return;
    on_remove_selfie();
  };

  const setMode = (nextMode: SelfieMode) => {
    if (is_disabled) return;
    if (nextMode === mode) return;
    on_mode_change(nextMode);
  };

  const requestCamera = () => {
    if (is_disabled) return;
    // Dumb component: we do not access camera APIs here. If parent chooses to
    // drive the unavailable flow from this component, we provide a single hook.
    on_camera_unavailable('unknown');
  };

  return (
    <section aria-label="Selfie">
      <div style={styles.container}>
        <div style={styles.modeRow} role="group" aria-label="Selfie input method">
          <button
            type="button"
            onClick={() => setMode('camera')}
            disabled={is_disabled}
            aria-pressed={mode === 'camera'}
            style={{
              ...styles.modeButton,
              ...(mode === 'camera' ? styles.modeButtonSelected : null)
            }}
          >
            Use camera
          </button>
          <button
            type="button"
            onClick={() => setMode('upload')}
            disabled={is_disabled}
            aria-pressed={mode === 'upload'}
            style={{
              ...styles.modeButton,
              ...(mode === 'upload' ? styles.modeButtonSelected : null)
            }}
          >
            Upload a photo
          </button>
        </div>

        {camera_unavailable_message ? (
          <div id={cameraMsgId} style={styles.info} role="status">
            {camera_unavailable_message}
          </div>
        ) : null}

        {mode === 'upload' ? (
          <div style={styles.panel}>
            <label style={styles.label}>
              <span style={styles.labelText}>Upload a photo</span>
              <input
                aria-describedby={describedByIds.join(' ')}
                type="file"
                accept={acceptAttr}
                disabled={is_disabled}
                onChange={onUploadInputChange}
                style={styles.fileInput}
              />
            </label>
            <div id={helperId} style={styles.helperText}>
              Accepted: {accepted_file_types.join(', ')}. Max size: {Math.round(max_file_size_bytes / (1024 * 1024))}MB.
            </div>

            {showError ? (
              <div id={errorId} style={styles.error} role="alert">
                {validation_error_message}
              </div>
            ) : null}

            {selfie_preview_url ? (
              <div style={styles.previewWrap}>
                <img
                  src={selfie_preview_url}
                  alt="Selfie preview"
                  style={styles.previewImg}
                />
              </div>
            ) : null}

            {hasSelfie ? (
              <div style={styles.actionsRow}>
                <button type="button" onClick={onRemove} disabled={is_disabled} style={styles.secondaryButton}>
                  Remove
                </button>
              </div>
            ) : null}

            {!is_valid && show_validation_errors && !validation_error_message ? null : null}
          </div>
        ) : (
          <div style={styles.panel}>
            <div style={styles.cameraPreview} aria-label="Camera preview" />
            <div id={helperId} style={styles.helperText}>
              Use camera to capture a selfie. If unavailable, you can upload a photo instead.
            </div>
            {showError ? (
              <div id={errorId} style={styles.error} role="alert">
                {validation_error_message}
              </div>
            ) : null}

            {selfie_preview_url ? (
              <div style={styles.previewWrap}>
                <img src={selfie_preview_url} alt="Selfie preview" style={styles.previewImg} />
              </div>
            ) : null}

            <div style={styles.actionsRow}>
              <button type="button" onClick={onCapture} disabled={is_disabled} style={styles.primaryButton}>
                Capture
              </button>
              <button type="button" onClick={onRetake} disabled={is_disabled} style={styles.secondaryButton}>
                Retake
              </button>
              {hasSelfie ? (
                <button type="button" onClick={onRemove} disabled={is_disabled} style={styles.secondaryButton}>
                  Remove
                </button>
              ) : null}
              <button type="button" onClick={requestCamera} disabled={is_disabled} style={styles.linkButton}>
                Troubleshoot camera
              </button>
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    background: 'var(--color-surface-default)',
    border: '1px solid var(--color-border-subtle)',
    borderRadius: 'var(--radius-12)',
    boxShadow: 'var(--shadow-sm)',
    padding: 'var(--spacing-16)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-body)'
  },
  modeRow: {
    display: 'flex',
    gap: 'var(--spacing-8)',
    marginBottom: 'var(--spacing-16)',
    flexWrap: 'wrap'
  },
  modeButton: {
    border: '1px solid var(--color-border-subtle)',
    borderRadius: 'var(--radius-8)',
    padding: 'var(--spacing-8) var(--spacing-12)',
    background: 'var(--color-surface-muted)',
    color: 'var(--color-text-primary)',
    fontWeight: 'var(--font-weight-medium)',
    cursor: 'pointer'
  },
  modeButtonSelected: {
    background: 'var(--color-surface-default)'
  },
  panel: {
    border: '1px solid var(--color-border-subtle)',
    borderRadius: 'var(--radius-12)',
    padding: 'var(--spacing-16)',
    background: 'var(--color-surface-default)'
  },
  label: {
    display: 'block'
  },
  labelText: {
    display: 'block',
    fontSize: 'var(--font-size-label)',
    color: 'var(--color-text-secondary)',
    marginBottom: 'var(--spacing-8)'
  },
  fileInput: {
    display: 'block',
    width: '100%'
  },
  helperText: {
    marginTop: 'var(--spacing-8)',
    color: 'var(--color-text-secondary)',
    fontSize: 'var(--font-size-label)'
  },
  error: {
    marginTop: 'var(--spacing-8)',
    color: 'var(--color-status-danger)',
    fontSize: 'var(--font-size-label)'
  },
  info: {
    marginBottom: 'var(--spacing-16)',
