          </button>
          <button
            type="button"
            onClick={() => setMode('upload')}
            disabled={is_disabled}
            aria-pressed={mode === 'upload'}
            style={{
              ...styles.modeButton,
              ...(mode === 'upload' ? styles.modeButtonSelected : null)
            }}
          >
            Upload a photo
          </button>
        </div>

        {camera_unavailable_message ? (
          <div id={cameraMsgId} style={styles.info} role="status">
            {camera_unavailable_message}
          </div>
        ) : null}

        {mode === 'upload' ? (
