                  alt="Selfie preview"
                  style={styles.previewImg}
                />
              </div>
            ) : null}

            {hasSelfie ? (
              <div style={styles.actionsRow}>
                <button type="button" onClick={onRemove} disabled={is_disabled} style={styles.secondaryButton}>
                  Remove
                </button>
              </div>
            ) : null}

            {!is_valid && show_validation_errors && !validation_error_message ? null : null}
          </div>
        ) : (
          <div style={styles.panel}>
            <div style={styles.cameraPreview} aria-label="Camera preview" />
            <div id={helperId} style={styles.helperText}>
              Use camera to capture a selfie. If unavailable, you can upload a photo instead.
            </div>
            {showError ? (
              <div id={errorId} style={styles.error} role="alert">
                {validation_error_message}
              </div>
            ) : null}

            {selfie_preview_url ? (
              <div style={styles.previewWrap}>
                <img src={selfie_preview_url} alt="Selfie preview" style={styles.previewImg} />
              </div>
            ) : null}

            <div style={styles.actionsRow}>
              <button type="button" onClick={onCapture} disabled={is_disabled} style={styles.primaryButton}>
                Capture
              </button>
              <button type="button" onClick={onRetake} disabled={is_disabled} style={styles.secondaryButton}>
                Retake
              </button>
              {hasSelfie ? (
                <button type="button" onClick={onRemove} disabled={is_disabled} style={styles.secondaryButton}>
                  Remove
                </button>
              ) : null}
              <button type="button" onClick={requestCamera} disabled={is_disabled} style={styles.linkButton}>
                Troubleshoot camera
              </button>
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

