mponentInterfaces":[{"accepts":[{"description":"Ordered list of wizard step labels to render in the indicator (display-only, non-interactive).","name":"steps","required":true,"type":"string[]"},{"description":"Zero-based index of the currently active step; the corresponding item is marked with aria-current="step".","name":"current_step_index","required":true,"type":"number"},{"description":"Total number of steps, used for helper text such as "Step X of 3" (should match steps.length).","name":"total_steps","required":true,"type":"number"},{"description":"Accessible label for the <nav> wrapping the step list (e.g., "KYC steps").","name":"aria_label","required":false,"type":"string"}],"componentCode":"kyc_step_indicator","componentName":"Step indicator","returns":[]},{"accepts":[{"description":"Current values for the personal info fields (controlled inputs).","name":"values","required":true,"type":"PersonalInfoValues"},{"description":"Per-field validation errors to render inline and to associate via aria-describedby.","name":"errors","required":true,"type":"PersonalInfoErrors"},{"description":"Whether to show validation feedback (e.g., after blur/submit attempt).","name":"show_validation","required":true,"type":"boolean"},{"description":"Disables all inputs when true (e.g., during navigation/submission).","name":"is_disabled","required":false,"type":"boolean"},{"description":"Callback fired when any field value changes.","name":"on_change","required":true,"type":"(payload: PersonalInfoChangePayload) => void"},{"description":"Callback fired when a field is blurred; may be used to trigger validation-on-blur in the parent.","name":"on_blur","required":false,"type":"(field_name: PersonalInfoFieldName) => void"}],"componentCode":"personal_info_step","componentName":"Personal info step","returns":[{"description":"Emitted when the user edits a personal info field.","name":"change","required":true,"type":"PersonalInfoChangePayload"},{"description":"Emitted when a personal info field loses focus (optional validation hook).","name":"blur","required":false,"type":"PersonalInfoFieldName"}]},{"accepts":[{"description":"Current selfie input mode selected by the user (camera or file upload). Used to render the appropriate UI branch and preserve selection when navigating back/next.","name":"mode","required":true,"type":"SelfieMode"},{"description":"Selected selfie image file when provided via upload (or derived from a captured selfie if the parent converts capture output into a File). Null when no selfie is selected.","name":"selfie_file","required":false,"type":"File | null"},{"description":"Preview URL/data URL for the currently selected or captured selfie image. Null when no selfie is available.","name":"selfie_preview_url","required":false,"type":"string | null"},{"description":"Inline message shown when camera is unavailable or permission is denied (e.g., "Camera unavailable. Upload a selfie instead."). Null when not applicable.","name":"camera_unavailable_message","required":false,"type":"string | null"},{"description":"Whether the step is currently valid (exactly one selfie is provided via capture or upload). Used by the parent to gate Next; the step can also use this to decide whether to show an error state after submit/next attempt.","name":"is_valid","required":true,"type":"boolean"},{"description":"Whether to display validation errors for this step (typically set after a Next attempt on an invalid step).","name":"show_validation_errors","required":true,"type":"boolean"},{"description":"Validation error message for missing/invalid selfie, rendered inline and associated to controls via aria-describedby when show_validation_errors is true.","name":"validation_error_message","required":false,"type":"string | null"},{"description":"Accepted file extensions/MIME types for selfie upload (per decisions: .jpg/.jpeg/.png).","name":"accepted_file_types","required":true,"type":"string[]"},{"description":"Maximum allowed file size in bytes for selfie upload (per decisions: 10MB).","name":"max_file_size_bytes","required":true,"type":"number"},{"description":"Disables all interactive controls in the step (used when wizard is submitting or navigation should be locked).","name":"is_disabled","required":true,"type":"boolean"},{"description":"Callback when user selects the input mode (camera vs upload).","name":"on_mode_change","required":true,"type":"(mode: SelfieMode) => void"},{"description":"Callback when user picks an upload file. Parent performs validation and sets selfie_file/selfie_preview_url and validity state.","name":"on_upload_file","required":true,"type":"(file: File) => void"},{"description":"Callback when user requests removing the current selfie (clears file/preview and validity).","name":"on_remove_selfie","required":true,"type":"() => void"},{"description":"Callback when user presses Capture in camera mode, providing an image data URL for preview/storage. Parent may convert to File and store it.","name":"on_capture_selfie","required":true,"type":"(image_data_url: string) => void"},{"description":"Callback when user presses Retake in camera mode (clears current capture/preview and returns to live preview).","name":"on_retake_selfie","required":true,"type":"() => void"},{"description":"Callback invoked when the component detects camera is unavailable or permission is denied, so the parent can set camera_unavailable_message and switch mode to upload if desired.","name":"on_camera_unavailable","required":true,"type":"(reason: CameraUnavailableReason) => void"}],"componentCode":"selfie_step","componentName":"Selfie step","returns":[]},{"accepts":[{"description":"Visible label text for the back navigation control.","name":"label","required":true,"type":"string"},{"description":"Whether the back button is disabled (e.g., Step 1, or during submission). When true, the underlying control uses the native disabled attribute.","name":"disabled","required":true,"type":"boolean"},{"description":"Click handler invoked to request navigation to the previous step.","name":"on_back","required":true,"type":"() => void"}],"componentCode":"wizard_back_button","componentName":"Back button","returns":[{"description":"Emitted when the user activates the back button (mouse, touch, keyboard). Not emitted when disabled.","name":"back_requested","required":true,"type":"() => void"}]},{"accepts":[{"description":"Visible label text for the button (e.g., "Next", "Uploading…", "Submitting…").","name":"label","required":true,"type":"string"},{"description":"Whether the button is disabled (e.g., current step invalid, uploads/submission in progress, or navigation locked).","name":"disabled","required":true,"type":"boolean"},{"description":"Whether the button should present a loading state (used alongside a loading label such as "Uploading…" or "Submitting…").","name":"loading","required":false,"type":"boolean"},{"description":"Callback fired when the user activates the button (click/keyboard). Parent is responsible for validation gating and navigation behavior.","name":"on_press","required":true,"type":"() => void"}],"componentCode":"wizard_next_button","componentName":"Next button","returns":[{"description":"Emitted when the user activates the Next button (click, Enter, or Space).","name":"press","required":true,"type":"void"}]},{"accepts":[{"description":"Current verification status to display.","name":"status","required":true,"type":"KycVerificationStatus"},{"description":"Optional rejection reason text to display when status is rejected; if omitted, component should render a fallback reason message.","name":"rejection_reason","required":false,"type":"string | null"},{"description":"Whether to show the "Start over" action when status is rejected.","name":"show_start_over","required":false,"type":"boolean"},{"description":"Callback invoked when the user activates the "Start over" action (typically resets wizard to Step 1 and clears local step data).","name":"on_start_over","required":false,"type":"() => void"},{"description":"Accessible label text for screen readers announcing the status (e.g., "Verification status: Pending review"). If not provided, the component should derive it from status.","name":"sr_status_label","required":false,"type":"string"}],"componentCode":"verification_status","componentName":"Verification status","returns":[{"description":"Emitted when the user chooses to start the KYC process over from the rejected status view.","name":"start_over","required":true,"type":"void"}]}],"relatedComponentSourceFiles":[{"componentCode":"kyc_step_indicator","filename":"/app/generated/frontend/src/components/KycStepIndicator/KycStepIndicator.tsx"},{"componentCode":"personal_info_step","filename":"/app/generated/frontend/src/components/PersonalInfoStep/PersonalInfoStep.tsx"},{"componentCode":"selfie_step","filename":"/app/generated/frontend/src/components/SelfieStep/SelfieStep.tsx"},{"componentCode":"wizard_back_button","filename":"/app/generated/frontend/src/components/WizardBackButton/WizardBackButton.tsx"},{"componentCode":"wizard_next_button","filename":"/app/generated/frontend/src/components/WizardNextButton/WizardNextButton.tsx"},{"componentCode":"verification_status","filename":"/app/generated/frontend/src/components/VerificationStatus/VerificationStatus.tsx"}],"resolvingGaps":{"decisions":[{"affectedComponentCodes":["kyc_step_indicator","kyc_verification_wizard"],"code":"step_indicator_a11y_semantics","decision":"Implement the step indicator as an ordered list (<ol>) inside a <nav aria-label="KYC steps">. Each step label is rendered as plain text (non-interactive). The current step item sets aria-current="step" and includes visually rendered helper text "Step X of 3". Additionally, the wizard renders a dedicated aria-live="polite" region that announces on step changes: "Step X of 3: {stepName}".","rationale":"This defines explicit semantics and announcements without adding step-click navigation that is not specified. It conservatively improves screen reader understanding of progress and current position using standard patterns (nav, list, aria-current, aria-live).","sourceGap":"Step indicator semantics and announcements are undefined (e.g., current step conveyed to screen readers, progress text, aria-current)"},{"affectedComponentCodes":["kyc_verification_wizard","wizard_back_button","wizard_next_button","personal_info_step","document_upload_step","selfie_step"],"code":"wizard_keyboard_and_focus_management","decision":"Use standard Tab navigation with no focus trapping. Back/Next are native <button type="button"> elements and activate via Enter/Space by default. On Next/Back step change, programmatically move focus to the new step's <h2> heading (tabIndex="-1"). On validation failure, prevent navigation and move focus to the first invalid field; also set aria-invalid="true" on invalid controls and associate each error message via aria-describedby.","rationale":"This fully specifies keyboard model and focus behavior with conventional, testable rules, avoiding custom keybindings or traps that could reduce accessibility. It also ensures errors are discoverable and focus is placed predictably.","sourceGap":"Keyboard navigation model is unspecified (tab order across step content and Back/Next, Enter/Space activation, step changes not trapping focus)"},{"affectedComponentCodes":["kyc_verification_wizard","wizard_back_button","wizard_next_button"],"code":"wizard_default_step_and_back_disabled","decision":"On first load, default to Step 1 (Personal info). The Back button is disabled (disabled attribute) on Step 1. Step indicator reflects Step 1 as current.","rationale":"This resolves the initial wizard state and Back disabled behavior with the most conservative linear wizard pattern and no assumptions about prior progress.","sourceGap":"Initial wizard state is unspecified (which step is default on first load, whether previously completed steps are prefilled)"},{"affectedComponentCodes":["kyc_verification_wizard","wizard_next_button","personal_info_step","document_upload_step","selfie_step"],"code":"per_step_validation_and_next_gating","decision":"Treat each step as required to proceed. Next is disabled until the current step is valid. Validation runs on blur and on Next click; errors render inline beneath fields. Minimum validity rules: Personal info step requires non-empty "Legal first name", "Legal last name", and "Date of birth" (date input). Document upload step requires at least one successfully added file that passes client-side validation. Selfie step requires one selfie image provided via capture or upload.","rationale":"This defines concrete gating and minimal schemas needed to implement and test the wizard flow without inventing extensive field sets. It uses conservative required-only inputs consistent with typical KYC steps.","sourceGap":"Per-step validation states are missing (required fields, inline errors, and blocking Next until valid)"},{"affectedComponentCodes":["document_upload_step"],"code":"document_upload_interaction_and_a11y","decision":"Implement a single drop zone that is also keyboard-operable: the drop zone is a <button type="button"> styled as a panel with label text "Upload documents" and instructions "Drag and drop or choose files". Activating it opens a hidden <input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png">. The button uses aria-describedby to reference instruction text and any error text. Drag-and-drop is additive; file picker is always available as the accessible alternative.","rationale":"This explicitly provides a keyboard-accessible alternative and clear labeling for the drop target, meeting the drag-and-drop accessibility gaps while staying within the specified upload methods.","sourceGap":"File upload drop zone accessibility is undefined (keyboard-operable alternative to drag-and-drop, clear label/instructions, ARIA for drop target)"},{"affectedComponentCodes":["document_upload_step"],"code":"document_upload_limits_and_errors","decision":"Allow up to 5 files. Enforce client-side constraints: allowed types PDF/JPG/PNG and max size 10MB per file. On invalid type or oversize, reject the file, show an inline error summary within the upload step (role="alert") and a per-file error row. Error messages are referenced from the file input via aria-describedby. Detect duplicates by matching name+size and reject with "This file was already added".","rationale":"This resolves missing limits and error handling with conservative bounds and deterministic rules, enabling consistent UI, tests, and accessibility associations without requiring backend behavior assumptions.","sourceGap":"Document upload error states are missing (file too large, unsupported type, upload failed, network error, duplicate file)"},{"affectedComponentCodes":["document_upload_step","wizard_next_button"],"code":"document_upload_progress_remove_and_next_loading","decision":"On add, files enter an "uploading" state with an indeterminate progress indicator per file and a "Remove" action available at all times. While any file is uploading, Next is disabled and shows a loading label "Uploading…". If an upload fails, the file row shows "Upload failed" with a "Retry" action; Next remains disabled until all remaining files are in a successful state or removed.","rationale":"This specifies in-progress, failure, retry, and navigation locking behavior required for a robust upload step without inventing server-specific progress APIs.","sourceGap":"Document upload in-progress state is unspecified (uploading indicator, per-file progress, cancel/remove)"},{"affectedComponentCodes":["selfie_step"],"code":"selfie_capture_and_fallback_states","decision":"Provide two options in the selfie step: "Use camera" and "Upload a photo". Camera path: show live preview (16:9 container that scales responsively), buttons "Capture" and "Retake" (native buttons). If permission is denied or camera unavailable, automatically switch to the upload option and display an inline message "Camera unavailable. Upload a selfie instead." Upload path accepts .jpg/.jpeg/.png up to 10MB and shows a preview with "Remove/Replace".","rationale":"This defines a complete, accessible selfie collection approach including denied/unavailable states and a non-camera fallback, aligning with the gap without over-specifying UI beyond necessary controls.","sourceGap":"Selfie step states are missing (camera permission denied, camera unavailable, capture in progress, retake, upload fallback)"},{"affectedComponentCodes":["kyc_verification_wizard","wizard_next_button","wizard_back_button"],"code":"final_submission_and_global_error","decision":"On Step 3 Next, perform a final submission request. During submission, disable Back/Next and change Next label to "Submitting…". On submission success, replace step content with the verification status view defaulting to "Pending review". On API failure (fetch existing status or submit), render a global inline error banner at the top of the wizard (role="alert") with text "Something went wrong. Please try again." and a "Retry" button that repeats the failed request.","rationale":"This explicitly defines the missing submission state and global error handling with a simple retry mechanism, enabling deterministic UX and test coverage without assuming complex backend flows.","sourceGap":"Final submission state is missing (submitting KYC package before status is shown)"},{"affectedComponentCodes":["verification_status"],"code":"status_non_color_and_rejection_reason","decision":"Render status with both icon and text: Pending review (clock icon), Approved (check icon), Rejected (x icon). Include a screen-reader label that announces "Verification status: {status}". For Rejected, display a "Reason" text block if provided by API; if no reason is available, show "Reason: Not provided". For Rejected, also show a primary action "Start over" that resets the wizard to Step 1 and clears step data in local state.","rationale":"This resolves reliance on color alone and defines a conservative rejection follow-up that does not assume partial editability; it provides a clear next action and works whether or not a reason is returned.","sourceGap":"Rejected status follow-up state is unspecified (whether rejection includes reason text and what user can do next)"},{"affectedComponentCodes":["kyc_verification_wizard","kyc_step_indicator","document_upload_step","verification_status"],"code":"responsive_layout_rules","decision":"For widths < 480px: step indicator stacks vertically with full-width items and wraps long labels to multiple lines (no truncation). Back/Next actions become a sticky bottom bar with Back on the left and Next on the right, each min-height 44px. Document upload drop zone becomes full-width with min-height 120px and tap targets (buttons) at least 44px tall. Uploaded files render as a vertical list with filename wrapping and actions in a trailing overflow menu if needed. Verification status content stacks: icon+status on first row, message/reason below, actions full-width.","rationale":"This defines concrete mobile behavior for wrapping, sizing, and action placement using conservative accessibility-friendly sizing and avoiding truncation that could hide critical info.","sourceGap":"Layout rules for small screens are unspecified (step indicator wrapping/stacking, placement of Back/Next actions, and spacing between sections)"}]},"targetComponent":{"code":"kyc_verification_wizard","name":"KYC verification wizard","parentCode":null,"purpose":"Guide the user through KYC steps with navigation and final status display.","statePolicy":"smart","type":"wizard"},"targetComponentInterface":{"accepts":[{"description":"Initial step to display when the wizard first mounts. Defaults to 1 (Personal info) if not provided.","name":"initial_step_index","required":false,"type":"number"},{"description":"Optional initial values for Personal info step fields (legal_first_name, legal_last_name, date_of_birth) used to prefill the form when returning to the wizard.","name":"initial_personal_info","required":false,"type":"KycPersonalInfo"},{"description":"Optional initial documents state, typically used when returning to the wizard mid-flow (e.g., already uploaded documents).","name":"initial_documents","required":false,"type":"KycDocumentItem[]"},{"description":"Optional initial selfie state, typically used when returning to the wizard mid-flow (e.g., already provided selfie).","name":"initial_selfie","required":false,"type":"KycSelfieValue"},{"description":"If provided, the wizard bypasses the 3 steps and shows the verification status view (pending_review, approved, rejected).","name":"initial_verification_status","required":false,"type":"KycVerificationStatus"},{"description":"Optional rejection reason text to display when status is rejected. If omitted and status is rejected, the UI shows 'Reason: Not provided'.","name":"initial_rejection_reason","required":false,"type":"string"},{"description":"Async handler invoked when the user completes Step 3 and clicks Next to submit the full KYC package.","name":"on_submit_kyc","required":true,"type":"(payload: SubmitKycPayload) => Promise<SubmitKycResult>"},{"description":"Async handler invoked when the user presses Retry in the global error banner after a failed submit attempt.","name":"on_retry_submit","required":false,"type":"() => Promise<SubmitKycResult>"}],"componentCode":"kyc_verification_wizard","componentName":"KYC verification wizard","returns":[{"description":"Emitted when the current step changes due to Back/Next navigation.","name":"step_change","required":true,"type":"StepChangePayload"},{"description":"Emitted when final submission is initiated from Step 3 (before async completion).","name":"submit_start","required":true,"type":"SubmitKycPayload"},{"description":"Emitted when final submission succeeds and the wizard transitions to the verification status view.","name":"submit_success","required":true,"type":"SubmitKycSuccessPayload"},{"description":"Emitted when final submission fails and the wizard shows the global error banner.","name":"submit_error","required":true,"type":"SubmitKycErrorPayload"},{"description":"Emitted when the user selects 'Start over' from the rejected status view, resetting wizard state back to Step 1.","name":"start_over","required":true,"type":"() => void"}]},"targetSourceFilePath":"/app/generated/frontend/src/components/KycVerificationWizard/KycVerificationWizard.tsx","targetUnitTests":{"componentCode":"kyc_verification_wizard","componentName":"KYC verification wizard","coveredBehaviors":["Defaults to Step 1 (Personal info) when initial_step_index is not provided and disables Back on Step 1","Renders a step indicator with aria-current="step" on the current step and includes helper text "Step X of 3"","Announces step changes via an aria-live="polite" region with text "Step X of 3: {stepName}"","Moves focus to the new step <h2> heading (tabIndex=-1) on Next/Back navigation","Disables Next until the current step is valid (per-step gating)","On final submission from Step 3, disables Back/Next and changes Next label to "Submitting…"","On submit success, transitions to verification status view showing Pending review by default","On submit failure, shows a global error banner (role="alert") with retry action; retry invokes on_retry_submit when provided and transitions to success on resolve","When initial_verification_status is provided, bypasses steps and renders the verification status view","When initial_verification_status is rejected and no reason is provided, renders fallback "Reason: Not provided" and Start over resets wizard to Step 1"],"coveredStates":["Step 1: Personal info (initial/default)","Step 2: Document upload","Step 3: Selfie","Submitting state (Next shows "Submitting…", navigation disabled)","Global submit error banner with Retry","Verification status view (pending_review via default on success)","Verification status view (rejected with fallback reason and Start over)"],"files":[{"filename":"/app/generated/frontend/src/components/KycVerificationWizard/KycVerificationWizard.spec.tsx","content":"import React from 'react';
import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import KycVerificationWizard from './KycVerificationWizard';

jest.mock('../KycStepIndicator/KycStepIndicator', () => ({
  __esModule: true,
  default: ({ steps, current_step_index, total_steps, aria_label }: any) => {
    const label = aria_label ?? 'KYC steps';
    return (
      <nav aria-label={label}>
        <div>{`Step ${current_step_index + 1} of ${total_steps}`}</div>
        <ol>
          {steps.map((s: string, idx: number) => (
            <li key={s} aria-current={idx === current_step_index ? 'step' : undefined}>
              {s}
            </li>
          ))}
        </ol>
      </nav>
    );
  }
}));

jest.mock('../WizardBackButton/WizardBackButton', () => ({
  __esModule: true,
  default: ({ label, disabled, on_back }: any) => (
    <button type="button" onClick={on_back} disabled={disabled}>
      {label}
    </button>
  )
}));

jest.mock('../WizardNextButton/WizardNextButton', () => ({
  __esModule: true,
  default: ({ label, disabled, loading, on_press }: any) => (
    <button type="button" onClick={on_press} disabled={disabled} aria-busy={loading ? 'true' : undefined}>
      {label}
    </button>
  )
}));

jest.mock('../PersonalInfoStep/PersonalInfoStep', () => ({
  __esModule: true,
  default: ({ values, errors, show_validation, is_disabled, on_change, on_blur }: any) => (
    <section>
      <h2 tabIndex={-1}>Personal info</h2>
      <label htmlFor="legal_first_name">Legal first name</label>
      <input
        id="legal_first_name"
        name="legal_first_name"
        disabled={!!is_disabled}
        value={values.legal_first_name ?? ''}
        aria-invalid={show_validation && !!errors.legal_first_name ? 'true' : undefined}
        aria-describedby={show_validation && errors.legal_first_name ? 'err_legal_first_name' : undefined}
        onChange={(e) => on_change({ field_name: 'legal_first_name', value: (e.target as HTMLInputElement).value })}
        onBlur={() => on_blur?.('legal_first_name')}
      />
      {show_validation && errors.legal_first_name ? (
        <div id="err_legal_first_name">{errors.legal_first_name}</div>
      ) : null}

