import KycStepIndicator from '../KycStepIndicator/KycStepIndicator';
import PersonalInfoStep from '../PersonalInfoStep/PersonalInfoStep';
import DocumentUploadStep from '../DocumentUploadStep/DocumentUploadStep';
import SelfieStep from '../SelfieStep/SelfieStep';
