  function validateDocFile(file: File): string | null {
    if (!ACCEPTED_DOC_MIME.has(file.type)) {
      return 'Unsupported file type. Please upload a PDF, JPG, or PNG.';
    }
    if (file.size > MAX_DOC_BYTES) {
      return 'File is too large. Max size is 10MB.';
    }
    const isDup = documents.some((d) => d.file.name === file.name && d.file.size === file.size);
    if (isDup) {
