    }, 50);
  }

  function handleAddDocuments(files: File[]) {
    setGlobalError(null);

    const accepted: UploadFileRow[] = [];
    const errors: string[] = [];

    for (const f of files) {
      const err = validateDocFile(f);
      if (err) {
        errors.push(err);
        continue;
      }
      const id = uid('doc');
      accepted.push({ id, file: f, status: 'uploading' });
    }

    if (errors.length > 0) {
      setDocErrorSummary(errors[0]);
    } else {
      setDocErrorSummary(null);
    }

    if (accepted.length === 0) return;

