import DocumentUploadStep from './DocumentUploadStep';

type KycDocumentUploadItem = {
  id: string;
  file_name: string;
  status: 'uploading' | 'success' | 'error';
  error_message?: string | null;
};

describe('DocumentUploadStep', () => {
  const accepted = ['.pdf', '.jpg', '.jpeg', '.png', 'application/pdf', 'image/jpeg', 'image/png'];

  const baseProps = (overrides?: Partial<React.ComponentProps<typeof DocumentUploadStep>>) => ({
    max_files: 5,
    max_file_size_bytes: 10 * 1024 * 1024,
    accepted_file_types: accepted,
    files: [] as KycDocumentUploadItem[],
    is_disabled: false,
    is_uploading: false,
    error_summary: undefined,
    dropzone_label: 'Upload documents',
    dropzone_instructions: 'Drag and drop or choose files',
    on_add_files: jest.fn(),
    on_remove_file: jest.fn(),
    on_retry_file: jest.fn(),
    ...overrides
  });

  function getFileInput(container: HTMLElement): HTMLInputElement {
    const input = container.querySelector('input[type="file"]') as HTMLInputElement | null;
    if (!input) throw new Error('Expected a hidden <input type="file"> in DocumentUploadStep');
    return input;
  }

  it('renders a keyboard-operable drop zone button with label and instructions', () => {
    render(<DocumentUploadStep {...baseProps()} />);

    const button = screen.getByRole('button', { name: 'Upload documents' });
    expect(button).toBeInTheDocument();

    expect(screen.getByText('Drag and drop or choose files')).toBeInTheDocument();
  });

  it('clicking the drop zone triggers the hidden file input click', async () => {
    const user = userEvent.setup();
    const { container } = render(<DocumentUploadStep {...baseProps()} />);

    const input = getFileInput(container);
    const clickSpy = jest.spyOn(input, 'click');

    await user.click(screen.getByRole('button', { name: 'Upload documents' }));
    expect(clickSpy).toHaveBeenCalled();
  });

  it('configures the file input with multiple and accept derived from accepted_file_types', () => {
    const { container } = render(
      <DocumentUploadStep
        {...baseProps({
          accepted_file_types: ['.pdf', 'image/png']
        })}
      />
    );

    const input = getFileInput(container);
    expect(input.multiple).toBe(true);

    // Implementation may join with commas; we assert it contains both entries.
    expect(input.getAttribute('accept') || '').toContain('.pdf');
    expect(input.getAttribute('accept') || '').toContain('image/png');
  });

  it('calls on_add_files when the user selects files via the file input', () => {
    const props = baseProps();
    const { container } = render(<DocumentUploadStep {...props} />);

    const input = getFileInput(container);
    const f1 = new File(['a'], 'a.pdf', { type: 'application/pdf' });
    const f2 = new File(['b'], 'b.png', { type: 'image/png' });

    fireEvent.change(input, { target: { files: [f1, f2] } });

    expect(props.on_add_files).toHaveBeenCalledTimes(1);
    expect(props.on_add_files).toHaveBeenCalledWith([f1, f2]);
  });

  it('calls on_add_files when files are dropped onto the drop zone', () => {
    const props = baseProps();
    render(<DocumentUploadStep {...props} />);

    const dropZoneButton = screen.getByRole('button', { name: 'Upload documents' });

    const f1 = new File(['a'], 'a.jpg', { type: 'image/jpeg' });
    const f2 = new File(['b'], 'b.pdf', { type: 'application/pdf' });

    const dataTransfer = {
      files: [f1, f2],
      items: []
    } as unknown as DataTransfer;

    fireEvent.drop(dropZoneButton, { dataTransfer });

    expect(props.on_add_files).toHaveBeenCalledTimes(1);
    expect(props.on_add_files).toHaveBeenCalledWith([f1, f2]);
  });

  it('renders error_summary as an alert and associates it to the upload control via aria-describedby', () => {
    const { container } = render(
      <DocumentUploadStep
        {...baseProps({
          error_summary: 'Unsupported file type'
        })}
      />
    );

    const alert = screen.getByRole('alert');
    expect(alert).toHaveTextContent('Unsupported file type');

    const input = getFileInput(container);
    const describedBy = input.getAttribute('aria-describedby') || '';
    // At minimum, the input should reference something when an error summary exists.
    expect(describedBy.trim().length).toBeGreaterThan(0);
  });

  it('renders controlled file rows and allows removing a file (calls on_remove_file with file_id)', async () => {
    const user = userEvent.setup();
    const props = baseProps({
      files: [
        { id: 'file_1', file_name: 'passport.pdf', status: 'success' },
        { id: 'file_2', file_name: 'license.jpg', status: 'uploading' }
      ] as KycDocumentUploadItem[]
    });

    render(<DocumentUploadStep {...props} />);

    expect(screen.getByText('passport.pdf')).toBeInTheDocument();
    expect(screen.getByText('license.jpg')).toBeInTheDocument();

    // We assume each row exposes a "Remove" button.
    const removeButtons = screen.getAllByRole('button', { name: /remove/i });
    await user.click(removeButtons[0]);

    expect(props.on_remove_file).toHaveBeenCalledTimes(1);
    expect(props.on_remove_file).toHaveBeenCalledWith('file_1');
  });

  it('for an error file row, exposes a Retry action and calls on_retry_file with file_id', async () => {
    const user = userEvent.setup();
    const props = baseProps({
      files: [
        { id: 'file_err', file_name: 'bad.pdf', status: 'error', error_message: 'Upload failed' }
      ] as KycDocumentUploadItem[]
    });

    render(<DocumentUploadStep {...props} />);

    expect(screen.getByText('bad.pdf')).toBeInTheDocument();

    const retryButton = screen.getByRole('button', { name: /retry/i });
    await user.click(retryButton);

    expect(props.on_retry_file).toHaveBeenCalledTimes(1);
    expect(props.on_retry_file).toHaveBeenCalledWith('file_err');
  });

  it('disables interactions when is_disabled is true (drop zone and row actions)', async () => {
    const user = userEvent.setup();
    const props = baseProps({
      is_disabled: true,
      files: [
        { id: 'file_1', file_name: 'passport.pdf', status: 'success' },
        { id: 'file_err', file_name: 'bad.pdf', status: 'error', error_message: 'Upload failed' }
      ] as KycDocumentUploadItem[]
    });

    render(<DocumentUploadStep {...props} />);

    const dropZoneButton = screen.getByRole('button', { name: 'Upload documents' });
    expect(dropZoneButton).toBeDisabled();

    const removeButton = screen.getAllByRole('button', { name: /remove/i })[0];
    expect(removeButton).toBeDisabled();

    const retryButton = screen.getByRole('button', { name: /retry/i });
    expect(retryButton).toBeDisabled();

    await user.click(dropZoneButton);
    await user.click(removeButton);
    await user.click(retryButton);

    expect(props.on_add_files).not.toHaveBeenCalled();
    expect(props.on_remove_file).not.toHaveBeenCalled();
    expect(props.on_retry_file).not.toHaveBeenCalled();
  });
});
