import React from 'react';

export type PageChangePayload = { current_page: number };
export type PageSizeChangePayload = { page_size: number };

export type TransactionPaginationProps = {
  /** Current 1-based page number being displayed. */
  current_page: number;
  /** Total number of transactions available across all pages. */
  total_count: number;
  /** Current page size (rows per page). */
  page_size: number;
  /** Allowed page size options for the selector. Defaults to [25, 50, 100]. */
  page_size_options?: number[];
  /** Whether controls are disabled due to an in-flight fetch. */
  is_loading?: boolean;
  /** Fired when user requests a different page. */
  on_page_change: (payload: PageChangePayload) => void;
  /** Fired when user changes the rows-per-page value. */
  on_page_size_change: (payload: PageSizeChangePayload) => void;
};

function clamp(n: number, min: number, max: number) {
  return Math.min(max, Math.max(min, n));
}

function computeTotalPages(totalCount: number, pageSize: number) {
  if (!totalCount || totalCount <= 0 || !pageSize || pageSize <= 0) return 0;
  return Math.ceil(totalCount / pageSize);
}

const srOnly: React.CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: 'hidden',
  clip: 'rect(0, 0, 0, 0)',
  whiteSpace: 'nowrap',
  border: 0,
};

const styles: Record<string, React.CSSProperties> = {
  root: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 'var(--spacing-16)',
    padding: 'var(--spacing-12) var(--spacing-16)',
    background: 'var(--color-surface-default)',
    borderTop: '1px solid var(--color-border-subtle)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-body)',
  },
  left: {
    display: 'flex',
    alignItems: 'center',
    gap: 'var(--spacing-8)',
  },
  label: {
    color: 'var(--color-text-secondary)',
    fontSize: 'var(--font-size-label)',
    fontWeight: 'var(--font-weight-medium)',
  },
  select: {
    fontSize: 'var(--font-size-body)',
    padding: 'var(--spacing-4) var(--spacing-8)',
    borderRadius: 'var(--radius-8)',
    border: '1px solid var(--color-border-subtle)',
    background: 'var(--color-surface-default)',
    color: 'var(--color-text-primary)',
  },
  right: {
    display: 'flex',
    alignItems: 'center',
    gap: 'var(--spacing-8)',
  },
  pageText: {
    color: 'var(--color-text-secondary)',
    fontSize: 'var(--font-size-body)',
  },
  nav: {
    display: 'flex',
    alignItems: 'center',
    gap: 'var(--spacing-4)',
  },
  button: {
    fontSize: 'var(--font-size-body)',
    padding: 'var(--spacing-4) var(--spacing-8)',
    borderRadius: 'var(--radius-8)',
    border: '1px solid var(--color-border-subtle)',
    background: 'var(--color-surface-default)',
    color: 'var(--color-text-primary)',
    boxShadow: 'var(--shadow-sm)',
    cursor: 'pointer',
  },
  buttonDisabled: {
    cursor: 'not-allowed',
    opacity: 0.6,
    boxShadow: 'none',
  },
};

export default function TransactionPagination(props: TransactionPaginationProps) {
  const {
    current_page,
    total_count,
    page_size,
    page_size_options,
    is_loading = false,
    on_page_change,
    on_page_size_change,
  } = props;

  const options = (page_size_options && page_size_options.length > 0 ? page_size_options : [25, 50, 100]).map((n) => Number(n));

  const totalPages = computeTotalPages(total_count, page_size);

  // Keep display stable for totalPages=0; tests expect "Page 1 of 0".
  const displayPage = totalPages === 0 ? 1 : clamp(current_page, 1, totalPages);

  const isFirstPage = displayPage <= 1;
  const isLastPage = totalPages === 0 || displayPage >= totalPages;

  const disableNav = is_loading || totalPages === 0;

  const goToPage = (page: number) => {
    if (disableNav) return;
    const next = totalPages === 0 ? 1 : clamp(page, 1, totalPages);
    if (next === displayPage) return;
    on_page_change({ current_page: next });
  };

  const onChangePageSize: React.ChangeEventHandler<HTMLSelectElement> = (e) => {
    if (is_loading) return;
    const nextSize = Number(e.target.value);
    on_page_size_change({ page_size: nextSize });
  };

  const btnStyle = (disabled: boolean): React.CSSProperties => ({
    ...styles.button,
    ...(disabled ? styles.buttonDisabled : null),
  });

  return (
    <div style={styles.root}>
      <div style={styles.left}>
        <label style={styles.label}>
          Rows per page
          <span style={srOnly}> selector</span>
          <select
            aria-label="Rows per page"
            style={styles.select}
            value={String(page_size)}
            onChange={onChangePageSize}
            disabled={is_loading}
          >
            {options.map((n) => (
              <option key={n} value={String(n)}>
                {n}
              </option>
            ))}
          </select>
        </label>
      </div>

      <div style={styles.right}>
        <div aria-live="polite" style={styles.pageText}>
          Page {displayPage} of {totalPages}
        </div>

        <div style={styles.nav}>
          <button
            type="button"
            style={btnStyle(disableNav || isFirstPage)}
            onClick={() => goToPage(1)}
            disabled={disableNav || isFirstPage}
            aria-label="First page"
          >
            First
          </button>
          <button
            type="button"
            style={btnStyle(disableNav || isFirstPage)}
            onClick={() => goToPage(displayPage - 1)}
            disabled={disableNav || isFirstPage}
            aria-label="Previous page"
          >
            Previous
          </button>
          <button
            type="button"
            style={btnStyle(disableNav || isLastPage)}
            onClick={() => goToPage(displayPage + 1)}
            disabled={disableNav || isLastPage}
            aria-label="Next page"
          >
            Next
          </button>
          <button
            type="button"
            style={btnStyle(disableNav || isLastPage)}
            onClick={() => goToPage(totalPages)}
            disabled={disableNav || isLastPage}
            aria-label="Last page"
          >
            Last
          </button>
        </div>
      </div>
    </div>
  );
}

import React from 'react';

type SupportedStatus = 'pending' | 'completed' | 'failed' | 'refunded';

type NormalizedStatus = SupportedStatus | 'unknown';

export interface TransactionStatusBadgeProps {
  /**
   * Transaction status value used to determine label and styling.
   * Supported: "pending", "completed", "failed", "refunded".
   * Any other value renders the neutral "Unknown" badge.
   */
  status: string;
}

const LABELS: Record<NormalizedStatus, string> = {
  pending: 'Pending',
  completed: 'Completed',
  failed: 'Failed',
  refunded: 'Refunded',
  unknown: 'Unknown'
};

function normalizeStatus(status: string): NormalizedStatus {
  const s = (status ?? '').toString().trim().toLowerCase();
  if (s === 'pending' || s === 'completed' || s === 'failed' || s === 'refunded') return s;
  return 'unknown';
}

function statusStyles(status: NormalizedStatus): React.CSSProperties {
  // Use only tokenized CSS variables from the whitelist.
  // Keep shape/typography consistent and set a distinctive colored left border.
  const base: React.CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    gap: 'var(--spacing-4)',
    padding: 'var(--spacing-4) var(--spacing-8)',
    borderRadius: 'var(--radius-8)',
    border: '1px solid var(--color-border-subtle)',
    background: 'var(--color-surface-muted)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-label)',
    fontWeight: 'var(--font-weight-medium)',
    lineHeight: 1
  };

  const leftBorderColorVar: Record<NormalizedStatus, string> = {
    pending: 'var(--color-status-warning)',
    completed: 'var(--color-status-success)',
    failed: 'var(--color-status-danger)',
    refunded: 'var(--color-text-secondary)',
    unknown: 'var(--color-text-secondary)'
  };

  return {
    ...base,
    borderLeft: `4px solid ${leftBorderColorVar[status]}`
  };
}

export function TransactionStatusBadge({ status }: TransactionStatusBadgeProps) {
  const normalized = normalizeStatus(status);

  return (
    <span
      data-status={normalized}
      style={statusStyles(normalized)}
      aria-label={`Status: ${LABELS[normalized]}`}
    >
      {LABELS[normalized]}
      <style>{`
        @media (forced-colors: active) {
          [data-status] {
            forced-color-adjust: auto;
            background: transparent !important;
            border: 1px solid currentColor !important;
            border-left-width: 4px !important;
            color: CanvasText !important;
          }
        }
      `}</style>
    </span>
  );
}

import React from 'react';

import { TransactionPagination } from '../TransactionPagination/TransactionPagination';
import { TransactionStatusBadge } from '../TransactionStatusBadge/TransactionStatusBadge';

export type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: string;
  merchant_name: string;
  payment_method: string;
};

export type TransactionSortKey = 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method' | (string & {});

export type SortChangePayload = {
  sort_key: TransactionSortKey;
  sort_direction: 'asc' | 'desc';
};

export type PageChangePayload = { page?: number; current_page?: number };
export type PageSizeChangePayload = { page_size: 25 | 50 | 100; page?: number; current_page?: number };
export type OpenTransactionDetailsPayload = TransactionRow;

export type TransactionTableProps = {
  transactions: TransactionRow[];
  total_count: number;
  is_initial_loading: boolean;
  is_fetching: boolean;
  has_error: boolean;
  error_message?: string;
  current_page: number;
  page_size: 25 | 50 | 100;
  sort_key: TransactionSortKey;
  sort_direction: 'asc' | 'desc';
  on_sort_change: (payload: SortChangePayload) => void;
  on_page_change: (payload: PageChangePayload) => void;
  on_page_size_change: (payload: PageSizeChangePayload) => void;
  on_open_details: (payload: OpenTransactionDetailsPayload) => void;
  on_retry: () => void;
};

const SORTABLE_COLUMNS: Array<{ key: TransactionSortKey; label: string }> = [
  { key: 'date', label: 'Date' },
  { key: 'amount', label: 'Amount' },
  { key: 'status', label: 'Status' },
  { key: 'merchant_name', label: 'Merchant Name' },
  { key: 'payment_method', label: 'Payment Method' },
];

function toAriaSort(direction: 'asc' | 'desc') {
  return direction === 'asc' ? 'ascending' : 'descending';
}

function getDetailsAriaLabel(txn: TransactionRow) {
  const merchant = txn.merchant_name?.trim();
  const date = txn.date?.trim();
  if (merchant && date) return `View details for transaction ${merchant} on ${date}`;
  if (merchant) return `View details for transaction ${merchant}`;
  if (date) return `View details for transaction on ${date}`;
  return 'View transaction details';
}

export function TransactionTable(props: TransactionTableProps) {
  const {
    transactions,
    total_count,
    is_initial_loading,
    is_fetching,
    has_error,
    error_message,
    current_page,
    page_size,
    sort_key,
    sort_direction,
    on_sort_change,
    on_page_change,
    on_page_size_change,
    on_open_details,
    on_retry,
  } = props;

  const isInteractionLocked = !!is_fetching;

  const showPagination = !is_initial_loading && !has_error && total_count > 0;

  const handleSortActivate = (colKey: TransactionSortKey) => {
    if (isInteractionLocked) return;

    const isSame = colKey === sort_key;
    const nextDirection: 'asc' | 'desc' = isSame ? (sort_direction === 'asc' ? 'desc' : 'asc') : 'asc';

    on_sort_change({ sort_key: colKey, sort_direction: nextDirection });
  };

  const handleRowClick = (txn: TransactionRow) => {
    if (isInteractionLocked) return;
    on_open_details(txn);
  };

  const handleDetailsClick = (e: React.MouseEvent, txn: TransactionRow) => {
    e.stopPropagation();
    if (isInteractionLocked) return;
    on_open_details(txn);
  };

  const handlePageChange = (payload: PageChangePayload) => {
    if (isInteractionLocked) return;
    on_page_change(payload);
  };

  const handlePageSizeChange = (payload: PageSizeChangePayload) => {
    if (isInteractionLocked) return;
    on_page_size_change(payload);
  };

  const renderBody = () => {
    if (has_error) {
      return (
        <tr>
          <td colSpan={6} style={styles.stateCell}>
            <div style={styles.stateTitle}>{error_message ?? 'Unable to load transactions.'}</div>
            <button
              type="button"
              onClick={on_retry}
              style={styles.retryButton}
              className="tt-focus"
            >
              Retry
            </button>
          </td>
        </tr>
      );
    }

    if (!is_initial_loading && total_count === 0) {
      return (
        <tr>
          <td colSpan={6} style={styles.stateCell}>
            <div style={styles.stateTitle}>No transactions to display.</div>
          </td>
        </tr>
      );
    }

    if (is_initial_loading) {
      return Array.from({ length: 10 }).map((_, i) => (
        <tr key={`skeleton-${i}`}>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '7rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '5rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '6rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '10rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '12rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '6rem' }} />
          </td>
        </tr>
      ));
    }

    return transactions.map((txn) => (
      <tr
        key={txn.id}
        onClick={() => handleRowClick(txn)}
        style={{ ...styles.tr, ...(isInteractionLocked ? styles.trLocked : null) }}
      >
        <td style={styles.tdNoWrap}>{txn.date}</td>
        <td style={styles.tdNoWrap}>{String(txn.amount)}</td>
        <td style={styles.tdNoWrap}>
          <TransactionStatusBadge status={txn.status} />
        </td>
        <td style={styles.tdEllipsis} title={txn.merchant_name}>
          {txn.merchant_name}
        </td>
        <td style={styles.tdEllipsis} title={txn.payment_method}>
          {txn.payment_method}
        </td>
        <td style={styles.tdAction}>
          <button
            type="button"
            onClick={(e) => handleDetailsClick(e, txn)}
            aria-label={getDetailsAriaLabel(txn)}
            disabled={isInteractionLocked}
            style={styles.detailsButton}
            className="tt-focus"
          >
            View details
          </button>
        </td>
      </tr>
    ));
  };

  return (
    <div style={styles.card}>
      <style>
        {`
          .tt-focus:focus-visible {
            outline: 2px solid var(--color-text-primary);
            outline-offset: 2px;
          }
        `}
      </style>

      <div style={styles.scrollWrap}>
        <div style={styles.tableWrap}>
          <table role="table" style={styles.table}>
            <thead>
              <tr>
                {SORTABLE_COLUMNS.map((col) => {
                  const isActive = col.key === sort_key;
                  const ariaSort = isActive ? toAriaSort(sort_direction) : undefined;
                  const indicator = isActive ? (sort_direction === 'asc' ? '▲' : '▼') : '';
                  const sr = isActive ? ` (sorted ${toAriaSort(sort_direction)})` : '';

                  return (
                    <th
                      key={String(col.key)}
                      style={styles.th}
                      aria-sort={ariaSort as any}
                      scope="col"
                    >
                      <button
                        type="button"
                        onClick={() => handleSortActivate(col.key)}
                        disabled={isInteractionLocked}
                        style={styles.sortButton}
                        className="tt-focus"
                        aria-label={`Sort by ${col.label}`}
                      >
                        <span style={styles.thLabel}>{col.label}</span>
                        <span aria-hidden="true" style={styles.sortIndicator}>
                          {indicator}
                        </span>
                        <span style={styles.visuallyHidden}>{sr}</span>
                      </button>
                    </th>
                  );
                })}
                <th style={styles.th} scope="col">
                  <span style={styles.thLabel}>Actions</span>
                </th>
              </tr>
            </thead>
            <tbody style={styles.tbody}>{renderBody()}</tbody>
          </table>

          {is_fetching && !is_initial_loading && !has_error && (
            <div style={styles.fetchOverlay} aria-hidden="true">
              <div style={styles.fetchOverlayInner}>Loading…</div>
            </div>
          )}
        </div>
      </div>

      {showPagination ? (
        <div style={styles.paginationWrap}>
          <TransactionPagination
            current_page={current_page}
            total_count={total_count}
            page_size={page_size}
            is_loading={isInteractionLocked}
            on_page_change={handlePageChange}
            on_page_size_change={handlePageSizeChange}
          />
        </div>
      ) : null}
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  card: {
