describe('TransactionPagination', () => {
  test('renders page status as "Page X of Y" using ceil(total_count / page_size)', () => {
    renderComponent({ current_page: 1, total_count: 260, page_size: 25 });
    // 260/25 = 10.4 => 11 pages
    expect(screen.getByText(/page\s+1\s+of\s+11/i)).toBeInTheDocument();
  });

  test('disables First/Previous on first page and enables Next/Last when there are more pages', () => {
    renderComponent({ current_page: 1, total_count: 260, page_size: 25 });

    expect(screen.getByRole('button', { name: /first page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /previous page/i })).toBeDisabled();

    expect(screen.getByRole('button', { name: /next page/i })).toBeEnabled();
    expect(screen.getByRole('button', { name: /last page/i })).toBeEnabled();
  });

  test('disables Next/Last on last page and enables First/Previous', () => {
    // totalPages = 11
    renderComponent({ current_page: 11, total_count: 260, page_size: 25 });

    expect(screen.getByRole('button', { name: /first page/i })).toBeEnabled();
    expect(screen.getByRole('button', { name: /previous page/i })).toBeEnabled();

    expect(screen.getByRole('button', { name: /next page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /last page/i })).toBeDisabled();
  });

  test('clicking Next/Previous/First/Last calls on_page_change with the requested page', async () => {
    const { user, props } = renderComponent({ current_page: 5, total_count: 260, page_size: 25 });
    const onPageChange = props.on_page_change as jest.Mock;

    await user.click(screen.getByRole('button', { name: /next page/i }));
    expect(onPageChange).toHaveBeenCalledWith(expect.objectContaining({ current_page: 6 }));

    await user.click(screen.getByRole('button', { name: /previous page/i }));
    expect(onPageChange).toHaveBeenCalledWith(expect.objectContaining({ current_page: 4 }));

    await user.click(screen.getByRole('button', { name: /first page/i }));
    expect(onPageChange).toHaveBeenCalledWith(expect.objectContaining({ current_page: 1 }));

    await user.click(screen.getByRole('button', { name: /last page/i }));
    expect(onPageChange).toHaveBeenCalledWith(expect.objectContaining({ current_page: 11 }));

    expect(onPageChange).toHaveBeenCalledTimes(4);
  });

  test('renders a rows-per-page selector labeled "Rows per page" with default options (25/50/100) and reflects current page_size', () => {
    renderComponent({ page_size: 50 });

    // Label association can be either <label> or aria-label; getByLabelText covers both.
    const select = screen.getByLabelText(/rows per page/i) as HTMLSelectElement;
    expect(select).toBeInTheDocument();
    expect(select.value).toBe('50');

    const options = Array.from(select.querySelectorAll('option')).map((o) => o.value);
    expect(options).toEqual(expect.arrayContaining(['25', '50', '100']));
  });

  test('uses provided page_size_options when passed', () => {
    renderComponent({ page_size: 10, page_size_options: [10, 20, 30] });
    const select = screen.getByLabelText(/rows per page/i) as HTMLSelectElement;
    const options = Array.from(select.querySelectorAll('option')).map((o) => o.value);
    expect(options).toEqual(['10', '20', '30']);
  });

  test('changing rows per page calls on_page_size_change with the selected page size', async () => {
    const { user, props } = renderComponent({ page_size: 25 });
    const onPageSizeChange = props.on_page_size_change as jest.Mock;

    const select = screen.getByLabelText(/rows per page/i);
    await user.selectOptions(select, '100');

    expect(onPageSizeChange).toHaveBeenCalledWith(expect.objectContaining({ page_size: 100 }));
    expect(onPageSizeChange).toHaveBeenCalledTimes(1);
  });

  test('when is_loading=true, disables navigation buttons and rows-per-page selector and prevents callbacks', async () => {
    const { user, props } = renderComponent({ current_page: 2, total_count: 260, page_size: 25, is_loading: true });
    const onPageChange = props.on_page_change as jest.Mock;
    const onPageSizeChange = props.on_page_size_change as jest.Mock;

    expect(screen.getByRole('button', { name: /first page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /previous page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /next page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /last page/i })).toBeDisabled();

    const select = screen.getByLabelText(/rows per page/i);
    expect(select).toBeDisabled();

    await user.click(screen.getByRole('button', { name: /next page/i }));
    expect(onPageChange).not.toHaveBeenCalled();

    // userEvent will not change disabled selects; this ensures no handler fires.
    try {
      await user.selectOptions(select, '50');
    } catch {
      // ignore user-event errors in case underlying element isn't a <select>
    }
    expect(onPageSizeChange).not.toHaveBeenCalled();
  });

  test('when total_count=0, shows "Page 1 of 0" (or equivalent) and disables navigation', () => {
    renderComponent({ current_page: 1, total_count: 0, page_size: 25 });

    expect(screen.getByText(/page\s+1\s+of\s+0/i)).toBeInTheDocument();

    expect(screen.getByRole('button', { name: /first page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /previous page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /next page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /last page/i })).toBeDisabled();
  });
});

import React from 'react';

export type PageChangePayload = { current_page: number };
export type PageSizeChangePayload = { page_size: number };

export type TransactionPaginationProps = {
  /** Current 1-based page number being displayed. */
  current_page: number;
  /** Total number of transactions available across all pages. */
  total_count: number;
  /** Current page size (rows per page). */
  page_size: number;
  /** Allowed page size options for the selector. Defaults to [25, 50, 100]. */
  page_size_options?: number[];
  /** Whether controls are disabled due to an in-flight fetch. */
  is_loading?: boolean;
  /** Fired when user requests a different page. */
  on_page_change: (payload: PageChangePayload) => void;
  /** Fired when user changes the rows-per-page value. */
  on_page_size_change: (payload: PageSizeChangePayload) => void;
};

function clamp(n: number, min: number, max: number) {
  return Math.min(max, Math.max(min, n));
}

function computeTotalPages(totalCount: number, pageSize: number) {
  if (!totalCount || totalCount <= 0 || !pageSize || pageSize <= 0) return 0;
  return Math.ceil(totalCount / pageSize);
}

const srOnly: React.CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: 'hidden',
  clip: 'rect(0, 0, 0, 0)',
  whiteSpace: 'nowrap',
  border: 0,
};

const styles: Record<string, React.CSSProperties> = {
  root: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 'var(--spacing-16)',
    padding: 'var(--spacing-12) var(--spacing-16)',
    background: 'var(--color-surface-default)',
    borderTop: '1px solid var(--color-border-subtle)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-body)',
  },
  left: {
    display: 'flex',
    alignItems: 'center',
    gap: 'var(--spacing-8)',
  },
  label: {
    color: 'var(--color-text-secondary)',
    fontSize: 'var(--font-size-label)',
    fontWeight: 'var(--font-weight-medium)',
  },
  select: {
    fontSize: 'var(--font-size-body)',
    padding: 'var(--spacing-4) var(--spacing-8)',
    borderRadius: 'var(--radius-8)',
    border: '1px solid var(--color-border-subtle)',
    background: 'var(--color-surface-default)',
    color: 'var(--color-text-primary)',
  },
  right: {
    display: 'flex',
    alignItems: 'center',
    gap: 'var(--spacing-8)',
  },
  pageText: {
    color: 'var(--color-text-secondary)',
    fontSize: 'var(--font-size-body)',
  },
  nav: {
    display: 'flex',
    alignItems: 'center',
    gap: 'var(--spacing-4)',
  },
  button: {
    fontSize: 'var(--font-size-body)',
    padding: 'var(--spacing-4) var(--spacing-8)',
    borderRadius: 'var(--radius-8)',
    border: '1px solid var(--color-border-subtle)',
    background: 'var(--color-surface-default)',
    color: 'var(--color-text-primary)',
    boxShadow: 'var(--shadow-sm)',
    cursor: 'pointer',
  },
  buttonDisabled: {
    cursor: 'not-allowed',
    opacity: 0.6,
    boxShadow: 'none',
  },
};

export default function TransactionPagination(props: TransactionPaginationProps) {
  const {
    current_page,
    total_count,
    page_size,
    page_size_options,
    is_loading = false,
    on_page_change,
    on_page_size_change,
  } = props;

  const options = (page_size_options && page_size_options.length > 0 ? page_size_options : [25, 50, 100]).map((n) => Number(n));

  const totalPages = computeTotalPages(total_count, page_size);

  // Keep display stable for totalPages=0; tests expect "Page 1 of 0".
  const displayPage = totalPages === 0 ? 1 : clamp(current_page, 1, totalPages);

  const isFirstPage = displayPage <= 1;
  const isLastPage = totalPages === 0 || displayPage >= totalPages;

  const disableNav = is_loading || totalPages === 0;

  const goToPage = (page: number) => {
    if (disableNav) return;
    const next = totalPages === 0 ? 1 : clamp(page, 1, totalPages);
    if (next === displayPage) return;
    on_page_change({ current_page: next });
  };

  const onChangePageSize: React.ChangeEventHandler<HTMLSelectElement> = (e) => {
    if (is_loading) return;
    const nextSize = Number(e.target.value);
    on_page_size_change({ page_size: nextSize });
  };

  const btnStyle = (disabled: boolean): React.CSSProperties => ({
    ...styles.button,
    ...(disabled ? styles.buttonDisabled : null),
  });

  return (
    <div style={styles.root}>
      <div style={styles.left}>
        <label style={styles.label}>
          Rows per page
          <span style={srOnly}> selector</span>
          <select
            aria-label="Rows per page"
            style={styles.select}
            value={String(page_size)}
            onChange={onChangePageSize}
            disabled={is_loading}
          >
            {options.map((n) => (
              <option key={n} value={String(n)}>
                {n}
              </option>
            ))}
          </select>
        </label>
      </div>

      <div style={styles.right}>
        <div aria-live="polite" style={styles.pageText}>
          Page {displayPage} of {totalPages}
        </div>

        <div style={styles.nav}>
          <button
            type="button"
            style={btnStyle(disableNav || isFirstPage)}
            onClick={() => goToPage(1)}
            disabled={disableNav || isFirstPage}
            aria-label="First page"
          >
            First
          </button>
          <button
            type="button"
            style={btnStyle(disableNav || isFirstPage)}
            onClick={() => goToPage(displayPage - 1)}
            disabled={disableNav || isFirstPage}
            aria-label="Previous page"
          >
            Previous
          </button>
          <button
            type="button"
            style={btnStyle(disableNav || isLastPage)}
            onClick={() => goToPage(displayPage + 1)}
            disabled={disableNav || isLastPage}
            aria-label="Next page"
          >
            Next
          </button>
          <button
            type="button"
            style={btnStyle(disableNav || isLastPage)}
            onClick={() => goToPage(totalPages)}
            disabled={disableNav || isLastPage}
            aria-label="Last page"
          >
            Last
          </button>
        </div>
      </div>
    </div>
  );
}

import React from 'react';

type SupportedStatus = 'pending' | 'completed' | 'failed' | 'refunded';

type NormalizedStatus = SupportedStatus | 'unknown';

export interface TransactionStatusBadgeProps {
  /**
   * Transaction status value used to determine label and styling.
   * Supported: "pending", "completed", "failed", "refunded".
   * Any other value renders the neutral "Unknown" badge.
   */
  status: string;
}

const LABELS: Record<NormalizedStatus, string> = {
  pending: 'Pending',
  completed: 'Completed',
  failed: 'Failed',
  refunded: 'Refunded',
  unknown: 'Unknown'
};

function normalizeStatus(status: string): NormalizedStatus {
  const s = (status ?? '').toString().trim().toLowerCase();
  if (s === 'pending' || s === 'completed' || s === 'failed' || s === 'refunded') return s;
  return 'unknown';
}

function statusStyles(status: NormalizedStatus): React.CSSProperties {
  // Use only tokenized CSS variables from the whitelist.
  // Keep shape/typography consistent and set a distinctive colored left border.
  const base: React.CSSProperties = {
    display: 'inline-flex',
    alignItems: 'center',
    gap: 'var(--spacing-4)',
    padding: 'var(--spacing-4) var(--spacing-8)',
    borderRadius: 'var(--radius-8)',
    border: '1px solid var(--color-border-subtle)',
    background: 'var(--color-surface-muted)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-label)',
    fontWeight: 'var(--font-weight-medium)',
    lineHeight: 1
  };

  const leftBorderColorVar: Record<NormalizedStatus, string> = {
    pending: 'var(--color-status-warning)',
    completed: 'var(--color-status-success)',
    failed: 'var(--color-status-danger)',
    refunded: 'var(--color-text-secondary)',
    unknown: 'var(--color-text-secondary)'
  };

  return {
    ...base,
    borderLeft: `4px solid ${leftBorderColorVar[status]}`
  };
}

export function TransactionStatusBadge({ status }: TransactionStatusBadgeProps) {
  const normalized = normalizeStatus(status);

  return (
    <span
      data-status={normalized}
      style={statusStyles(normalized)}
      aria-label={`Status: ${LABELS[normalized]}`}
    >
      {LABELS[normalized]}
      <style>{`
        @media (forced-colors: active) {
          [data-status] {
            forced-color-adjust: auto;
            background: transparent !important;
            border: 1px solid currentColor !important;
            border-left-width: 4px !important;
            color: CanvasText !important;
          }
        }
      `}</style>
    </span>
  );
}

import React from 'react';

import { TransactionPagination } from '../TransactionPagination/TransactionPagination';
