  sort_direction: 'asc' | 'desc';
};

export type PageChangePayload = { page?: number; current_page?: number };
export type PageSizeChangePayload = { page_size: 25 | 50 | 100; page?: number; current_page?: number };
export type OpenTransactionDetailsPayload = TransactionRow;

export type TransactionTableProps = {
  transactions: TransactionRow[];
  total_count: number;
  is_initial_loading: boolean;
  is_fetching: boolean;
  has_error: boolean;
  error_message?: string;
