type Txn = {
  id: string;
  date: string;
  amount: string | number;
  status: string;
  merchant_name: string;
  payment_method: string;
};

function makeTxn(overrides: Partial<Txn> = {}): Txn {
  return {
    id: overrides.id ?? 't_1',
    date: overrides.date ?? '2026-01-02',
    amount: overrides.amount ?? '12.34',
    status: overrides.status ?? 'completed',
    merchant_name: overrides.merchant_name ?? 'Acme Inc',
    payment_method: overrides.payment_method ?? 'Visa •••• 4242',
  };
}

function renderSubject(props?: Partial<React.ComponentProps<typeof TransactionTable>>) {
  const defaultProps: React.ComponentProps<typeof TransactionTable> = {
    transactions: [makeTxn({ id: 't_1' }), makeTxn({ id: 't_2', merchant_name: 'Shop Co', date: '2026-01-03' })],
    total_count: 52,
    is_initial_loading: false,
    is_fetching: false,
    has_error: false,
    error_message: undefined,
    current_page: 1,
