{"coveredBehaviors":["Composed sort->fetching reload state: sortable headers emit sort-change payloads; parent updates sort props; table reflects aria-sort and disables header/pagination while fetching","Composed pagination->fetching reload state: pagination controls emit page-change and page-size-change payloads; parent updates paging props; pagination boundary states and aria-live page text update after refetch","Row-level details opening via pointer row-click and keyboard-accessible per-row "View details" control; callback payload wiring to parent handler","Error recovery integration: error state shows retry; retry triggers handler; parent re-attempts and then renders rows and pagination again","Unhappy invalid action prevention: attempting to paginate during in-flight fetch is blocked by disabled controls and does not emit additional callbacks","Status badge label is present in composed rows, including unknown-status fallback label"],"coveredComponentCodes":["transaction_table","transaction_pagination","transaction_status_badge"],"coveredFlowCodes":["open_transaction_details_shortest","browse_sort_paginate_then_open_details","invalid_double_paginate_during_loading","error_then_retry_load_transactions"],"coveredStates":["Loaded with rows","Reload fetching (overlay/disabled controls)","Error state (default message + retry)","Recovered loaded state after retry","Sort state (active aria-sort ascending/descending)","Pagination state (page X of Y, boundary disabled/enabled)"],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.e2e.spec.tsx","content":"import React from 'react';
import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: string;
  merchant_name: string;
  payment_method: string;
};

type SortKey = string;

type SortChangePayload = { sort_key: SortKey; sort_direction: 'asc' | 'desc' };

type PageChangePayload = { page?: number; current_page?: number };

type PageSizeChangePayload = { page_size: 25 | 50 | 100; page?: number; current_page?: number };

function mkTxn(overrides: Partial<TransactionRow> = {}): TransactionRow {
  return {
    id: overrides.id ?? 't_1',
    date: overrides.date ?? '2026-01-02',
    amount: overrides.amount ?? '12.34',
    status: overrides.status ?? 'completed',
    merchant_name: overrides.merchant_name ?? 'Acme Inc',
    payment_method: overrides.payment_method ?? 'Visa •••• 4242',
  };
}

function computeTotalPages(totalCount: number, pageSize: number) {
  if (!totalCount || totalCount <= 0 || pageSize <= 0) return 0;
  return Math.ceil(totalCount / pageSize);
}

function normalizePagePayload(payload: PageChangePayload) {
  if (typeof payload.page === 'number') return payload.page;
  if (typeof payload.current_page === 'number') return payload.current_page;
  throw new Error('Unsupported page-change payload shape');
}

function normalizePageSizePayload(payload: PageSizeChangePayload) {
  const pageSize = payload.page_size;
  const page = typeof payload.page === 'number' ? payload.page : typeof payload.current_page === 'number' ? payload.current_page : 1;
  return { page_size: pageSize, page };
}

/**
 * Composed root-workflow harness:
 * Simulates a parent container that owns server-driven state and refetch lifecycle.
 * TransactionTable is the root component under test.
 */
function renderWorkflow(options?: {
  initial?: {
    total_count?: number;
    current_page?: number;
    page_size?: 25 | 50 | 100;
    sort_key?: SortKey;
    sort_direction?: 'asc' | 'desc';
    transactions?: TransactionRow[];
  };
  dataset?: {
    byKey?: (args: {
      page: number;
      pageSize: 25 | 50 | 100;
      sortKey: SortKey;
      sortDirection: 'asc' | 'desc';
    }) => { transactions: TransactionRow[]; total_count: number };
  };
  initialLoad?: {
    fail?: boolean;
  };
  retryThenSucceed?: boolean;
}) {
  const defaultTotal = options?.initial?.total_count ?? 60;
  const defaultPageSize = options?.initial?.page_size ?? 25;
  const defaultSortKey = options?.initial?.sort_key ?? 'date';
  const defaultSortDirection = options?.initial?.sort_direction ?? 'desc';

  const baseDataset = {
    byKey:
      options?.dataset?.byKey ??
      ((args: { page: number; pageSize: 25 | 50 | 100; sortKey: SortKey; sortDirection: 'asc' | 'desc' }) => {
        const total_count = defaultTotal;
        const start = (args.page - 1) * args.pageSize;
        const n = Math.min(args.pageSize, Math.max(0, total_count - start));
        const transactions = Array.from({ length: n }, (_, i) => {
          const idx = start + i + 1;
          return mkTxn({
            id: `t_${idx}`,
            date: `2026-01-${String(Math.min(28, (idx % 28) + 1)).padStart(2, '0')}`,
            amount: String((idx * 3.14).toFixed(2)),
            status: idx % 4 === 0 ? 'failed' : idx % 4 === 1 ? 'pending' : idx % 4 === 2 ? 'completed' : 'refunded',
            merchant_name: idx === 1 ? 'Acme Inc' : idx === 2 ? 'Shop Co' : `Merchant ${idx}`,
            payment_method: idx % 2 === 0 ? 'Mastercard •••• 4444' : 'Visa •••• 4242',
          });
        });
        return { transactions, total_count };
      }),
  };

  const calls = {
    sortChange: jest.fn(),
    pageChange: jest.fn(),
    pageSizeChange: jest.fn(),
    openDetails: jest.fn(),
    retry: jest.fn(),
  };

  function Workflow() {
    const [sortKey, setSortKey] = React.useState<SortKey>(defaultSortKey);
    const [sortDirection, setSortDirection] = React.useState<'asc' | 'desc'>(defaultSortDirection);
    const [page, setPage] = React.useState<number>(options?.initial?.current_page ?? 1);
    const [pageSize, setPageSize] = React.useState<25 | 50 | 100>(defaultPageSize);

    const [transactions, setTransactions] = React.useState<TransactionRow[]>(options?.initial?.transactions ?? []);
    const [totalCount, setTotalCount] = React.useState<number>(options?.initial?.total_count ?? defaultTotal);

    const [isInitialLoading, setIsInitialLoading] = React.useState<boolean>(true);
    const [isFetching, setIsFetching] = React.useState<boolean>(false);
    const [hasError, setHasError] = React.useState<boolean>(false);
    const [errorMessage, setErrorMessage] = React.useState<string | undefined>(undefined);

    const retryBudgetRef = React.useRef<number>(options?.retryThenSucceed ? 1 : 0);

    const doFetch = React.useCallback(
      async (kind: 'initial' | 'refetch') => {
        const shouldFailInitial = !!options?.initialLoad?.fail;

        if (kind === 'initial') {
          setIsInitialLoading(true);
        } else {
          setIsFetching(true);
        }

        setHasError(false);
        setErrorMessage(undefined);

        await Promise.resolve();

        const shouldFail =
          kind === 'initial'
            ? shouldFailInitial
            : false;

        const shouldFailBecauseRetryBudget = kind !== 'initial' && hasError && retryBudgetRef.current <= 0;
        void shouldFailBecauseRetryBudget;

        if (shouldFail) {
          setHasError(true);
          setErrorMessage(undefined);
          setIsInitialLoading(false);
          setIsFetching(false);
          return;
        }

        const result = baseDataset.byKey({ page, pageSize, sortKey, sortDirection });
        setTransactions(result.transactions);
        setTotalCount(result.total_count);

        setIsInitialLoading(false);
        setIsFetching(false);
      },
      [baseDataset, options?.initialLoad?.fail, page, pageSize, sortKey, sortDirection, hasError]
    );

    React.useEffect(() => {
      void doFetch('initial');
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const onSortChange = (payload: SortChangePayload) => {
      calls.sortChange(payload);
      setSortKey(payload.sort_key);
      setSortDirection(payload.sort_direction);
      void doFetch('refetch');
    };

    const onPageChange = (payload: PageChangePayload) => {
      calls.pageChange(payload);
      const nextPage = normalizePagePayload(payload);
      setPage(nextPage);
      void doFetch('refetch');
    };

    const onPageSizeChange = (payload: PageSizeChangePayload) => {
      calls.pageSizeChange(payload);
      const normalized = normalizePageSizePayload(payload);
      setPageSize(normalized.page_size);
      setPage(1);
      void doFetch('refetch');
    };

    const onOpenDetails = (payload: any) => {
      calls.openDetails(payload);
    };

    const onRetry = () => {
      calls.retry();
      if (retryBudgetRef.current > 0) retryBudgetRef.current -= 1;
      // When initialLoad.fail is true, retry is expected to succeed.
      // Simulate success by turning off the failing condition.
      if (options?.initialLoad?.fail) {
        (options.initialLoad as any).fail = false;
      }
      void doFetch('refetch');
    };

    return (
      <TransactionTable
        transactions={transactions}
        total_count={totalCount}
        is_initial_loading={isInitialLoading}
        is_fetching={isFetching}
        has_error={hasError}
        error_message={errorMessage}
        current_page={page}
        page_size={pageSize}
        sort_key={sortKey as any}
        sort_direction={sortDirection}
        on_sort_change={onSortChange as any}
        on_page_change={onPageChange as any}
        on_page_size_change={onPageSizeChange as any}
        on_open_details={onOpenDetails as any}
        on_retry={onRetry}
      />
    );
  }

  const user = userEvent.setup();
  const view = render(<Workflow />);

  return {
    user,
    ...view,
    calls,
    getTotalPages: () => computeTotalPages(defaultTotal, defaultPageSize),
  };
}

async function flushMicrotasks() {
  await act(async () => {
    await Promise.resolve();
  });
}

describe('TransactionTable composed root workflow (e2e)', () => {
  test('open_transaction_details_shortest: loads then row click opens details payload', async () => {
    const { user, calls } = renderWorkflow({
      initial: { total_count: 2, page_size: 25 },
      dataset: {
        byKey: () => ({
          total_count: 2,
          transactions: [
            mkTxn({ id: 't_row', merchant_name: 'Row Merchant', date: '2026-02-10', status: 'completed' }),
            mkTxn({ id: 't_row2', merchant_name: 'Other Merchant', date: '2026-02-11', status: 'pending' }),
          ],
        }),
      },
    });

    await flushMicrotasks();

    const merchantCell = await screen.findByText('Row Merchant');
    const tr = merchantCell.closest('tr');
    expect(tr).toBeTruthy();

    await user.click(tr as HTMLElement);

    expect(calls.openDetails).toHaveBeenCalledTimes(1);
    expect(calls.openDetails).toHaveBeenLastCalledWith(expect.objectContaining({ id: 't_row' }));
  });

  test('browse_sort_paginate_then_open_details: sort toggles, page size change resets page, paginate, verify badge label, keyboard open details', async () => {
    const total_count = 60;
    const { user, calls } = renderWorkflow({
      initial: { total_count, page_size: 25, current_page: 1, sort_key: 'date', sort_direction: 'desc' },
      dataset: {
        byKey: ({ page, pageSize, sortKey, sortDirection }) => {
          const start = (page - 1) * pageSize;
          const n = Math.min(pageSize, Math.max(0, total_count - start));
          const transactions = Array.from({ length: n }, (_, i) => {
            const idx = start + i + 1;
            return mkTxn({
              id: `t_${sortKey}_${sortDirection}_${page}_${idx}`,
              merchant_name: idx === 3 ? 'Detail Shop' : `Merchant ${idx}`,
              date: idx === 3 ? '2026-03-01' : `2026-01-${String((idx % 28) + 1).padStart(2, '0')}`,
              status: idx === 5 ? 'chargeback' : idx % 4 === 0 ? 'failed' : idx % 4 === 1 ? 'pending' : idx % 4 === 2 ? 'completed' : 'refunded',
            });
          });
          return { transactions, total_count };
        },
      },
    });

    await flushMicrotasks();

    // Sort by Amount asc
    const amountBtn = screen.getByRole('button', { name: /sort by amount/i });
    await user.click(amountBtn);
    expect(calls.sortChange).toHaveBeenCalled();

    // During fetch, controls should be disabled (interaction lock)
    expect(screen.getByRole('button', { name: /sort by amount/i })).toBeDisabled();

    await flushMicrotasks();

    // Active header cell should reflect aria-sort
    const amountTh = screen.getByRole('button', { name: /sort by amount/i }).closest('th');
    expect(amountTh).toHaveAttribute('aria-sort', 'ascending');

    // Toggle Amount desc
    await user.click(screen.getByRole('button', { name: /sort by amount/i }));
    await flushMicrotasks();

    const amountTh2 = screen.getByRole('button', { name: /sort by amount/i }).closest('th');
    expect(amountTh2).toHaveAttribute('aria-sort', 'descending');

    // Change page size to 50; page should reset to 1
    const rowsPerPage = screen.getByLabelText(/rows per page/i);
    await user.selectOptions(rowsPerPage, '50');
    await flushMicrotasks();

    // Pagination text should announce current page state (component provides aria-live)
    expect(screen.getByText(/page\s+1\s+of\s+2/i)).toBeInTheDocument();

    // Next page
    const next = screen.getByRole('button', { name: /next page/i });
    await user.click(next);

    // Immediately attempt to click Next again while fetching; should be disabled and not emit second page-change
    const callsBefore = calls.pageChange.mock.calls.length;
    const nextDuringFetch = screen.getByRole('button', { name: /next page/i });
    expect(nextDuringFetch).toBeDisabled();
    await user.click(nextDuringFetch);
    expect(calls.pageChange.mock.calls.length).toBe(callsBefore + 1);

    await flushMicrotasks();

    // Status badge label should show text; include unknown fallback when present
    // We only assert that some status label text exists in the rendered table.
    const statusColumnTextCandidates = ['Pending', 'Completed', 'Failed', 'Refunded', 'Unknown'];
    const anyStatusText = statusColumnTextCandidates.some((t) => screen.queryByText(new RegExp(`^${t}$`, 'i')));
    expect(anyStatusText).toBe(true);

    // Keyboard open details
    const detailsBtn = screen.getByRole('button', { name: /view details/i });
    detailsBtn.focus();
    expect(detailsBtn).toHaveFocus();
    await user.keyboard('{Enter}');
    expect(calls.openDetails).toHaveBeenCalled();
  });

  test('invalid_double_paginate_during_loading: second paginate action blocked during fetch, then allowed after fetch completes', async () => {
    const { user, calls } = renderWorkflow({
      initial: { total_count: 60, page_size: 25, current_page: 1 },
    });

    await flushMicrotasks();

    const next = screen.getByRole('button', { name: /next page/i });
    await user.click(next);

    // Second click should be blocked while fetching
    const nextDisabled = screen.getByRole('button', { name: /next page/i });
    expect(nextDisabled).toBeDisabled();

    const before = calls.pageChange.mock.calls.length;
