reload state: sortable headers emit sort-change payloads; parent updates sort props; table reflects aria-sort and disables header/pagination while fetching","Composed pagination->fetching reload state: pagination controls emit page-change and page-size-change payloads; parent updates paging props; pagination boundary states and aria-live page text update after refetch","Row-level details opening via pointer row-click and keyboard-accessible per-row "View details" control; callback payload wiring to parent handler","Error recovery integration: error state shows retry; retry triggers handler; parent re-attempts and then renders rows and pagination again","Unhappy invalid action prevention: attempting to paginate during in-flight fetch is blocked by disabled controls and does not emit additional callbacks","Status badge label is present in composed rows, including unknown-status fallback label"],"coveredComponentCodes":["transaction_table","transaction_pagination","transaction_status_badge"],"coveredFlowCodes":["open_transaction_details_shortest","browse_sort_paginate_then_open_details","invalid_double_paginate_during_loading","error_then_retry_load_transactions"],"coveredStates":["Loaded with rows","Reload fetching (overlay/disabled controls)","Error state (default message + retry)","Recovered loaded state after retry","Sort state (active aria-sort ascending/descending)","Pagination state (page X of Y, boundary disabled/enabled)"],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.e2e.spec.tsx","content":"import React from 'react';
import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: string;
  merchant_name: string;
  payment_method: string;
};

type SortKey = string;

type SortChangePayload = { sort_key: SortKey; sort_direction: 'asc' | 'desc' };

type PageChangePayload = { page?: number; current_page?: number };

type PageSizeChangePayload = { page_size: 25 | 50 | 100; page?: number; current_page?: number };

function mkTxn(overrides: Partial<TransactionRow> = {}): TransactionRow {
  return {
    id: overrides.id ?? 't_1',
    date: overrides.date ?? '2026-01-02',
    amount: overrides.amount ?? '12.34',
    status: overrides.status ?? 'completed',
    merchant_name: overrides.merchant_name ?? 'Acme Inc',
    payment_method: overrides.payment_method ?? 'Visa •••• 4242',
  };
}

function computeTotalPages(totalCount: number, pageSize: number) {
  if (!totalCount || totalCount <= 0 || pageSize <= 0) return 0;
  return Math.ceil(totalCount / pageSize);
}

function normalizePagePayload(payload: PageChangePayload) {
  if (typeof payload.page === 'number') return payload.page;
  if (typeof payload.current_page === 'number') return payload.current_page;
  throw new Error('Unsupported page-change payload shape');
}

function normalizePageSizePayload(payload: PageSizeChangePayload) {
  const pageSize = payload.page_size;
  const page = typeof payload.page === 'number' ? payload.page : typeof payload.current_page === 'number' ? payload.current_page : 1;
  return { page_size: pageSize, page };
}

/**
 * Composed root-workflow harness:
 * Simulates a parent container that owns server-driven state and refetch lifecycle.
 * TransactionTable is the root component under test.
 */
function renderWorkflow(options?: {
  initial?: {
    total_count?: number;
    current_page?: number;
    page_size?: 25 | 50 | 100;
    sort_key?: SortKey;
    sort_direction?: 'asc' | 'desc';
    transactions?: TransactionRow[];
  };
  dataset?: {
    byKey?: (args: {
      page: number;
      pageSize: 25 | 50 | 100;
      sortKey: SortKey;
      sortDirection: 'asc' | 'desc';
    }) => { transactions: TransactionRow[]; total_count: number };
  };
  initialLoad?: {
    fail?: boolean;
  };
  retryThenSucceed?: boolean;
}) {
  const defaultTotal = options?.initial?.total_count ?? 60;
  const defaultPageSize = options?.initial?.page_size ?? 25;
  const defaultSortKey = options?.initial?.sort_key ?? 'date';
  const defaultSortDirection = options?.initial?.sort_direction ?? 'desc';

  const baseDataset = {
    byKey:
      options?.dataset?.byKey ??
      ((args: { page: number; pageSize: 25 | 50 | 100; sortKey: SortKey; sortDirection: 'asc' | 'desc' }) => {
        const total_count = defaultTotal;
        const start = (args.page - 1) * args.pageSize;
        const n = Math.min(args.pageSize, Math.max(0, total_count - start));
        const transactions = Array.from({ length: n }, (_, i) => {
          const idx = start + i + 1;
          return mkTxn({
            id: `t_${idx}`,
            date: `2026-01-${String(Math.min(28, (idx % 28) + 1)).padStart(2, '0')}`,
            amount: String((idx * 3.14).toFixed(2)),
            status: idx % 4 === 0 ? 'failed' : idx % 4 === 1 ? 'pending' : idx % 4 === 2 ? 'completed' : 'refunded',
            merchant_name: idx === 1 ? 'Acme Inc' : idx === 2 ? 'Shop Co' : `Merchant ${idx}`,
            payment_method: idx % 2 === 0 ? 'Mastercard •••• 4444' : 'Visa •••• 4242',
          });
        });
        return { transactions, total_count };
      }),
  };

  const calls = {
    sortChange: jest.fn(),
    pageChange: jest.fn(),
    pageSizeChange: jest.fn(),
    openDetails: jest.fn(),
    retry: jest.fn(),
  };

  function Workflow() {
    const [sortKey, setSortKey] = React.useState<SortKey>(defaultSortKey);
    const [sortDirection, setSortDirection] = React.useState<'asc' | 'desc'>(defaultSortDirection);
    const [page, setPage] = React.useState<number>(options?.initial?.current_page ?? 1);
    const [pageSize, setPageSize] = React.useState<25 | 50 | 100>(defaultPageSize);

    const [transactions, setTransactions] = React.useState<TransactionRow[]>(options?.initial?.transactions ?? []);
    const [totalCount, setTotalCount] = React.useState<number>(options?.initial?.total_count ?? defaultTotal);

    const [isInitialLoading, setIsInitialLoading] = React.useState<boolean>(true);
    const [isFetching, setIsFetching] = React.useState<boolean>(false);
    const [hasError, setHasError] = React.useState<boolean>(false);
    const [errorMessage, setErrorMessage] = React.useState<string | undefined>(undefined);

    const retryBudgetRef = React.useRef<number>(options?.retryThenSucceed ? 1 : 0);

    const doFetch = React.useCallback(
      async (kind: 'initial' | 'refetch') => {
        const shouldFailInitial = !!options?.initialLoad?.fail;

        if (kind === 'initial') {
          setIsInitialLoading(true);
        } else {
          setIsFetching(true);
        }

        setHasError(false);
        setErrorMessage(undefined);

        await Promise.resolve();

        const shouldFail =
          kind === 'initial'
            ? shouldFailInitial
            : false;

        const shouldFailBecauseRetryBudget = kind !== 'initial' && hasError && retryBudgetRef.current <= 0;
        void shouldFailBecauseRetryBudget;

        if (shouldFail) {
          setHasError(true);
          setErrorMessage(undefined);
          setIsInitialLoading(false);
          setIsFetching(false);
          return;
        }

        const result = baseDataset.byKey({ page, pageSize, sortKey, sortDirection });
        setTransactions(result.transactions);
        setTotalCount(result.total_count);

        setIsInitialLoading(false);
        setIsFetching(false);
      },
      [baseDataset, options?.initialLoad?.fail, page, pageSize, sortKey, sortDirection, hasError]
    );

    React.useEffect(() => {
      void doFetch('initial');
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const onSortChange = (payload: SortChangePayload) => {
      calls.sortChange(payload);
      setSortKey(payload.sort_key);
      setSortDirection(payload.sort_direction);
      void doFetch('refetch');
    };

    const onPageChange = (payload: PageChangePayload) => {
      calls.pageChange(payload);
      const nextPage = normalizePagePayload(payload);
      setPage(nextPage);
      void doFetch('refetch');
    };

    const onPageSizeChange = (payload: PageSizeChangePayload) => {
      calls.pageSizeChange(payload);
      const normalized = normalizePageSizePayload(payload);
      setPageSize(normalized.page_size);
      setPage(1);
      void doFetch('refetch');
    };

    const onOpenDetails = (payload: any) => {
      calls.openDetails(payload);
    };

    const onRetry = () => {
      calls.retry();
      if (retryBudgetRef.current > 0) retryBudgetRef.current -= 1;
      // When initialLoad.fail is true, retry is expected to succeed.
      // Simulate success by turning off the failing condition.
      if (options?.initialLoad?.fail) {
        (options.initialLoad as any).fail = false;
      }
      void doFetch('refetch');
    };

    return (
      <TransactionTable
        transactions={transactions}
        total_count={totalCount}
        is_initial_loading={isInitialLoading}
        is_fetching={isFetching}
        has_error={hasError}
        error_message={errorMessage}
        current_page={page}
        page_size={pageSize}
        sort_key={sortKey as any}
        sort_direction={sortDirection}
        on_sort_change={onSortChange as any}
        on_page_change={onPageChange as any}
        on_page_size_change={onPageSizeChange as any}
        on_open_details={onOpenDetails as any}
        on_retry={onRetry}
      />
    );
  }

  const user = userEvent.setup();
  const view = render(<Workflow />);

  return {
    user,
    ...view,
    calls,
    getTotalPages: () => computeTotalPages(defaultTotal, defaultPageSize),
  };
}

async function flushMicrotasks() {
  await act(async () => {
    await Promise.resolve();
  });
}

describe('TransactionTable composed root workflow (e2e)', () => {
  test('open_transaction_details_shortest: loads then row click opens details payload', async () => {
    const { user, calls } = renderWorkflow({
      initial: { total_count: 2, page_size: 25 },
      dataset: {
        byKey: () => ({
          total_count: 2,
          transactions: [
            mkTxn({ id: 't_row', merchant_name: 'Row Merchant', date: '2026-02-10', status: 'completed' }),
            mkTxn({ id: 't_row2', merchant_name: 'Other Merchant', date: '2026-02-11', status: 'pending' }),
          ],
        }),
      },
    });

    await flushMicrotasks();

    const merchantCell = await screen.findByText('Row Merchant');
    const tr = merchantCell.closest('tr');
    expect(tr).toBeTruthy();

    await user.click(tr as HTMLElement);

    expect(calls.openDetails).toHaveBeenCalledTimes(1);
    expect(calls.openDetails).toHaveBeenLastCalledWith(expect.objectContaining({ id: 't_row' }));
  });

  test('browse_sort_paginate_then_open_details: sort toggles, page size change resets page, paginate, verify badge label, keyboard open details', async () => {
    const total_count = 60;
    const { user, calls } = renderWorkflow({
      initial: { total_count, page_size: 25, current_page: 1, sort_key: 'date', sort_direction: 'desc' },
      dataset: {
        byKey: ({ page, pageSize, sortKey, sortDirection }) => {
          const start = (page - 1) * pageSize;
          const n = Math.min(pageSize, Math.max(0, total_count - start));
          const transactions = Array.from({ length: n }, (_, i) => {
            const idx = start + i + 1;
            return mkTxn({
              id: `t_${sortKey}_${sortDirection}_${page}_${idx}`,
              merchant_name: idx === 3 ? 'Detail Shop' : `Merchant ${idx}`,
              date: idx === 3 ? '2026-03-01' : `2026-01-${String((idx % 28) + 1).padStart(2, '0')}`,
              status: idx === 5 ? 'chargeback' : idx % 4 === 0 ? 'failed' : idx % 4 === 1 ? 'pending' : idx % 4 === 2 ? 'completed' : 'refunded',
            });
          });
          return { transactions, total_count };
        },
      },
    });

    await flushMicrotasks();

    // Sort by Amount asc
    const amountBtn = screen.getByRole('button', { name: /sort by amount/i });
    await user.click(amountBtn);
    expect(calls.sortChange).toHaveBeenCalled();

    // During fetch, controls should be disabled (interaction lock)
    expect(screen.getByRole('button', { name: /sort by amount/i })).toBeDisabled();

    await flushMicrotasks();

    // Active header cell should reflect aria-sort
    const amountTh = screen.getByRole('button', { name: /sort by amount/i }).closest('th');
    expect(amountTh).toHaveAttribute('aria-sort', 'ascending');

    // Toggle Amount desc
    await user.click(screen.getByRole('button', { name: /sort by amount/i }));
    await flushMicrotasks();

    const amountTh2 = screen.getByRole('button', { name: /sort by amount/i }).closest('th');
    expect(amountTh2).toHaveAttribute('aria-sort', 'descending');

    // Change page size to 50; page should reset to 1
    const rowsPerPage = screen.getByLabelText(/rows per page/i);
    await user.selectOptions(rowsPerPage, '50');
    await flushMicrotasks();

    // Pagination text should announce current page state (component provides aria-live)
    expect(screen.getByText(/page\s+1\s+of\s+2/i)).toBeInTheDocument();

    // Next page
    const next = screen.getByRole('button', { name: /next page/i });
    await user.click(next);

    // Immediately attempt to click Next again while fetching; should be disabled and not emit second page-change
    const callsBefore = calls.pageChange.mock.calls.length;
    const nextDuringFetch = screen.getByRole('button', { name: /next page/i });
    expect(nextDuringFetch).toBeDisabled();
    await user.click(nextDuringFetch);
    expect(calls.pageChange.mock.calls.length).toBe(callsBefore + 1);

    await flushMicrotasks();

    // Status badge label should show text; include unknown fallback when present
    // We only assert that some status label text exists in the rendered table.
    const statusColumnTextCandidates = ['Pending', 'Completed', 'Failed', 'Refunded', 'Unknown'];
    const anyStatusText = statusColumnTextCandidates.some((t) => screen.queryByText(new RegExp(`^${t}$`, 'i')));
    expect(anyStatusText).toBe(true);

    // Keyboard open details
    const detailsBtn = screen.getByRole('button', { name: /view details/i });
    detailsBtn.focus();
    expect(detailsBtn).toHaveFocus();
    await user.keyboard('{Enter}');
    expect(calls.openDetails).toHaveBeenCalled();
  });

  test('invalid_double_paginate_during_loading: second paginate action blocked during fetch, then allowed after fetch completes', async () => {
    const { user, calls } = renderWorkflow({
      initial: { total_count: 60, page_size: 25, current_page: 1 },
    });

    await flushMicrotasks();

    const next = screen.getByRole('button', { name: /next page/i });
    await user.click(next);

    // Second click should be blocked while fetching
    const nextDisabled = screen.getByRole('button', { name: /next page/i });
    expect(nextDisabled).toBeDisabled();

    const before = calls.pageChange.mock.calls.length;
    await user.click(nextDisabled);
    expect(calls.pageChange.mock.calls.length).toBe(before);

    await flushMicrotasks();

    // After load completes, next should be enabled again (not last page in this dataset)
    const nextAfter = screen.getByRole('button', { name: /next page/i });
    expect(nextAfter).toBeEnabled();

    await user.click(nextAfter);
    expect(calls.pageChange.mock.calls.length).toBe(before + 1);
  });

  test('error_then_retry_load_transactions: initial fetch fails, error shown with Retry, retry succeeds and rows render', async () => {
    const initialLoad = { fail: true };
    const { user, calls } = renderWorkflow({
      initial: { total_count: 2, page_size: 25, current_page: 1 },
      initialLoad,
      dataset: {
        byKey: () => ({
          total_count: 2,
          transactions: [
            mkTxn({ id: 't_ok_1', merchant_name: 'Recovered Merchant', date: '2026-04-01', status: 'completed' }),
            mkTxn({ id: 't_ok_2', merchant_name: 'Recovered Merchant 2', date: '2026-04-02', status: 'refunded' }),
          ],
        }),
      },
    });

    await flushMicrotasks();

    // Error state
    expect(await screen.findByText(/unable to load transactions\./i)).toBeInTheDocument();

    const retryBtn = screen.getByRole('button', { name: /retry/i });
    await user.click(retryBtn);
    expect(calls.retry).toHaveBeenCalledTimes(1);

    await flushMicrotasks();

    // Recovered rows
    expect(await screen.findByText('Recovered Merchant')).toBeInTheDocument();

    // Pagination appears when total_count > 0
    expect(screen.getByText(/page\s+1\s+of\s+1/i)).toBeInTheDocument();

    // Default sort reflected (Date desc per resolving-gaps decision); verify active header cell has aria-sort="descending" on Date.
    const dateTh = screen.getByRole('button', { name: /sort by date/i }).closest('th');
    expect(dateTh).toHaveAttribute('aria-sort', 'descending');
  });
});
"}],"rootComponentCode":"transaction_table","rootComponentName":"Transaction Table"},"framework":"React","gapAnalysis":{"accessibilityGaps":["Sorting controls are not specified as keyboard-operable header buttons with proper aria-sort and accessible names","Row-click interaction lacks keyboard equivalent (Enter/Space) and focusable row/interactive element semantics","Focus visible styling is not specified for sortable headers, rows, and pagination controls","Status badge relies on color but no non-color cue requirements (text already present, but contrast/forced-colors behavior not defined)","Pagination controls lack defined ARIA labels (e.g., next/previous, page size selector, current page announcement)"],"missingStates":["Table loading state (initial load and reloading on sort/paginate)","Table empty state when there are no transactions","Table error state when data fetch fails (and retry behavior)","Sorting state details: default sort column/direction, unsorted state, and sort direction indicator behavior","Row hover/active/selected state styling (especially for clickable rows)","Disabled/unavailable pagination states (first/prev disabled on first page; next/last disabled on last page)","Page size change behavior state: whether changing page size resets to page 1 and how selection is reflected","Unknown/unsupported status fallback state (if API returns a status outside pending/completed/failed/refunded)"],"recommendations":["Define sort UX spec: default sort, whether multi-sort is allowed, toggle order (none→asc→desc or asc↔desc), and header iconography","Implement sortable headers as buttons with aria-sort and screen-reader text indicating current sort column and direction","Make row navigation accessible by providing a dedicated 'View details' link/button in a cell or make the row a focusable element with Enter/Space activation and clear focus ring","Specify loading UX (skeleton vs spinner), including whether table keeps previous rows during resort/repaginate (stale-while-revalidate) and how interactions are disabled during loading","Add explicit empty and error render paths with actionable messaging and a retry control","Define pagination model precisely: total count availability, total pages calculation, current page display format, and behavior when total changes","Specify status badge design tokens beyond color (text color, background, border, contrast targets, forced-colors/high-contrast handling) and a fallback styling for unknown statuses","Document interactive state styles (hover/pressed/selected) for rows, header buttons, and pagination elements to ensure consistent implementation"],"responsiveGaps":["No rules for handling narrow viewports: whether columns wrap, truncate with ellipsis, or collapse into a stacked/card layout","No priority order for hiding/reordering columns on small screens (e.g., payment method vs merchant name)","No specification for horizontal scrolling vs responsive reflow when all 5 columns do not fit","No guidance on long content overflow (merchant names, payment method strings) and max widths per column","Pagination placement and layout on mobile (stacking page size selector and navigation, touch target sizing) are not defined"]},"parsing":{"businessContext":"Display and browse transactions in a tabular view with sortable columns, paginated results, status badges, and row-level access to transaction details.","components":[{"code":"transaction_table","name":"Transaction Table","parentCode":null,"purpose":"Present a list of transactions with sortable columns, pagination, status badges, and row interaction to open details.","statePolicy":"smart","type":"table"},{"code":"transaction_status_badge","name":"Transaction Status Badge","parentCode":"transaction_table","purpose":"Render the transaction status as a colored badge for each row.","statePolicy":"dumb","type":"badge"},{"code":"transaction_pagination","name":"Transaction Pagination","parentCode":"transaction_table","purpose":"Control paging through the transaction list and selecting page size.","statePolicy":"smart","type":"pagination"}],"constraints":[{"componentCode":"transaction_table","description":"Supports sorting by any column.","type":"sorting"},{"componentCode":"transaction_table","description":"Supports pagination with page sizes 25, 50, or 100 items per page.","type":"pagination"},{"componentCode":"transaction_status_badge","description":"Allowed status values: pending, completed, failed, refunded.","type":"state"}],"content":[{"code":"col_date","componentCode":"transaction_table","description":"Transaction date column.","kind":"column","name":"Date","isRequired":true},{"code":"col_amount","componentCode":"transaction_table","description":"Transaction amount column.","kind":"column","name":"Amount","isRequired":true},{"code":"col_status","componentCode":"transaction_table","description":"Transaction status column rendered with a colored badge.","kind":"column","name":"Status","isRequired":true},{"code":"col_merchant_name","componentCode":"transaction_table","description":"Merchant name column.","kind":"column","name":"Merchant Name","isRequired":true},{"code":"col_payment_method","componentCode":"transaction_table","description":"Payment method column.","kind":"column","name":"Payment Method","isRequired":true},{"code":"status_pending","componentCode":"transaction_status_badge","description":"Pending transaction status.","kind":"status","name":"Pending","isRequired":true},{"code":"status_completed","componentCode":"transaction_status_badge","description":"Completed transaction status.","kind":"status","name":"Completed","isRequired":true},{"code":"status_failed","componentCode":"transaction_status_badge","description":"Failed transaction status.","kind":"status","name":"Failed","isRequired":true},{"code":"status_refunded","componentCode":"transaction_status_badge","description":"Refunded transaction status.","kind":"status","name":"Refunded","isRequired":true}],"interactions":[{"code":"sort_by_column","componentCode":"transaction_table","description":"User sorts the table by any column.","targetComponentCode":null,"type":"sort"},{"code":"paginate_transactions","componentCode":"transaction_pagination","description":"User paginates through the transaction list and can change page size to 25/50/100.","targetComponentCode":"transaction_table","type":"paginate"},{"code":"open_transaction_details","componentCode":"transaction_table","description":"Clicking a row opens transaction details.","targetComponentCode":null,"type":"open_details"}],"rootComponentCode":"transaction_table","specifiedStates":[{"code":"state_pending","componentCode":"transaction_status_badge","description":"Badge displays pending status styling.","isExplicit":true,"name":"Pending"},{"code":"state_completed","componentCode":"transaction_status_badge","description":"Badge displays completed status styling.","isExplicit":true,"name":"Completed"},{"code":"state_failed","componentCode":"transaction_status_badge","description":"Badge displays failed status styling.","isExplicit":true,"name":"Failed"},{"code":"state_refunded","componentCode":"transaction_status_badge","description":"Badge displays refunded status styling.","isExplicit":true,"name":"Refunded"}],"tokenReferences":[{"componentCode":"transaction_status_badge","description":"Status-to-color mapping for the badge (pending/completed/failed/refunded).","name":"status color","type":"color"},{"componentCode":"transaction_status_badge","description":"Badge corner rounding.","name":"badge radius","type":"radius"},{"componentCode":"transaction_table","description":"Typography used for table header and cell text.","name":"table typography","type":"typography"},{"componentCode":"transaction_table","description":"Horizontal/vertical padding and row spacing for the table.","name":"table spacing","type":"spacing"}]},"projectRootPath":"/app/generated/frontend","relatedComponentInterfaces":[{"accepts":[{"description":"Transaction status value used to determine label and styling. Supported: "pending", "completed", "failed", "refunded". Any other value renders the neutral "Unknown" badge.","name":"status","required":true,"type":"string"}],"componentCode":"transaction_status_badge","componentName":"Transaction Status Badge","returns":[]}],"relatedComponentSourceFiles":[{"componentCode":"transaction_status_badge","filename":"/app/generated/frontend/src/components/TransactionStatusBadge/TransactionStatusBadge.tsx"}],"resolvingGaps":{"decisions":[{"affectedComponentCodes":["transaction_table"],"code":"sortable_headers_as_buttons_with_aria_sort","decision":"Implement each sortable column header as a <button type="button"> inside the <th>. The button accessible name is "Sort by {ColumnName}". Maintain sort state in the table as {sortKey, sortDirection}. Apply aria-sort to the <th> of the active sort column only: "ascending" or "descending"; all other headers have no aria-sort attribute. The header button shows a visual sort indicator (up/down chevron) and includes visually-hidden text that announces "sorted ascending/descending" for the active column.","rationale":"This makes sorting explicitly keyboard-operable and screen-reader discoverable using standard table semantics with aria-sort, while keeping the rest of the headers neutral. Using a button in the header is the most conservative, widely supported pattern for interactive sorting.","sourceGap":"Sorting controls are not specified as keyboard-operable header buttons with proper aria-sort and accessible names"},{"affectedComponentCodes":["transaction_table"],"code":"sort_state_defaults_and_toggle_behavior","decision":"Default sort is Date descending on initial render. Sorting is single-column only (no multi-sort). Clicking/activating a header toggles direction between ascending and descending for that column; selecting a different column sets that column to ascending on first activation. There is no unsorted state once data is shown.","rationale":"Defines deterministic sorting behavior needed for implementation and testing. Choosing a common default (most recent first) and a simple two-state toggle avoids ambiguous "none" state handling and multi-sort complexity.","sourceGap":"Sorting state details: default sort column/direction, unsorted state, and sort direction indicator behavior"},{"affectedComponentCodes":["transaction_table"],"code":"row_keyboard_access_via_dedicated_details_link","decision":"Do not make the entire <tr> focusable. Add a dedicated "View details" action as the last focusable element within each row (e.g., a <a> or <button>) with accessible name "View details for transaction {merchant} on {date}" (fallback to "View transaction details" if values missing). Mouse click anywhere on the row also triggers the same action, but keyboard access is provided via the dedicated control.","rationale":"Provides a clear, standard keyboard path without relying on nonstandard focusable row semantics, while preserving the brief’s row-click convenience for pointer users. This conservatively reduces accessibility risk and complexity.","sourceGap":"Row-click interaction lacks keyboard equivalent (Enter/Space) and focusable row/interactive element semantics"},{"affectedComponentCodes":["transaction_table","transaction_pagination"],"code":"focus_visible_styles_required","decision":"Apply a visible focus indicator to sortable header buttons, the per-row "View details" control, and all pagination controls using :focus-visible. The focus ring must be at least 2px and not removed; it must be visible against both header and body backgrounds.","rationale":"Explicitly defines focus-visible styling targets so downstream implementation and QA can verify keyboard navigation. Keeping the requirement generic (thickness/visibility) is conservative given missing design tokens.","sourceGap":"Focus visible styling is not specified for sortable headers, rows, and pagination controls"},{"affectedComponentCodes":["transaction_status_badge"],"code":"status_badge_non_color_and_forced_colors_behavior","decision":"Status badge must always render the status text label (Pending/Completed/Failed/Refunded) and never rely on color alone. In forced-colors/high-contrast mode, render the badge with a 1px solid border using currentColor and transparent background; ensure text remains visible (use CanvasText/currentColor). Maintain a minimum 4.5:1 contrast ratio for text against badge background in normal mode.","rationale":"Resolves the non-color cue and high-contrast ambiguity with a standard, testable approach that works across themes and forced-colors modes while preserving the existing text cue.","sourceGap":"Status badge relies on color but no non-color cue requirements (text already present, but contrast/forced-colors behavior not defined)"},{"affectedComponentCodes":["transaction_status_badge"],"code":"unknown_status_fallback_badge","decision":"If the API returns a status outside pending/completed/failed/refunded, render a neutral badge labeled "Unknown" using the same badge shape and typography, with a gray/neutral styling distinct from the known statuses.","rationale":"Prevents rendering failures and ensures consistent UI when backend expands statuses. Using a neutral "Unknown" is conservative and avoids misrepresenting the status.","sourceGap":"Unknown/unsupported status fallback state (if API returns a status outside pending/completed/failed/refunded)"},{"affectedComponentCodes":["transaction_table"],"code":"loading_state_skeleton_and_interaction_lock","decision":"Provide a loading state: on initial load, render a table skeleton with header visible and 10 placeholder rows. On sort or pagination changes, keep existing rows visible and show an inline loading overlay (or row-level skeleton) while fetching; disable header sort buttons and pagination controls during the fetch to prevent concurrent requests.","rationale":"Defines both initial and reloading behaviors and avoids flicker by keeping prior content while updating. Disabling interactions during fetch is conservative and simplifies state management and testing.","sourceGap":"Table loading state (initial load and reloading on sort/paginate)"},{"affectedComponentCodes":["transaction_table"],"code":"empty_state_rendering","decision":"If there are zero transactions after loading completes, render an empty state in the table body area that spans all columns with message: "No transactions to display." Keep the table header visible and keep pagination hidden/disabled when total count is 0.","rationale":"Provides a clear, minimal empty state without inventing filtering or onboarding content. Keeping headers visible maintains context and reduces layout shift.","sourceGap":"Table empty state when there are no transactions"},{"affectedComponentCodes":["transaction_table"],"code":"error_state_with_retry","decision":"If data fetch fails, render an error state in the table body area spanning all columns with message: "Unable to load transactions." Provide a "Retry" button that re-attempts the last request (same sort/page/pageSize).","rationale":"Defines an actionable error path and a deterministic retry behavior needed for implementation and automated tests, without adding extra recovery flows.","sourceGap":"Table error state when data fetch fails (and retry behavior)"},{"affectedComponentCodes":["transaction_table"],"code":"row_interactive_hover_pressed_styles","decision":"For pointer users, rows show hover styling (subtle background change) indicating clickability. When the row’s "View details" control is active/pressed, show a pressed state on that control (not on the entire row). No persistent "selected" row state is used in the table.","rationale":"Resolves ambiguity around hover/active/selected states while avoiding introducing a selection model not mentioned in the brief.","sourceGap":"Row hover/active/selected state styling (especially for clickable rows)"},{"affectedComponentCodes":["transaction_pagination"],"code":"pagination_model_and_total_count_requirement","decision":"Pagination is server-driven and requires totalCount from the data source. Compute totalPages = ceil(totalCount / pageSize). Display current page as "Page X of Y". If totalCount changes and the current page exceeds totalPages, clamp current page to totalPages and refetch.","rationale":"Defines a precise, testable pagination model and handles dynamic totals conservatively by clamping to the last valid page instead of erroring or showing empty pages unexpectedly.","sourceGap":"Define pagination model precisely: total count availability, total pages calculation, current page display format, and behavior when total changes"},{"affectedComponentCodes":["transaction_pagination"],"code":"pagination_controls_disabled_states","decision":"Provide First/Previous/Next/Last controls. Disable First and Previous when currentPage == 1. Disable Next and Last when currentPage == totalPages or totalPages == 0. Disabled controls are not focusable and use aria-disabled only if rendered as non-button elements; prefer native disabled buttons.","rationale":"Explicitly defines boundary behavior and a conservative accessibility-friendly implementation using native disabled semantics.","sourceGap":"Disabled/unavailable pagination states (first/prev disabled on first page; next/last disabled on last page)"},{"affectedComponentCodes":["transaction_pagination"],"code":"page_size_change_resets_page","decision":"Page size selector offers 25, 50, 100. Changing page size resets currentPage to 1 and triggers a refetch with the current sort settings preserved. The selector reflects the active page size value.","rationale":"Resetting to page 1 is the most predictable behavior and avoids landing on an out-of-range page after a page size change.","sourceGap":"Page size change behavior state: whether changing page size resets to page 1 and how selection is reflected"},{"affectedComponentCodes":["transaction_pagination"],"code":"pagination_aria_labels_and_live_announcement","decision":"Add aria-labels: First="First page", Previous="Previous page", Next="Next page", Last="Last page". Page size select has label "Rows per page". Add an aria-live="polite" region that announces "Page {X} of {Y}" after pagination changes and "Sorted by {ColumnName} {Direction}" after sort changes.","rationale":"Resolves missing ARIA labeling and provides minimal announcements for state changes without overcomplicating the UI with verbose narration.","sourceGap":"Pagination controls lack defined ARIA labels (e.g., next/previous, page size selector, current page announcement)"},{"affectedComponentCodes":["transaction_table","transaction_pagination"],"code":"responsive_horizontal_scroll_and_column_overflow","decision":"On narrow viewports, keep the table layout (no card/stacked conversion) and enable horizontal scrolling by wrapping the table in an overflow-x:auto container. For Merchant Name and Payment Method cells, truncate with ellipsis (white-space: nowrap; overflow: hidden; text-overflow: ellipsis) and show full content via native title attribute. Date, Amount, and Status do not wrap. No columns are hidden or reordered responsively.","rationale":"Chooses the least disruptive responsive strategy consistent with a table component and avoids speculative column priority/hiding rules. Ellipsis + title is a conservative overflow solution requiring no additional components.","sourceGap":"No rules for handling narrow viewports: whether columns wrap, truncate with ellipsis, or collapse into a stacked/card layout"}]},"targetComponent":{"code":"transaction_table","name":"Transaction Table","parentCode":null,"purpose":"Present a list of transactions with sortable columns, pagination, status badges, and row interaction to open details.","statePolicy":"smart","type":"table"},"targetComponentInterface":{"accepts":[{"description":"Array of transactions to render in the table body (already fetched for the current sort/page/page_size). Each item should include: id, date, amount, status, merchant_name, payment_method.","name":"transactions","required":true,"type":"TransactionRow[]"},{"description":"Total number of transactions available on the server for the current query context; used to compute total pages.","name":"total_count","required":true,"type":"number"},{"description":"Whether the initial load is in progress; when true the table renders a skeleton with header visible and placeholder rows.","name":"is_initial_loading","required":true,"type":"boolean"},{"description":"Whether a reload fetch is in progress due to sort/pagination changes; when true, keep current rows visible, show loading overlay, and disable sort and pagination controls.","name":"is_fetching","required":true,"type":"boolean"},{"description":"Whether the table is in an error state for the last fetch attempt; when true, show the error row spanning all columns and a Retry button.","name":"has_error","required":true,"type":"boolean"},{"description":"Current error message to display when has_error is true. If omitted, component uses default copy: "Unable to load transactions."","name":"error_message","required":false,"type":"string"},{"description":"Current 1-based page index.","name":"current_page","required":true,"type":"number"},{"description":"Current page size; allowed values are 25, 50, or 100.","name":"page_size","required":true,"type":"25 | 50 | 100"},{"description":"Current single-column sort key.","name":"sort_key","required":true,"type":"TransactionSortKey"},{"description":"Current sort direction for sort_key.","name":"sort_direction","required":true,"type":""asc" | "desc""},{"description":"Callback invoked when the user activates a sortable header. If a different column is chosen, direction is set to asc; if the same column is chosen, direction toggles asc/desc.","name":"on_sort_change","required":true,"type":"(payload: SortChangePayload) => void"},{"description":"Callback invoked when the user changes pages via pagination controls (First/Previous/Next/Last).","name":"on_page_change","required":true,"type":"(payload: PageChangePayload) => void"},{"description":"Callback invoked when the user changes page size; caller should reset to page 1 and refetch while preserving current sort.","name":"on_page_size_change","required":true,"type":"(payload: PageSizeChangePayload) => void"},{"description":"Callback invoked when user triggers viewing details for a transaction, either by clicking the row or activating the per-row "View details" control.","name":"on_open_details","required":true,"type":"(payload: OpenTransactionDetailsPayload) => void"},{"description":"Callback invoked when the user clicks Retry in the error state; should re-attempt the last request using the same sort/page/page_size.","name":"on_retry","required":true,"type":"() => void"}],"componentCode":"transaction_table","componentName":"Transaction Table","returns":[{"description":"Emitted when user requests a sort change by activating a column header button.","name":"sort_change","required":true,"type":"SortChangePayload"},{"description":"Emitted when user requests a page change via pagination controls.","name":"page_change","required":true,"type":"PageChangePayload"},{"description":"Emitted when user requests a page size change (25/50/100); intended to reset to page 1.","name":"page_size_change","required":true,"type":"PageSizeChangePayload"},{"description":"Emitted when user requests to open transaction details for a specific row.","name":"open_details","required":true,"type":"OpenTransactionDetailsPayload"},{"description":"Emitted when user clicks the Retry button in the error state.","name":"retry","required":true,"type":"void"}]},"targetSourceFilePath":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.tsx","targetUnitTests":{"componentCode":"transaction_table","componentName":"Transaction Table","coveredBehaviors":["Renders table headers for Date/Amount/Status/Merchant Name/Payment Method with sortable header buttons named "Sort by {Column}"","Invokes on_sort_change with asc when a different column is chosen; toggles asc/desc when the same column is activated again","Applies aria-sort="ascending"/"descending" only to the active sorted column header cell","Initial loading: renders a skeleton/placeholder state while keeping the header visible","Fetching reload: keeps current rows visible while disabling sort buttons and pagination controls","Row click triggers on_open_details with the transaction payload/id","Per-row "View details" control triggers on_open_details and has an accessible name that includes merchant and date when available","Error state renders default copy when error_message is not provided and exposes a Retry button that calls on_retry","Empty state renders "No transactions to display." spanning all columns and hides/disables pagination when total_count is 0","Pagination wiring: forwards on_page_change from pagination controls and on_page_size_change from rows-per-page selector"],"coveredStates":["Initial loading (skeleton)","Loaded with rows","Reload fetching (overlay/disabled controls)","Error state (default message + retry)","Empty state (no transactions)"],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.spec.tsx","content":"import React from 'react';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

jest.mock('../TransactionPagination/TransactionPagination', () => {
  return {
    __esModule: true,
    TransactionPagination: ({
      current_page,
      total_count,
      page_size,
      is_loading,
      on_page_change,
      on_page_size_change,
    }: any) => {
      const totalPages = page_size > 0 ? Math.ceil((total_count ?? 0) / page_size) : 0;
      return (
        <div data-testid="pagination">
          <div aria-live="polite">Page {current_page} of {totalPages}</div>
          <button
            type="button"
            aria-label="First page"
            disabled={!!is_loading || current_page === 1 || totalPages === 0}
            onClick={() => on_page_change({ page: 1 })}
          >
            First
          </button>
          <button
            type="button"
            aria-label="Previous page"
            disabled={!!is_loading || current_page === 1 || totalPages === 0}
            onClick={() => on_page_change({ page: Math.max(1, current_page - 1) })}
          >
            Prev
          </button>
          <button
            type="button"
            aria-label="Next page"
            disabled={!!is_loading || current_page >= totalPages || totalPages === 0}
            onClick={() => on_page_change({ page: Math.min(totalPages, current_page + 1) })}
          >
            Next
          </button>
          <button
            type="button"
            aria-label="Last page"
            disabled={!!is_loading || current_page >= totalPages || totalPages === 0}
            onClick={() => on_page_change({ page: totalPages })}
          >
            Last
          </button>

          <label>
            Rows per page
            <select
              aria-label="Rows per page"
              disabled={!!is_loading}
              value={page_size}
              onChange={(e) => on_page_size_change({ page_size: Number(e.target.value), page: 1 })}
            >
              <option value={25}>25</option>
              <option value={50}>50</option>
              <option value={100}>100</option>
            </select>
          </label>
        </div>
      );
    },
  };
});

jest.mock('../TransactionStatusBadge/TransactionStatusBadge', () => {
  return {
    __esModule: true,
    TransactionStatusBadge: ({ status }: any) => (
      <span data-testid="status-badge">{String(status)}</span>
    ),
  };
});

type Txn = {
  id: string;
  date: string;
  amount: string | number;
  status: string;
  merchant_name: string;
  payment_method: string;
};

function makeTxn(overrides: Partial<Txn> = {}): Txn {
  return {
    id: overrides.id ?? 't_1',
    date: overrides.date ?? '2026-01-02',
    amount: overrides.amount ?? '12.34',
    status: overrides.status ?? 'completed',
    merchant_name: overrides.merchant_name ?? 'Acme Inc',
    payment_method: overrides.payment_method ?? 'Visa •••• 4242',
  };
}

function renderSubject(props?: Partial<React.ComponentProps<typeof TransactionTable>>) {
  const defaultProps: React.ComponentProps<typeof TransactionTable> = {
    transactions: [makeTxn({ id: 't_1' }), makeTxn({ id: 't_2', merchant_name: 'Shop Co', date: '2026-01-03' })],
    total_count: 52,
    is_initial_loading: false,
    is_fetching: false,
    has_error: false,
    error_message: undefined,
    current_page: 1,
    page_size: 25,
    sort_key: 'date' as any,
    sort_direction: 'desc',
    on_sort_change: jest.fn(),
    on_page_change: jest.fn(),
    on_page_size_change: jest.fn(),
    on_open_details: jest.fn(),
    on_retry: jest.fn(),
  };

  const merged = { ...defaultProps, ...props };
  const utils = render(<TransactionTable {...merged} />);
  return {
    ...utils,
    props: merged,
  };
}

describe('TransactionTable', () => {
  test('renders column headers and sortable header buttons with accessible names', () => {
    renderSubject();

    // Table semantics
    expect(screen.getByRole('table')).toBeInTheDocument();

    // Sort buttons per resolving-gaps decision
    expect(screen.getByRole('button', { name: /sort by date/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /sort by amount/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /sort by status/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /sort by merchant name/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /sort by payment method/i })).toBeInTheDocument();
  });

  test('applies aria-sort only to the active sort column header cell', () => {
    renderSubject({ sort_key: 'amount' as any, sort_direction: 'asc' });

    const amountSortButton = screen.getByRole('button', { name: /sort by amount/i });
    const th = amountSortButton.closest('th');
    expect(th).toHaveAttribute('aria-sort', 'ascending');

    const dateTh = screen.getByRole('button', { name: /sort by date/i }).closest('th');
    const statusTh = screen.getByRole('button', { name: /sort by status/i }).closest('th');

    // Only active column has aria-sort; others omit it
    expect(dateTh).not.toHaveAttribute('aria-sort');
    expect(statusTh).not.toHaveAttribute('aria-sort');
  });

  test('invokes on_sort_change: switching column sets asc, clicking same column toggles direction', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({ sort_key: 'date' as any, sort_direction: 'desc' });

    await user.click(screen.getByRole('button', { name: /sort by amount/i }));
    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
    expect(props.on_sort_change).toHaveBeenLastCalledWith(
      expect.objectContaining({ sort_key: 'amount', sort_direction: 'asc' })
    );

    // Re-render as if parent applied new sort
    const onSort = props.on_sort_change as jest.Mock;
    const last = onSort.mock.calls[onSort.mock.calls.length - 1][0];

    renderSubject({
      sort_key: last.sort_key,
      sort_direction: last.sort_direction,
      on_sort_change: props.on_sort_change,
    });

    await user.click(screen.getByRole('button', { name: /sort by amount/i }));
    expect(props.on_sort_change).toHaveBeenCalledTimes(2);
    expect(props.on_sort_change).toHaveBeenLastCalledWith(
      expect.objectContaining({ sort_key: 'amount', sort_direction: 'desc' })
    );
  });

  test('initial loading shows skeleton/placeholder rows while keeping header visible', () => {
    renderSubject({ is_initial_loading: true, transactions: [], total_count: 0 });

    // Header buttons still present during skeleton state
    expect(screen.getByRole('button', { name: /sort by date/i })).toBeInTheDocument();

    // We don't assume exact skeleton implementation; assert there is no "No transactions" empty state
    expect(screen.queryByText(/no transactions to display/i)).not.toBeInTheDocument();
  });

  test('fetching reload keeps existing rows visible and disables sort and pagination controls', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({ is_fetching: true });

    // Existing content remains visible
    expect(screen.getByText('Acme Inc')).toBeInTheDocument();

    // Sort buttons disabled while fetching
    expect(screen.getByRole('button', { name: /sort by date/i })).toBeDisabled();

    // Pagination disabled while fetching
    const pagination = screen.getByTestId('pagination');
    expect(within(pagination).getByRole('button', { name: /next page/i })).toBeDisabled();
    expect(within(pagination).getByLabelText(/rows per page/i)).toBeDisabled();

    await user.click(screen.getByRole('button', { name: /sort by amount/i }));
    expect(props.on_sort_change).not.toHaveBeenCalled();

    await user.click(within(pagination).getByRole('button', { name: /next page/i }));
    expect(props.on_page_change).not.toHaveBeenCalled();
  });

  test('clicking a row triggers on_open_details for that transaction', async () => {
    const user = userEvent.setup();
    const { props } = renderSubject({
