            <TransactionStatusBadge status={txn.status} />
          </td>
          <td className="tt_td tt_truncate" title={txn.merchant_name}>
            {txn.merchant_name}
          </td>
          <td className="tt_td tt_truncate" title={txn.payment_method}>
            {txn.payment_method}
          </td>
          <td className="tt_td tt_actions">
            <button
              type="button"
              className="tt_details"
              onClick={onDetails}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  // Button already activates on Enter/Space, but keep this to ensure stopPropagation consistently.
                  e.preventDefault();
                  onDetails(e);
                }
              }}
              aria-label={makeDetailsAriaLabel(txn)}
              disabled={controlsDisabled}
            >
              View details
            </button>
          </td>
        </tr>
      );
    });
  };

  return (
    <div className="tt_root">
      <div className="tt_scroll">
        <table className="tt_table" role="table">
          <thead className="tt_thead">
            <tr>
              {COLUMNS.map((col) => {
                const isActive = sort_key === col.key;
                const ariaSort = ariaSortValue(isActive, sort_direction);
                const directionText = isActive ? (sort_direction === 'asc' ? 'sorted ascending' : 'sorted descending') : '';

                return (
                  <th key={col.key} className="tt_th" aria-sort={ariaSort as any}>
                    <button
                      type="button"
                      className="tt_sortBtn"
                      onClick={() => handleSortActivate(col.key)}
                      disabled={controlsDisabled}
                      aria-label={`Sort by ${col.label}`}
                    >
                      <span className="tt_thLabel">{col.label}</span>
                      <span className="tt_sortIcon" aria-hidden="true">
                        {isActive ? (sort_direction === 'asc' ? '▲' : '▼') : '↕'}
                      </span>
                      {isActive ? <span className="tt_srOnly">{directionText}</span> : null}
                    </button>
                  </th>
                );
              })}
              <th className="tt_th tt_actionsHeader">Actions</th>
            </tr>
          </thead>
          <tbody className="tt_tbody">{renderBody()}</tbody>
        </table>

        {is_fetching && !is_initial_loading ? (
          <div className="tt_overlay" aria-hidden="true">
            <div className="tt_overlayInner">Loading…</div>
          </div>
        ) : null}
      </div>

      {showPagination ? (
        <div className="tt_pagination">
          <TransactionPagination
            current_page={current_page}
            total_count={total_count}
            page_size={page_size}
            is_loading={controlsDisabled}
            on_page_change={(payload: PageChangePayload) => {
              if (controlsDisabled) return;
              on_page_change(payload);
            }}
            on_page_size_change={(payload: PageSizeChangePayload) => {
              if (controlsDisabled) return;
              on_page_size_change(payload);
            }}
          />
        </div>
      ) : null}

      <style>{`
        .tt_root {
          color: var(--color-text-primary);
