      // Simulate success by turning off the failing condition.
      if (options?.initialLoad?.fail) {
        (options.initialLoad as any).fail = false;
      }
      void doFetch('refetch');
    };

    return (
      <TransactionTable
        transactions={transactions}
        total_count={totalCount}
        is_initial_loading={isInitialLoading}
        is_fetching={isFetching}
        has_error={hasError}
        error_message={errorMessage}
        current_page={page}
        page_size={pageSize}
        sort_key={sortKey as any}
        sort_direction={sortDirection}
        on_sort_change={onSortChange as any}
        on_page_change={onPageChange as any}
        on_page_size_change={onPageSizeChange as any}
        on_open_details={onOpenDetails as any}
        on_retry={onRetry}
      />
