mponentInterfaces":{"components":[{"accepts":[{"description":"Transaction status value used to determine label and styling. Supported: "pending", "completed", "failed", "refunded". Any other value renders the neutral "Unknown" badge.","name":"status","required":true,"type":"string"}],"componentCode":"transaction_status_badge","componentName":"Transaction Status Badge","returns":[]},{"accepts":[{"description":"Array of transactions to render in the table body (already fetched for the current sort/page/page_size). Each item should include: id, date, amount, status, merchant_name, payment_method.","name":"transactions","required":true,"type":"TransactionRow[]"},{"description":"Total number of transactions available on the server for the current query context; used to compute total pages.","name":"total_count","required":true,"type":"number"},{"description":"Whether the initial load is in progress; when true the table renders a skeleton with header visible and placeholder rows.","name":"is_initial_loading","required":true,"type":"boolean"},{"description":"Whether a reload fetch is in progress due to sort/pagination changes; when true, keep current rows visible, show loading overlay, and disable sort and pagination controls.","name":"is_fetching","required":true,"type":"boolean"},{"description":"Whether the table is in an error state for the last fetch attempt; when true, show the error row spanning all columns and a Retry button.","name":"has_error","required":true,"type":"boolean"},{"description":"Current error message to display when has_error is true. If omitted, component uses default copy: "Unable to load transactions."","name":"error_message","required":false,"type":"string"},{"description":"Current 1-based page index.","name":"current_page","required":true,"type":"number"},{"description":"Current page size; allowed values are 25, 50, or 100.","name":"page_size","required":true,"type":"25 | 50 | 100"},{"description":"Current single-column sort key.","name":"sort_k