import styles from './TransactionStatusBadge.module.css';

export type TransactionStatus = 'pending' | 'completed' | 'failed' | 'refunded';

export interface TransactionStatusBadgeProps {
  /**
   * Transaction status value used to determine label and styling.
   * Supported: "pending", "completed", "failed", "refunded".
   * Any other value renders the neutral "Unknown" badge.
   */
  status: string;
}

function normalizeStatus(status: string): TransactionStatus | 'unknown' {
  const v = String(status || '').trim().toLowerCase();
  if (v === 'pending' || v === 'completed' || v === 'failed' || v === 'refunded') return v;
  return 'unknown';
}

function labelFor(status: TransactionStatus | 'unknown'): string {
  switch (status) {
    case 'pending':
      return 'Pending';
    case 'completed':
      return 'Completed';
    case 'failed':
      return 'Failed';
    case 'refunded':
      return 'Refunded';
    default:
      return 'Unknown';
  }
}

export function TransactionStatusBadge({ status }: TransactionStatusBadgeProps) {
  const normalized = normalizeStatus(status);
  const label = labelFor(normalized);

  return (
    <span
      className={[styles.root, styles[`status_${normalized}`]].filter(Boolean).join(' ')}
      data-status={normalized}
    >
      {label}
    </span>
  );
}
