  current_page: number;
  /** Total number of transactions available across all pages (used to compute total pages). */
  total_count: number;
  /** Current page size (rows per page). */
  page_size: number;
  /** Allowed page size options for the rows-per-page selector. */
  page_size_options?: number[];
  /** Whether pagination controls are disabled due to an in-flight fetch. */
  is_loading?: boolean;
  /** Callback fired when the user requests a different page (via first/prev/next/last). */
  on_page_change: (payload: PageChangePayload) => void;
  /** Callback fired when the user changes the rows-per-page value. */
  on_page_size_change: (payload: PageSizeChangePayload) => void;
};

function clamp(n: number, min: number, max: number) {
  return Math.max(min, Math.min(max, n));
}

function computeTotalPages(totalCount: number, pageSize: number) {
  if (!totalCount || totalCount <= 0 || !pageSize || pageSize <= 0) return 0;
  return Math.ceil(totalCount / pageSize);
}

export default function TransactionPagination(props: TransactionPaginationProps) {
  const {
    current_page,
    total_count,
    page_size,
    page_size_options,
    is_loading = false,
    on_page_change,
    on_page_size_change,
  } = props;

  const options = (page_size_options && page_size_options.length > 0 ? page_size_options : [25, 50, 100]) as number[];

  const totalPages = computeTotalPages(total_count, page_size);

  // If current_page is out of range, clamp for UI display.
  // (Parent container may clamp/refetch; we keep component deterministic.)
  const safeCurrentPage = totalPages === 0 ? 1 : clamp(current_page, 1, totalPages);

  const navDisabled = is_loading || totalPages === 0;
  const isFirstPage = safeCurrentPage <= 1;
  const isLastPage = totalPages === 0 ? true : safeCurrentPage >= totalPages;

  const disableFirstPrev = navDisabled || isFirstPage;
  const disableNextLast = navDisabled || isLastPage;

  const requestPage = (nextPage: number) => {
    if (navDisabled) return;
    const requested = totalPages === 0 ? 1 : clamp(nextPage, 1, totalPages);
    if (requested === safeCurrentPage) return;
    on_page_change({ current_page: requested });
  };

  const onChangePageSize: React.ChangeEventHandler<HTMLSelectElement> = (e) => {
    if (is_loading) return;
    const next = Number(e.target.value);
    if (!Number.isFinite(next)) return;
    on_page_size_change({ page_size: next });
  };

  return (
    <div style={styles.root}>
      <div aria-live="polite" style={styles.pageStatus}>
        Page {safeCurrentPage} of {totalPages}
      </div>

      <div style={styles.controls}>
        <button
          type="button"
          aria-label="First page"
          disabled={disableFirstPrev}
          onClick={() => requestPage(1)}
          style={styles.button}
        >
          First
        </button>
        <button
          type="button"
          aria-label="Previous page"
          disabled={disableFirstPrev}
          onClick={() => requestPage(safeCurrentPage - 1)}
          style={styles.button}
        >
          Previous
        </button>
        <button
          type="button"
          aria-label="Next page"
          disabled={disableNextLast}
          onClick={() => requestPage(safeCurrentPage + 1)}
          style={styles.button}
        >
          Next
        </button>
        <button
          type="button"
          aria-label="Last page"
          disabled={disableNextLast}
          onClick={() => requestPage(totalPages)}
          style={styles.button}
        >
          Last
        </button>

        <div style={styles.spacer} />

        <label style={styles.label}>
          Rows per page
          <select
            aria-label="Rows per page"
            disabled={is_loading}
            value={String(page_size)}
            onChange={onChangePageSize}
            style={styles.select}
          >
            {options.map((n) => (
              <option key={n} value={String(n)}>
                {n}
              </option>
            ))}
          </select>
        </label>
      </div>

      <style>{focusStyles}</style>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  root: {
    display: 'flex',
    flexDirection: 'column',
    gap: 'var(--spacing-8)',
    padding: 'var(--spacing-12)',
    background: 'var(--color-surface-default)',
    border: '1px solid var(--color-border-subtle)',
    borderRadius: 'var(--radius-12)',
    boxShadow: 'var(--shadow-sm)',
    color: 'var(--color-text-primary)',
    fontSize: 'var(--font-size-body)',
  },
  pageStatus: {
    fontSize: 'var(--font-size-body)',
    color: 'var(--color-text-secondary)',
  },
  controls: {
    display: 'flex',
    alignItems: 'center',
    gap: 'var(--spacing-8)',
    flexWrap: 'wrap',
  },
  button: {
    appearance: 'none',
    border: '1px solid var(--color-border-subtle)',
    background: 'var(--color-surface-muted)',
    color: 'var(--color-text-primary)',
    borderRadius: 'var(--radius-8)',
    padding: 'var(--spacing-8) var(--spacing-12)',
    fontSize: 'var(--font-size-body)',
    cursor: 'pointer',
  },
  spacer: {
    flex: 1,
    minWidth: 'var(--spacing-12)',
  },
  label: {
    display: 'inline-flex',
    alignItems: 'center',
    gap: 'var(--spacing-8)',
    fontSize: 'var(--font-size-label)',
    color: 'var(--color-text-secondary)',
    fontWeight: 'var(--font-weight-medium)',
  },
  select: {
    fontSize: 'var(--font-size-body)',
    padding: 'var(--spacing-8) var(--spacing-12)',
    borderRadius: 'var(--radius-8)',
    border: '1px solid var(--color-border-subtle)',
    background: 'var(--color-surface-default)',
    color: 'var(--color-text-primary)',
  },
};

const focusStyles = `
  button:focus-visible,
  select:focus-visible {
    outline: 2px solid var(--color-text-primary);
    outline-offset: 2px;
  }

  button:disabled {
    cursor: not-allowed;
    opacity: 0.6;
  }
`;
"},{"filename":"/app/generated/frontend/src/components/TransactionStatusBadge/TransactionStatusBadge.tsx","content":"import React from 'react';
import styles from './TransactionStatusBadge.module.css';

export type TransactionStatus = 'pending' | 'completed' | 'failed' | 'refunded';

export interface TransactionStatusBadgeProps {
  /**
   * Transaction status value used to determine label and styling.
   * Supported: "pending", "completed", "failed", "refunded".
   * Any other value renders the neutral "Unknown" badge.
   */
  status: string;
}

function normalizeStatus(status: string): TransactionStatus | 'unknown' {
  const v = String(status || '').trim().toLowerCase();
  if (v === 'pending' || v === 'completed' || v === 'failed' || v === 'refunded') return v;
  return 'unknown';
}

function labelFor(status: TransactionStatus | 'unknown'): string {
  switch (status) {
    case 'pending':
      return 'Pending';
    case 'completed':
      return 'Completed';
    case 'failed':
      return 'Failed';
    case 'refunded':
      return 'Refunded';
    default:
      return 'Unknown';
  }
}

export function TransactionStatusBadge({ status }: TransactionStatusBadgeProps) {
  const normalized = normalizeStatus(status);
  const label = labelFor(normalized);

  return (
    <span
      className={[styles.root, styles[`status_${normalized}`]].filter(Boolean).join(' ')}
      data-status={normalized}
    >
      {label}
    </span>
  );
}
