"},{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.tsx","content":"import React from 'react';
import { TransactionPagination } from '../TransactionPagination/TransactionPagination';
import { TransactionStatusBadge } from '../TransactionStatusBadge/TransactionStatusBadge';

export type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: string;
  merchant_name: string;
  payment_method: string;
};

export type TransactionSortKey = 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method' | (string & {});
export type SortChangePayload = { sort_key: TransactionSortKey; sort_direction: 'asc' | 'desc' };
export type PageChangePayload = { page?: number; current_page?: number };
export type PageSizeChangePayload = { page_size: 25 | 50 | 100; page?: number; current_page?: number };
export type OpenTransactionDetailsPayload = TransactionRow;

export type TransactionTableProps = {
  transactions: TransactionRow[];
  total_count: number;
  is_initial_loading: boolean;
  is_fetching: boolean;
  has_error: boolean;
  error_message?: string;
  current_page: number;
  page_size: 25 | 50 | 100;
  sort_key: TransactionSortKey;
  sort_direction: 'asc' | 'desc';
  on_sort_change: (payload: SortChangePayload) => void;
  on_page_change: (payload: PageChangePayload) => void;
  on_page_size_change: (payload: PageSizeChangePayload) => void;
  on_open_details: (payload: OpenTransactionDetailsPayload) => void;
  on_retry: () => void;
};

const COLUMNS: Array<{
  key: Exclude<TransactionSortKey, string> | 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method';
  label: string;
  isTruncating?: boolean;
}> = [
  { key: 'date', label: 'Date' },
  { key: 'amount', label: 'Amount' },
  { key: 'status', label: 'Status' },
  { key: 'merchant_name', label: 'Merchant Name', isTruncating: true },
  { key: 'payment_method', label: 'Payment Method', isTruncating: true },
];

function ariaSortValue(isActive: boolean, direction: 'asc' | 'desc') {
  if (!isActive) return undefined;
  return direction === 'asc' ? 'ascending' : 'descending';
}

function nextSortDirection(params: { currentKey: TransactionSortKey; currentDirection: 'asc' | 'desc'; clickedKey: TransactionSortKey }) {
  const { currentKey, currentDirection, clickedKey } = params;
  if (clickedKey !== currentKey) return 'asc' as const;
  return currentDirection === 'asc' ? ('desc' as const) : ('asc' as const);
}

function makeDetailsAriaLabel(txn: TransactionRow) {
  const merchant = (txn.merchant_name ?? '').trim();
  const date = (txn.date ?? '').trim();
  if (merchant && date) return `View details for transaction ${merchant} on ${date}`;
  if (merchant) return `View details for transaction ${merchant}`;
  if (date) return `View details for transaction on ${date}`;
  return 'View transaction details';
}

export function TransactionTable(props: TransactionTableProps) {
  const {
    transactions,
    total_count,
    is_initial_loading,
    is_fetching,
    has_error,
    error_message,
    current_page,
    page_size,
    sort_key,
    sort_direction,
    on_sort_change,
    on_page_change,
    on_page_size_change,
    on_open_details,
    on_retry,
  } = props;

  const controlsDisabled = !!is_fetching;

  const showEmpty = !is_initial_loading && !has_error && total_count === 0;
  const showPagination = !is_initial_loading && !has_error && total_count > 0;

  const handleSortActivate = (key: TransactionSortKey) => {
    if (controlsDisabled) return;
    const dir = nextSortDirection({ currentKey: sort_key, currentDirection: sort_direction, clickedKey: key });
    on_sort_change({ sort_key: key, sort_direction: dir });
  };

  const handleRowClick = (txn: TransactionRow) => {
    if (has_error || is_initial_loading) return;
    on_open_details(txn);
  };

  const renderBody = () => {
    if (has_error) {
      return (
        <tr>
          <td colSpan={COLUMNS.length + 1} className="tt_stateCell">
            <div className="tt_stateBlock" role="alert">
              <div className="tt_stateTitle">{(error_message ?? 'Unable to load transactions.').trim()}</div>
              <button type="button" className="tt_retry" onClick={on_retry} disabled={controlsDisabled}>
                Retry
              </button>
            </div>
          </td>
        </tr>
      );
    }

    if (showEmpty) {
      return (
        <tr>
          <td colSpan={COLUMNS.length + 1} className="tt_stateCell">
            <div className="tt_stateBlock">
              <div className="tt_stateTitle">No transactions to display.</div>
            </div>
          </td>
        </tr>
      );
    }

    if (is_initial_loading) {
      return Array.from({ length: 10 }, (_, i) => (
        <tr key={`sk_${i}`} className="tt_skeletonRow" aria-hidden="true">
          <td className="tt_td">
            <div className="tt_skeleton" />
          </td>
          <td className="tt_td">
            <div className="tt_skeleton" />
          </td>
          <td className="tt_td">
            <div className="tt_skeleton" />
          </td>
          <td className="tt_td">
            <div className="tt_skeleton" />
          </td>
          <td className="tt_td">
            <div className="tt_skeleton" />
          </td>
          <td className="tt_td tt_actions">
            <div className="tt_skeleton" />
          </td>
        </tr>
      ));
    }

    return transactions.map((txn) => {
      const onRow = () => handleRowClick(txn);
      const onDetails = (e: React.MouseEvent | React.KeyboardEvent) => {
        e.stopPropagation();
        on_open_details(txn);
      };

      return (
        <tr key={txn.id} className="tt_tr" onClick={onRow}>
          <td className="tt_td tt_nowrap">{txn.date}</td>
          <td className="tt_td tt_nowrap">{txn.amount}</td>
          <td className="tt_td tt_nowrap">
            <TransactionStatusBadge status={txn.status} />
          </td>
          <td className="tt_td tt_truncate" title={txn.merchant_name}>
            {txn.merchant_name}
          </td>
          <td className="tt_td tt_truncate" title={txn.payment_method}>
            {txn.payment_method}
          </td>
          <td className="tt_td tt_actions">
            <button
              type="button"
              className="tt_details"
              onClick={onDetails}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  // Button already activates on Enter/Space, but keep this to ensure stopPropagation consistently.
                  e.preventDefault();
                  onDetails(e);
                }
              }}
              aria-label={makeDetailsAriaLabel(txn)}
              disabled={controlsDisabled}
            >
              View details
            </button>
          </td>
        </tr>
      );
    });
  };

  return (
    <div className="tt_root">
      <div className="tt_scroll">
        <table className="tt_table" role="table">
          <thead className="tt_thead">
            <tr>
              {COLUMNS.map((col) => {
                const isActive = sort_key === col.key;
                const ariaSort = ariaSortValue(isActive, sort_direction);
                const directionText = isActive ? (sort_direction === 'asc' ? 'sorted ascending' : 'sorted descending') : '';

                return (
                  <th key={col.key} className="tt_th" aria-sort={ariaSort as any}>
                    <button
                      type="button"
                      className="tt_sortBtn"
                      onClick={() => handleSortActivate(col.key)}
                      disabled={controlsDisabled}
                      aria-label={`Sort by ${col.label}`}
                    >
                      <span className="tt_thLabel">{col.label}</span>
                      <span className="tt_sortIcon" aria-hidden="true">
                        {isActive ? (sort_direction === 'asc' ? '▲' : '▼') : '↕'}
                      </span>
                      {isActive ? <span className="tt_srOnly">{directionText}</span> : null}
                    </button>
                  </th>
                );
              })}
              <th className="tt_th tt_actionsHeader">Actions</th>
            </tr>
          </thead>
          <tbody className="tt_tbody">{renderBody()}</tbody>
        </table>

        {is_fetching && !is_initial_loading ? (
          <div className="tt_overlay" aria-hidden="true">
            <div className="tt_overlayInner">Loading…</div>
          </div>
        ) : null}
      </div>

      {showPagination ? (
        <div className="tt_pagination">
          <TransactionPagination
            current_page={current_page}
            total_count={total_count}
            page_size={page_size}
            is_loading={controlsDisabled}
            on_page_change={(payload: PageChangePayload) => {
              if (controlsDisabled) return;
              on_page_change(payload);
            }}
            on_page_size_change={(payload: PageSizeChangePayload) => {
              if (controlsDisabled) return;
              on_page_size_change(payload);
            }}
          />
        </div>
      ) : null}

      <style>{`
        .tt_root {
          color: var(--color-text-primary);
          font-size: var(--font-size-body);
        }
        .tt_scroll {
          position: relative;
          overflow-x: auto;
          background: var(--color-surface-default);
          border: 1px solid var(--color-border-subtle);
          border-radius: var(--radius-12);
          box-shadow: var(--shadow-sm);
        }
        .tt_table {
          width: 100%;
          border-collapse: collapse;
          min-width: 720px;
        }
        .tt_thead {
          background: var(--color-surface-muted);
        }
        .tt_th {
          text-align: left;
          padding: var(--spacing-12) var(--spacing-16);
          font-size: var(--font-size-label);
          font-weight: var(--font-weight-medium);
          color: var(--color-text-secondary);
          border-bottom: 1px solid var(--color-border-subtle);
          white-space: nowrap;
        }
        .tt_sortBtn {
          appearance: none;
          border: 0;
          background: transparent;
          padding: 0;
          margin: 0;
          color: inherit;
          font: inherit;
          display: inline-flex;
          align-items: center;
          gap: var(--spacing-8);
          cursor: pointer;
        }
        .tt_sortBtn:disabled {
          cursor: not-allowed;
          opacity: 0.6;
        }
        .tt_sortBtn:focus-visible,
        .tt_details:focus-visible,
        .tt_retry:focus-visible {
          outline: 2px solid var(--color-border-danger);
          outline-offset: 2px;
          border-radius: var(--radius-8);
        }
        .tt_sortIcon {
          color: var(--color-text-secondary);
          font-size: var(--font-size-label);
          line-height: 1;
        }
        .tt_td {
          padding: var(--spacing-12) var(--spacing-16);
          border-bottom: 1px solid var(--color-border-subtle);
          vertical-align: middle;
          background: var(--color-surface-default);
        }
        .tt_tr {
          cursor: pointer;
        }
        .tt_tr:hover .tt_td {
          background: var(--color-surface-muted);
        }
        .tt_nowrap {
          white-space: nowrap;
        }
        .tt_truncate {
          max-width: 0;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
        }
        .tt_actionsHeader {
          width: 1%;
        }
        .tt_actions {
          white-space: nowrap;
          text-align: right;
        }
        .tt_details {
          appearance: none;
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border-radius: var(--radius-8);
          padding: var(--spacing-8) var(--spacing-12);
          font-size: var(--font-size-body);
          cursor: pointer;
        }
        .tt_details:disabled {
          cursor: not-allowed;
          opacity: 0.6;
        }
        .tt_details:active {
          background: var(--color-surface-muted);
        }
        .tt_stateCell {
          padding: var(--spacing-24);
          background: var(--color-surface-default);
        }
        .tt_stateBlock {
          display: flex;
          align-items: center;
          justify-content: space-between;
          gap: var(--spacing-16);
        }
        .tt_stateTitle {
          color: var(--color-text-primary);
          font-weight: var(--font-weight-medium);
        }
        .tt_retry {
          appearance: none;
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border-radius: var(--radius-8);
          padding: var(--spacing-8) var(--spacing-12);
          font-size: var(--font-size-body);
          cursor: pointer;
        }
        .tt_retry:disabled {
          cursor: not-allowed;
          opacity: 0.6;
        }
        .tt_skeletonRow .tt_td {
          background: var(--color-surface-default);
        }
        .tt_skeleton {
          height: 14px;
          border-radius: var(--radius-8);
          background: var(--color-surface-muted);
          width: 100%;
        }
        .tt_overlay {
          position: absolute;
          inset: 0;
          background: rgba(255, 255, 255, 0.55);
          display: flex;
          align-items: center;
          justify-content: center;
          pointer-events: none;
        }
        .tt_overlayInner {
          color: var(--color-text-secondary);
          font-size: var(--font-size-body);
          background: var(--color-surface-default);
          border: 1px solid var(--color-border-subtle);
          border-radius: var(--radius-12);
          padding: var(--spacing-8) var(--spacing-12);
        }
        .tt_pagination {
          padding: var(--spacing-12) 0 0 0;
        }
        .tt_srOnly {
          position: absolute;
          width: 1px;
          height: 1px;
          padding: 0;
          margin: -1px;
          overflow: hidden;
          clip: rect(0, 0, 0, 0);
          white-space: nowrap;
          border: 0;
        }
      `}</style>
    </div>
  );
}
