leted transaction status.","kind":"status","name":"Completed","isRequired":true},{"code":"status_failed","componentCode":"transaction_status_badge","description":"Failed transaction status.","kind":"status","name":"Failed","isRequired":true},{"code":"status_refunded","componentCode":"transaction_status_badge","description":"Refunded transaction status.","kind":"status","name":"Refunded","isRequired":true}],"interactions":[{"code":"sort_by_column","componentCode":"transaction_table","description":"User sorts the table by any column.","targetComponentCode":null,"type":"sort"},{"code":"paginate_transactions","componentCode":"transaction_pagination","description":"User paginates through the transaction list and can change page size to 25/50/100.","targetComponentCode":"transaction_table","type":"paginate"},{"code":"open_transaction_details","componentCode":"transaction_table","description":"Clicking a row opens transaction details.","targetComponentCode":null,"type":"open_details"}],"rootComponentCode":"transaction_table","specifiedStates":[{"code":"state_pending","componentCode":"transaction_status_badge","description":"Badge displays pending status styling.","isExplicit":true,"name":"Pending"},{"code":"state_completed","componentCode":"transaction_status_badge","description":"Badge displays completed status styling.","isExplicit":true,"name":"Completed"},{"code":"state_failed","componentCode":"transaction_status_badge","description":"Badge displays failed status styling.","isExplicit":true,"name":"Failed"},{"code":"state_refunded","componentCode":"transaction_status_badge","description":"Badge displays refunded status styling.","isExplicit":true,"name":"Refunded"}],"tokenReferences":[{"componentCode":"transaction_status_badge","description":"Status-to-color mapping for the badge (pending/completed/failed/refunded).","name":"status color","type":"color"},{"componentCode":"transaction_status_badge","description":"Badge corner rounding.","name":"badge radius","type":"rad