        <td style={styles.tdNoWrap}>
          <TransactionStatusBadge status={txn.status} />
        </td>
        <td style={styles.tdEllipsis} title={txn.merchant_name}>
          {txn.merchant_name}
        </td>
        <td style={styles.tdEllipsis} title={txn.payment_method}>
          {txn.payment_method}
        </td>
        <td style={styles.tdAction}>
          <button
            type="button"
            onClick={(e) => handleDetailsClick(e, txn)}
            aria-label={getDetailsAriaLabel(txn)}
            disabled={isInteractionLocked}
            style={styles.detailsButton}
            className="tt-focus"
          >
            View details
          </button>
        </td>
      </tr>
    ));
  };

  return (
    <div style={styles.card}>
      <style>
        {`
          .tt-focus:focus-visible {
            outline: 2px solid var(--color-text-primary);
            outline-offset: 2px;
          }
        `}
      </style>

      <div style={styles.scrollWrap}>
        <div style={styles.tableWrap}>
          <table role="table" style={styles.table}>
            <thead>
              <tr>
                {SORTABLE_COLUMNS.map((col) => {
                  const isActive = col.key === sort_key;
                  const ariaSort = isActive ? toAriaSort(sort_direction) : undefined;
                  const indicator = isActive ? (sort_direction === 'asc' ? '▲' : '▼') : '';
                  const sr = isActive ? ` (sorted ${toAriaSort(sort_direction)})` : '';

                  return (
                    <th
                      key={String(col.key)}
                      style={styles.th}
                      aria-sort={ariaSort as any}
                      scope="col"
                    >
                      <button
                        type="button"
                        onClick={() => handleSortActivate(col.key)}
                        disabled={isInteractionLocked}
                        style={styles.sortButton}
                        className="tt-focus"
                        aria-label={`Sort by ${col.label}`}
                      >
                        <span style={styles.thLabel}>{col.label}</span>
                        <span aria-hidden="true" style={styles.sortIndicator}>
                          {indicator}
                        </span>
                        <span style={styles.visuallyHidden}>{sr}</span>
                      </button>
                    </th>
                  );
                })}
                <th style={styles.th} scope="col">
                  <span style={styles.thLabel}>Actions</span>
                </th>
              </tr>
            </thead>
            <tbody style={styles.tbody}>{renderBody()}</tbody>
          </table>

          {is_fetching && !is_initial_loading && !has_error && (
            <div style={styles.fetchOverlay} aria-hidden="true">
              <div style={styles.fetchOverlayInner}>Loading…</div>
            </div>
          )}
        </div>
      </div>

      {showPagination ? (
        <div style={styles.paginationWrap}>
          <TransactionPagination
            current_page={current_page}
            total_count={total_count}
            page_size={page_size}
            is_loading={isInteractionLocked}
            on_page_change={handlePageChange}
            on_page_size_change={handlePageSizeChange}
          />
        </div>
      ) : null}
    </div>
  );
}

