import { TransactionPagination } from '../TransactionPagination/TransactionPagination';
import { TransactionStatusBadge } from '../TransactionStatusBadge/TransactionStatusBadge';

export type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: string;
  merchant_name: string;
  payment_method: string;
};

export type TransactionSortKey = 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method' | (string & {});

export type SortChangePayload = {
  sort_key: TransactionSortKey;
  sort_direction: 'asc' | 'desc';
};

export type PageChangePayload = { page?: number; current_page?: number };
export type PageSizeChangePayload = { page_size: 25 | 50 | 100; page?: number; current_page?: number };
export type OpenTransactionDetailsPayload = TransactionRow;

export type TransactionTableProps = {
  transactions: TransactionRow[];
  total_count: number;
  is_initial_loading: boolean;
  is_fetching: boolean;
  has_error: boolean;
  error_message?: string;
  current_page: number;
  page_size: 25 | 50 | 100;
  sort_key: TransactionSortKey;
  sort_direction: 'asc' | 'desc';
  on_sort_change: (payload: SortChangePayload) => void;
  on_page_change: (payload: PageChangePayload) => void;
  on_page_size_change: (payload: PageSizeChangePayload) => void;
  on_open_details: (payload: OpenTransactionDetailsPayload) => void;
  on_retry: () => void;
};

const SORTABLE_COLUMNS: Array<{ key: TransactionSortKey; label: string }> = [
  { key: 'date', label: 'Date' },
  { key: 'amount', label: 'Amount' },
  { key: 'status', label: 'Status' },
  { key: 'merchant_name', label: 'Merchant Name' },
  { key: 'payment_method', label: 'Payment Method' },
];

function toAriaSort(direction: 'asc' | 'desc') {
  return direction === 'asc' ? 'ascending' : 'descending';
}

function getDetailsAriaLabel(txn: TransactionRow) {
  const merchant = txn.merchant_name?.trim();
  const date = txn.date?.trim();
  if (merchant && date) return `View details for transaction ${merchant} on ${date}`;
  if (merchant) return `View details for transaction ${merchant}`;
  if (date) return `View details for transaction on ${date}`;
  return 'View transaction details';
}

export function TransactionTable(props: TransactionTableProps) {
  const {
    transactions,
    total_count,
    is_initial_loading,
    is_fetching,
    has_error,
    error_message,
    current_page,
    page_size,
    sort_key,
    sort_direction,
    on_sort_change,
    on_page_change,
    on_page_size_change,
    on_open_details,
    on_retry,
  } = props;

  const isInteractionLocked = !!is_fetching;

  const showPagination = !is_initial_loading && !has_error && total_count > 0;

  const handleSortActivate = (colKey: TransactionSortKey) => {
    if (isInteractionLocked) return;

    const isSame = colKey === sort_key;
    const nextDirection: 'asc' | 'desc' = isSame ? (sort_direction === 'asc' ? 'desc' : 'asc') : 'asc';

    on_sort_change({ sort_key: colKey, sort_direction: nextDirection });
  };

  const handleRowClick = (txn: TransactionRow) => {
    if (isInteractionLocked) return;
    on_open_details(txn);
  };

  const handleDetailsClick = (e: React.MouseEvent, txn: TransactionRow) => {
    e.stopPropagation();
    if (isInteractionLocked) return;
    on_open_details(txn);
  };

  const handlePageChange = (payload: PageChangePayload) => {
    if (isInteractionLocked) return;
    on_page_change(payload);
  };

  const handlePageSizeChange = (payload: PageSizeChangePayload) => {
    if (isInteractionLocked) return;
    on_page_size_change(payload);
  };

  const renderBody = () => {
    if (has_error) {
      return (
        <tr>
          <td colSpan={6} style={styles.stateCell}>
            <div style={styles.stateTitle}>{error_message ?? 'Unable to load transactions.'}</div>
            <button
              type="button"
              onClick={on_retry}
              style={styles.retryButton}
              className="tt-focus"
            >
              Retry
            </button>
          </td>
        </tr>
      );
    }

    if (!is_initial_loading && total_count === 0) {
      return (
        <tr>
          <td colSpan={6} style={styles.stateCell}>
            <div style={styles.stateTitle}>No transactions to display.</div>
          </td>
        </tr>
      );
    }

    if (is_initial_loading) {
      return Array.from({ length: 10 }).map((_, i) => (
        <tr key={`skeleton-${i}`}>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '7rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '5rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '6rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '10rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '12rem' }} />
          </td>
          <td style={styles.td}>
            <div style={{ ...styles.skeletonBlock, width: '6rem' }} />
          </td>
        </tr>
      ));
    }

    return transactions.map((txn) => (
      <tr
        key={txn.id}
        onClick={() => handleRowClick(txn)}
        style={{ ...styles.tr, ...(isInteractionLocked ? styles.trLocked : null) }}
      >
        <td style={styles.tdNoWrap}>{txn.date}</td>
        <td style={styles.tdNoWrap}>{String(txn.amount)}</td>
        <td style={styles.tdNoWrap}>
          <TransactionStatusBadge status={txn.status} />
        </td>
        <td style={styles.tdEllipsis} title={txn.merchant_name}>
          {txn.merchant_name}
        </td>
        <td style={styles.tdEllipsis} title={txn.payment_method}>
          {txn.payment_method}
        </td>
        <td style={styles.tdAction}>
          <button
            type="button"
            onClick={(e) => handleDetailsClick(e, txn)}
            aria-label={getDetailsAriaLabel(txn)}
            disabled={isInteractionLocked}
            style={styles.detailsButton}
            className="tt-focus"
          >
            View details
          </button>
        </td>
      </tr>
    ));
  };

  return (
    <div style={styles.card}>
      <style>
        {`
          .tt-focus:focus-visible {
            outline: 2px solid var(--color-text-primary);
            outline-offset: 2px;
          }
        `}
      </style>

      <div style={styles.scrollWrap}>
        <div style={styles.tableWrap}>
          <table role="table" style={styles.table}>
            <thead>
              <tr>
                {SORTABLE_COLUMNS.map((col) => {
                  const isActive = col.key === sort_key;
                  const ariaSort = isActive ? toAriaSort(sort_direction) : undefined;
                  const indicator = isActive ? (sort_direction === 'asc' ? '▲' : '▼') : '';
                  const sr = isActive ? ` (sorted ${toAriaSort(sort_direction)})` : '';

                  return (
                    <th
                      key={String(col.key)}
                      style={styles.th}
                      aria-sort={ariaSort as any}
                      scope="col"
                    >
                      <button
                        type="button"
                        onClick={() => handleSortActivate(col.key)}
                        disabled={isInteractionLocked}
                        style={styles.sortButton}
                        className="tt-focus"
                        aria-label={`Sort by ${col.label}`}
                      >
                        <span style={styles.thLabel}>{col.label}</span>
                        <span aria-hidden="true" style={styles.sortIndicator}>
                          {indicator}
                        </span>
                        <span style={styles.visuallyHidden}>{sr}</span>
                      </button>
                    </th>
                  );
                })}
                <th style={styles.th} scope="col">
                  <span style={styles.thLabel}>Actions</span>
                </th>
              </tr>
            </thead>
            <tbody style={styles.tbody}>{renderBody()}</tbody>
          </table>

          {is_fetching && !is_initial_loading && !has_error && (
            <div style={styles.fetchOverlay} aria-hidden="true">
              <div style={styles.fetchOverlayInner}>Loading…</div>
            </div>
          )}
        </div>
      </div>

      {showPagination ? (
        <div style={styles.paginationWrap}>
          <TransactionPagination
            current_page={current_page}
            total_count={total_count}
            page_size={page_size}
            is_loading={isInteractionLocked}
            on_page_change={handlePageChange}
            on_page_size_change={handlePageSizeChange}
          />
        </div>
      ) : null}
    </div>
  );
}

