    // sorting disabled in error
    const dateHeader = getHeaderCell('Date');
    const dateSortButton = within(dateHeader).getByRole('button', { name: /date/i });
    await user.click(dateSortButton);
    expect(props.on_sort_change).not.toHaveBeenCalled();

    // pagination exists but disabled when error
    const pagination = screen.getByTestId('pagination');
    expect(within(pagination).getByRole('button', { name: /next page/i })).toBeDisabled();
    expect(within(pagination).getByRole('button', { name: /previous page/i })).toBeDisabled();
    expect(within(pagination).getByRole('combobox', { name: /page size/i })).toBeDisabled();
  });

  test('empty state shows "No transactions" and hides pagination', () => {
