  test('renders row overlay link with default href and accessible name; click emits details_link_activated', async () => {
    const user = userEvent.setup();
    const props = makeProps();
    render(<TransactionTable {...props} />);

    const link = screen.getByRole('link', { name: 'View transaction tx_1' });
    expect(link).toHaveAttribute('href', '/transactions/tx_1');

    await user.click(link);
    expect(props.on_details_link_activated).toHaveBeenCalledTimes(1);
    expect(props.on_details_link_activated).toHaveBeenCalledWith(
