  test('merchant name and payment method cells include title attributes for full text overflow fallback', () => {
    const props = makeProps();
    render(<TransactionTable {...props} />);

    expect(screen.getByTitle(props.transactions[0].merchant_name)).toBeInTheDocument();
    expect(screen.getByTitle(props.transactions[0].payment_method)).toBeInTheDocument();
