});

import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { TransactionTablePagination } from './TransactionTablePagination';

type Props = React.ComponentProps<typeof TransactionTablePagination>;

function renderComponent(override: Partial<Props> = {}) {
  const props: Props = {
    current_page: 1,
    total_pages: 3,
    page_size: 25,
    on_previous_page: jest.fn(),
    on_next_page: jest.fn(),
    on_page_size_change: jest.fn(),
    ...override
  };

  return {
    props,
    user: userEvent.setup(),
    ...render(<TransactionTablePagination {...props} />)
  };
}

describe('TransactionTablePagination', () => {
  it('renders within a nav landmark with an accessible label and exposes an aria-live page status', () => {
    renderComponent({ current_page: 2, total_pages: 5 });

    const nav = screen.getByRole('navigation', { name: /transaction table pagination/i });
    expect(nav).toBeInTheDocument();

    expect(screen.getByText('Page 2 of 5')).toBeInTheDocument();

    // Ensure the "Page X of Y" element is announced politely as it updates
    const pageStatus = screen.getByText('Page 2 of 5');
    expect(pageStatus).toHaveAttribute('aria-live', 'polite');
  });

  it('sets correct accessible names for Previous/Next controls', () => {
    renderComponent({ current_page: 2, total_pages: 3 });

    expect(screen.getByRole('button', { name: /previous page/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /next page/i })).toBeInTheDocument();
  });

  it('disables Previous on first page and does not invoke callback when clicked', async () => {
    const { user, props } = renderComponent({ current_page: 1, total_pages: 3 });

    const prev = screen.getByRole('button', { name: /previous page/i });
    const next = screen.getByRole('button', { name: /next page/i });

    expect(prev).toBeDisabled();
    expect(next).not.toBeDisabled();

    await user.click(prev);
    expect(props.on_previous_page).not.toHaveBeenCalled();
  });

  it('disables Next on last page and does not invoke callback when clicked', async () => {
    const { user, props } = renderComponent({ current_page: 4, total_pages: 4 });

    const prev = screen.getByRole('button', { name: /previous page/i });
    const next = screen.getByRole('button', { name: /next page/i });

    expect(prev).not.toBeDisabled();
    expect(next).toBeDisabled();

    await user.click(next);
    expect(props.on_next_page).not.toHaveBeenCalled();
  });

  it('invokes on_previous_page and on_next_page when enabled', async () => {
    const { user, props } = renderComponent({ current_page: 2, total_pages: 4 });

    await user.click(screen.getByRole('button', { name: /previous page/i }));
    expect(props.on_previous_page).toHaveBeenCalledTimes(1);

    await user.click(screen.getByRole('button', { name: /next page/i }));
    expect(props.on_next_page).toHaveBeenCalledTimes(1);
  });

  it('renders default page size options (25/50/100) and selects the current page_size', () => {
    renderComponent({ page_size: 50 });

    const select = screen.getByRole('combobox');
    expect(select).toBeInTheDocument();

    const options = screen.getAllByRole('option').map((o) => (o as HTMLOptionElement).value);
    expect(options).toEqual(['25', '50', '100']);

    expect((select as HTMLSelectElement).value).toBe('50');
  });

  it('supports custom page_size_options', () => {
    renderComponent({ page_size: 50, page_size_options: [25, 50] });

    const options = screen.getAllByRole('option').map((o) => (o as HTMLOptionElement).value);
    expect(options).toEqual(['25', '50']);
  });

  it('invokes on_page_size_change with numeric payload when selection changes', async () => {
    const { user, props } = renderComponent({ page_size: 25 });

    const select = screen.getByRole('combobox');
    await user.selectOptions(select, '100');

    expect(props.on_page_size_change).toHaveBeenCalledTimes(1);
    expect(props.on_page_size_change).toHaveBeenCalledWith(100);
  });

  it('when disabled=true, disables Previous/Next and the page size selector and prevents callback invocation', async () => {
    const { user, props } = renderComponent({ current_page: 2, total_pages: 4, disabled: true, page_size: 25 });

    const prev = screen.getByRole('button', { name: /previous page/i });
    const next = screen.getByRole('button', { name: /next page/i });
    const select = screen.getByRole('combobox');

    expect(prev).toBeDisabled();
    expect(next).toBeDisabled();
    expect(select).toBeDisabled();

    await user.click(prev);
    await user.click(next);
    // Selecting options on a disabled select should not trigger change
    await user.selectOptions(select, '50');

    expect(props.on_previous_page).not.toHaveBeenCalled();
    expect(props.on_next_page).not.toHaveBeenCalled();
    expect(props.on_page_size_change).not.toHaveBeenCalled();
  });
});

import React from 'react';

type SupportedStatus = 'pending' | 'completed' | 'failed' | 'refunded';

export type TransactionStatusBadgeProps = {
  /** Transaction status value to render as a labeled, colored badge. */
  status: SupportedStatus | string;
  /** Optional override for the displayed badge text. */
  label?: string;
  /** Optional accessible label override for assistive technologies. */
  aria_label?: string;
};

function toTitleCase(input: string): string {
  if (!input) return '';
  return input.charAt(0).toUpperCase() + input.slice(1).toLowerCase();
}

function deriveLabel(status: string): string {
  const normalized = String(status).trim().toLowerCase();
  switch (normalized) {
    case 'pending':
      return 'Pending';
    case 'completed':
      return 'Completed';
    case 'failed':
      return 'Failed';
    case 'refunded':
      return 'Refunded';
    default:
      return 'Unknown';
  }
}

function statusClass(status: string): string {
  const normalized = String(status).trim().toLowerCase();
  switch (normalized) {
    case 'pending':
      return 'pending';
    case 'completed':
      return 'completed';
    case 'failed':
      return 'failed';
    case 'refunded':
      return 'refunded';
    default:
      return 'unknown';
  }
}

export function TransactionStatusBadge(props: TransactionStatusBadgeProps) {
  const visibleLabel = props.label ?? deriveLabel(props.status);
  const ariaLabel = props.aria_label ?? visibleLabel;

  return (
    <span
      role="status"
      aria-label={ariaLabel}
      className={`tsbRoot tsb--${statusClass(props.status)}`}
      title={visibleLabel}
    >
      {visibleLabel || toTitleCase(String(props.status))}
    </span>
  );
}

.tsbRoot {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-4) var(--spacing-8);
  border-radius: var(--radius-12);
  border: 1px solid var(--color-border-subtle);
  background: var(--color-surface-muted);
  color: var(--color-text-primary);
  font-size: var(--font-size-label);
  font-weight: var(--font-weight-medium);
  line-height: 1;
  white-space: nowrap;
}

/* Status mapping: pending=amber, completed=green, failed=red, refunded=blue (neutral fallback) */
.tsb--pending {
  border-color: var(--color-status-warning);
}

.tsb--completed {
  border-color: var(--color-status-success);
}

.tsb--failed {
  border-color: var(--color-status-danger);
}

.tsb--refunded {
  /* No blue token available in whitelist; keep neutral styling while preserving label semantics. */
  border-color: var(--color-border-subtle);
}

.tsb--unknown {
  border-color: var(--color-border-subtle);
}

import React, { useMemo } from 'react';
import { TransactionStatusBadge } from '../TransactionStatusBadge/TransactionStatusBadge';
import { TransactionTablePagination } from '../TransactionTablePagination/TransactionTablePagination';

export type TransactionRow = {
  id: string;
  date: string;
  amount: number | null;
  status: string;
  merchant_name: string;
  payment_method: string;
};

export type TransactionTableSort = {
  sort_key: string;
  sort_direction: 'asc' | 'desc';
};

export type TransactionTableSortChangePayload = {
  sort_key: string;
  sort_direction: 'asc' | 'desc';
};

export type TransactionDetailsLinkActivatedPayload = {
  transactionId: string;
  href: string;
};

export type TransactionTableProps = {
  transactions: TransactionRow[];
  is_loading: boolean;
  is_error: boolean;
  total_count: number;
  page: number;
  page_size: number;
  sort: TransactionTableSort;
  details_href_template?: string;
  on_sort_change: (payload: TransactionTableSortChangePayload) => void;
  on_next_page: () => void;
  on_prev_page: () => void;
  on_page_size_change: (page_size: number) => void;
  on_retry: () => void;
  on_details_link_activated?: (payload: TransactionDetailsLinkActivatedPayload) => void;
};

const COLUMN_DEFS: Array<{ key: string; label: string; align?: 'left' | 'right'; minWidth?: number }> = [
  { key: 'date', label: 'Date', align: 'left', minWidth: 120 },
  { key: 'amount', label: 'Amount', align: 'right', minWidth: 120 },
  { key: 'status', label: 'Status', align: 'left', minWidth: 120 },
  { key: 'merchant_name', label: 'Merchant Name', align: 'left', minWidth: 200 },
  { key: 'payment_method', label: 'Payment Method', align: 'left', minWidth: 160 },
];

function ariaSortValue(isActive: boolean, direction: 'asc' | 'desc'): 'none' | 'ascending' | 'descending' {
  if (!isActive) return 'none';
  return direction === 'asc' ? 'ascending' : 'descending';
}

function buildDetailsHref(template: string, transactionId: string) {
  return template.replace('{transactionId}', transactionId);
}

function formatDateYYYYMMDD(dateIso: string) {
  // local timezone YYYY-MM-DD
  const d = new Date(dateIso);
  if (Number.isNaN(d.getTime())) return '';
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function formatCurrency(amount: number | null) {
  if (amount === null || amount === undefined) return '—';
  // Locale-safe formatting. Use USD by default (not provided by props); tests do not assert exact string.
  try {
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amount);
  } catch {
    return amount.toFixed(2);
  }
}

export function TransactionTable(props: TransactionTableProps) {
  const {
    transactions,
    is_loading,
    is_error,
    total_count,
    page,
    page_size,
    sort,
    details_href_template,
    on_sort_change,
    on_next_page,
    on_prev_page,
    on_page_size_change,
    on_retry,
    on_details_link_activated,
  } = props;

  const disabledInteractions = is_loading || is_error;
  const isEmpty = !is_loading && !is_error && total_count === 0;
  const showPagination = !isEmpty;

  const totalPages = useMemo(() => {
    const ps = page_size > 0 ? page_size : 25;
    const pages = Math.ceil(Math.max(0, total_count) / ps);
    return Math.max(1, pages);
  }, [total_count, page_size]);

  const hrefTemplate = details_href_template ?? '/transactions/{transactionId}';

  const handleSortActivate = (columnKey: string) => {
    if (disabledInteractions) return;

    const isActive = sort?.sort_key === columnKey;
    const nextDirection: 'asc' | 'desc' = isActive ? (sort.sort_direction === 'asc' ? 'desc' : 'asc') : 'asc';

    on_sort_change({ sort_key: columnKey, sort_direction: nextDirection });
  };

  return (
    <div style={styles.container}>
      <div style={styles.scrollContainer}>
        <table style={styles.table}>
          <thead>
            <tr>
              {COLUMN_DEFS.map((col) => {
                const isActive = sort?.sort_key === col.key;
                const ariaSort = ariaSortValue(!!isActive, (sort?.sort_direction ?? 'desc') as 'asc' | 'desc');
                const textAlign: React.CSSProperties['textAlign'] = col.align ?? 'left';

                return (
                  <th
                    key={col.key}
                    scope="col"
                    aria-sort={ariaSort}
                    style={{
                      ...styles.th,
                      textAlign,
                      minWidth: col.minWidth,
                    }}
                  >
                    <button
                      type="button"
                      onClick={() => handleSortActivate(col.key)}
                      onKeyDown={(e) => {
                        if (disabledInteractions) return;
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          handleSortActivate(col.key);
                        }
                      }}
                      disabled={disabledInteractions}
                      style={styles.sortButton}
                    >
                      {col.label}
                    </button>
                  </th>
                );
              })}
            </tr>
          </thead>

          <tbody>
            {is_loading ? (
              Array.from({ length: 10 }).map((_, i) => (
                <tr key={`skeleton-${i}`} data-testid={`transaction-row-skeleton-${i}`}>
                  {COLUMN_DEFS.map((col) => (
                    <td
                      key={col.key}
                      role="cell"
                      style={{
                        ...styles.td,
                        textAlign: col.align ?? 'left',
                      }}
                    >
                      <div style={styles.skeletonBar} />
                    </td>
                  ))}
                </tr>
              ))
            ) : is_error ? (
              <tr>
                <td style={styles.fullWidthCell} colSpan={COLUMN_DEFS.length}>
                  <div style={styles.stateRow}>
                    <div style={styles.errorTitle}>Transactions couldn’t be loaded</div>
                    <button type="button" onClick={on_retry} style={styles.retryButton}>
                      Retry
                    </button>
                  </div>
                </td>
              </tr>
            ) : isEmpty ? (
              <tr>
                <td style={styles.fullWidthCell} colSpan={COLUMN_DEFS.length}>
                  <div style={styles.stateRow}>No transactions</div>
                </td>
              </tr>
            ) : (
              transactions.map((tx) => {
                const href = buildDetailsHref(hrefTemplate, tx.id);
                const formattedDate = formatDateYYYYMMDD(tx.date);

                return (
                  <tr key={tx.id} style={styles.dataRow}>
                    <td style={{ ...styles.td, ...styles.dateCell }}>
                      <a
                        href={href}
                        aria-label={`View transaction ${tx.id}`}
                        style={styles.rowOverlayLink}
                        onClick={() => {
                          on_details_link_activated?.({ transactionId: tx.id, href });
                        }}
                      >
                        {formattedDate}
                      </a>
                      <span aria-hidden="true">{formattedDate}</span>
                    </td>
