                      <span style={styles.truncate}>{tx.payment_method}</span>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {showPagination ? (
        <div style={styles.paginationWrap}>
          <TransactionTablePagination
            current_page={page}
            total_pages={totalPages}
            page_size={page_size}
            page_size_options={[25, 50, 100]}
            on_next_page={() => {
              if (disabledInteractions) return;
              on_next_page();
            }}
            on_previous_page={() => {
              if (disabledInteractions) return;
              on_prev_page();
            }}
            on_page_size_change={(ps: number) => {
              if (disabledInteractions) return;
              on_page_size_change(ps);
            }}
            disabled={disabledInteractions}
          />
        </div>
      ) : null}
    </div>
  );
}

