{"componentCode":"transaction_table","componentName":"Transaction Table","files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.tsx","content":"import React, { useMemo } from 'react';

import { TransactionStatusBadge } from '../TransactionStatusBadge/TransactionStatusBadge';
import { TransactionTablePagination } from '../TransactionTablePagination/TransactionTablePagination';

type TransactionRow = {
  id: string;
  date: string; // ISO string
  amount: number | null;
  status: string;
  merchant_name: string;
  payment_method: string;
};

type TransactionTableSort = {
  sort_key: string;
  sort_direction: 'asc' | 'desc';
};

type TransactionTableSortChangePayload = {
  sort_key: string;
  sort_direction: 'asc' | 'desc';
};

type TransactionDetailsLinkActivatedPayload = {
  transactionId: string;
  href: string;
};

type Props = {
  transactions: TransactionRow[];
  is_loading: boolean;
  is_error: boolean;
  total_count: number;
  page: number;
  page_size: number;
  sort: TransactionTableSort;
  details_href_template?: string;
  on_sort_change: (payload: TransactionTableSortChangePayload) => void;
  on_next_page: () => void;
  on_prev_page: () => void;
  on_page_size_change: (page_size: number) => void;
  on_retry: () => void;
  on_details_link_activated?: (payload: TransactionDetailsLinkActivatedPayload) => void;
};

const COLUMNS: Array<{
  key: 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method';
  label: 'Date' | 'Amount' | 'Status' | 'Merchant Name' | 'Payment Method';
  align?: 'left' | 'right';
  minWidthPx: number;
}> = [
  { key: 'date', label: 'Date', align: 'left', minWidthPx: 120 },
  { key: 'amount', label: 'Amount', align: 'right', minWidthPx: 120 },
  { key: 'status', label: 'Status', align: 'left', minWidthPx: 120 },
  { key: 'merchant_name', label: 'Merchant Name', align: 'left', minWidthPx: 200 },
  { key: 'payment_method', label: 'Payment Method', align: 'left', minWidthPx: 160 }
];

function getAriaSortForHeader(columnKey: string, sort: TransactionTableSort): 'none' | 'ascending' | 'descending' {
  if (sort.sort_key !== columnKey) return 'none';
  return sort.sort_direction === 'asc' ? 'ascending' : 'descending';
}

function nextSort(columnKey: string, current: TransactionTableSort): TransactionTableSort {
  if (current.sort_key === columnKey) {
    return { sort_key: columnKey, sort_direction: current.sort_direction === 'asc' ? 'desc' : 'asc' };
  }
  // Switching columns activates ascending per decision.
  return { sort_key: columnKey, sort_direction: 'asc' };
}

function formatDateYMDLocal(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function formatCurrency(amount: number | null): string {
  if (amount === null || amount === undefined) return '';
  try {
    // Currency not provided; use a safe default.
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amount);
  } catch {
    return amount.toFixed(2);
  }
}

