      <div style={styles.tableScroll}>
        <table style={styles.table}>
          <thead>
            <tr>
              {COLUMNS.map((col) => {
                const ariaSort = getAriaSortForHeader(col.key, sort);
                const thStyle = {
                  ...styles.th,
                  ...(col.align === 'right' ? styles.alignRight : null),
