              })}
            </tr>
          </thead>
          <tbody>
            {is_loading ? (
              Array.from({ length: 10 }).map((_, idx) => (
                <tr key={`sk_${idx}`} data-testid={`transaction-row-skeleton-${idx}`}>
                  {COLUMNS.map((col, cidx) => (
                    <td
                      key={`${idx}_${col.key}`}
                      style={{
                        ...styles.td,
                        ...(col.align === 'right' ? styles.alignRight : null),
                        minWidth: col.minWidthPx,
                      }}
                    >
                      <div style={styles.skeletonLine} aria-hidden="true" />
                    </td>
                  ))}
                </tr>
              ))
            ) : is_error ? (
              <tr>
                <td style={styles.stateCell} colSpan={COLUMNS.length}>
                  <div style={styles.errorBox}>
                    <div style={styles.errorTitle}>Transactions couldn’t be loaded</div>
                    <button type="button" style={styles.retryButton} onClick={on_retry}>
                      Retry
                    </button>
                  </div>
                </td>
              </tr>
            ) : isEmpty ? (
              <tr>
                <td style={styles.stateCell} colSpan={COLUMNS.length}>
                  No transactions
                </td>
              </tr>
            ) : (
              transactions.map((tx) => {
                const href = makeDetailsHref(hrefTemplate, tx.id);

                return (
                  <tr key={tx.id} style={styles.row}>
                    <td style={{ ...styles.td, minWidth: 120, position: 'relative' }}>
                      <a
                        href={href}
                        style={styles.rowOverlayLink}
                        aria-label={`View transaction ${tx.id}`}
                        onClick={() => {
                          on_details_link_activated?.({ transactionId: tx.id, href });
                        }}
                      />
                      <span style={styles.cellContent}>{formatDateYMDLocal(tx.date)}</span>
                    </td>
                    <td style={{ ...styles.td, ...styles.alignRight, minWidth: 120 }}>
                      {formatCurrency(tx.amount)}
                    </td>
                    <td style={{ ...styles.td, minWidth: 120 }}>
                      <TransactionStatusBadge status={tx.status} />
                    </td>
                    <td style={{ ...styles.td, minWidth: 200 }}>
                      <span
                        style={styles.truncate}
                        title={tx.merchant_name}
                        tabIndex={0}
                      >
                        {tx.merchant_name}
                      </span>
                    </td>
                    <td style={{ ...styles.td, minWidth: 160 }}>
                      <span
                        style={styles.truncate}
                        title={tx.payment_method}
                        tabIndex={0}
                      >
                        {tx.payment_method}
                      </span>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {!isEmpty && (
        <div style={styles.paginationWrap}>
          <TransactionTablePagination
            current_page={page}
            total_pages={total_pages}
            page_size={page_size}
            page_size_options={[25, 50, 100]}
            disabled={disabledInteractions}
            on_next_page={on_next_page}
            on_previous_page={on_prev_page}
            on_page_size_change={on_page_size_change}
          />
        </div>
      )}
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    background: 'var(--color-surface-default)',
    border: '1px solid var(--color-border-subtle)',
    borderRadius: 'var(--radius-12)',
    boxShadow: 'var(--shadow-sm)',
