type SupportedStatus = 'pending' | 'completed' | 'failed' | 'refunded';

export type TransactionStatusBadgeProps = {
  /** Transaction status value to render. */
  status: SupportedStatus | string;
  /** Optional override for the displayed badge text. */
  label?: string;
  /** Optional accessible label override for assistive technologies. */
  aria_label?: string;
};

const STATUS_LABELS: Record<SupportedStatus, string> = {
  pending: 'Pending',
  completed: 'Completed',
  failed: 'Failed',
  refunded: 'Refunded'
};

type BadgeTone = 'pending' | 'completed' | 'failed' | 'refunded' | 'unknown';

function getTone(status: string): BadgeTone {
  switch (status) {
    case 'pending':
    case 'completed':
    case 'failed':
    case 'refunded':
      return status;
    default:
      return 'unknown';
  }
}

function deriveVisibleLabel(status: string, labelOverride?: string): string {
  if (typeof labelOverride === 'string' && labelOverride.trim().length > 0) return labelOverride;

  const tone = getTone(status);
  if (tone === 'unknown') return 'Unknown';
  return STATUS_LABELS[tone];
}

/**
 * Dumb/presentational badge.
 * - Always renders visible text (not color-only).
 * - aria-label defaults to the visible text unless overridden.
 */
export function TransactionStatusBadge(props: TransactionStatusBadgeProps) {
  const { status, label, aria_label } = props;

  const tone = getTone(status);
  const visibleLabel = deriveVisibleLabel(status, label);
  const ariaLabel = (aria_label && aria_label.trim().length > 0 ? aria_label : visibleLabel).trim();

  return (
    <span role="status" aria-label={ariaLabel} data-tone={tone} style={styles.badge(tone)}>
      {visibleLabel}
    </span>
  );
}

const styles = {
  badge: (tone: BadgeTone): React.CSSProperties => {
    const { backgroundColor, borderColor, color } = getToneColors(tone);

    return {
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 'var(--spacing-4) var(--spacing-8)',
      borderRadius: '9999px',
      border: `1px solid ${borderColor}`,
      background: backgroundColor,
      color,
      fontSize: 'var(--font-size-label)',
      fontWeight: 'var(--font-weight-medium)',
      lineHeight: 1,
      whiteSpace: 'nowrap'
    };
  }
};

function getToneColors(tone: BadgeTone): {
  backgroundColor: string;
  borderColor: string;
  color: string;
} {
  // Use only whitelisted design tokens.
  switch (tone) {
    case 'completed':
      return {
        backgroundColor: 'var(--color-status-success)',
        borderColor: 'var(--color-status-success)',
        color: 'var(--color-surface-default)'
      };
    case 'pending':
      return {
        backgroundColor: 'var(--color-status-warning)',
        borderColor: 'var(--color-status-warning)',
        color: 'var(--color-surface-default)'
      };
    case 'failed':
      return {
        backgroundColor: 'var(--color-status-danger)',
        borderColor: 'var(--color-status-danger)',
        color: 'var(--color-surface-default)'
      };
    case 'refunded':
      // No "info" token is available; use muted surface with subtle border.
      return {
        backgroundColor: 'var(--color-surface-muted)',
        borderColor: 'var(--color-border-subtle)',
        color: 'var(--color-text-primary)'
      };
    case 'unknown':
    default:
      return {
        backgroundColor: 'var(--color-surface-muted)',
        borderColor: 'var(--color-border-subtle)',
        color: 'var(--color-text-secondary)'
      };
  }
}
