import { TransactionStatusBadge } from '../TransactionStatusBadge/TransactionStatusBadge';
import { TransactionTablePagination } from '../TransactionTablePagination/TransactionTablePagination';

type TransactionRow = {
  id: string;
  date: string; // ISO string
  amount: number | null;
  status: string;
  merchant_name: string;
  payment_method: string;
};

type TransactionTableSort = {
  sort_key: string;
  sort_direction: 'asc' | 'desc';
};

type TransactionTableSortChangePayload = {
  sort_key: string;
  sort_direction: 'asc' | 'desc';
};

type TransactionDetailsLinkActivatedPayload = {
  transactionId: string;
  href: string;
};

type Props = {
  transactions: TransactionRow[];
  is_loading: boolean;
  is_error: boolean;
  total_count: number;
  page: number;
  page_size: number;
  sort: TransactionTableSort;
  details_href_template?: string;
  on_sort_change: (payload: TransactionTableSortChangePayload) => void;
  on_next_page: () => void;
  on_prev_page: () => void;
  on_page_size_change: (page_size: number) => void;
  on_retry: () => void;
  on_details_link_activated?: (payload: TransactionDetailsLinkActivatedPayload) => void;
};

const COLUMNS: Array<{
  key: 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method';
  label: 'Date' | 'Amount' | 'Status' | 'Merchant Name' | 'Payment Method';
  align?: 'left' | 'right';
  minWidthPx: number;
}> = [
  { key: 'date', label: 'Date', align: 'left', minWidthPx: 120 },
  { key: 'amount', label: 'Amount', align: 'right', minWidthPx: 120 },
  { key: 'status', label: 'Status', align: 'left', minWidthPx: 120 },
  { key: 'merchant_name', label: 'Merchant Name', align: 'left', minWidthPx: 200 },
  { key: 'payment_method', label: 'Payment Method', align: 'left', minWidthPx: 160 }
];

function getAriaSortForHeader(columnKey: string, sort: TransactionTableSort): 'none' | 'ascending' | 'descending' {
  if (sort.sort_key !== columnKey) return 'none';
  return sort.sort_direction === 'asc' ? 'ascending' : 'descending';
}

function nextSort(columnKey: string, current: TransactionTableSort): TransactionTableSort {
  if (current.sort_key === columnKey) {
    return { sort_key: columnKey, sort_direction: current.sort_direction === 'asc' ? 'desc' : 'asc' };
  }
  // Switching columns activates ascending per decision.
  return { sort_key: columnKey, sort_direction: 'asc' };
}

function formatDateYMDLocal(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function formatCurrency(amount: number | null): string {
  if (amount === null || amount === undefined) return '';
  try {
    // Currency not provided; use a safe default.
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amount);
  } catch {
    return amount.toFixed(2);
  }
}

function makeDetailsHref(template: string, transactionId: string) {
  return template.replace('{transactionId}', transactionId);
}

export function TransactionTable(props: Props) {
  const {
    transactions,
    is_loading,
    is_error,
    total_count,
    page,
    page_size,
    sort,
    details_href_template,
    on_sort_change,
    on_next_page,
    on_prev_page,
    on_page_size_change,
    on_retry,
    on_details_link_activated,
  } = props;

  const disabledInteractions = is_loading || is_error;
  const isEmpty = !is_loading && !is_error && total_count === 0;

  const total_pages = useMemo(() => {
    const safePageSize = page_size > 0 ? page_size : 25;
    return Math.max(1, Math.ceil(Math.max(0, total_count) / safePageSize));
  }, [total_count, page_size]);

  const hrefTemplate = details_href_template ?? '/transactions/{transactionId}';

  const handleSortActivate = (columnKey: string) => {
    if (disabledInteractions) return;
    const next = nextSort(columnKey, sort);
    on_sort_change({ sort_key: next.sort_key, sort_direction: next.sort_direction });
  };

  return (
    <div style={styles.container}>
      <div style={styles.tableScroll}>
        <table style={styles.table}>
          <thead>
            <tr>
              {COLUMNS.map((col) => {
                const ariaSort = getAriaSortForHeader(col.key, sort);
                const thStyle = {
                  ...styles.th,
                  ...(col.align === 'right' ? styles.alignRight : null),
                  minWidth: col.minWidthPx,
                } as React.CSSProperties;

                return (
                  <th key={col.key} style={thStyle} aria-sort={ariaSort} scope="col">
                    <button
                      type="button"
                      style={styles.sortButton}
                      onClick={() => handleSortActivate(col.key)}
                      disabled={disabledInteractions}
                      aria-label={col.label}
                    >
                      {col.label}
                    </button>
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody>
            {is_loading ? (
              Array.from({ length: 10 }).map((_, idx) => (
                <tr key={`sk_${idx}`} data-testid={`transaction-row-skeleton-${idx}`}>
                  {COLUMNS.map((col, cidx) => (
                    <td
                      key={`${idx}_${col.key}`}
                      style={{
                        ...styles.td,
                        ...(col.align === 'right' ? styles.alignRight : null),
                        minWidth: col.minWidthPx,
                      }}
                    >
                      <div style={styles.skeletonLine} aria-hidden="true" />
                    </td>
                  ))}
                </tr>
              ))
            ) : is_error ? (
              <tr>
                <td style={styles.stateCell} colSpan={COLUMNS.length}>
                  <div style={styles.errorBox}>
                    <div style={styles.errorTitle}>Transactions couldn’t be loaded</div>
                    <button type="button" style={styles.retryButton} onClick={on_retry}>
                      Retry
                    </button>
                  </div>
                </td>
              </tr>
            ) : isEmpty ? (
              <tr>
                <td style={styles.stateCell} colSpan={COLUMNS.length}>
                  No transactions
                </td>
              </tr>
            ) : (
              transactions.map((tx) => {
                const href = makeDetailsHref(hrefTemplate, tx.id);

                return (
                  <tr key={tx.id} style={styles.row}>
                    <td style={{ ...styles.td, minWidth: 120, position: 'relative' }}>
                      <a
                        href={href}
                        style={styles.rowOverlayLink}
                        aria-label={`View transaction ${tx.id}`}
                        onClick={() => {
                          on_details_link_activated?.({ transactionId: tx.id, href });
                        }}
                      />
                      <span style={styles.cellContent}>{formatDateYMDLocal(tx.date)}</span>
                    </td>
                    <td style={{ ...styles.td, ...styles.alignRight, minWidth: 120 }}>
                      {formatCurrency(tx.amount)}
                    </td>
                    <td style={{ ...styles.td, minWidth: 120 }}>
                      <TransactionStatusBadge status={tx.status} />
                    </td>
                    <td style={{ ...styles.td, minWidth: 200 }}>
                      <span
                        style={styles.truncate}
                        title={tx.merchant_name}
                        tabIndex={0}
                      >
                        {tx.merchant_name}
                      </span>
                    </td>
                    <td style={{ ...styles.td, minWidth: 160 }}>
                      <span
                        style={styles.truncate}
                        title={tx.payment_method}
                        tabIndex={0}
                      >
                        {tx.payment_method}
                      </span>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {!isEmpty && (
        <div style={styles.paginationWrap}>
          <TransactionTablePagination
            current_page={page}
            total_pages={total_pages}
            page_size={page_size}
            page_size_options={[25, 50, 100]}
            disabled={disabledInteractions}
            on_next_page={on_next_page}
            on_previous_page={on_prev_page}
            on_page_size_change={on_page_size_change}
          />
        </div>
      )}
    </div>
  );
}

