ed transition shows header throughout and disables/re-enables sorting and pagination appropriately","Keyboard sorting (Enter/Space) on header updates aria-sort and triggers parent sort change; parent re-renders with new sort and data","Pagination Next/Previous and page-size change propagate via callbacks; parent updates page/page_size (reset to page 1 on size change) while preserving sort; pagination aria-live text updates","Row overlay link accessible name and href generation (default and template override) and navigation-style behavior; emits details activation callback payload","Unhappy boundary action: disabled Previous on first page blocks action and does not trigger callbacks; recovery via Next works","Unhappy error state: renders error message and Retry; disables sorting/pagination; Retry triggers refetch and recovers to loaded"],"coveredComponentCodes":["transaction_table","transaction_table_pagination","transaction_status_badge"],"coveredFlowCodes":["view_and_open_transaction_details","explore_sort_paginate_change_page_size_then_open_details","invalid_action_pagination_boundary_and_recovery","error_load_then_retry_success"],"coveredStates":["loading","default (loaded with rows)","error","first page boundary (Previous disabled)"],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.e2e.spec.tsx","content":"import React from 'react';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

type Tx = {
  id: string;
  date: string;
  amount: number | null;
  status: string;
  merchant_name: string;
  payment_method: string;
};

type Sort = { sort_key: string; sort_direction: 'asc' | 'desc' };

function makeTransactions(kind: 'page1' | 'page2'): Tx[] {
  if (kind === 'page1') {
    return [
      {
        id: 'tx_100',
        date: '2026-04-02T09:00:00.000Z',
        amount: 50,
        status: 'pending',
        merchant_name: 'Very Long Merchant Name That Should Probably Truncate In The Cell',
        payment_method: 'Visa •••• 1234',
      },
      {
        id: 'tx_101',
        date: '2026-04-01T12:34:56.000Z',
        amount: 10,
        status: 'completed',
        merchant_name: 'Coffee Shop',
        payment_method: 'Mastercard •••• 9999',
      },
      {
        id: 'tx_102',
        date: '2026-03-31T10:00:00.000Z',
        amount: null,
        status: 'refunded',
        merchant_name: 'Bookstore',
        payment_method: 'Amex •••• 0005',
      },
    ];
  }

  return [
    {
      id: 'tx_200',
      date: '2026-04-03T11:00:00.000Z',
      amount: 5,
      status: 'failed',
      merchant_name: 'Transit Authority',
      payment_method: 'Cash',
    },
    {
      id: 'tx_201',
      date: '2026-04-03T12:00:00.000Z',
      amount: 75,
      status: 'completed',
      merchant_name: 'Grocery',
      payment_method: 'Visa •••• 4444',
    },
  ];
}

function getHeaderCell(name: string) {
  return screen.getByRole('columnheader', { name });
}

function getSortButtonInHeader(name: string) {
  const th = getHeaderCell(name);
  return within(th).getByRole('button', { name: new RegExp(name, 'i') });
}

function getPaginationNav() {
  return screen.getByRole('navigation', { name: /transaction table pagination/i });
}

function getPageStatusText() {
  // text is defined in decisions: "Page X of Y" with aria-live polite
  return screen.getByText(/Page \d+ of \d+/i);
}

describe('TransactionTable composed workflow (integration/e2e)', () => {
  test('shortest happy: load -> render -> open details via overlay link', async () => {
    const user = userEvent.setup();

    const on_sort_change = jest.fn();
    const on_next_page = jest.fn();
    const on_prev_page = jest.fn();
    const on_page_size_change = jest.fn();
    const on_retry = jest.fn();
    const on_details_link_activated = jest.fn();

    const { rerender } = render(
      <TransactionTable
        transactions={[]}
        is_loading={true}
        is_error={false}
        total_count={50}
        page={1}
        page_size={25}
        sort={{ sort_key: 'date', sort_direction: 'desc' }}
        on_sort_change={on_sort_change}
        on_next_page={on_next_page}
        on_prev_page={on_prev_page}
        on_page_size_change={on_page_size_change}
        on_retry={on_retry}
        on_details_link_activated={on_details_link_activated}
      />
    );

    // Header visible during loading; skeleton rows present.
    expect(getHeaderCell('Date')).toBeInTheDocument();
    expect(screen.getAllByTestId(/transaction-row-skeleton/i)).toHaveLength(10);

    // Simulate fetch completion.
    rerender(
      <TransactionTable
        transactions={makeTransactions('page1')}
        is_loading={false}
        is_error={false}
        total_count={50}
        page={1}
        page_size={25}
        sort={{ sort_key: 'date', sort_direction: 'desc' }}
        on_sort_change={on_sort_change}
        on_next_page={on_next_page}
        on_prev_page={on_prev_page}
        on_page_size_change={on_page_size_change}
        on_retry={on_retry}
        on_details_link_activated={on_details_link_activated}
      />
    );

    // Default sort state reflected via aria-sort (active Date descending).
    expect(getHeaderCell('Date')).toHaveAttribute('aria-sort', 'descending');
    expect(getHeaderCell('Amount')).toHaveAttribute('aria-sort', 'none');

    // Open details via accessible overlay link.
    const link = screen.getByRole('link', { name: 'View transaction tx_100' });
    expect(link).toHaveAttribute('href', '/transactions/tx_100');

    await user.click(link);
    expect(on_details_link_activated).toHaveBeenCalledTimes(1);
    expect(on_details_link_activated).toHaveBeenCalledWith(
      expect.objectContaining({ transactionId: 'tx_100', href: '/transactions/tx_100' })
    );
  });

  test('exploratory happy: keyboard sort -> toggle -> paginate -> change page size resets page 1 (keeps sort) -> tooltip/title -> open details', async () => {
    const user = userEvent.setup();

    // Harness state
    let sort: Sort = { sort_key: 'date', sort_direction: 'desc' };
    let page = 1;
    let page_size: 25 | 50 | 100 = 25;

    const on_sort_change = jest.fn((payload: any) => {
      sort = { sort_key: payload.sort_key, sort_direction: payload.sort_direction };
      rerenderTable({ is_loading: true });
    });
    const on_next_page = jest.fn(() => {
      page = Math.min(page + 1, 2);
      rerenderTable({ is_loading: true });
    });
    const on_prev_page = jest.fn(() => {
      page = Math.max(page - 1, 1);
      rerenderTable({ is_loading: true });
    });
    const on_page_size_change = jest.fn((ps: number) => {
      page_size = ps as 25 | 50 | 100;
      page = 1;
      rerenderTable({ is_loading: true });
    });
    const on_retry = jest.fn();
    const on_details_link_activated = jest.fn();

    const getRowsForState = (): Tx[] => {
      const base = page === 1 ? makeTransactions('page1') : makeTransactions('page2');
      const copy = [...base];
      const key = sort.sort_key as keyof Tx;
      copy.sort((a, b) => {
        const av = a[key] as any;
        const bv = b[key] as any;
        const aNull = av === null || av === undefined || av === '';
        const bNull = bv === null || bv === undefined || bv === '';
        if (aNull && bNull) return 0;
        if (aNull) return 1;
        if (bNull) return -1;
        if (av < bv) return sort.sort_direction === 'asc' ? -1 : 1;
        if (av > bv) return sort.sort_direction === 'asc' ? 1 : -1;
        return 0;
      });
      return copy;
    };

    const baseProps = {
      total_count: 50,
      details_href_template: '/transactions/{transactionId}',
      on_sort_change,
      on_next_page,
      on_prev_page,
      on_page_size_change,
      on_retry,
      on_details_link_activated,
    };

    const { rerender } = render(
      <TransactionTable
        transactions={[]}
        is_loading={true}
        is_error={false}
        total_count={baseProps.total_count}
        page={page}
        page_size={page_size}
        sort={sort}
        details_href_template={baseProps.details_href_template}
        on_sort_change={baseProps.on_sort_change}
        on_next_page={baseProps.on_next_page}
        on_prev_page={baseProps.on_prev_page}
        on_page_size_change={baseProps.on_page_size_change}
        on_retry={baseProps.on_retry}
        on_details_link_activated={baseProps.on_details_link_activated}
      />
    );

    function rerenderTable(override: Partial<{ is_loading: boolean; is_error: boolean }> = {}) {
      const is_loading = override.is_loading ?? false;
      const is_error = override.is_error ?? false;

      rerender(
        <TransactionTable
          transactions={is_loading || is_error ? [] : getRowsForState()}
          is_loading={is_loading}
          is_error={is_error}
          total_count={baseProps.total_count}
          page={page}
          page_size={page_size}
          sort={sort}
          details_href_template={baseProps.details_href_template}
          on_sort_change={baseProps.on_sort_change}
          on_next_page={baseProps.on_next_page}
          on_prev_page={baseProps.on_prev_page}
          on_page_size_change={baseProps.on_page_size_change}
          on_retry={baseProps.on_retry}
          on_details_link_activated={baseProps.on_details_link_activated}
        />
      );
    }

    // Initial load completes.
    rerenderTable({ is_loading: false });
    expect(getHeaderCell('Date')).toHaveAttribute('aria-sort', 'descending');

    // Keyboard sort by Amount (Enter) should request sort change; harness transitions loading then loaded.
    const amountBtn = getSortButtonInHeader('Amount');
    amountBtn.focus();
    await user.keyboard('{Enter}');
    expect(on_sort_change).toHaveBeenCalledTimes(1);

    // During transition, skeleton rows and disabled pagination.
    expect(screen.getAllByTestId(/transaction-row-skeleton/i)).toHaveLength(10);
    const navDuringSort = getPaginationNav();
    expect(within(navDuringSort).getByRole('button', { name: /next page/i })).toBeDisabled();

    // Complete sort load: set the state as if parent applied Amount asc (per decision for switching columns).
    sort = { sort_key: 'amount', sort_direction: 'asc' };
    rerenderTable({ is_loading: false });
    expect(getHeaderCell('Amount')).toHaveAttribute('aria-sort', 'ascending');
    expect(getHeaderCell('Date')).toHaveAttribute('aria-sort', 'none');

    // Toggle sort (Space) to descending.
    amountBtn.focus();
    await user.keyboard(' ');
    expect(on_sort_change).toHaveBeenCalledTimes(2);
    sort = { sort_key: 'amount', sort_direction: 'desc' };
    rerenderTable({ is_loading: false });
    expect(getHeaderCell('Amount')).toHaveAttribute('aria-sort', 'descending');

    // Paginate Next.
    const nav = getPaginationNav();
    const next = within(nav).getByRole('button', { name: /next page/i });
    await user.click(next);
    expect(on_next_page).toHaveBeenCalledTimes(1);
    // Transition state
    expect(screen.getAllByTestId(/transaction-row-skeleton/i)).toHaveLength(10);

    // Complete page change.
    page = 2;
    rerenderTable({ is_loading: false });
    // Pagination text should update.
    const pageStatus = getPageStatusText();
    expect(pageStatus).toHaveTextContent(/Page 2 of/i);
    expect(pageStatus).toHaveAttribute('aria-live', 'polite');

    // Change page size to 100 -> resets to page 1 while keeping sort.
    const nav2 = getPaginationNav();
    const select = within(nav2).getByRole('combobox', { name: /page size/i });
    await user.selectOptions(select, '100');
    expect(on_page_size_change).toHaveBeenCalledTimes(1);
    expect(on_page_size_change).toHaveBeenCalledWith(100);

    // Complete page size change.
    page_size = 100;
    page = 1;
    rerenderTable({ is_loading: false });
    expect(getHeaderCell('Amount')).toHaveAttribute('aria-sort', 'descending');
    expect(getPageStatusText()).toHaveTextContent(/Page 1 of/i);

    // Tooltip/title fallback exposure for long merchant name (baseline: title attr).
    const longMerchant = makeTransactions('page1')[0].merchant_name;
    expect(screen.getByTitle(longMerchant)).toBeInTheDocument();

    // Open details from explored state.
    const link = screen.getByRole('link', { name: 'View transaction tx_100' });
    await user.click(link);
    expect(on_details_link_activated).toHaveBeenCalled();
    expect(on_details_link_activated).toHaveBeenLastCalledWith(
      expect.objectContaining({ transactionId: 'tx_100', href: '/transactions/tx_100' })
    );
  });

  test('unhappy invalid action: cannot go previous on first page; recover by going next', async () => {
    const user = userEvent.setup();

    const on_sort_change = jest.fn();
    const on_next_page = jest.fn();
    const on_prev_page = jest.fn();
    const on_page_size_change = jest.fn();
    const on_retry = jest.fn();

    render(
      <TransactionTable
        transactions={makeTransactions('page1')}
        is_loading={false}
        is_error={false}
        total_count={50}
        page={1}
        page_size={25}
        sort={{ sort_key: 'date', sort_direction: 'desc' }}
        on_sort_change={on_sort_change}
        on_next_page={on_next_page}
        on_prev_page={on_prev_page}
        on_page_size_change={on_page_size_change}
        on_retry={on_retry}
      />
    );

    const nav = getPaginationNav();
    expect(getPageStatusText()).toHaveTextContent('Page 1 of');

    const prev = within(nav).getByRole('button', { name: /previous page/i });
    const next = within(nav).getByRole('button', { name: /next page/i });

    expect(prev).toBeDisabled();
    expect(next).not.toBeDisabled();

    // Attempt invalid action at boundary.
    await user.click(prev);
    expect(on_prev_page).not.toHaveBeenCalled();
    // Page text stays stable.
    expect(getPageStatusText()).toHaveTextContent('Page 1 of');

    // Recover by using enabled control.
    await user.click(next);
    expect(on_next_page).toHaveBeenCalledTimes(1);
  });

  test('unhappy error then retry success: error disables interactions; retry triggers callback; then renders rows', async () => {
    const user = userEvent.setup();

    const on_sort_change = jest.fn();
    const on_next_page = jest.fn();
    const on_prev_page = jest.fn();
    const on_page_size_change = jest.fn();
    const on_retry = jest.fn();

    const { rerender } = render(
      <TransactionTable
        transactions={[]}
        is_loading={false}
        is_error={true}
        total_count={50}
        page={1}
        page_size={25}
        sort={{ sort_key: 'date', sort_direction: 'desc' }}
        on_sort_change={on_sort_change}
        on_next_page={on_next_page}
        on_prev_page={on_prev_page}
        on_page_size_change={on_page_size_change}
        on_retry={on_retry}
      />
    );

    expect(screen.getByText(/Transactions couldn’t be loaded/i)).toBeInTheDocument();

    // Sorting should be blocked in error.
    const dateBtn = getSortButtonInHeader('Date');
    await user.click(dateBtn);
    expect(on_sort_change).not.toHaveBeenCalled();

    // Pagination should be disabled in error.
    const nav = getPaginationNav();
    expect(within(nav).getByRole('button', { name: /next page/i })).toBeDisabled();
    expect(within(nav).getByRole('button', { name: /previous page/i })).toBeDisabled();
    expect(within(nav).getByRole('combobox', { name: /page size/i })).toBeDisabled();

    // Retry.
    const retry = screen.getByRole('button', { name: /retry/i });
    await user.click(retry);
    expect(on_retry).toHaveBeenCalledTimes(1);

    // Simulate retry loading then success.
    rerender(
      <TransactionTable
        transactions={[]}
        is_loading={true}
        is_error={false}
        total_count={50}
        page={1}
        page_size={25}
        sort={{ sort_key: 'date', sort_direction: 'desc' }}
        on_sort_change={on_sort_change}
        on_next_page={on_next_page}
        on_prev_page={on_prev_page}
        on_page_size_change={on_page_size_change}
        on_retry={on_retry}
      />
    );
    expect(screen.getAllByTestId(/transaction-row-skeleton/i)).toHaveLength(10);

    rerender(
      <TransactionTable
        transactions={makeTransactions('page1')}
        is_loading={false}
        is_error={false}
        total_count={50}
        page={1}
        page_size={25}
        sort={{ sort_key: 'date', sort_direction: 'desc' }}
        on_sort_change={on_sort_change}
        on_next_page={on_next_page}
        on_prev_page={on_prev_page}
        on_page_size_change={on_page_size_change}
        on_retry={on_retry}
      />
    );

    // Error replaced by data.
    expect(screen.queryByText(/Transactions couldn’t be loaded/i)).not.toBeInTheDocument();
    expect(screen.getByRole('link', { name: 'View transaction tx_100' })).toBeInTheDocument();

    // Pagination interactive again.
    const navAfter = getPaginationNav();
    expect(within(navAfter).getByRole('button', { name: /next page/i })).not.toBeDisabled();
  });
});
"}],"rootComponentCode":"transaction_table","rootComponentName":"Transaction Table"},"framework":"React","gapAnalysis":{"accessibilityGaps":["Define keyboard interaction for sortable headers (tab focus, Enter/Space to sort) and announce sort state via aria-sort","Row click opens details but no accessible affordance is defined (e.g., row as link/button with role and accessible name) or alternative action for keyboard users","Pagination controls need explicit labeling for screen readers (current page, next/previous, page size selector) and focus order behavior","Status conveyed by color only is possible; specify text/aria-label remains present and ensure badge meaning is announced non-visually","Specify focus-visible styling for interactive elements (headers, rows, pagination) to meet keyboard usability"],"missingStates":["Loading state for initial fetch and for sort/pagination transitions (skeleton/placeholder vs spinner)","Empty state when there are no transactions (and whether headers/pagination remain visible)","Error state for failed data fetch (and retry behavior)","No-results state when the dataset is empty due to filtering/search (even if filtering is out of scope, clarify if applicable or omit)","Disabled states for pagination at boundaries (first/last page) and for unavailable page size options","Unknown/unsupported status value handling (fallback badge style/label)"],"recommendations":["Specify table column data formats and alignment rules: date format/timezone, currency formatting for amount, right/left alignment, and negative/zero handling","Define sorting rules per column: default sort column/direction, tri-state vs bi-state toggling, stable sort behavior, and how null/blank values sort","Define pagination UI specifics: which controls appear (prev/next, first/last, page numbers), where the 25/50/100 selector lives, and whether page resets to 1 when page size changes","Clarify the navigation pattern for row click: opens modal drawer vs new page/route, whether middle-click/new-tab is supported, and whether there is a dedicated 'View details' action","Provide explicit status-to-style mapping (badge background/text colors) and contrast requirements; include fallback styling for unknown statuses","Document data overflow behavior per column (truncate with ellipsis, wrap, tooltip on hover/focus) especially for merchant name and payment method"],"responsiveGaps":["Define small-screen behavior for 5-column table (horizontal scroll vs column stacking vs hiding lower-priority columns)","Specify how pagination layout adapts on mobile (page size selector placement, collapsing page numbers, sticky footer/header behavior)","Define responsive truncation/line-wrapping rules for long merchant names and payment methods to avoid layout breakage","Clarify minimum column widths and whether the table becomes scrollable within a container to prevent viewport overflow"]},"parsing":{"businessContext":"View and browse a list of transactions with sorting, pagination, status indicators, and access to transaction details.","components":[{"code":"transaction_table","name":"Transaction Table","parentCode":null,"purpose":"Display transactions in a sortable, paginated table with status badges and row-level access to details.","statePolicy":"smart","type":"table"},{"code":"transaction_table_pagination","name":"Transaction Table Pagination","parentCode":"transaction_table","purpose":"Control page navigation and page size for the transaction list.","statePolicy":"smart","type":"pagination"},{"code":"transaction_status_badge","name":"Transaction Status Badge","parentCode":"transaction_table","purpose":"Render a colored status badge for each transaction status value.","statePolicy":"dumb","type":"badge"}],"constraints":[{"componentCode":"transaction_table","description":"Supports sorting by any column.","type":"sorting"},{"componentCode":"transaction_table","description":"Pagination supports 25/50/100 items per page.","type":"pagination"}],"content":[{"code":"col_date","componentCode":"transaction_table","description":"Transaction date column.","kind":"column","name":"Date","isRequired":true},{"code":"col_amount","componentCode":"transaction_table","description":"Transaction amount column.","kind":"column","name":"Amount","isRequired":true},{"code":"col_status","componentCode":"transaction_table","description":"Transaction status column rendered with a colored badge.","kind":"column","name":"Status","isRequired":true},{"code":"col_merchant_name","componentCode":"transaction_table","description":"Merchant name column.","kind":"column","name":"Merchant Name","isRequired":true},{"code":"col_payment_method","componentCode":"transaction_table","description":"Payment method column.","kind":"column","name":"Payment Method","isRequired":true},{"code":"status_pending","componentCode":"transaction_status_badge","description":"Pending status value.","kind":"status","name":"Pending","isRequired":true},{"code":"status_completed","componentCode":"transaction_status_badge","description":"Completed status value.","kind":"status","name":"Completed","isRequired":true},{"code":"status_failed","componentCode":"transaction_status_badge","description":"Failed status value.","kind":"status","name":"Failed","isRequired":true},{"code":"status_refunded","componentCode":"transaction_status_badge","description":"Refunded status value.","kind":"status","name":"Refunded","isRequired":true}],"interactions":[{"code":"sort_by_column","componentCode":"transaction_table","description":"Sort transactions by the selected column.","targetComponentCode":null,"type":"sort"},{"code":"paginate_transactions","componentCode":"transaction_table_pagination","description":"Navigate between pages and change items per page (25/50/100).","targetComponentCode":"transaction_table","type":"paginate"},{"code":"open_transaction_details","componentCode":"transaction_table","description":"Clicking a row opens the transaction details view.","targetComponentCode":null,"type":"open_details"}],"rootComponentCode":"transaction_table","specifiedStates":[],"tokenReferences":[{"componentCode":"transaction_status_badge","description":"Badge colors mapped per status (pending, completed, failed, refunded).","name":"status color","type":"color"}]},"projectRootPath":"/app/generated/frontend","relatedComponentInterfaces":[{"accepts":[{"description":"Transaction status value to render as a labeled, colored badge. Supported: "pending", "completed", "failed", "refunded". Unknown/unsupported values should render a neutral gray badge labeled "Unknown".","name":"status","required":true,"type":""pending" | "completed" | "failed" | "refunded" | string"},{"description":"Optional override for the displayed badge text. If omitted, the component derives the label from `status` (e.g., pending -> "Pending"), and uses "Unknown" for unsupported values.","name":"label","required":false,"type":"string"},{"description":"Optional accessible label override for assistive technologies. If omitted, aria-label matches the visible text label.","name":"aria_label","required":false,"type":"string"}],"componentCode":"transaction_status_badge","componentName":"Transaction Status Badge","returns":[]}],"relatedComponentSourceFiles":[{"componentCode":"transaction_status_badge","filename":"/app/generated/frontend/src/components/TransactionStatusBadge/TransactionStatusBadge.tsx"}],"resolvingGaps":{"decisions":[{"affectedComponentCodes":["transaction_table"],"code":"sortable_header_keyboard_and_aria_sort","decision":"Implement each sortable column header as a focusable button within the <th>. Support Enter/Space to toggle sorting on that column. Apply aria-sort on the corresponding <th> with values "none" (unsorted), "ascending", or "descending"; only the actively sorted column has ascending/descending and all others are "none".","rationale":"This defines a complete keyboard interaction and a standards-based announcement of sort state without changing the visual design requirements, enabling accessible sorting for all columns.","sourceGap":"Define keyboard interaction for sortable headers (tab focus, Enter/Space to sort) and announce sort state via aria-sort"},{"affectedComponentCodes":["transaction_table"],"code":"row_details_accessible_action","decision":"Make the first cell in each row (Date) contain a full-row overlay anchor link styled to cover the row hit area. The link navigates to a details route pattern "/transactions/{transactionId}". The link accessible name is "View transaction {transactionId}". Preserve standard link behaviors (keyboard Enter, open in new tab via context menu/middle click).","rationale":"Using a real link provides a clear, keyboard-accessible affordance for opening details and supports common navigation expectations conservatively without inventing a modal/drawer pattern.","sourceGap":"Row click opens details but no accessible affordance is defined (e.g., row as link/button with role and accessible name) or alternative action for keyboard users"},{"affectedComponentCodes":["transaction_table_pagination"],"code":"pagination_controls_labels_and_focus","decision":"Pagination includes: Previous button, Next button, and a page size <select> with options 25/50/100. Wrap controls in a <nav aria-label="Transaction table pagination">. Previous/Next have aria-label "Previous page" / "Next page" and use disabled=true at boundaries. Render current page text "Page X of Y" as an aria-live="polite" region that updates on page changes. Tab order is Previous -> Next -> Page size selector.","rationale":"This specifies explicit labels, boundary disabled behavior, and a deterministic focus order while keeping the UI minimal and consistent with the brief (no requirement for page numbers/first/last).","sourceGap":"Pagination controls need explicit labeling for screen readers (current page, next/previous, page size selector) and focus order behavior"},{"affectedComponentCodes":["transaction_status_badge"],"code":"status_badge_text_not_color_only","decision":"Always render the status text inside the badge (e.g., "Pending"). The badge element includes aria-label identical to the visible text. Do not rely on color to convey meaning; color is supplementary only.","rationale":"Keeping status text present ensures non-visual users receive the same information and resolves the risk of color-only encoding without requiring extra UI elements.","sourceGap":"Status conveyed by color only is possible; specify text/aria-label remains present and ensure badge meaning is announced non-visually"},{"affectedComponentCodes":["transaction_table","transaction_table_pagination"],"code":"focus_visible_styles","decision":"Apply a consistent focus-visible ring to interactive elements: sortable header buttons, row overlay links, pagination buttons, and the page size select. Use a 2px outline with 2px offset and ensure it is visible on all status badge background colors.","rationale":"Explicit focus-visible styling ensures keyboard usability across all interactive controls without prescribing a full theme, and it is a conservative accessibility baseline.","sourceGap":"Specify focus-visible styling for interactive elements (headers, rows, pagination) to meet keyboard usability"},{"affectedComponentCodes":["transaction_table"],"code":"loading_empty_error_states","decision":"Add three table-level states: (1) Loading: show 10-row skeleton placeholders while retaining the table header; disable sorting and pagination controls. (2) Empty: show a single full-width row message "No transactions"; keep headers visible and hide pagination. (3) Error: show a full-width message "Transactions couldn’t be loaded" with a "Retry" button that re-triggers fetch; keep headers visible and disable sorting/pagination until success.","rationale":"These states cover the primary data lifecycle gaps (loading/empty/error) in a way that preserves layout stability and defines control availability for downstream implementation and tests.","sourceGap":"Loading state for initial fetch and for sort/pagination transitions (skeleton/placeholder vs spinner)"},{"affectedComponentCodes":["transaction_table"],"code":"sort_behavior_defaults_and_nulls","decision":"Default sort is Date descending. Sorting is bi-state per column: selecting a column toggles ascending/descending; selecting a different column activates that column in ascending order. Sorting is stable. Null/blank values always sort last in both directions.","rationale":"This fully specifies predictable sort rules (default, toggling, stability, null handling) with conservative choices commonly used in transaction tables.","sourceGap":"Define sorting rules per column: default sort column/direction, tri-state vs bi-state toggling, stable sort behavior, and how null/blank values sort"},{"affectedComponentCodes":["transaction_table_pagination"],"code":"pagination_page_size_change_resets","decision":"When page size changes (25/50/100), reset to page 1 and refetch/recompute the dataset for that new size. Keep the current sort applied.","rationale":"Resetting to page 1 prevents out-of-range pages after size changes and preserves the user’s chosen ordering, minimizing surprises and edge cases.","sourceGap":"Define pagination UI specifics: which controls appear (prev/next, first/last, page numbers), where the 25/50/100 selector lives, and whether page resets to 1 when page size changes"},{"affectedComponentCodes":["transaction_table"],"code":"column_formats_and_alignment","decision":"Date displays as "YYYY-MM-DD" in the user’s local timezone. Amount displays as a currency formatted using the user locale with two decimal places; negative amounts display with a leading minus sign. Align Amount right; all other columns left.","rationale":"This resolves formatting and alignment ambiguities with locale-safe defaults and conventional financial table alignment without requiring additional inputs.","sourceGap":"Specify table column data formats and alignment rules: date format/timezone, currency formatting for amount, right/left alignment, and negative/zero handling"},{"affectedComponentCodes":["transaction_status_badge"],"code":"status_to_style_mapping_and_unknown_fallback","decision":"Map statuses to badge styles: pending=amber, completed=green, failed=red, refunded=blue. Ensure text contrast meets WCAG AA for normal text. For unknown/unsupported status values, render a neutral gray badge with text "Unknown" and aria-label "Unknown".","rationale":"This provides an explicit mapping plus an accessible fallback, preventing rendering failures when new status values appear.","sourceGap":"Unknown/unsupported status value handling (fallback badge style/label)"},{"affectedComponentCodes":["transaction_table"],"code":"overflow_truncation_with_tooltips","decision":"Merchant Name and Payment Method cells are single-line with truncation (ellipsis). On hover and keyboard focus, show a tooltip containing the full text; the cell also includes a title attribute with the full value as a baseline fallback.","rationale":"This prevents layout breakage from long strings while still enabling access to the full content for mouse and keyboard users with a conservative fallback.","sourceGap":"Document data overflow behavior per column (truncate with ellipsis, wrap, tooltip on hover/focus) especially for merchant name and payment method"},{"affectedComponentCodes":["transaction_table","transaction_table_pagination"],"code":"responsive_horizontal_scroll_and_min_widths","decision":"On small screens, keep the 5-column table and enable horizontal scrolling within a container (overflow-x:auto) rather than stacking/hiding columns. Set minimum widths: Date 120px, Amount 120px, Status 120px, Merchant Name 200px, Payment Method 160px. Pagination stays below the table; controls wrap to two lines if needed with page size selector on the second line.","rationale":"Horizontal scroll is the most conservative responsive strategy for dense tabular data, and minimum widths prevent column collapse while keeping behavior deterministic for implementation.","sourceGap":"Define small-screen behavior for 5-column table (horizontal scroll vs column stacking vs hiding lower-priority columns)"}]},"targetComponent":{"code":"transaction_table","name":"Transaction Table","parentCode":null,"purpose":"Display transactions in a sortable, paginated table with status badges and row-level access to details.","statePolicy":"smart","type":"table"},"targetComponentInterface":{"accepts":[{"description":"Array of transactions to render in the table for the current page (already paginated upstream). Each item must include id, date, amount, status, merchant_name, payment_method.","name":"transactions","required":true,"type":"TransactionRow[]"},{"description":"Whether the table is currently loading (initial load or during sort/pagination transitions). When true, show 10-row skeleton placeholders, keep header visible, and disable sorting/pagination interactions.","name":"is_loading","required":true,"type":"boolean"},{"description":"Whether the table is in an error state after a failed fetch. When true, show error message row and Retry action; disable sorting/pagination interactions.","name":"is_error","required":true,"type":"boolean"},{"description":"Total number of transactions across all pages, used to compute page count and drive pagination visibility ('hide pagination when empty').","name":"total_count","required":true,"type":"number"},{"description":"Current 1-based page index.","name":"page","required":true,"type":"number"},{"description":"Current page size. Must be one of 25, 50, 100.","name":"page_size","required":true,"type":"number"},{"description":"Current active sort state applied to the dataset. Default is { sort_key: 'date', sort_direction: 'desc' }. Only the active column should have aria-sort ascending/descending; others are 'none'.","name":"sort","required":true,"type":"TransactionTableSort"},{"description":"Optional override for the route pattern used by the row overlay link. Supports token {transactionId}. Defaults to '/transactions/{transactionId}'.","name":"details_href_template","required":false,"type":"string"},{"description":"Callback invoked when a sortable column header is activated (click or Enter/Space). Parent should apply the specified sort rules (bi-state toggling, stable sort, nulls last) and update data + sort prop.","name":"on_sort_change","required":true,"type":"(payload: TransactionTableSortChangePayload) => void"},{"description":"Callback invoked when the user requests the next page from pagination controls.","name":"on_next_page","required":true,"type":"() => void"},{"description":"Callback invoked when the user requests the previous page from pagination controls.","name":"on_prev_page","required":true,"type":"() => void"},{"description":"Callback invoked when the page size selector changes (25/50/100). Parent should reset to page 1 while preserving current sort and refresh data.","name":"on_page_size_change","required":true,"type":"(page_size: number) => void"},{"description":"Callback invoked when the Retry button is activated in the error state to re-trigger fetching.","name":"on_retry","required":true,"type":"() => void"}],"componentCode":"transaction_table","componentName":"Transaction Table","returns":[{"description":"Emitted when the user activates a row overlay link to open transaction details (primary click/keyboard activation). Useful for analytics or interception; navigation is performed by the link itself unless prevented externally.","name":"details_link_activated","required":false,"type":"TransactionDetailsLinkActivatedPayload"}]},"targetSourceFilePath":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.tsx","targetUnitTests":{"componentCode":"transaction_table","componentName":"Transaction Table","coveredBehaviors":["Renders table column headers (Date, Amount, Status, Merchant Name, Payment Method)","Applies aria-sort="descending" to the active sorted column header (Date) and aria-sort="none" to others","Invokes on_sort_change on sortable header click with bi-state toggling when the active column is clicked again","Invokes on_sort_change on Enter/Space keydown on sortable header buttons","Disables sorting interactions while is_loading=true or is_error=true","Loading state renders 10 skeleton rows and keeps header visible","Error state renders error message and Retry button; Retry invokes on_retry; sorting/pagination disabled","Empty state renders "No transactions" and hides pagination","Renders row overlay link in Date cell with accessible name "View transaction {transactionId}"","Row overlay link href defaults to /transactions/{transactionId} and supports override via details_href_template","Emits details_link_activated event payload when overlay link is clicked","Amount cells are right-aligned","Merchant Name and Payment Method cells include title attributes with full text for overflow fallback"],"coveredStates":["default (loaded with rows)","loading","error","empty"],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.spec.tsx","content":"import React from 'react';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

jest.mock('../TransactionStatusBadge/TransactionStatusBadge', () => ({
  TransactionStatusBadge: ({ status, label, aria_label }: any) => (
    <span data-testid="status-badge" aria-label={aria_label ?? label ?? String(status)}>
      {label ?? String(status)}
    </span>
  ),
}));

jest.mock('../TransactionTablePagination/TransactionTablePagination', () => ({
  TransactionTablePagination: (props: any) => (
    <div data-testid="pagination">
      <button onClick={props.on_previous_page} disabled={!!props.disabled} aria-label="Previous page">
        Previous
      </button>
      <button onClick={props.on_next_page} disabled={!!props.disabled} aria-label="Next page">
        Next
      </button>
      <label>
        Page size
        <select
          aria-label="Page size"
          disabled={!!props.disabled}
          value={props.page_size}
          onChange={(e) => props.on_page_size_change(Number((e.target as HTMLSelectElement).value))}
        >
          {(props.page_size_options ?? [25, 50, 100]).map((n: number) => (
            <option key={n} value={n}>
              {n}
            </option>
          ))}
        </select>
      </label>
      <div aria-live="polite">Page {props.current_page} of {props.total_pages}</div>
    </div>
  ),
}));

type Tx = {
  id: string;
  date: string;
  amount: number | null;
  status: string;
  merchant_name: string;
  payment_method: string;
};

defaultProps = undefined as unknown as {
  transactions: Tx[];
  is_loading: boolean;
  is_error: boolean;
  total_count: number;
  page: number;
  page_size: 25 | 50 | 100;
  sort: { sort_key: string; sort_direction: 'asc' | 'desc' };
  details_href_template?: string;
  on_sort_change: jest.Mock;
  on_next_page: jest.Mock;
  on_prev_page: jest.Mock;
  on_page_size_change: jest.Mock;
  on_retry: jest.Mock;
  on_details_link_activated?: jest.Mock;
};

const makeProps = (overrides: Partial<any> = {}) => {
  const props = {
    transactions: [
      {
        id: 'tx_1',
        date: '2026-04-01T12:34:56.000Z',
        amount: 123.45,
        status: 'pending',
        merchant_name: 'Very Long Merchant Name That Should Probably Truncate In The Cell',
        payment_method: 'Visa •••• 1234',
      },
      {
        id: 'tx_2',
        date: '2026-04-02T09:00:00.000Z',
        amount: -10,
        status: 'completed',
        merchant_name: 'Coffee Shop',
        payment_method: 'Mastercard •••• 9999',
      },
    ] as Tx[],
    is_loading: false,
    is_error: false,
    total_count: 50,
    page: 1,
    page_size: 25,
    sort: { sort_key: 'date', sort_direction: 'desc' as const },
    on_sort_change: jest.fn(),
    on_next_page: jest.fn(),
    on_prev_page: jest.fn(),
    on_page_size_change: jest.fn(),
    on_retry: jest.fn(),
    on_details_link_activated: jest.fn(),
    ...overrides,
  };
  return props;
};

const getHeaderCell = (name: string) => screen.getByRole('columnheader', { name });

describe('TransactionTable', () => {
  test('renders headers and sets aria-sort only on active sorted column', () => {
    const props = makeProps({ sort: { sort_key: 'date', sort_direction: 'desc' } });
    render(<TransactionTable {...props} />);

    expect(getHeaderCell('Date')).toBeInTheDocument();
    expect(getHeaderCell('Amount')).toBeInTheDocument();
    expect(getHeaderCell('Status')).toBeInTheDocument();
    expect(getHeaderCell('Merchant Name')).toBeInTheDocument();
    expect(getHeaderCell('Payment Method')).toBeInTheDocument();

    expect(getHeaderCell('Date')).toHaveAttribute('aria-sort', 'descending');
    expect(getHeaderCell('Amount')).toHaveAttribute('aria-sort', 'none');
    expect(getHeaderCell('Status')).toHaveAttribute('aria-sort', 'none');
    expect(getHeaderCell('Merchant Name')).toHaveAttribute('aria-sort', 'none');
    expect(getHeaderCell('Payment Method')).toHaveAttribute('aria-sort', 'none');
  });

  test('invokes on_sort_change when clicking a sortable header and toggles direction when re-sorting same column', async () => {
    const user = userEvent.setup();

    const props = makeProps({ sort: { sort_key: 'amount', sort_direction: 'asc' } });
    render(<TransactionTable {...props} />);

    const amountHeader = getHeaderCell('Amount');
    const amountSortButton = within(amountHeader).getByRole('button', { name: /amount/i });

    await user.click(amountSortButton);
    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
    // bi-state toggle
    expect(props.on_sort_change.mock.calls[0][0]).toEqual(
      expect.objectContaining({ sort_key: 'amount', sort_direction: 'desc' })
    );
  });

  test('invokes on_sort_change via keyboard Enter/Space on header button', async () => {
    const user = userEvent.setup();

    const props = makeProps({ sort: { sort_key: 'date', sort_direction: 'desc' } });
    render(<TransactionTable {...props} />);

    const statusHeader = getHeaderCell('Status');
    const statusSortButton = within(statusHeader).getByRole('button', { name: /status/i });

    statusSortButton.focus();
    expect(statusSortButton).toHaveFocus();

    await user.keyboard('{Enter}');
    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
    // switching to a different column activates ascending
    expect(props.on_sort_change.mock.calls[0][0]).toEqual(
      expect.objectContaining({ sort_key: expect.any(String), sort_direction: 'asc' })
    );

    props.on_sort_change.mockClear();
    statusSortButton.focus();
    await user.keyboard(' ');
    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
  });

  test('disables sorting interactions while loading', async () => {
    const user = userEvent.setup();
    const props = makeProps({ is_loading: true });
    render(<TransactionTable {...props} />);

    const amountHeader = getHeaderCell('Amount');
    const amountSortButton = within(amountHeader).getByRole('button', { name: /amount/i });

    await user.click(amountSortButton);
    expect(props.on_sort_change).not.toHaveBeenCalled();
  });

  test('loading state renders 10 skeleton rows and keeps header visible', () => {
    const props = makeProps({ is_loading: true, transactions: [] });
    render(<TransactionTable {...props} />);

    // header visible
    expect(getHeaderCell('Date')).toBeInTheDocument();

    // skeleton rows
    const skeletons = screen.getAllByTestId(/transaction-row-skeleton/i);
    expect(skeletons).toHaveLength(10);
  });

  test('error state renders message and Retry button; retry invokes on_retry; sorting/pagination disabled', async () => {
    const user = userEvent.setup();
    const props = makeProps({ is_error: true, transactions: [], total_count: 50 });
    render(<TransactionTable {...props} />);

    expect(screen.getByText(/Transactions couldn’t be loaded/i)).toBeInTheDocument();

    const retry = screen.getByRole('button', { name: /retry/i });
    await user.click(retry);
    expect(props.on_retry).toHaveBeenCalledTimes(1);

    // sorting disabled in error
    const dateHeader = getHeaderCell('Date');
    const dateSortButton = within(dateHeader).getByRole('button', { name: /date/i });
    await user.click(dateSortButton);
    expect(props.on_sort_change).not.toHaveBeenCalled();

    // pagination exists but disabled when error
    const pagination = screen.getByTestId('pagination');
    expect(within(pagination).getByRole('button', { name: /next page/i })).toBeDisabled();
    expect(within(pagination).getByRole('button', { name: /previous page/i })).toBeDisabled();
    expect(within(pagination).getByRole('combobox', { name: /page size/i })).toBeDisabled();
  });

  test('empty state shows "No transactions" and hides pagination', () => {
    const props = makeProps({ transactions: [], total_count: 0, is_loading: false, is_error: false });
    render(<TransactionTable {...props} />);

    expect(screen.getByText(/no transactions/i)).toBeInTheDocument();
    expect(screen.queryByTestId('pagination')).not.toBeInTheDocument();
  });

  test('renders row overlay link with default href and accessible name; click emits details_link_activated', async () => {
    const user = userEvent.setup();
    const props = makeProps();
    render(<TransactionTable {...props} />);

    const link = screen.getByRole('link', { name: 'View transaction tx_1' });
    expect(link).toHaveAttribute('href', '/transactions/tx_1');

    await user.click(link);
    expect(props.on_details_link_activated).toHaveBeenCalledTimes(1);
    expect(props.on_details_link_activated).toHaveBeenCalledWith(
      expect.objectContaining({ transactionId: 'tx_1', href: '/transactions/tx_1' })
    );
  });

  test('row overlay link uses details_href_template override', () => {
    const props = makeProps({ details_href_template: '/t/{transactionId}/details' });
    render(<TransactionTable {...props} />);

    const link = screen.getByRole('link', { name: 'View transaction tx_1' });
    expect(link).toHaveAttribute('href', '/t/tx_1/details');
  });

  test('amount column cells are right-aligned', () => {
    const props = makeProps();
    render(<TransactionTable {...props} />);

    const amountHeader = getHeaderCell('Amount');
    expect(amountHeader).toHaveStyle({ textAlign: 'right' });

    // first data row amount cell is the second column
    const rows = screen.getAllByRole('row');
    const firstDataRow = rows[1];
    const cells = within(firstDataRow).getAllByRole('cell');
    const amountCell = cells[1];
    expect(amountCell).toHaveStyle({ textAlign: 'right' });
  });

  test('merchant name and payment method cells include title attributes for full text overflow fallback', () => {
    const props = makeProps();
    render(<TransactionTable {...props} />);

    expect(screen.getByTitle(props.transactions[0].merchant_name)).toBeInTheDocument();
    expect(screen.getByTitle(props.transactions[0].payment_method)).toBeInTheDocument();
  });
});
