"#f3f4f6","color.text.primary":"#111827","color.text.secondary":"#6b7280","font.weight.medium":"500","radius.12":"12px","radius.8":"8px","shadow.sm":"0 1px 2px rgba(17, 24, 39, 0.08)","spacing.12":"12px","spacing.16":"16px","spacing.24":"24px","spacing.4":"4px","spacing.8":"8px","typography.body":"14px","typography.label":"12px"}},"e2eTests":{"coveredBehaviors":["Composed loading -> loaded transition shows header throughout and disables/re-enables sorting and pagination appropriately","Keyboard sorting (Enter/Space) on header updates aria-sort and triggers parent sort change; parent re-renders with new sort and data","Pagination Next/Previous and page-size change propagate via callbacks; parent updates page/page_size (reset to page 1 on size change) while preserving sort; pagination aria-live text updates","Row overlay link accessible name and href generation (default and template override) and navigation-style behavior; emits details activation callback payload","Unhappy boundary action: disabled Previous on first page blocks action and does not trigger callbacks; recovery via Next works","Unhappy error state: renders error message and Retry; disables sorting/pagination; Retry triggers refetch and recovers to loaded"],"coveredComponentCodes":["transaction_table","transaction_table_pagination","transaction_status_badge"],"coveredFlowCodes":["view_and_open_transaction_details","explore_sort_paginate_change_page_size_then_open_details","invalid_action_pagination_boundary_and_recovery","error_load_then_retry_success"],"coveredStates":["loading","default (loaded with rows)","error","first page boundary (Previous disabled)"],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.e2e.spec.tsx","content":"import React from 'react';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

type Tx = {
  id: string;
  date: string;
  amount: number | null;
  status: string;
  merchant_name: string;
  payment_method: string;
};

type Sort = { sort_key: string; sort_direction: 'asc' | 'desc' };

function makeTransactions(kind: 'page1' | 'page2'): Tx[] {
  if (kind === 'page1') {
    return [
      {
        id: 'tx_100',
        date: '2026-04-02T09:00:00.000Z',
        amount: 50,
        status: 'pending',
        merchant_name: 'Very Long Merchant Name That Should Probably Truncate In The Cell',
        payment_method: 'Visa •••• 1234',
      },
      {
        id: 'tx_101',
        date: '2026-04-01T12:34:56.000Z',
        amount: 10,
        status: 'completed',
        merchant_name: 'Coffee Shop',
        payment_method: 'Mastercard •••• 9999',
      },
      {
        id: 'tx_102',
        date: '2026-03-31T10:00:00.000Z',
        amount: null,
        status: 'refunded',
        merchant_name: 'Bookstore',
        payment_method: 'Amex •••• 0005',
      },
    ];
  }

  return [
    {
      id: 'tx_200',
      date: '2026-04-03T11:00:00.000Z',
      amount: 5,
      status: 'failed',
      merchant_name: 'Transit Authority',
      payment_method: 'Cash',
    },
    {
      id: 'tx_201',
      date: '2026-04-03T12:00:00.000Z',
      amount: 75,
      status: 'completed',
      merchant_name: 'Grocery',
      payment_method: 'Visa •••• 4444',
    },
  ];
}

function getHeaderCell(name: string) {
  return screen.getByRole('columnheader', { name });
}

function getSortButtonInHeader(name: string) {
  const th = getHeaderCell(name);
  return within(th).getByRole('button', { name: new RegExp(name, 'i') });
}

function getPaginationNav() {
  return screen.getByRole('navigation', { name: /transaction table pagination/i });
}

function getPageStatusText() {
  // text is defined in decisions: "Page X of Y" with aria-live polite
  return screen.getByText(/Page \d+ of \d+/i);
}

describe('TransactionTable composed workflow (integration/e2e)', () => {
  test('shortest happy: load -> render -> open details via overlay link', async () => {
    const user = userEvent.setup();

    const on_sort_change = jest.fn();
    const on_next_page = jest.fn();
    const on_prev_page = jest.fn();
    const on_page_size_change = jest.fn();
    const on_retry = jest.fn();
    const on_details_link_activated = jest.fn();

    const { rerender } = render(
      <TransactionTable
        transactions={[]}
        is_loading={true}
        is_error={false}
        total_count={50}
        page={1}
        page_size={25}
        sort={{ sort_key: 'date', sort_direction: 'desc' }}
        on_sort_change={on_sort_change}
        on_next_page={on_next_page}
        on_prev_page={on_prev_page}
        on_page_size_change={on_page_size_change}
        on_retry={on_retry}
        on_details_link_activated={on_details_link_activated}
      />
    );

    // Header visible during loading; skeleton rows present.
    expect(getHeaderCell('Date')).toBeInTheDocument();
    expect(screen.getAllByTestId(/transaction-row-skeleton/i)).toHaveLength(10);

    // Simulate fetch completion.
    rerender(
      <TransactionTable
        transactions={makeTransactions('page1')}
        is_loading={false}
        is_error={false}
        total_count={50}
        page={1}
        page_size={25}
        sort={{ sort_key: 'date', sort_direction: 'desc' }}
        on_sort_change={on_sort_change}
        on_next_page={on_next_page}
        on_prev_page={on_prev_page}
        on_page_size_change={on_page_size_change}
        on_retry={on_retry}
        on_details_link_activated={on_details_link_activated}
      />
    );

    // Default sort state reflected via aria-sort (active Date descending).
    expect(getHeaderCell('Date')).toHaveAttribute('aria-sort', 'descending');
    expect(getHeaderCell('Amount')).toHaveAttribute('aria-sort', 'none');

    // Open details via accessible overlay link.
    const link = screen.getByRole('link', { name: 'View transaction tx_100' });
    expect(link).toHaveAttribute('href', '/transactions/tx_100');

    await user.click(link);
    expect(on_details_link_activated).toHaveBeenCalledTimes(1);
    expect(on_details_link_activated).toHaveBeenCalledWith(
      expect.objectContaining({ transactionId: 'tx_100', href: '/transactions/tx_100' })
    );
  });

  test('exploratory happy: keyboard sort -> toggle -> paginate -> change page size resets page 1 (keeps sort) -> tooltip/title -> open details', async () => {
    const user = userEvent.setup();

    // Harness state
    let sort: Sort = { sort_key: 'date', sort_direction: 'desc' };
    let page = 1;
    let page_size: 25 | 50 | 100 = 25;

    const on_sort_change = jest.fn((payload: any) => {
      sort = { sort_key: payload.sort_key, sort_direction: payload.sort_direction };
      rerenderTable({ is_loading: true });
    });
    const on_next_page = jest.fn(() => {
      page = Math.min(page + 1, 2);
      rerenderTable({ is_loading: true });
    });
    const on_prev_page = jest.fn(() => {
      page = Math.max(page - 1, 1);
      rerenderTable({ is_loading: true });
    });
    const on_page_size_change = jest.fn((ps: number) => {
      page_size = ps as 25 | 50 | 100;
      page = 1;
      rerenderTable({ is_loading: true });
    });
    const on_retry = jest.fn();
    const on_details_link_activated = jest.fn();

    const getRowsForState = (): Tx[] => {
      const base = page === 1 ? makeTransactions('page1') : makeTransactions('page2');
      const copy = [...base];
      const key = sort.sort_key as keyof Tx;
      copy.sort((a, b) => {
        const av = a[key] as any;
        const bv = b[key] as any;
        const aNull = av === null || av === undefined || av === '';
        const bNull = bv === null || bv === undefined || bv === '';
        if (aNull && bNull) return 0;
        if (aNull) return 1;
        if (bNull) return -1;
        if (av < bv) return sort.sort_direction === 'asc' ? -1 : 1;
        if (av > bv) return sort.sort_direction === 'asc' ? 1 : -1;
        return 0;
      });
      return copy;
    };

    const baseProps = {
      total_count: 50,
      details_href_template: '/transactions/{transactionId}',
      on_sort_change,
      on_next_page,
      on_prev_page,
      on_page_size_change,
      on_retry,
      on_details_link_activated,
    };

    const { rerender } = render(
      <TransactionTable
        transactions={[]}
        is_loading={true}
        is_error={false}
        total_count={baseProps.total_count}
        page={page}
        page_size={page_size}
        sort={sort}
        details_href_template={baseProps.details_href_template}
        on_sort_change={baseProps.on_sort_change}
        on_next_page={baseProps.on_next_page}
        on_prev_page={baseProps.on_prev_page}
        on_page_size_change={baseProps.on_page_size_change}
        on_retry={baseProps.on_retry}
        on_details_link_activated={baseProps.on_details_link_activated}
      />
    );

    function rerenderTable(override: Partial<{ is_loading: boolean; is_error: boolean }> = {}) {
      const is_loading = override.is_loading ?? false;
      const is_error = override.is_error ?? false;

      rerender(
        <TransactionTable
          transactions={is_loading || is_error ? [] : getRowsForState()}
          is_loading={is_loading}
          is_error={is_error}
          total_count={baseProps.total_count}
          page={page}
          page_size={page_size}
          sort={sort}
          details_href_template={baseProps.details_href_template}
          on_sort_change={baseProps.on_sort_change}
          on_next_page={baseProps.on_next_page}
          on_prev_page={baseProps.on_prev_page}
          on_page_size_change={baseProps.on_page_size_change}
          on_retry={baseProps.on_retry}
          on_details_link_activated={baseProps.on_details_link_activated}
        />
      );
    }

    // Initial load completes.
    rerenderTable({ is_loading: false });
    expect(getHeaderCell('Date')).toHaveAttribute('aria-sort', 'descending');

    // Keyboard sort by Amount (Enter) should request sort change; harness transitions loading then loaded.
    const amountBtn = getSortButtonInHeader('Amount');
    amountBtn.focus();
    await user.keyboard('{Enter}');
    expect(on_sort_change).toHaveBeenCalledTimes(1);

    // During transition, skeleton rows and disabled pagination.
    expect(screen.getAllByTestId(/transaction-row-skeleton/i)).toHaveLength(10);
    const navDuringSort = getPaginationNav();
    expect(within(navDuringSort).getByRole('button', { name: /next page/i })).toBeDisabled();

    // Complete sort load: set the state as if parent applied Amount asc (per decision for switching columns).
    sort = { sort_key: 'amount', sort_direction: 'asc' };
    rerenderTable({ is_loading: false });
    expect(getHeaderCell('Amount')).toHaveAttribute('aria-sort', 'ascending');
    expect(getHeaderCell('Date')).toHaveAttribute('aria-sort', 'none');

