type SupportedStatus = 'pending' | 'completed' | 'failed' | 'refunded';

export type TransactionStatusBadgeProps = {
  /** Transaction status value to render as a labeled, colored badge. */
  status: SupportedStatus | string;
  /** Optional override for the displayed badge text. */
  label?: string;
  /** Optional accessible label override for assistive technologies. */
  aria_label?: string;
};

function toTitleCase(input: string): string {
  if (!input) return '';
  return input.charAt(0).toUpperCase() + input.slice(1).toLowerCase();
}

function deriveLabel(status: string): string {
  const normalized = String(status).trim().toLowerCase();
  switch (normalized) {
    case 'pending':
      return 'Pending';
    case 'completed':
      return 'Completed';
    case 'failed':
      return 'Failed';
    case 'refunded':
      return 'Refunded';
    default:
      return 'Unknown';
  }
}

function statusClass(status: string): string {
  const normalized = String(status).trim().toLowerCase();
  switch (normalized) {
    case 'pending':
      return 'pending';
    case 'completed':
      return 'completed';
    case 'failed':
      return 'failed';
    case 'refunded':
      return 'refunded';
    default:
      return 'unknown';
  }
}

export function TransactionStatusBadge(props: TransactionStatusBadgeProps) {
  const visibleLabel = props.label ?? deriveLabel(props.status);
  const ariaLabel = props.aria_label ?? visibleLabel;

  return (
    <span
      role="status"
      aria-label={ariaLabel}
      className={`tsbRoot tsb--${statusClass(props.status)}`}
      title={visibleLabel}
    >
      {visibleLabel || toTitleCase(String(props.status))}
    </span>
  );
}
