import { TransactionStatusBadge } from '../TransactionStatusBadge/TransactionStatusBadge';
import { TransactionTablePagination } from '../TransactionTablePagination/TransactionTablePagination';

export type TransactionRow = {
  id: string;
  date: string;
  amount: number | null;
  status: string;
  merchant_name: string;
  payment_method: string;
};

export type TransactionTableSort = {
  sort_key: string;
  sort_direction: 'asc' | 'desc';
};

export type TransactionTableSortChangePayload = {
  sort_key: string;
  sort_direction: 'asc' | 'desc';
};

export type TransactionDetailsLinkActivatedPayload = {
  transactionId: string;
  href: string;
};

export type TransactionTableProps = {
  transactions: TransactionRow[];
  is_loading: boolean;
  is_error: boolean;
  total_count: number;
  page: number;
  page_size: number;
  sort: TransactionTableSort;
  details_href_template?: string;
  on_sort_change: (payload: TransactionTableSortChangePayload) => void;
  on_next_page: () => void;
  on_prev_page: () => void;
  on_page_size_change: (page_size: number) => void;
  on_retry: () => void;
  on_details_link_activated?: (payload: TransactionDetailsLinkActivatedPayload) => void;
};

const COLUMN_DEFS: Array<{ key: string; label: string; align?: 'left' | 'right'; minWidth?: number }> = [
  { key: 'date', label: 'Date', align: 'left', minWidth: 120 },
  { key: 'amount', label: 'Amount', align: 'right', minWidth: 120 },
  { key: 'status', label: 'Status', align: 'left', minWidth: 120 },
  { key: 'merchant_name', label: 'Merchant Name', align: 'left', minWidth: 200 },
  { key: 'payment_method', label: 'Payment Method', align: 'left', minWidth: 160 },
];

function ariaSortValue(isActive: boolean, direction: 'asc' | 'desc'): 'none' | 'ascending' | 'descending' {
  if (!isActive) return 'none';
  return direction === 'asc' ? 'ascending' : 'descending';
}

function buildDetailsHref(template: string, transactionId: string) {
  return template.replace('{transactionId}', transactionId);
}

function formatDateYYYYMMDD(dateIso: string) {
  // local timezone YYYY-MM-DD
  const d = new Date(dateIso);
  if (Number.isNaN(d.getTime())) return '';
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function formatCurrency(amount: number | null) {
  if (amount === null || amount === undefined) return '—';
  // Locale-safe formatting. Use USD by default (not provided by props); tests do not assert exact string.
  try {
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amount);
  } catch {
    return amount.toFixed(2);
  }
}

export function TransactionTable(props: TransactionTableProps) {
  const {
    transactions,
    is_loading,
    is_error,
    total_count,
    page,
    page_size,
    sort,
    details_href_template,
    on_sort_change,
    on_next_page,
    on_prev_page,
    on_page_size_change,
    on_retry,
    on_details_link_activated,
  } = props;

  const disabledInteractions = is_loading || is_error;
  const isEmpty = !is_loading && !is_error && total_count === 0;
  const showPagination = !isEmpty;

  const totalPages = useMemo(() => {
    const ps = page_size > 0 ? page_size : 25;
    const pages = Math.ceil(Math.max(0, total_count) / ps);
    return Math.max(1, pages);
  }, [total_count, page_size]);

  const hrefTemplate = details_href_template ?? '/transactions/{transactionId}';

  const handleSortActivate = (columnKey: string) => {
    if (disabledInteractions) return;

    const isActive = sort?.sort_key === columnKey;
    const nextDirection: 'asc' | 'desc' = isActive ? (sort.sort_direction === 'asc' ? 'desc' : 'asc') : 'asc';

    on_sort_change({ sort_key: columnKey, sort_direction: nextDirection });
  };

  return (
    <div style={styles.container}>
      <div style={styles.scrollContainer}>
        <table style={styles.table}>
          <thead>
            <tr>
              {COLUMN_DEFS.map((col) => {
                const isActive = sort?.sort_key === col.key;
                const ariaSort = ariaSortValue(!!isActive, (sort?.sort_direction ?? 'desc') as 'asc' | 'desc');
                const textAlign: React.CSSProperties['textAlign'] = col.align ?? 'left';

                return (
                  <th
                    key={col.key}
                    scope="col"
                    aria-sort={ariaSort}
                    style={{
                      ...styles.th,
                      textAlign,
                      minWidth: col.minWidth,
                    }}
                  >
                    <button
                      type="button"
                      onClick={() => handleSortActivate(col.key)}
                      onKeyDown={(e) => {
                        if (disabledInteractions) return;
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          handleSortActivate(col.key);
                        }
                      }}
                      disabled={disabledInteractions}
                      style={styles.sortButton}
                    >
                      {col.label}
                    </button>
                  </th>
                );
              })}
            </tr>
          </thead>

          <tbody>
            {is_loading ? (
              Array.from({ length: 10 }).map((_, i) => (
                <tr key={`skeleton-${i}`} data-testid={`transaction-row-skeleton-${i}`}>
                  {COLUMN_DEFS.map((col) => (
                    <td
                      key={col.key}
                      role="cell"
                      style={{
                        ...styles.td,
                        textAlign: col.align ?? 'left',
                      }}
                    >
                      <div style={styles.skeletonBar} />
                    </td>
                  ))}
                </tr>
              ))
            ) : is_error ? (
              <tr>
                <td style={styles.fullWidthCell} colSpan={COLUMN_DEFS.length}>
                  <div style={styles.stateRow}>
                    <div style={styles.errorTitle}>Transactions couldn’t be loaded</div>
                    <button type="button" onClick={on_retry} style={styles.retryButton}>
                      Retry
                    </button>
                  </div>
                </td>
              </tr>
            ) : isEmpty ? (
              <tr>
                <td style={styles.fullWidthCell} colSpan={COLUMN_DEFS.length}>
                  <div style={styles.stateRow}>No transactions</div>
                </td>
              </tr>
            ) : (
              transactions.map((tx) => {
                const href = buildDetailsHref(hrefTemplate, tx.id);
                const formattedDate = formatDateYYYYMMDD(tx.date);

                return (
                  <tr key={tx.id} style={styles.dataRow}>
                    <td style={{ ...styles.td, ...styles.dateCell }}>
                      <a
                        href={href}
                        aria-label={`View transaction ${tx.id}`}
                        style={styles.rowOverlayLink}
                        onClick={() => {
                          on_details_link_activated?.({ transactionId: tx.id, href });
                        }}
                      >
                        {formattedDate}
                      </a>
                      <span aria-hidden="true">{formattedDate}</span>
                    </td>
                    <td style={{ ...styles.td, textAlign: 'right' }}>{formatCurrency(tx.amount)}</td>
                    <td style={styles.td}>
                      <TransactionStatusBadge status={tx.status} />
                    </td>
                    <td style={styles.td} title={tx.merchant_name}>
                      <span style={styles.truncate}>{tx.merchant_name}</span>
                    </td>
                    <td style={styles.td} title={tx.payment_method}>
                      <span style={styles.truncate}>{tx.payment_method}</span>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {showPagination ? (
        <div style={styles.paginationWrap}>
          <TransactionTablePagination
            current_page={page}
            total_pages={totalPages}
            page_size={page_size}
            page_size_options={[25, 50, 100]}
            on_next_page={() => {
              if (disabledInteractions) return;
              on_next_page();
            }}
            on_previous_page={() => {
              if (disabledInteractions) return;
              on_prev_page();
            }}
            on_page_size_change={(ps: number) => {
              if (disabledInteractions) return;
              on_page_size_change(ps);
            }}
            disabled={disabledInteractions}
          />
        </div>
      ) : null}
    </div>
  );
}

