type Props = {
  /** Current 1-based page index */
  current_page: number;
  /** Total number of pages */
  total_pages: number;
  /** Current page size */
  page_size: number;
  /** Allowed page size options */
  page_size_options?: number[];
  /** Disables all controls */
  disabled?: boolean;
  on_previous_page: () => void;
  on_next_page: () => void;
  on_page_size_change: (pageSize: number) => void;
};

const DEFAULT_PAGE_SIZE_OPTIONS = [25, 50, 100];

function clampInt(value: number, min: number, max: number) {
  if (!Number.isFinite(value)) return min;
  const v = Math.trunc(value);
  return Math.min(max, Math.max(min, v));
}

export function TransactionTablePagination(props: Props) {
  const {
    current_page,
    total_pages,
    page_size,
    page_size_options = DEFAULT_PAGE_SIZE_OPTIONS,
    disabled = false,
    on_previous_page,
    on_next_page,
    on_page_size_change,
  } = props;

  const safeTotalPages = Math.max(1, Math.trunc(total_pages || 1));
  const safeCurrentPage = clampInt(current_page || 1, 1, safeTotalPages);

  const isPrevDisabled = disabled || safeCurrentPage <= 1;
  const isNextDisabled = disabled || safeCurrentPage >= safeTotalPages;

  const handlePrev = () => {
    if (isPrevDisabled) return;
    on_previous_page();
  };

  const handleNext = () => {
    if (isNextDisabled) return;
    on_next_page();
  };

  const handlePageSizeChange: React.ChangeEventHandler<HTMLSelectElement> = (e) => {
    if (disabled) return;
    const next = Number(e.target.value);
    if (!Number.isFinite(next)) return;
    on_page_size_change(next);
  };

  return (
    <nav aria-label="Transaction table pagination" style={styles.nav}>
      <div style={styles.controlsRow}>
        <button
          type="button"
          aria-label="Previous page"
          disabled={isPrevDisabled}
          onClick={handlePrev}
          style={{ ...styles.button, ...(isPrevDisabled ? styles.buttonDisabled : null) }}
        >
          Previous
        </button>

        <button
          type="button"
          aria-label="Next page"
          disabled={isNextDisabled}
          onClick={handleNext}
          style={{ ...styles.button, ...(isNextDisabled ? styles.buttonDisabled : null) }}
        >
          Next
        </button>

        <div style={styles.pageStatus} aria-live="polite">
          Page {safeCurrentPage} of {safeTotalPages}
        </div>

        <label style={styles.pageSizeLabel}
          >
          <span style={styles.pageSizeLabelText}>Page size</span>
          <select
            aria-label="Page size"
            disabled={disabled}
            value={String(page_size)}
            onChange={handlePageSizeChange}
            style={{ ...styles.select, ...(disabled ? styles.selectDisabled : null) }}
          >
            {page_size_options.map((opt) => (
              <option key={opt} value={String(opt)}>
                {opt}
              </option>
            ))}
          </select>
        </label>
      </div>

      <style>{focusVisibleCss}</style>
    </nav>
  );
}

