us Badge","parentCode":"transaction_table","purpose":"Render a colored status badge for each transaction status value.","statePolicy":"dumb","type":"badge"}],"constraints":[{"componentCode":"transaction_table","description":"Supports sorting by any column.","type":"sorting"},{"componentCode":"transaction_table","description":"Pagination supports 25/50/100 items per page.","type":"pagination"}],"content":[{"code":"col_date","componentCode":"transaction_table","description":"Transaction date column.","kind":"column","name":"Date","isRequired":true},{"code":"col_amount","componentCode":"transaction_table","description":"Transaction amount column.","kind":"column","name":"Amount","isRequired":true},{"code":"col_status","componentCode":"transaction_table","description":"Transaction status column rendered with a colored badge.","kind":"column","name":"Status","isRequired":true},{"code":"col_merchant_name","componentCode":"transaction_table","description":"Merchant name column.","kind":"column","name":"Merchant Name","isRequired":true},{"code":"col_payment_method","componentCode":"transaction_table","description":"Payment method column.","kind":"column","name":"Payment Method","isRequired":true},{"code":"status_pending","componentCode":"transaction_status_badge","description":"Pending status value.","kind":"status","name":"Pending","isRequired":true},{"code":"status_completed","componentCode":"transaction_status_badge","description":"Completed status value.","kind":"status","name":"Completed","isRequired":true},{"code":"status_failed","componentCode":"transaction_status_badge","description":"Failed status value.","kind":"status","name":"Failed","isRequired":true},{"code":"status_refunded","componentCode":"transaction_status_badge","description":"Refunded status value.","kind":"status","name":"Refunded","isRequired":true}],"interactions":[{"code":"sort_by_column","componentCode":"transaction_table","description":"Sort transactions by the selected column.","targetComponentCo