tCodes":["transaction_table"],"code":"overflow_truncation_with_tooltips","decision":"Merchant Name and Payment Method cells are single-line with truncation (ellipsis). On hover and keyboard focus, show a tooltip containing the full text; the cell also includes a title attribute with the full value as a baseline fallback.","rationale":"This prevents layout breakage from long strings while still enabling access to the full content for mouse and keyboard users with a conservative fallback.","sourceGap":"Document data overflow behavior per column (truncate with ellipsis, wrap, tooltip on hover/focus) especially for merchant name and payment method"},{"affectedComponentCodes":["transaction_table","transaction_table_pagination"],"code":"responsive_horizontal_scroll_and_min_widths","decision":"On small screens, keep the 5-column table and enable horizontal scrolling within a container (overflow-x:auto) rather than stacking/hiding columns. Set minimum widths: Date 120px, Amount 120px, Status 120px, Merchant Name 200px, Payment Method 160px. Pagination stays below the table; controls wrap to two lines if needed with page size selector on the second line.","rationale":"Horizontal scroll is the most conservative responsive strategy for dense tabular data, and minimum widths prevent column collapse while keeping behavior deterministic for implementation.","sourceGap":"Define small-screen behavior for 5-column table (horizontal scroll vs column stacking vs hiding lower-priority columns)"}]},"unitTests":{"components":[{"componentCode":"transaction_status_badge","componentName":"Transaction Status Badge","coveredBehaviors":["Renders derived label text from supported `status` values (Pending/Completed/Failed/Refunded)","Renders neutral fallback label "Unknown" for unsupported status values","Uses `label` prop to override visible text regardless of status","Defaults `aria-label` to the visible label text when `aria_label` is not provided","Uses `aria_label` prop to override the accessible name while keeping visible label unchanged"],"coveredStates":["Supported statuses (pending/completed/failed/refunded)","Unknown/unsupported status fallback","Label override","Aria-label override"],"files":[{"filename":"/app/generated/frontend/src/components/TransactionStatusBadge/TransactionStatusBadge.spec.tsx","content":"import React from 'react';
import { render, screen } from '@testing-library/react';
import '@testing-library/jest-dom';

import { TransactionStatusBadge } from './TransactionStatusBadge';

describe('TransactionStatusBadge', () => {
  const getBadge = () => {
    // Prefer role-based query. If the implementation uses a <span> without role,
    // fall back to locating by text.
    const byStatus = screen.queryByRole('status');
    if (byStatus) return byStatus;

    const byLabel = screen.queryByLabelText(/.+/);
    if (byLabel) return byLabel;

    // last resort: find any element containing the expected label in each test
    throw new Error('Could not locate badge element. Ensure component renders an accessible element (e.g., role="status" or aria-label).');
  };

  it.each([
    ['pending', 'Pending'],
    ['completed', 'Completed'],
    ['failed', 'Failed'],
    ['refunded', 'Refunded']
  ])('derives visible label and aria-label from supported status "%s"', (status, expectedLabel) => {
    render(<TransactionStatusBadge status={status as string} />);

    // Visible label text present (not color-only)
    expect(screen.getByText(expectedLabel)).toBeInTheDocument();

    // Accessible name defaults to visible label
    const badge = getBadge();
    expect(badge).toHaveAttribute('aria-label', expectedLabel);
  });

  it('renders fallback "Unknown" label and aria-label for unsupported status', () => {
    render(<TransactionStatusBadge status="chargeback" />);

    expect(screen.getByText('Unknown')).toBeInTheDocument();

    const badge = getBadge();
    expect(badge).toHaveAttribute('aria-label', 'Unknown');
  });

  it('uses `label` prop to override the visible label and defaults aria-label to that overridden label', () => {
    render(<TransactionStatusBadge status="pending" label="Awaiting settlement" />);

    expect(screen.getByText('Awaiting settlement')).toBeInTheDocument();

    const badge = getBadge();
    expect(badge).toHaveAttribute('aria-label', 'Awaiting settlement');
  });

  it('uses `aria_label` to override accessible name while keeping visible label unchanged', () => {
    render(
      <TransactionStatusBadge
        status="failed"
        aria_label="Transaction failed"
      />
    );

    // Visible label still derived from status
    expect(screen.getByText('Failed')).toBeInTheDocument();

    const badge = getBadge();
    expect(badge).toHaveAttribute('aria-label', 'Transaction failed');
  });

  it('prefers `aria_label` over default when both `label` and `aria_label` are provided', () => {
    render(
      <TransactionStatusBadge
        status="completed"
        label="Done"
        aria_label="Transaction completed"
      />
    );

    // Visible text uses label override
    expect(screen.getByText('Done')).toBeInTheDocument();

    // Accessible name uses aria_label override
    const badge = getBadge();
    expect(badge).toHaveAttribute('aria-label', 'Transaction completed');
  });
});
