import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

jest.mock('../TransactionStatusBadge/TransactionStatusBadge', () => ({
  TransactionStatusBadge: ({ status, label, aria_label }: any) => (
    <span data-testid="status-badge" aria-label={aria_label ?? label ?? String(status)}>
      {label ?? String(status)}
    </span>
  ),
}));

jest.mock('../TransactionTablePagination/TransactionTablePagination', () => ({
  TransactionTablePagination: (props: any) => (
    <div data-testid="pagination">
      <button onClick={props.on_previous_page} disabled={!!props.disabled} aria-label="Previous page">
        Previous
      </button>
      <button onClick={props.on_next_page} disabled={!!props.disabled} aria-label="Next page">
        Next
      </button>
      <label>
        Page size
        <select
          aria-label="Page size"
          disabled={!!props.disabled}
          value={props.page_size}
          onChange={(e) => props.on_page_size_change(Number((e.target as HTMLSelectElement).value))}
        >
          {(props.page_size_options ?? [25, 50, 100]).map((n: number) => (
            <option key={n} value={n}>
              {n}
            </option>
          ))}
        </select>
      </label>
      <div aria-live="polite">Page {props.current_page} of {props.total_pages}</div>
    </div>
  ),
}));

type Tx = {
  id: string;
  date: string;
  amount: number | null;
  status: string;
  merchant_name: string;
  payment_method: string;
};

defaultProps = undefined as unknown as {
  transactions: Tx[];
  is_loading: boolean;
  is_error: boolean;
  total_count: number;
  page: number;
  page_size: 25 | 50 | 100;
  sort: { sort_key: string; sort_direction: 'asc' | 'desc' };
  details_href_template?: string;
  on_sort_change: jest.Mock;
  on_next_page: jest.Mock;
  on_prev_page: jest.Mock;
  on_page_size_change: jest.Mock;
  on_retry: jest.Mock;
  on_details_link_activated?: jest.Mock;
};

const makeProps = (overrides: Partial<any> = {}) => {
  const props = {
    transactions: [
      {
        id: 'tx_1',
        date: '2026-04-01T12:34:56.000Z',
        amount: 123.45,
        status: 'pending',
        merchant_name: 'Very Long Merchant Name That Should Probably Truncate In The Cell',
        payment_method: 'Visa •••• 1234',
      },
      {
        id: 'tx_2',
        date: '2026-04-02T09:00:00.000Z',
        amount: -10,
        status: 'completed',
        merchant_name: 'Coffee Shop',
        payment_method: 'Mastercard •••• 9999',
      },
    ] as Tx[],
    is_loading: false,
    is_error: false,
    total_count: 50,
    page: 1,
    page_size: 25,
    sort: { sort_key: 'date', sort_direction: 'desc' as const },
    on_sort_change: jest.fn(),
    on_next_page: jest.fn(),
    on_prev_page: jest.fn(),
    on_page_size_change: jest.fn(),
    on_retry: jest.fn(),
    on_details_link_activated: jest.fn(),
    ...overrides,
  };
  return props;
};

const getHeaderCell = (name: string) => screen.getByRole('columnheader', { name });

describe('TransactionTable', () => {
  test('renders headers and sets aria-sort only on active sorted column', () => {
    const props = makeProps({ sort: { sort_key: 'date', sort_direction: 'desc' } });
    render(<TransactionTable {...props} />);

    expect(getHeaderCell('Date')).toBeInTheDocument();
    expect(getHeaderCell('Amount')).toBeInTheDocument();
    expect(getHeaderCell('Status')).toBeInTheDocument();
    expect(getHeaderCell('Merchant Name')).toBeInTheDocument();
    expect(getHeaderCell('Payment Method')).toBeInTheDocument();

    expect(getHeaderCell('Date')).toHaveAttribute('aria-sort', 'descending');
    expect(getHeaderCell('Amount')).toHaveAttribute('aria-sort', 'none');
    expect(getHeaderCell('Status')).toHaveAttribute('aria-sort', 'none');
    expect(getHeaderCell('Merchant Name')).toHaveAttribute('aria-sort', 'none');
    expect(getHeaderCell('Payment Method')).toHaveAttribute('aria-sort', 'none');
  });

  test('invokes on_sort_change when clicking a sortable header and toggles direction when re-sorting same column', async () => {
    const user = userEvent.setup();

    const props = makeProps({ sort: { sort_key: 'amount', sort_direction: 'asc' } });
    render(<TransactionTable {...props} />);

    const amountHeader = getHeaderCell('Amount');
    const amountSortButton = within(amountHeader).getByRole('button', { name: /amount/i });

    await user.click(amountSortButton);
    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
    // bi-state toggle
    expect(props.on_sort_change.mock.calls[0][0]).toEqual(
      expect.objectContaining({ sort_key: 'amount', sort_direction: 'desc' })
    );
  });

  test('invokes on_sort_change via keyboard Enter/Space on header button', async () => {
    const user = userEvent.setup();

    const props = makeProps({ sort: { sort_key: 'date', sort_direction: 'desc' } });
    render(<TransactionTable {...props} />);

    const statusHeader = getHeaderCell('Status');
    const statusSortButton = within(statusHeader).getByRole('button', { name: /status/i });

    statusSortButton.focus();
    expect(statusSortButton).toHaveFocus();

    await user.keyboard('{Enter}');
    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
    // switching to a different column activates ascending
    expect(props.on_sort_change.mock.calls[0][0]).toEqual(
      expect.objectContaining({ sort_key: expect.any(String), sort_direction: 'asc' })
    );

    props.on_sort_change.mockClear();
    statusSortButton.focus();
    await user.keyboard(' ');
    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
  });

  test('disables sorting interactions while loading', async () => {
    const user = userEvent.setup();
    const props = makeProps({ is_loading: true });
    render(<TransactionTable {...props} />);

    const amountHeader = getHeaderCell('Amount');
    const amountSortButton = within(amountHeader).getByRole('button', { name: /amount/i });

    await user.click(amountSortButton);
    expect(props.on_sort_change).not.toHaveBeenCalled();
  });

  test('loading state renders 10 skeleton rows and keeps header visible', () => {
    const props = makeProps({ is_loading: true, transactions: [] });
    render(<TransactionTable {...props} />);

    // header visible
    expect(getHeaderCell('Date')).toBeInTheDocument();

    // skeleton rows
    const skeletons = screen.getAllByTestId(/transaction-row-skeleton/i);
    expect(skeletons).toHaveLength(10);
  });

  test('error state renders message and Retry button; retry invokes on_retry; sorting/pagination disabled', async () => {
    const user = userEvent.setup();
    const props = makeProps({ is_error: true, transactions: [], total_count: 50 });
    render(<TransactionTable {...props} />);

    expect(screen.getByText(/Transactions couldn’t be loaded/i)).toBeInTheDocument();

    const retry = screen.getByRole('button', { name: /retry/i });
    await user.click(retry);
    expect(props.on_retry).toHaveBeenCalledTimes(1);

    // sorting disabled in error
    const dateHeader = getHeaderCell('Date');
    const dateSortButton = within(dateHeader).getByRole('button', { name: /date/i });
    await user.click(dateSortButton);
    expect(props.on_sort_change).not.toHaveBeenCalled();

    // pagination exists but disabled when error
    const pagination = screen.getByTestId('pagination');
    expect(within(pagination).getByRole('button', { name: /next page/i })).toBeDisabled();
    expect(within(pagination).getByRole('button', { name: /previous page/i })).toBeDisabled();
    expect(within(pagination).getByRole('combobox', { name: /page size/i })).toBeDisabled();
  });

  test('empty state shows "No transactions" and hides pagination', () => {
    const props = makeProps({ transactions: [], total_count: 0, is_loading: false, is_error: false });
    render(<TransactionTable {...props} />);

    expect(screen.getByText(/no transactions/i)).toBeInTheDocument();
    expect(screen.queryByTestId('pagination')).not.toBeInTheDocument();
  });

  test('renders row overlay link with default href and accessible name; click emits details_link_activated', async () => {
    const user = userEvent.setup();
    const props = makeProps();
    render(<TransactionTable {...props} />);

    const link = screen.getByRole('link', { name: 'View transaction tx_1' });
    expect(link).toHaveAttribute('href', '/transactions/tx_1');

    await user.click(link);
    expect(props.on_details_link_activated).toHaveBeenCalledTimes(1);
    expect(props.on_details_link_activated).toHaveBeenCalledWith(
      expect.objectContaining({ transactionId: 'tx_1', href: '/transactions/tx_1' })
    );
  });

  test('row overlay link uses details_href_template override', () => {
    const props = makeProps({ details_href_template: '/t/{transactionId}/details' });
    render(<TransactionTable {...props} />);

    const link = screen.getByRole('link', { name: 'View transaction tx_1' });
    expect(link).toHaveAttribute('href', '/t/tx_1/details');
  });

  test('amount column cells are right-aligned', () => {
    const props = makeProps();
    render(<TransactionTable {...props} />);

    const amountHeader = getHeaderCell('Amount');
    expect(amountHeader).toHaveStyle({ textAlign: 'right' });

    // first data row amount cell is the second column
    const rows = screen.getAllByRole('row');
    const firstDataRow = rows[1];
    const cells = within(firstDataRow).getAllByRole('cell');
    const amountCell = cells[1];
    expect(amountCell).toHaveStyle({ textAlign: 'right' });
  });

  test('merchant name and payment method cells include title attributes for full text overflow fallback', () => {
    const props = makeProps();
    render(<TransactionTable {...props} />);

    expect(screen.getByTitle(props.transactions[0].merchant_name)).toBeInTheDocument();
    expect(screen.getByTitle(props.transactions[0].payment_method)).toBeInTheDocument();
  });
});
