import React from 'react';
import { TransactionTableStatusBadge } from '../TransactionTableStatusBadge/TransactionTableStatusBadge';
import { TransactionTablePagination } from '../TransactionTablePagination/TransactionTablePagination';

export type TransactionStatus = 'pending' | 'completed' | 'failed' | 'refunded';
export type SortDirection = 'ascending' | 'descending';
export type TransactionSortColumn = 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method';

export type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: TransactionStatus;
  merchant_name: string;
  payment_method: string;
};

export type SortChangePayload = {
  column: TransactionSortColumn;
  direction: SortDirection;
};

export type OpenTransactionDetailsPayload = { id: string } & Record<string, any>;

export type TransactionTableProps = {
  transactions: TransactionRow[];
  is_loading: boolean;
  is_error: boolean;
  sort_column: TransactionSortColumn;
  sort_direction: SortDirection;
  page: number;
  page_size: number;
  total_results: number;
  on_sort_change: (payload: SortChangePayload) => void;
  on_page_change: (page: number) => void;
  on_page_size_change: (page_size: number) => void;
  on_open_details: (payload: OpenTransactionDetailsPayload) => void;
  on_retry: () => void;
};

const COLUMNS: Array<{ key: TransactionSortColumn; label: string; minWidth: number }> = [
  { key: 'date', label: 'Date', minWidth: 120 },
  { key: 'amount', label: 'Amount', minWidth: 120 },
  { key: 'status', label: 'Status', minWidth: 120 },
  { key: 'merchant_name', label: 'Merchant Name', minWidth: 200 },
  { key: 'payment_method', label: 'Payment Method', minWidth: 160 }
];

function getNextSortDirection(currentColumn: TransactionSortColumn, currentDirection: SortDirection, nextColumn: TransactionSortColumn) {
  if (nextColumn !== currentColumn) return 'ascending' as const;
  return currentDirection === 'ascending' ? ('descending' as const) : ('ascending' as const);
}

function SortIndicator(props: { isActive: boolean; direction: SortDirection }) {
  const { isActive, direction } = props;
  if (!isActive) return <span aria-hidden="true" className="tt-sort-indicator" />;
  return (
    <span aria-hidden="true" className="tt-sort-indicator">
      {direction === 'ascending' ? '▲' : '▼'}
    </span>
  );
}

function SkeletonRow(props: { columns: number }) {
  return (
    <tr>
      {Array.from({ length: props.columns }).map((_, idx) => (
        <td key={idx} className="tt-td">
          <div className="tt-skeleton" />
        </td>
      ))}
    </tr>
  );
}

export function TransactionTable(props: TransactionTableProps) {
  const {
    transactions,
    is_loading,
    is_error,
    sort_column,
    sort_direction,
    page,
    page_size,
    total_results,
    on_sort_change,
    on_page_change,
    on_page_size_change,
    on_open_details,
    on_retry
  } = props;

  const interactionsDisabled = is_loading || is_error;

  const onHeaderActivate = (column: TransactionSortColumn) => {
    if (interactionsDisabled) return;
    const nextDirection = getNextSortDirection(sort_column, sort_direction, column);
    on_sort_change({ column, direction: nextDirection });
  };

  const renderBody = () => {
    if (is_loading) {
      return (
        <>
          {Array.from({ length: 10 }).map((_, i) => (
            <SkeletonRow key={i} columns={COLUMNS.length} />
          ))}
        </>
      );
    }

    if (is_error) {
      return (
        <tr>
          <td className="tt-td" colSpan={COLUMNS.length}>
            <div className="tt-stateRow">
              <div className="tt-stateTitle">Transactions failed to load</div>
              <button className="tt-button" type="button" onClick={on_retry}>
                Retry
              </button>
            </div>
          </td>
        </tr>
      );
    }

    if (transactions.length === 0) {
      return (
        <tr>
          <td className="tt-td" colSpan={COLUMNS.length}>
            <div className="tt-stateRow">
              <div className="tt-stateTitle">No transactions to display</div>
            </div>
          </td>
        </tr>
      );
    }

    return (
      <>
        {transactions.map((t) => {
          const viewLabel = `View transaction details for ${t.merchant_name} on ${t.date}`;
          return (
            <tr
              key={t.id}
              className="tt-tr"
              onClick={() => on_open_details({ id: t.id })}
            >
              <td className="tt-td">
                <div className="tt-dateCell">
                  <button
                    type="button"
                    className="tt-linkButton"
                    aria-label={viewLabel}
                    onClick={(e) => {
                      e.stopPropagation();
                      on_open_details({ id: t.id });
                    }}
                  >
                    View details
                  </button>
                  <span className="tt-dateText">{t.date}</span>
                </div>
              </td>
              <td className="tt-td tt-mono">{t.amount}</td>
              <td className="tt-td">
                <TransactionTableStatusBadge status={t.status as any} />
              </td>
              <td className="tt-td">
                <span className="tt-ellipsis" title={t.merchant_name}>
                  {t.merchant_name}
                </span>
              </td>
              <td className="tt-td">
                <span className="tt-ellipsis" title={t.payment_method}>
                  {t.payment_method}
                </span>
              </td>
            </tr>
          );
        })}
      </>
    );
  };

  return (
    <div className="tt-root">
      <div className="tt-scroll" role="region" aria-label="Transactions table">
        <table className="tt-table">
          <thead className="tt-thead">
            <tr>
              {COLUMNS.map((col) => {
                const isActive = col.key === sort_column;
                const thProps: React.ThHTMLAttributes<HTMLTableCellElement> = {
                  className: 'tt-th',
                  style: { minWidth: col.minWidth }
                };
                if (isActive) thProps['aria-sort'] = sort_direction;

                return (
                  <th key={col.key} scope="col" {...thProps}>
                    <button
                      type="button"
                      className="tt-headerButton"
                      disabled={interactionsDisabled}
                      onClick={() => onHeaderActivate(col.key)}
                    >
                      <span className="tt-headerLabel">{col.label}</span>
                      <SortIndicator isActive={isActive} direction={sort_direction} />
                    </button>
                  </th>
                );
              })}
            </tr>
          </thead>
          <tbody className="tt-tbody">{renderBody()}</tbody>
        </table>
      </div>

      <div className="tt-pagination">
        <TransactionTablePagination
          page={page}
          page_size={page_size}
          total_results={total_results}
          is_disabled={interactionsDisabled}
          on_page_change={on_page_change}
          on_page_size_change={on_page_size_change}
        />
      </div>

      <style>{`
        .tt-root {
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border: 1px solid var(--color-border-subtle);
          border-radius: var(--radius-12);
          box-shadow: var(--shadow-sm);
          padding: var(--spacing-16);
        }

        .tt-scroll {
          overflow-x: auto;
        }

        .tt-table {
          width: 100%;
          border-collapse: separate;
          border-spacing: 0;
          min-width: 720px;
        }

        .tt-th,
        .tt-td {
          padding: var(--spacing-12);
          border-bottom: 1px solid var(--color-border-subtle);
          text-align: left;
          vertical-align: middle;
          font-size: var(--font-size-body);
        }

        .tt-th {
          background: var(--color-surface-muted);
          font-size: var(--font-size-label);
          font-weight: var(--font-weight-medium);
          color: var(--color-text-secondary);
        }

        .tt-headerButton {
          appearance: none;
          border: none;
          background: transparent;
          padding: 0;
