  /** Callback invoked when user requests a page change via First/Previous/Next/Last controls. */
  on_page_change: (page: number) => void;
  /** Callback invoked when user changes Rows per page. */
  on_page_size_change: (page_size: number) => void;
};

function clampInt(value: number, min: number, max: number) {
  const v = Number.isFinite(value) ? Math.trunc(value) : min;
  return Math.min(max, Math.max(min, v));
}

function computeTotalPages(totalResults: number, pageSize: number) {
  const safeTotal = Math.max(0, Math.trunc(totalResults));
  const safeSize = Math.max(1, Math.trunc(pageSize));
  return Math.max(1, Math.ceil(safeTotal / safeSize));
}

export function TransactionTablePagination(props: TransactionTablePaginationProps) {
  const pageSizeOptions = props.page_size_options ?? [25, 50, 100];

  const totalPages = computeTotalPages(props.total_results, props.page_size);
  const currentPage = clampInt(props.page, 1, totalPages);

  const isOnFirst = currentPage <= 1;
  const isOnLast = currentPage >= totalPages;

  const disableAll = props.is_disabled;
  const disableFirstPrev = disableAll || isOnFirst;
  const disableNextLast = disableAll || isOnLast;

  const onFirst = () => props.on_page_change(1);
  const onPrev = () => props.on_page_change(Math.max(1, currentPage - 1));
  const onNext = () => props.on_page_change(Math.min(totalPages, currentPage + 1));
  const onLast = () => props.on_page_change(totalPages);

  return (
