});

import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTablePagination } from './TransactionTablePagination';

type Props = React.ComponentProps<typeof TransactionTablePagination>;

function renderComponent(override: Partial<Props> = {}) {
  const props: Props = {
    page: 2,
    page_size: 25,
    total_results: 120,
    is_disabled: false,
    page_size_options: [25, 50, 100],
    on_page_change: jest.fn(),
    on_page_size_change: jest.fn(),
    ...override
  };

  const view = render(<TransactionTablePagination {...props} />);
  return { ...view, props };
}

describe('TransactionTablePagination', () => {
  it('renders pagination landmark and summary text', () => {
    renderComponent({ page: 2, page_size: 25, total_results: 120 });

    // Landmark / region
    expect(screen.getByLabelText('Transaction pagination')).toBeInTheDocument();

    // Total pages = ceil(120/25)=5
    expect(screen.getByText(/Page\s+2\s+of\s+5/i)).toBeInTheDocument();
    expect(screen.getByText(/120\s+results/i)).toBeInTheDocument();

    // Rows per page label
    expect(screen.getByText(/Rows per page/i)).toBeInTheDocument();
  });

  it('invokes on_page_change with correct target pages for First/Previous/Next/Last', async () => {
    const user = userEvent.setup();
    const { props } = renderComponent({ page: 2, page_size: 25, total_results: 120 }); // 5 pages

    await user.click(screen.getByRole('button', { name: 'First page' }));
    expect(props.on_page_change).toHaveBeenCalledWith(1);

    await user.click(screen.getByRole('button', { name: 'Previous page' }));
    expect(props.on_page_change).toHaveBeenCalledWith(1);

    await user.click(screen.getByRole('button', { name: 'Next page' }));
    expect(props.on_page_change).toHaveBeenCalledWith(3);

    await user.click(screen.getByRole('button', { name: 'Last page' }));
    expect(props.on_page_change).toHaveBeenCalledWith(5);
  });

  it('disables First/Previous on the first page (and disabled buttons are not focusable)', async () => {
    const user = userEvent.setup();
    renderComponent({ page: 1, page_size: 25, total_results: 120, is_disabled: false });

    const first = screen.getByRole('button', { name: 'First page' });
    const prev = screen.getByRole('button', { name: 'Previous page' });
    const next = screen.getByRole('button', { name: 'Next page' });
    const last = screen.getByRole('button', { name: 'Last page' });

    expect(first).toBeDisabled();
    expect(prev).toBeDisabled();
    expect(next).not.toBeDisabled();
    expect(last).not.toBeDisabled();

    await user.tab();
    // First focusable control should not be a disabled boundary button
    expect(document.activeElement).not.toBe(first);
    expect(document.activeElement).not.toBe(prev);
  });

  it('disables Next/Last on the last page', () => {
    // total pages = ceil(100/25)=4
    renderComponent({ page: 4, page_size: 25, total_results: 100, is_disabled: false });

    expect(screen.getByRole('button', { name: 'First page' })).not.toBeDisabled();
    expect(screen.getByRole('button', { name: 'Previous page' })).not.toBeDisabled();
    expect(screen.getByRole('button', { name: 'Next page' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Last page' })).toBeDisabled();

    expect(screen.getByText(/Page\s+4\s+of\s+4/i)).toBeInTheDocument();
  });

  it('calls on_page_size_change with the selected page size', async () => {
    const user = userEvent.setup();
    const { props } = renderComponent({ page: 1, page_size: 25, total_results: 10, is_disabled: false });

    // Associate by label text; supports both <label>+<select> and aria-label
    const selector = screen.getByLabelText(/Rows per page/i);
    await user.selectOptions(selector, '100');

    expect(props.on_page_size_change).toHaveBeenCalledWith(100);
  });

  it('disables all controls when is_disabled=true', () => {
    renderComponent({ is_disabled: true, page: 2, page_size: 25, total_results: 120 });

    expect(screen.getByRole('button', { name: 'First page' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Previous page' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Next page' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Last page' })).toBeDisabled();

    const selector = screen.getByLabelText(/Rows per page/i);
    expect(selector).toBeDisabled();
  });
});

import React from 'react';
import { TransactionTableStatusBadge } from '../TransactionTableStatusBadge/TransactionTableStatusBadge';
import { TransactionTablePagination } from '../TransactionTablePagination/TransactionTablePagination';

export type TransactionStatus = 'pending' | 'completed' | 'failed' | 'refunded';
export type SortDirection = 'ascending' | 'descending';
export type TransactionSortColumn = 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method';

export type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: TransactionStatus;
  merchant_name: string;
  payment_method: string;
};

export type SortChangePayload = {
  column: TransactionSortColumn;
  direction: SortDirection;
};

export type OpenTransactionDetailsPayload = { id: string } & Record<string, any>;

export type TransactionTableProps = {
  transactions: TransactionRow[];
  is_loading: boolean;
  is_error: boolean;
  sort_column: TransactionSortColumn;
  sort_direction: SortDirection;
  page: number;
  page_size: number;
  total_results: number;
  on_sort_change: (payload: SortChangePayload) => void;
  on_page_change: (page: number) => void;
  on_page_size_change: (page_size: number) => void;
  on_open_details: (payload: OpenTransactionDetailsPayload) => void;
  on_retry: () => void;
};

const COLUMNS: Array<{ key: TransactionSortColumn; label: string; minWidth: number }> = [
  { key: 'date', label: 'Date', minWidth: 120 },
  { key: 'amount', label: 'Amount', minWidth: 120 },
  { key: 'status', label: 'Status', minWidth: 120 },
  { key: 'merchant_name', label: 'Merchant Name', minWidth: 200 },
  { key: 'payment_method', label: 'Payment Method', minWidth: 160 }
];

function getNextSortDirection(currentColumn: TransactionSortColumn, currentDirection: SortDirection, nextColumn: TransactionSortColumn) {
  if (nextColumn !== currentColumn) return 'ascending' as const;
  return currentDirection === 'ascending' ? ('descending' as const) : ('ascending' as const);
}

function SortIndicator(props: { isActive: boolean; direction: SortDirection }) {
  const { isActive, direction } = props;
  if (!isActive) return <span aria-hidden="true" className="tt-sort-indicator" />;
  return (
    <span aria-hidden="true" className="tt-sort-indicator">
      {direction === 'ascending' ? '▲' : '▼'}
    </span>
  );
}

function SkeletonRow(props: { columns: number }) {
  return (
    <tr>
      {Array.from({ length: props.columns }).map((_, idx) => (
        <td key={idx} className="tt-td">
          <div className="tt-skeleton" />
        </td>
      ))}
    </tr>
  );
}

export function TransactionTable(props: TransactionTableProps) {
  const {
    transactions,
    is_loading,
    is_error,
    sort_column,
    sort_direction,
    page,
    page_size,
    total_results,
    on_sort_change,
    on_page_change,
    on_page_size_change,
    on_open_details,
    on_retry
  } = props;

  const interactionsDisabled = is_loading || is_error;

  const onHeaderActivate = (column: TransactionSortColumn) => {
    if (interactionsDisabled) return;
    const nextDirection = getNextSortDirection(sort_column, sort_direction, column);
    on_sort_change({ column, direction: nextDirection });
  };

  const renderBody = () => {
    if (is_loading) {
      return (
        <>
          {Array.from({ length: 10 }).map((_, i) => (
            <SkeletonRow key={i} columns={COLUMNS.length} />
          ))}
        </>
      );
    }

    if (is_error) {
      return (
        <tr>
          <td className="tt-td" colSpan={COLUMNS.length}>
            <div className="tt-stateRow">
              <div className="tt-stateTitle">Transactions failed to load</div>
              <button className="tt-button" type="button" onClick={on_retry}>
                Retry
              </button>
            </div>
          </td>
        </tr>
      );
    }

    if (transactions.length === 0) {
      return (
        <tr>
          <td className="tt-td" colSpan={COLUMNS.length}>
            <div className="tt-stateRow">
              <div className="tt-stateTitle">No transactions to display</div>
            </div>
          </td>
        </tr>
      );
    }

    return (
      <>
        {transactions.map((t) => {
          const viewLabel = `View transaction details for ${t.merchant_name} on ${t.date}`;
          return (
            <tr
