      "content": "import React from 'react';
import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

type TransactionStatus = 'pending' | 'completed' | 'failed' | 'refunded';
type SortDirection = 'ascending' | 'descending';
type TransactionSortColumn = 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method';

type TransactionRow = {
  id: string;
  date: string;
  amount: number;
  status: TransactionStatus;
  merchant_name: string;
  payment_method: string;
};

type SortChangePayload = { column: TransactionSortColumn; direction: SortDirection };
type OpenTransactionDetailsPayload = { id: string } & Record<string, any>;

function makeTransactions(count: number): TransactionRow[] {
  const base: TransactionRow[] = [];
  for (let i = 0; i < count; i++) {
    const day = String(28 - (i % 28)).padStart(2, '0');
    base.push({
      id: `tx_${i + 1}`,
      date: `2026-03-${day}`,
      amount: i % 3 === 0 ? 10 : i % 3 === 1 ? 20 : 10, // intentional ties to exercise stable-sort assumptions
      status: (i % 4 === 0
        ? 'completed'
        : i % 4 === 1
          ? 'pending'
          : i % 4 === 2
            ? 'failed'
            : 'refunded') as TransactionStatus,
      merchant_name:
        i === 0
          ? 'A very long merchant name that should be truncated in narrow layouts'
          : `Merchant ${i + 1}`,
      payment_method: i === 0 ? 'Visa •••• 4242' : `Card •••• ${String(1000 + i).slice(-4)}`
    });
  }
  return base;
}

function sortData(data: TransactionRow[], column: TransactionSortColumn, direction: SortDirection): TransactionRow[] {
  const dir = direction === 'ascending' ? 1 : -1;
  const indexed = data.map((row, idx) => ({ row, idx }));
  indexed.sort((a, b) => {
    let av: any = (a.row as any)[column];
    let bv: any = (b.row as any)[column];

    // normalize for deterministic comparisons
    if (column === 'status' || column === 'merchant_name' || column === 'payment_method' || column === 'date') {
      av = String(av);
      bv = String(bv);
    }

    if (av < bv) return -1 * dir;
    if (av > bv) return 1 * dir;
    // stable sort
    return a.idx - b.idx;
  });
  return indexed.map((x) => x.row);
}

function paginateData(data: TransactionRow[], page: number, pageSize: number): TransactionRow[] {
  const start = (page - 1) * pageSize;
  return data.slice(start, start + pageSize);
}

function totalPages(totalResults: number, pageSize: number) {
  return Math.max(1, Math.ceil(totalResults / pageSize));
}

/**
 * Harness composes the root TransactionTable with realistic parent-controlled state.
 * It exercises component boundaries:
 * - TransactionTable -> parent callbacks
 * - parent state transitions -> TransactionTable props
 * - TransactionTablePagination interactions -> parent -> table
 * - status badge render in the table rows
 */
function TransactionTableHarness(props: {
  initialData: TransactionRow[];
  initialSort?: SortChangePayload;
  initialPage?: number;
  initialPageSize?: number;
  /** fail the next fetch after a triggering action; useful for unhappy-flow */
  failNextFetchRef?: { current: boolean };
  onOpenDetails?: (payload: OpenTransactionDetailsPayload) => void;
}) {
  const { initialData, failNextFetchRef } = props;
  const [data] = React.useState<TransactionRow[]>(initialData);

  const [sort, setSort] = React.useState<SortChangePayload>(
    props.initialSort ?? { column: 'date', direction: 'descending' }
  );
  const [page, setPage] = React.useState<number>(props.initialPage ?? 1);
  const [pageSize, setPageSize] = React.useState<number>(props.initialPageSize ?? 25);

  const [isLoading, setIsLoading] = React.useState<boolean>(true);
  const [isError, setIsError] = React.useState<boolean>(false);

  const lastRequestRef = React.useRef<{ sort: SortChangePayload; page: number; pageSize: number } | null>(null);

  const [liveMessage, setLiveMessage] = React.useState<string>('');

  const totalResults = data.length;

  const rows = React.useMemo(() => {
    const sorted = sortData(data, sort.column, sort.direction);
    return paginateData(sorted, page, pageSize);
  }, [data, sort, page, pageSize]);

  const runFetch = React.useCallback(
    async (next: { sort: SortChangePayload; page: number; pageSize: number }, announce?: { sort?: boolean; page?: boolean }) => {
      lastRequestRef.current = next;
      setIsError(false);
      setIsLoading(true);

      // simulate async fetch
      await new Promise((r) => setTimeout(r, 5));

      if (failNextFetchRef?.current) {
        failNextFetchRef.current = false;
        setIsLoading(false);
        setIsError(true);
        return;
      }

      setIsLoading(false);

      if (announce?.sort) {
        const colLabel =
          next.sort.column === 'date'
            ? 'Date'
            : next.sort.column === 'amount'
              ? 'Amount'
              : next.sort.column === 'status'
                ? 'Status'
                : next.sort.column === 'merchant_name'
                  ? 'Merchant Name'
                  : 'Payment Method';
        setLiveMessage(`Sorted by ${colLabel} ${next.sort.direction}`);
      }
      if (announce?.page) {
        setLiveMessage(`Page ${next.page} of ${totalPages(totalResults, next.pageSize)}`);
      }
    },
    [failNextFetchRef, totalResults]
  );

  React.useEffect(() => {
    // initial fetch
    void runFetch({ sort, page, pageSize }, { page: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onSortChange = async (payload: SortChangePayload) => {
    // Apply bi-state toggle + default rules at parent boundary:
    // - if same column: toggle
    // - if new column: ascending
    const nextSort: SortChangePayload =
      payload.column === sort.column
        ? { column: sort.column, direction: sort.direction === 'ascending' ? 'descending' : 'ascending' }
        : { column: payload.column, direction: 'ascending' };

    setSort(nextSort);
    // keep page (not specified to reset on sort); just refetch
    await runFetch({ sort: nextSort, page, pageSize }, { sort: true });
  };

  const onPageChange = async (nextPage: number) => {
    setPage(nextPage);
    await runFetch({ sort, page: nextPage, pageSize }, { page: true });
  };

  const onPageSizeChange = async (nextPageSize: number) => {
    setPageSize(nextPageSize);
    setPage(1);
    await runFetch({ sort, page: 1, pageSize: nextPageSize }, { page: true });
  };

  const onRetry = async () => {
    const last = lastRequestRef.current ?? { sort, page, pageSize };
    await runFetch({ sort: last.sort, page: last.page, pageSize: last.pageSize }, { page: true });
  };

  const onOpenDetails = (payload: OpenTransactionDetailsPayload) => {
    props.onOpenDetails?.(payload);
  };

  return (
    <div>
      <div aria-live="polite" data-testid="table-live-region">
        {liveMessage}
      </div>
      <TransactionTable
        transactions={rows as any}
        is_loading={isLoading}
        is_error={isError}
        sort_column={sort.column as any}
        sort_direction={sort.direction as any}
        page={page}
        page_size={pageSize}
        total_results={totalResults}
        on_sort_change={onSortChange as any}
        on_page_change={onPageChange as any}
        on_page_size_change={onPageSizeChange as any}
        on_open_details={onOpenDetails as any}
        on_retry={onRetry as any}
      />
    </div>
  );
}

async function waitForLoaded() {
  // When loaded, headers should be enabled and at least one View details control exists (for non-empty dataset)
  // If empty dataset, test will use different condition.
  await screen.findByRole('button', { name: /^Date$/i });
  expect(screen.getByRole('button', { name: /^Date$/i })).not.toBeDisabled();
}

describe('TransactionTable composed workflow (e2e)', () => {
  it('view_details_shortest: initial load -> open details from first row via dedicated control', async () => {
    const user = userEvent.setup();
    const data = makeTransactions(60);
    const onOpenDetails = jest.fn();

    render(<TransactionTableHarness initialData={data} onOpenDetails={onOpenDetails} />);

    // initial fetch: while loading, sorting/pagination are disabled
    const dateHeader = await screen.findByRole('button', { name: /^Date$/i });
    expect(dateHeader).toBeDisabled();

    // loaded
    await waitForLoaded();

    // default sort state: Date descending with aria-sort on Date <th> only
    const dateTh = screen.getByRole('button', { name: /^Date$/i }).closest('th');
    expect(dateTh).toHaveAttribute('aria-sort', 'descending');

    const amountTh = screen.getByRole('button', { name: /^Amount$/i }).closest('th');
    expect(amountTh).not.toHaveAttribute('aria-sort');

    // open details for the first visible row: since default sort is date desc, tx_1 is not necessarily first.
    // We validate the accessible-name pattern using the first rendered "View details" control.
    const firstDetailsBtn = screen.getAllByRole('button', { name: /^View transaction details for /i })[0];
    await user.click(firstDetailsBtn);

    expect(onOpenDetails).toHaveBeenCalledTimes(1);
    expect(onOpenDetails.mock.calls[0][0]).toEqual(expect.objectContaining({ id: expect.any(String) }));
  });

  it('explore_sort_paginate_then_details: sort -> toggle -> paginate -> change page size -> tooltip -> keyboard open details', async () => {
    const user = userEvent.setup();
    const data = makeTransactions(140);
    const onOpenDetails = jest.fn();

    render(<TransactionTableHarness initialData={data} onOpenDetails={onOpenDetails} />);

    // Wait for load and confirm default sort
    await waitForLoaded();
    expect(screen.getByRole('button', { name: /^Date$/i }).closest('th')).toHaveAttribute('aria-sort', 'descending');
    expect(screen.getByRole('button', { name: /^Amount$/i }).closest('th')).not.toHaveAttribute('aria-sort');

    // Sort by Amount -> should go loading and then aria-sort on Amount ascending; aria-live announces
    await user.click(screen.getByRole('button', { name: /^Amount$/i }));
    expect(screen.getByRole('button', { name: /^Amount$/i })).toBeDisabled();

    await act(async () => {
      await new Promise((r) => setTimeout(r, 10));
    });

    expect(screen.getByRole('button', { name: /^Amount$/i }).closest('th')).toHaveAttribute('aria-sort', 'ascending');
    expect(screen.getByTestId('table-live-region')).toHaveTextContent(/Sorted by Amount ascending/i);

    // Toggle Amount -> descending
    await user.click(screen.getByRole('button', { name: /^Amount$/i }));
    await act(async () => {
      await new Promise((r) => setTimeout(r, 10));
    });
    expect(screen.getByRole('button', { name: /^Amount$/i }).closest('th')).toHaveAttribute('aria-sort', 'descending');
    expect(screen.getByTestId('table-live-region')).toHaveTextContent(/Sorted by Amount descending/i);

    // Go to page 2
    const nextPage = screen.getByRole('button', { name: /Next page/i });
    await user.click(nextPage);
    await act(async () => {
      await new Promise((r) => setTimeout(r, 10));
    });
    expect(screen.getByTestId('table-live-region')).toHaveTextContent(/Page 2 of/i);

    // Changing page size to 100 resets to page 1
    const rowsPerPage = screen.getByLabelText(/Rows per page/i);
    await user.selectOptions(rowsPerPage, '100');
    await act(async () => {
      await new Promise((r) => setTimeout(r, 10));
    });
    expect(screen.getByTestId('table-live-region')).toHaveTextContent(/Page 1 of/i);

    // Tooltip via title attribute for overflow columns (merchant/payment method)
    // We expect at least one cell to have title equal to its full text per truncation rule.
    const longMerchantText = 'A very long merchant name that should be truncated in narrow layouts';
    const merchantCell = screen.getByText(longMerchantText);
    expect(merchantCell).toHaveAttribute('title', longMerchantText);

    const paymentCell = screen.getByText('Visa •••• 4242');
    expect(paymentCell).toHaveAttribute('title', 'Visa •••• 4242');

    // Keyboard open details
    onOpenDetails.mockClear();
    const detailsBtn = screen.getAllByRole('button', { name: /^View transaction details for /i })[0];
    detailsBtn.focus();
    expect(detailsBtn).toHaveFocus();
    await user.keyboard('{Enter}');

    expect(onOpenDetails).toHaveBeenCalledTimes(1);
    expect(onOpenDetails.mock.calls[0][0]).toEqual(expect.objectContaining({ id: expect.any(String) }));
  });

  it('unhappy_fetch_error_retry: sort triggers error -> error state blocks interactions -> Retry recovers and renders rows', async () => {
    const user = userEvent.setup();
    const data = makeTransactions(80);
    const failNextFetchRef = { current: false };

    render(<TransactionTableHarness initialData={data} failNextFetchRef={failNextFetchRef} />);

    await waitForLoaded();

    // Trigger a fetch that will fail (simulate backend error on sort)
    failNextFetchRef.current = true;
    await user.click(screen.getByRole('button', { name: /^Payment Method$/i }));

    // during loading, headers and pagination should be disabled
    expect(screen.getByRole('button', { name: /^Payment Method$/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /Next page/i })).toBeDisabled();

    await act(async () => {
      await new Promise((r) => setTimeout(r, 10));
    });

    // error row + retry; interactions remain disabled
    expect(screen.getByText(/Transactions failed to load/i)).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^Retry$/i })).toBeInTheDocument();

    expect(screen.getByRole('button', { name: /^Date$/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /Next page/i })).toBeDisabled();

    // Retry recovers
    await user.click(screen.getByRole('button', { name: /^Retry$/i }));

    // should go through loading again
    expect(screen.getByRole('button', { name: /^Date$/i })).toBeDisabled();

    await act(async () => {
      await new Promise((r) => setTimeout(r, 10));
    });

    // loaded again: error cleared and rows available
    expect(screen.queryByText(/Transactions failed to load/i)).not.toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^Date$/i })).not.toBeDisabled();
    expect(screen.getAllByRole('button', { name: /^View transaction details for /i }).length).toBeGreaterThan(0);
  });
