or {merchant} on {date}')","Add explicit ARIA patterns: aria-sort on headers, aria-live announcement for sort/page changes, and labels for page size selector and pagination buttons","Define badge design tokens and contrast requirements per status (text color, background color, border) to ensure WCAG-compliant contrast","Specify pagination model: show total count, page count, and whether page size change resets to page 1; define available controls (first/prev/next/last, direct page input) and their labels","Add system states and UI treatments: skeleton rows/spinner for loading, empty/error messaging copy, and retry action placement"],"responsiveGaps":["No behavior defined for small screens: whether the table becomes horizontally scrollable, columns collapse, or transforms into a stacked/card layout","Column priority not specified for responsive collapse/hide (which columns can be hidden first and how users access hidden data)","No truncation/wrapping rules for narrow widths (merchant name and payment method) and how that impacts row height","Pagination layout on mobile not specified (stacking of page controls and page-size selector, tap target sizing)","No specification for sticky header or scroll containment when the table overflows vertically or horizontally"]},"parsing":{"businessContext":"Viewing and managing a list of financial transactions.","components":[{"code":"transaction_table","name":"Transaction Table","parentCode":null,"purpose":"Displays transactions in a tabular layout with sortable columns, status badges, pagination, and row-level navigation to details.","statePolicy":"smart","type":"table"},{"code":"transaction_table_status_badge","name":"Transaction Status Badge","parentCode":"transaction_table","purpose":"Visually indicates the transaction status using text and color.","statePolicy":"dumb","type":"badge"},{"code":"transaction_table_pagination","name":"Transaction Table Pagination","parentCode":"transaction_table","purpose":"Controls page navigation and page size selection for the transaction list.","statePolicy":"smart","type":"pagination"}],"constraints":[{"componentCode":"transaction_table","description":"Supports sorting by any column.","type":"sorting"},{"componentCode":"transaction_table","description":"Supports pagination with page sizes 25, 50, or 100 items per page.","type":"pagination"}],"content":[{"code":"col_date","componentCode":"transaction_table","description":"Transaction date column.","kind":"column","name":"Date","isRequired":true},{"code":"col_amount","componentCode":"transaction_table","description":"Transaction amount column.","kind":"column","name":"Amount","isRequired":true},{"code":"col_status","componentCode":"transaction_table","description":"Transaction status column rendered as a colored badge.","kind":"column","name":"Status","isRequired":true},{"code":"col_merchant_name","componentCode":"transaction_table","description":"Merchant name column.","kind":"column","name":"Merchant Name","isRequired":true},{"code":"col_payment_method","componentCode":"transaction_table","description":"Payment method column.","kind":"column","name":"Payment Method","isRequired":true},{"code":"status_pending","componentCode":"transaction_table_status_badge","description":"Pending status label for a transaction.","kind":"status","name":"Pending","isRequired":true},{"code":"status_completed","componentCode":"transaction_table_status_badge","description":"Completed status label for a transaction.","kind":"status","name":"Completed","isRequired":true},{"code":"status_failed","componentCode":"transaction_table_status_badge","description":"Failed status label for a transaction.","kind":"status","name":"Failed","isRequired":true},{"code":"status_refunded","componentCode":"transaction_table_status_badge","description":"Refunded status label for a transaction.","kind":"status","name":"Refunded","isRequired":true}],"interactions":[{"code":"sort_by_column","componentCode":"transaction_table","description":"User sorts the table by any column.","targetComponentCode":null,"type":"sort"},{"code":"paginate_transactions","componentCode":"transaction_table_pagination","description":"User navigates between pages of transactions and changes page size.","targetComponentCode":"transaction_table","type":"paginate"},{"code":"open_transaction_details","componentCode":"transaction_table","description":"User clicks a row to open transaction details.","targetComponentCode":null,"type":"open_details"}],"rootComponentCode":"transaction_table","specifiedStates":[{"code":"state_pending","componentCode":"transaction_table_status_badge","description":"Badge displays pending status styling.","isExplicit":true,"name":"Pending"},{"code":"state_completed","componentCode":"transaction_table_status_badge","description":"Badge displays completed status styling.","isExplicit":true,"name":"Completed"},{"code":"state_failed","componentCode":"transaction_table_status_badge","description":"Badge displays failed status styling.","isExplicit":true,"name":"Failed"},{"code":"state_refunded","componentCode":"transaction_table_status_badge","description":"Badge displays refunded status styling.","isExplicit":true,"name":"Refunded"}],"tokenReferences":[{"componentCode":"transaction_table_status_badge","description":"Colors used to distinguish status values (pending, completed, failed, refunded).","name":"status color","type":"color"},{"componentCode":"transaction_table","description":"Spacing for table cells, rows, and header.","name":"table spacing","type":"spacing"},{"componentCode":"transaction_table","description":"Typography for table headers and cell text.","name":"table typography","type":"typography"},{"componentCode":"transaction_table_status_badge","description":"Badge corner rounding.","name":"badge radius","type":"radius"},{"componentCode":"transaction_table_status_badge","description":"Typography for status badge text.","name":"badge typography","type":"typography"}]},"projectRootPath":"/app/generated/frontend","relatedComponentInterfaces":[{"accepts":[{"description":"Transaction status value to display and style. Supported values: pending, completed, failed, refunded.","name":"status","required":true,"type":"TransactionStatus"},{"description":"Optional additional class name for custom styling hooks (spacing, alignment, etc.).","name":"class_name","required":false,"type":"string"}],"componentCode":"transaction_table_status_badge","componentName":"Transaction Status Badge","returns":[]}],"relatedComponentSourceFiles":[{"componentCode":"transaction_table_status_badge","filename":"/app/generated/frontend/src/components/TransactionTableStatusBadge/TransactionTableStatusBadge.tsx"}],"resolvingGaps":{"decisions":[{"affectedComponentCodes":["transaction_table"],"code":"sortable_header_button_semantics","decision":"Render each sortable column header as a native <button> within the <th>; the button label is the column name. Set aria-sort on the <th> for the active sort column only (values: "ascending" or "descending"); all other headers omit aria-sort. Keyboard: Enter/Space toggles sort. Provide a visible sort indicator icon adjacent to the header text inside the button.","rationale":"Using native buttons provides built-in keyboard and focus behavior without custom key handling. aria-sort on the <th> communicates current sort state to assistive tech in the standard table pattern, and limiting aria-sort to the active column avoids conflicting announcements.","sourceGap":"Sorting controls lack keyboard interaction and screen-reader semantics (which headers are buttons, current sort column/direction, aria-sort)"},{"affectedComponentCodes":["transaction_table"],"code":"sort_toggle_and_default","decision":"Default sort is Date descending. Sorting is bi-state per column: activating a different column sets direction to ascending; activating the same column toggles between ascending and descending. Sorting is stable (preserves input order for equal values).","rationale":"This resolves ambiguity around default and toggle model while staying conservative and predictable for users. Stable sorting avoids unexpected row reordering when values tie.","sourceGap":"Define sort behavior precisely: default sort column/direction, tri-state vs bi-state toggle, stable sort, and visual indicator (icon) placement in headers"},{"affectedComponentCodes":["transaction_table"],"code":"row_details_accessible_affordance","decision":"Do not make the entire row the only interactive control. Add a dedicated "View details" link/button in the first cell (Date column) for each row; it is keyboard focusable and activates on Enter/Space. The accessible name is "View transaction details for {merchantName} on {date}". Row click may still activate details with pointer, but keyboard users use the dedicated control.","rationale":"A dedicated interactive element provides clear semantics, focusability, and a screen-reader label without turning <tr> into a custom control. Allowing pointer row-click preserves the brief behavior while ensuring full keyboard accessibility.","sourceGap":"Row click to open details lacks an accessible affordance (keyboard activation, focusability, and clear label for screen readers)"},{"affectedComponentCodes":["transaction_table"],"code":"table_loading_empty_error_states","decision":"Implement three explicit render states in the table body: (1) Loading: show 10 skeleton rows matching the current column layout and disable sorting/pagination controls; (2) Empty: show a single full-width row with message "No transactions to display"; (3) Error: show a single full-width row with message "Transactions failed to load" and a "Retry" button that re-triggers the last fetch with current sort/page/pageSize.","rationale":"These states cover the missing operational scenarios (fetching, no data, failure) with concrete UI outputs and control behavior, enabling deterministic tests and consistent UX across sort/paginate transitions.","sourceGap":"Loading state while fetching transactions (initial load and during sort/paginate)"},{"affectedComponentCodes":["transaction_table_pagination"],"code":"pagination_model_and_disabled_boundaries","decision":"Pagination provides First, Previous, Next, Last buttons plus a page size selector (25/50/100). Display text: "Page X of Y" and "Z results". Changing page size resets to page 1. First/Previous are disabled on page 1; Next/Last are disabled on the final page. Disabled controls are not focusable.","rationale":"This fixes boundary behavior and defines a concrete pagination model and reset rule, keeping the control set minimal while supporting the required page sizes and clear user feedback.","sourceGap":"Specify pagination model: show total count, page count, and whether page size change resets to page 1; define available controls (first/prev/next/last, direct page input) and their labels"},{"affectedComponentCodes":["transaction_table_pagination"],"code":"pagination_accessible_labels_and_live_updates","decision":"Add accessible labels: pagination nav has aria-label "Transaction pagination"; page size selector has label "Rows per page"; First/Prev/Next/Last buttons have aria-labels "First page", "Previous page", "Next page", "Last page". Add an aria-live="polite" status region within the table container that announces "Sorted by {column} {direction}" on sort and "Page {x} of {y}" on page changes.","rationale":"Explicit labeling and polite announcements address screen-reader discoverability and feedback for dynamic updates without overcomplicating the interaction model.","sourceGap":"Pagination controls lack labeling for screen readers (current page, total pages/results, page size selector label) and focus order expectations"},{"affectedComponentCodes":["transaction_table","transaction_table_pagination"],"code":"focus_visible_requirements","decision":"Apply consistent :focus-visible styling to sortable header buttons, the "View details" control, and all pagination controls: 2px outline using the app focus color, 2px offset, and maintain at least 3:1 contrast against adjacent colors. Do not remove default outlines unless replaced by this rule.","rationale":"This creates a concrete, testable focus requirement for all interactive elements mentioned in the gaps and avoids relying on browser defaults that may be overridden by component styling.","sourceGap":"No focus-visible styling requirements specified for sortable headers, rows, and pagination controls"},{"affectedComponentCodes":["transaction_table_status_badge"],"code":"status_badge_contrast_and_noncolor_redundancy","decision":"Badges always render the status text (Pending/Completed/Failed/Refunded) and must meet WCAG 2.1 AA contrast for text against badge background (>=4.5:1). If a chosen background cannot meet contrast with the intended text color, use a neutral background with a 2px left border in the status color and standard text color to preserve meaning without relying on low-contrast fills.","rationale":"Text provides non-color reinforcement, and the contrast rule plus fallback prevents inaccessible color pairings while preserving status differentiation in a conservative way.","sourceGap":"Status badges rely on color; no non-color reinforcement specified beyond text and no guidance for contrast-compliant badge/background pairings"},{"affectedComponentCodes":["transaction_table"],"code":"cell_overflow_truncation_rules","decision":"Merchant Name and Payment Method cells are single-line with truncation (CSS ellipsis). On hover and keyboard focus (within cell), show a native tooltip via title attribute containing the full value. Row height remains fixed to a single line.","rationale":"This defines deterministic overflow handling on narrow widths without introducing complex custom tooltip components, and it remains accessible via focus-triggered title for keyboard users.","sourceGap":"Long-content overflow state for merchant name and payment method (truncate/wrap) and tooltip behavior if used"},{"affectedComponentCodes":["transaction_table"],"code":"responsive_table_horizontal_scroll_and_column_priority","decision":"On small screens, keep the table layout and enable horizontal scrolling within the table container (overflow-x: auto). Columns remain in the same order and are not hidden; minimum widths: Date 120px, Amount 120px, Status 120px, Merchant Name 200px, Payment Method 160px.","rationale":"Horizontal scroll is the least risky responsive strategy for a data table because it preserves all data and interactions without inventing a card layout or column hiding behavior not specified in the brief.","sourceGap":"No behavior defined for small screens: whether the table becomes horizontally scrollable, columns collapse, or transforms into a stacked/card layout"}]},"targetComponent":{"code":"transaction_table","name":"Transaction Table","parentCode":null,"purpose":"Displays transactions in a tabular layout with sortable columns, status badges, pagination, and row-level navigation to details.","statePolicy":"smart","type":"table"},"targetComponentInterface":{"accepts":[{"description":"Array of transactions to render for the current page (already sorted/paginated by the caller). Each item includes values for date, amount, status, merchant name, and payment method.","name":"transactions","required":true,"type":"TransactionRow[]"},{"description":"True while fetching transactions (initial load or during sort/pagination/page-size changes). When true, render skeleton rows and disable sorting/pagination interactions.","name":"is_loading","required":true,"type":"boolean"},{"description":"True when the last fetch failed. When true, render the error row with Retry and keep sorting/pagination disabled until a successful reload.","name":"is_error","required":true,"type":"boolean"},{"description":"Current sort column key. Used to set aria-sort on the active column header and show the correct sort indicator.","name":"sort_column","required":true,"type":"TransactionSortColumn"},{"description":"Current sort direction for the active sort column.","name":"sort_direction","required":true,"type":"SortDirection"},{"description":"Current (1-based) page index for pagination display and boundary disabling.","name":"page","required":true,"type":"number"},{"description":"Current selected page size. Expected values: 25, 50, or 100.","name":"page_size","required":true,"type":"number"},{"description":"Total number of results across all pages. Used to compute total pages and to display "Z results".","name":"total_results","required":true,"type":"number"},{"description":"Callback when a sortable header is activated. Caller applies bi-state sorting rules and triggers reload.","name":"on_sort_change","required":true,"type":"(payload: SortChangePayload) => void"},{"description":"Callback when the user requests a page change (First/Prev/Next/Last). Caller updates page and triggers reload.","name":"on_page_change","required":true,"type":"(page: number) => void"},{"description":"Callback when the user changes rows per page (25/50/100). Caller resets page to 1 and triggers reload.","name":"on_page_size_change","required":true,"type":"(page_size: number) => void"},{"description":"Callback when the user activates the per-row "View details" control (or clicks the row via pointer).","name":"on_open_details","required":true,"type":"(payload: OpenTransactionDetailsPayload) => void"},{"description":"Callback when the user presses the Retry button in the error state to re-trigger the last fetch with current sort/page/page_size.","name":"on_retry","required":true,"type":"() => void"}],"componentCode":"transaction_table","componentName":"Transaction Table","returns":[{"description":"Emitted when the user requests sorting by a column via the header button; includes the requested column and direction to apply.","name":"sort_change","required":true,"type":"SortChangePayload"},{"description":"Emitted when the user requests a different page via pagination controls; payload is the requested 1-based page number.","name":"page_change","required":true,"type":"number"},{"description":"Emitted when the user changes the page size via the rows-per-page selector; payload is the requested page size (25/50/100).","name":"page_size_change","required":true,"type":"number"},{"description":"Emitted when the user activates "View details" for a row (or clicks the row with a pointer) to open transaction details.","name":"open_details","required":true,"type":"OpenTransactionDetailsPayload"},{"description":"Emitted when the user clicks Retry in the error state to re-run the last fetch.","name":"retry","required":true,"type":"() => void"}]},"targetSourceFilePath":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.tsx","targetUnitTests":{"componentCode":"transaction_table","componentName":"Transaction Table","coveredBehaviors":["Renders all required column headers (Date, Amount, Status, Merchant Name, Payment Method) as sortable header buttons","Sets aria-sort only on the active sort column <th> with correct ascending/descending value; other headers omit aria-sort","Clicking a sortable header calls on_sort_change with the expected column and direction (bi-state toggle for same column; new column starts ascending)","When is_loading is true, renders skeleton rows and disables sort/pagination interactions","When is_error is true, renders full-width error row and Retry button; disables sort/pagination interactions; Retry calls on_retry","When transactions is empty and not loading/error, renders the empty state message","Each row renders a dedicated "View details" control with accessible name pattern and triggers on_open_details when activated (mouse and keyboard)","Merchant Name and Payment Method cells include title attributes with full text for native tooltip on truncation rule"],"coveredStates":["Default/data state (rows rendered)","Sorted state: active column + direction reflected via aria-sort","Loading state: skeleton rows and disabled controls","Error state: error message + Retry and disabled controls","Empty state: message "No transactions to display""],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.spec.tsx","content":"import React from 'react';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

import { TransactionTable } from './TransactionTable';

jest.mock('../TransactionTableStatusBadge/TransactionTableStatusBadge', () => ({
  TransactionTableStatusBadge: ({ status }: { status: string }) => (
    <span data-testid="status-badge">{status}</span>
  )
}));

jest.mock('../TransactionTablePagination/TransactionTablePagination', () => ({
  TransactionTablePagination: (props: any) => {
    const { page, page_size, total_results, is_disabled, on_page_change, on_page_size_change } = props;
    return (
      <div aria-label="Transaction pagination">
        <div>Page {page} of {Math.max(1, Math.ceil(total_results / page_size))}</div>
        <div>{total_results} results</div>
        <button aria-label="First page" disabled={is_disabled || page <= 1} onClick={() => on_page_change(1)}>First</button>
        <button aria-label="Previous page" disabled={is_disabled || page <= 1} onClick={() => on_page_change(page - 1)}>Prev</button>
        <button aria-label="Next page" disabled={is_disabled || page >= Math.max(1, Math.ceil(total_results / page_size))} onClick={() => on_page_change(page + 1)}>Next</button>
        <button aria-label="Last page" disabled={is_disabled || page >= Math.max(1, Math.ceil(total_results / page_size))} onClick={() => on_page_change(Math.max(1, Math.ceil(total_results / page_size)))}>Last</button>
        <label>
          Rows per page
          <select
            aria-label="Rows per page"
            disabled={is_disabled}
            value={page_size}
            onChange={(e) => on_page_size_change(Number((e.target as HTMLSelectElement).value))}
          >
            <option value={25}>25</option>
            <option value={50}>50</option>
            <option value={100}>100</option>
          </select>
        </label>
      </div>
    );
  }
}));

type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: 'pending' | 'completed' | 'failed' | 'refunded';
  merchant_name: string;
  payment_method: string;
};

type SortDirection = 'ascending' | 'descending';

describe('TransactionTable', () => {
  const baseTransactions: TransactionRow[] = [
    {
      id: 't1',
      date: '2026-03-10',
      amount: '10.00',
      status: 'completed',
      merchant_name: 'A very long merchant name that should be truncated in narrow layouts',
      payment_method: 'Visa •••• 4242'
    },
    {
      id: 't2',
      date: '2026-03-09',
      amount: '10.00',
      status: 'pending',
      merchant_name: 'Coffee Shop',
      payment_method: 'Mastercard •••• 1111'
    }
  ];

  function renderTable(overrides: Partial<React.ComponentProps<typeof TransactionTable>> = {}) {
    const props: React.ComponentProps<typeof TransactionTable> = {
      transactions: baseTransactions as any,
      is_loading: false,
      is_error: false,
      sort_column: 'date' as any,
      sort_direction: 'descending' as SortDirection,
      page: 1,
      page_size: 25,
      total_results: 2,
      on_sort_change: jest.fn(),
      on_page_change: jest.fn(),
      on_page_size_change: jest.fn(),
      on_open_details: jest.fn(),
      on_retry: jest.fn(),
      ...overrides
    };

    return {
      ...render(<TransactionTable {...props} />),
      props
    };
  }

  it('renders sortable header buttons and sets aria-sort only on the active column', () => {
    renderTable({ sort_column: 'date' as any, sort_direction: 'descending' });

    // Column headers present
    expect(screen.getByRole('button', { name: /^Date$/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^Amount$/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^Status$/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^Merchant Name$/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /^Payment Method$/i })).toBeInTheDocument();

    // aria-sort is applied to the <th> of the active column only
    const dateButton = screen.getByRole('button', { name: /^Date$/i });
    const dateTh = dateButton.closest('th');
    expect(dateTh).toHaveAttribute('aria-sort', 'descending');

    const otherButtons = [
      screen.getByRole('button', { name: /^Amount$/i }),
      screen.getByRole('button', { name: /^Status$/i }),
      screen.getByRole('button', { name: /^Merchant Name$/i }),
      screen.getByRole('button', { name: /^Payment Method$/i })
    ];
    for (const btn of otherButtons) {
      const th = btn.closest('th');
      expect(th).not.toHaveAttribute('aria-sort');
    }
  });

  it('invokes on_sort_change for a different column with ascending direction', async () => {
    const user = userEvent.setup();
    const { props } = renderTable({ sort_column: 'date' as any, sort_direction: 'descending' });

    await user.click(screen.getByRole('button', { name: /^Amount$/i }));

    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
    expect(props.on_sort_change).toHaveBeenCalledWith(
      expect.objectContaining({ column: 'amount', direction: 'ascending' })
    );
  });

  it('toggles sort direction when activating the same column', async () => {
    const user = userEvent.setup();
    const { props } = renderTable({ sort_column: 'amount' as any, sort_direction: 'ascending' });

    await user.click(screen.getByRole('button', { name: /^Amount$/i }));

    expect(props.on_sort_change).toHaveBeenCalledTimes(1);
    expect(props.on_sort_change).toHaveBeenCalledWith(
      expect.objectContaining({ column: 'amount', direction: 'descending' })
    );
  });

  it('renders loading skeleton rows and disables sorting/pagination interactions when is_loading=true', async () => {
    const user = userEvent.setup();
    const { props } = renderTable({ is_loading: true });

    // Skeleton heuristics: no data rows / no View details controls while loading
    expect(screen.queryByRole('button', { name: /View transaction details for/i })).not.toBeInTheDocument();

    // Sorting should be disabled while loading
    const amountHeader = screen.getByRole('button', { name: /^Amount$/i });
    expect(amountHeader).toBeDisabled();

    await user.click(amountHeader);
    expect(props.on_sort_change).not.toHaveBeenCalled();

    // Pagination should be disabled via is_disabled passed to pagination component
    const next = screen.getByRole('button', { name: /Next page/i });
    expect(next).toBeDisabled();

    await user.click(next);
    expect(props.on_page_change).not.toHaveBeenCalled();

    const rowsPerPage = screen.getByLabelText(/Rows per page/i);
    expect(rowsPerPage).toBeDisabled();
  });

  it('renders error row with Retry button and disables sorting/pagination when is_error=true; clicking Retry calls on_retry', async () => {
    const user = userEvent.setup();
    const { props } = renderTable({ is_error: true });

    expect(screen.getByText(/Transactions failed to load/i)).toBeInTheDocument();

    // Controls disabled
    expect(screen.getByRole('button', { name: /^Date$/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /Next page/i })).toBeDisabled();

    const retry = screen.getByRole('button', { name: /^Retry$/i });
    await user.click(retry);
    expect(props.on_retry).toHaveBeenCalledTimes(1);
  });

  it('renders empty state message when not loading/error and transactions is empty', () => {
    renderTable({ transactions: [] as any, total_results: 0 });

    expect(screen.getByText(/No transactions to display/i)).toBeInTheDocument();

    // Pagination still present; boundaries should be disabled (from our mock) on page 1 of 1
    expect(screen.getByText(/0 results/i)).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /First page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /Previous page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /Next page/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /Last page/i })).toBeDisabled();
  });

  it('provides a dedicated View details control per row with accessible name pattern and calls on_open_details on click and Enter', async () => {
    const user = userEvent.setup();
    const { props } = renderTable({});

    const expectedLabel = `View transaction details for ${baseTransactions[0].merchant_name} on ${baseTransactions[0].date}`;
    const viewDetails = screen.getByRole('button', { name: expectedLabel });

    await user.click(viewDetails);
    expect(props.on_open_details).toHaveBeenCalledTimes(1);
    expect(props.on_open_details).toHaveBeenCalledWith(expect.objectContaining({ id: 't1' }));

    props.on_open_details.mockClear();

    viewDetails.focus();
    expect(viewDetails).toHaveFocus();
    await user.keyboard('{Enter}');

    expect(props.on_open_details).toHaveBeenCalledTimes(1);
    expect(props.on_open_details).toHaveBeenCalledWith(expect.objectContaining({ id: 't1' }));
  });

  it('sets title attributes on Merchant Name and Payment Method cells for native tooltip (full value)', () => {
    renderTable({});

    // Find the row containing merchant name, then assert title attribute exists with full text.
    const merchantCell = screen.getByText(baseTransactions[0].merchant_name);
    expect(merchantCell).toHaveAttribute('title', baseTransactions[0].merchant_name);

    const paymentCell = screen.getByText(baseTransactions[0].payment_method);
    expect(paymentCell).toHaveAttribute('title', baseTransactions[0].payment_method);
  });

  it('renders status via the badge component for each row', () => {
    renderTable({});

    const badges = screen.getAllByTestId('status-badge');
    expect(badges).toHaveLength(baseTransactions.length);

    const badgeTexts = badges.map((b) => b.textContent);
    expect(badgeTexts).toEqual(expect.arrayContaining(['completed', 'pending']));
  });

  it('row click opens details with pointer interaction (in addition to dedicated control)', async () => {
    const user = userEvent.setup();
    const { props } = renderTable({});

    // Find a row by locating a cell and moving to closest <tr>
    const dateCell = screen.getByText(baseTransactions[0].date);
    const row = dateCell.closest('tr');
    expect(row).toBeTruthy();

    await user.click(row as HTMLElement);
    expect(props.on_open_details).toHaveBeenCalledWith(expect.objectContaining({ id: 't1' }));
  });
});
