              <tr>
                <td className="tt-stateCell" colSpan={headerCells.length}>
                  No transactions to display
                </td>
              </tr>
            ) : (
              transactions.map((row) => {
                const detailsLabel = `View transaction details for ${row.merchant_name} on ${row.date}`;
                return (
                  <tr
                    key={row.id}
                    className="tt-row"
                    onClick={(e) => {
                      if (isDisabled) return;
                      // Avoid double-activating when clicking the dedicated button.
                      const target = e.target as HTMLElement | null;
                      if (target && (target.closest('button') || target.closest('a'))) return;
                      openDetails(row);
                    }}
                  >
                    <td className="tt-td tt-dateCell">
                      <div className="tt-dateCellInner">
                        <button
                          type="button"
                          className="tt-viewDetailsButton"
                          onClick={() => openDetails(row)}
                          aria-label={detailsLabel}
                          disabled={isDisabled}
                        >
                          View details
                        </button>
                        <span className="tt-dateText">{row.date}</span>
                      </div>
                    </td>
                    <td className="tt-td tt-amountCell">{formatAmount(row.amount)}</td>
                    <td className="tt-td">
                      <TransactionTableStatusBadge status={row.status as any} />
                    </td>
                    <td className="tt-td tt-truncate" title={row.merchant_name}>
                      {row.merchant_name}
                    </td>
                    <td className="tt-td tt-truncate" title={row.payment_method}>
                      {row.payment_method}
                    </td>
                  </tr>
                );
              })
            )}
