,"sourceGap":"No behavior defined for small screens: whether the table becomes horizontally scrollable, columns collapse, or transforms into a stacked/card layout"}]},"targetComponent":{"code":"transaction_table_pagination","name":"Transaction Table Pagination","parentCode":"transaction_table","purpose":"Controls page navigation and page size selection for the transaction list.","statePolicy":"smart","type":"pagination"},"targetComponentInterface":{"accepts":[{"description":"Current 1-based page index being displayed.","name":"page","required":true,"type":"number"},{"description":"Current selected page size (rows per page). Expected values: 25, 50, or 100.","name":"page_size","required":true,"type":"number"},{"description":"Total number of results across all pages; used to compute total pages and to display "Z results".","name":"total_results","required":true,"type":"number"},{"description":"Whether pagination controls and page size selector are disabled (e.g., while the table is loading or in an error state).","name":"is_disabled","required":true,"type":"boolean"},{"description":"Available page size options shown in the Rows per page selector (per requirements: 25/50/100).","name":"page_size_options","required":false,"type":"number[]"},{"description":"Callback invoked when user requests a page change via First/Previous/Next/Last controls. Payload is the next 1-based page number.","name":"on_page_change","required":true,"type":"(page: number) => void"},{"description":"Callback invoked when user changes Rows per page. Payload is the selected page size; parent is responsible for resetting page to 1.","name":"on_page_size_change","required":true,"type":"(page_size: number) => void"}],"componentCode":"transaction_table_pagination","componentName":"Transaction Table Pagination","returns":[]},"targetSourceFilePath":"/app/generated/frontend/src/components/TransactionTablePagination/TransactionTablePagination.tsx","targetUnitTests":{"componentCode":"transaction_table_pagination","componentName":"Transaction Table Pagination","coveredBehaviors":["Renders accessible pagination landmark with aria-label "Transaction pagination"","Displays "Page X of Y" computed from total_results and page_size (ceil)","Displays "Z results" reflecting total_results","First/Previous buttons request page 1 / page-1; Next/Last request page+1 / totalPages","Boundary disabling: First/Previous disabled on page 1; Next/Last disabled on last page","Disabled controls are not focusable (disabled attribute)","Rows-per-page selector is labeled "Rows per page"","Changing page size calls on_page_size_change with the selected option","All pagination controls and page size selector are disabled when is_disabled=true"],"coveredStates":["Enabled on middle page (page > 1 and page < totalPages)","First page boundary","Last page boundary","Globally disabled (is_disabled=true)"],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTablePagination/TransactionTablePagination.spec.tsx","content":"import React from 'react';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTablePagination } from './TransactionTablePagination';

type Props = React.ComponentProps<typeof TransactionTablePagination>;

function renderComponent(override: Partial<Props> = {}) {
  const props: Props = {
    page: 2,
    page_size: 25,
    total_results: 120,
    is_disabled: false,
    page_size_options: [25, 50, 100],
    on_page_change: jest.fn(),
    on_page_size_change: jest.fn(),
    ...override
  };

  const view = render(<TransactionTablePagination {...props} />);
  return { ...view, props };
}

describe('TransactionTablePagination', () => {
  it('renders pagination landmark and summary text', () => {
    renderComponent({ page: 2, page_size: 25, total_results: 120 });

    // Landmark / region
    expect(screen.getByLabelText('Transaction pagination')).toBeInTheDocument();

    // Total pages = ceil(120/25)=5
    expect(screen.getByText(/Page\s+2\s+of\s+5/i)).toBeInTheDocument();
    expect(screen.getByText(/120\s+results/i)).toBeInTheDocument();

    // Rows per page label
    expect(screen.getByText(/Rows per page/i)).toBeInTheDocument();
  });

  it('invokes on_page_change with correct target pages for First/Previous/Next/Last', async () => {
    const user = userEvent.setup();
    const { props } = renderComponent({ page: 2, page_size: 25, total_results: 120 }); // 5 pages

    await user.click(screen.getByRole('button', { name: 'First page' }));
    expect(props.on_page_change).toHaveBeenCalledWith(1);

    await user.click(screen.getByRole('button', { name: 'Previous page' }));
    expect(props.on_page_change).toHaveBeenCalledWith(1);

    await user.click(screen.getByRole('button', { name: 'Next page' }));
    expect(props.on_page_change).toHaveBeenCalledWith(3);

    await user.click(screen.getByRole('button', { name: 'Last page' }));
    expect(props.on_page_change).toHaveBeenCalledWith(5);
  });

  it('disables First/Previous on the first page (and disabled buttons are not focusable)', async () => {
    const user = userEvent.setup();
    renderComponent({ page: 1, page_size: 25, total_results: 120, is_disabled: false });

    const first = screen.getByRole('button', { name: 'First page' });
    const prev = screen.getByRole('button', { name: 'Previous page' });
    const next = screen.getByRole('button', { name: 'Next page' });
    const last = screen.getByRole('button', { name: 'Last page' });

    expect(first).toBeDisabled();
    expect(prev).toBeDisabled();
    expect(next).not.toBeDisabled();
    expect(last).not.toBeDisabled();

    await user.tab();
    // First focusable control should not be a disabled boundary button
    expect(document.activeElement).not.toBe(first);
    expect(document.activeElement).not.toBe(prev);
  });

  it('disables Next/Last on the last page', () => {
    // total pages = ceil(100/25)=4
    renderComponent({ page: 4, page_size: 25, total_results: 100, is_disabled: false });

    expect(screen.getByRole('button', { name: 'First page' })).not.toBeDisabled();
    expect(screen.getByRole('button', { name: 'Previous page' })).not.toBeDisabled();
    expect(screen.getByRole('button', { name: 'Next page' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Last page' })).toBeDisabled();

    expect(screen.getByText(/Page\s+4\s+of\s+4/i)).toBeInTheDocument();
  });

  it('calls on_page_size_change with the selected page size', async () => {
    const user = userEvent.setup();
    const { props } = renderComponent({ page: 1, page_size: 25, total_results: 10, is_disabled: false });

    // Associate by label text; supports both <label>+<select> and aria-label
    const selector = screen.getByLabelText(/Rows per page/i);
    await user.selectOptions(selector, '100');

    expect(props.on_page_size_change).toHaveBeenCalledWith(100);
  });

  it('disables all controls when is_disabled=true', () => {
    renderComponent({ is_disabled: true, page: 2, page_size: 25, total_results: 120 });

    expect(screen.getByRole('button', { name: 'First page' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Previous page' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Next page' })).toBeDisabled();
    expect(screen.getByRole('button', { name: 'Last page' })).toBeDisabled();

    const selector = screen.getByLabelText(/Rows per page/i);
    expect(selector).toBeDisabled();
  });
});
"}]},"testFramework":"Jest + React Testing Library","validationFeedback":null,"userFlows":{"flows":[{"code":"view_details_shortest","completionCriteria":"Transaction details view is opened for the intended row via the dedicated control.","kind":"shortest_happy","name":"Open transaction details from the first row","steps":[{"action":"Land on the page containing the transaction table and wait for the initial fetch to complete.","code":"initial_load","componentCode":"transaction_table","expectedResult":"Table initially shows loading skeleton rows with sorting and pagination disabled; then renders rows sorted by Date descending with status badges visible and pagination showing "Page 1 of Y" and "Z results".","inputData":null},{"action":"Activate the "View details" control in the first row (in the Date column).","code":"activate_view_details_first_row","componentCode":"transaction_table","expectedResult":"Transaction details open for the selected transaction; the control has an accessible name "View transaction details for {merchantName} on {date}".","inputData":null}]},{"code":"explore_sort_paginate_then_details","completionCriteria":"User successfully sorts, paginates, changes page size (resetting to page 1), and opens details for a transaction.","kind":"exploratory_happy","name":"Explore sorting, pagination, page size, truncation tooltip, then open details","steps":[{"action":"Wait for the table to load and confirm default sort state.","code":"confirm_default_sort","componentCode":"transaction_table","expectedResult":"Rows are sorted by Date descending; the Date header <th> has aria-sort="descending" and displays a visible sort indicator icon; aria-sort is not present on other headers.","inputData":null},{"action":"Click the Amount column header button to sort by Amount.","code":"sort_by_amount_ascending","componentCode":"transaction_table","expectedResult":"Table enters loading state (skeleton rows) with sorting/pagination disabled; then renders sorted by Amount ascending (stable for equal values). aria-live announces "Sorted by Amount ascending"; Amount header <th> has aria-sort="ascending" and the indicator updates.","inputData":null},{"action":"Activate the Amount column header button again to toggle direction.","code":"toggle_amount_desc","componentCode":"transaction_table","expectedResult":"Table reloads and then renders sorted by Amount descending; aria-live announces "Sorted by Amount descending"; Amount header aria-sort updates to "descending".","inputData":null},{"action":"Click Next page in the pagination controls.","code":"go_to_page_2","componentCode":"transaction_table_pagination","expectedResult":"Table reloads and then shows Page 2 results; aria-live announces "Page 2 of Y"; First/Previous become enabled (and focusable) while on page > 1.","inputData":null},{"action":"Change page size to 100 using the Rows per page selector.","code":"change_page_size_100","componentCode":"transaction_table_pagination","expectedResult":"Page resets to 1; table reloads and then shows 100 rows (or fewer if total results < 100); pagination updates "Page 1 of Y" and "Z results"; aria-live announces "Page 1 of Y".","inputData":"100"},{"action":"Hover over a truncated Merchant Name cell to view the full value (or focus the cell content via keyboard).","code":"reveal_truncation_tooltip","componentCode":"transaction_table","expectedResult":"Cell remains single-line with ellipsis; the browser-native tooltip appears via the title attribute showing the full Merchant Name value.","inputData":null},{"action":"Use keyboard Tab to focus the "View details" control for a visible row and press Enter.","code":"keyboard_open_details","componentCode":"transaction_table","expectedResult":"A clear :focus-visible outline is shown on the focused control; pressing Enter opens transaction details for that row using the accessible name pattern.","inputData":null}]},{"code":"unhappy_fetch_error_retry","completionCriteria":"After a failed fetch, the user successfully retries and the table renders rows.","kind":"unhappy_invalid_input","name":"Sort triggers fetch error; user retries to recover","steps":[{"action":"Click the Payment Method column header button to request sorting by Payment Method.","code":"sort_by_payment_method","componentCode":"transaction_table","expectedResult":"Table enters loading state with skeleton rows and disables sorting/pagination while the request is in flight.","inputData":null},{"action":"Observe the request failure state.","code":"observe_error_state","componentCode":"transaction_table","expectedResult":"Table body renders a single full-width error row with message "Transactions failed to load" and a "Retry" button; previous data is not interactable; sorting/pagination remain disabled until a successful reload.","inputData":null},{"action":"Click the "Retry" button in the error row.","code":"retry_last_fetch","componentCode":"transaction_table","expectedResult":"The last fetch is re-triggered using the current sort/page/pageSize; table shows loading skeleton rows with controls disabled, then renders the transaction rows if the retry succeeds.","inputData":null}]},{"code":"empty_state_no_transactions","completionCriteria":"Empty state is displayed with the specified message when there are no transactions.","kind":"shortest_happy","name":"No transactions available shows empty state","steps":[{"action":"Load the transaction table when the dataset is empty.","code":"load_empty_dataset","componentCode":"transaction_table","expectedResult":"After loading completes, the table body renders a single full-width row with message "No transactions to display"; pagination reflects "Z results" where Z=0 and boundary buttons are disabled and not focusable.","inputData":null}]}]}}

