import { render, screen, within, act } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import '@testing-library/jest-dom';

import { TransactionTable } from './TransactionTable';

type TransactionStatus = 'pending' | 'completed' | 'failed' | 'refunded';
type SortDirection = 'ascending' | 'descending';
type TransactionSortColumn = 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method';

type TransactionRow = {
  id: string;
  date: string;
  amount: number;
  status: TransactionStatus;
  merchant_name: string;
  payment_method: string;
};

type SortChangePayload = { column: TransactionSortColumn; direction: SortDirection };
type OpenTransactionDetailsPayload = { id: string } & Record<string, any>;

function makeTransactions(count: number): TransactionRow[] {
  const base: TransactionRow[] = [];
  for (let i = 0; i < count; i++) {
    const day = String(28 - (i % 28)).padStart(2, '0');
    base.push({
      id: `tx_${i + 1}`,
      date: `2026-03-${day}`,
      amount: i % 3 === 0 ? 10 : i % 3 === 1 ? 20 : 10, // intentional ties to exercise stable-sort assumptions
      status: (i % 4 === 0
        ? 'completed'
        : i % 4 === 1
          ? 'pending'
          : i % 4 === 2
            ? 'failed'
            : 'refunded') as TransactionStatus,
      merchant_name:
        i === 0
          ? 'A very long merchant name that should be truncated in narrow layouts'
          : `Merchant ${i + 1}`,
      payment_method: i === 0 ? 'Visa •••• 4242' : `Card •••• ${String(1000 + i).slice(-4)}`
    });
  }
  return base;
}

function sortData(data: TransactionRow[], column: TransactionSortColumn, direction: SortDirection): TransactionRow[] {
  const dir = direction === 'ascending' ? 1 : -1;
  const indexed = data.map((row, idx) => ({ row, idx }));
  indexed.sort((a, b) => {
    let av: any = (a.row as any)[column];
    let bv: any = (b.row as any)[column];

    // normalize for deterministic comparisons
    if (column === 'status' || column === 'merchant_name' || column === 'payment_method' || column === 'date') {
      av = String(av);
      bv = String(bv);
    }

    if (av < bv) return -1 * dir;
    if (av > bv) return 1 * dir;
    // stable sort
    return a.idx - b.idx;
  });
  return indexed.map((x) => x.row);
}

function paginateData(data: TransactionRow[], page: number, pageSize: number): TransactionRow[] {
  const start = (page - 1) * pageSize;
  return data.slice(start, start + pageSize);
}

function totalPages(totalResults: number, pageSize: number) {
  return Math.max(1, Math.ceil(totalResults / pageSize));
}

/**
 * Harness composes the root TransactionTable with realistic parent-controlled state.
 * It exercises component boundaries:
 * - TransactionTable -> parent callbacks
 * - parent state transitions -> TransactionTable props
 * - TransactionTablePagination interactions -> parent -> table
 * - status badge render in the table rows
 */
function TransactionTableHarness(props: {
  initialData: TransactionRow[];
  initialSort?: SortChangePayload;
  initialPage?: number;
  initialPageSize?: number;
  /** fail the next fetch after a triggering action; useful for unhappy-flow */
  failNextFetchRef?: { current: boolean };
  onOpenDetails?: (payload: OpenTransactionDetailsPayload) => void;
}) {
  const { initialData, failNextFetchRef } = props;
  const [data] = React.useState<TransactionRow[]>(initialData);

  const [sort, setSort] = React.useState<SortChangePayload>(
    props.initialSort ?? { column: 'date', direction: 'descending' }
  );
  const [page, setPage] = React.useState<number>(props.initialPage ?? 1);
  const [pageSize, setPageSize] = React.useState<number>(props.initialPageSize ?? 25);

  const [isLoading, setIsLoading] = React.useState<boolean>(true);
  const [isError, setIsError] = React.useState<boolean>(false);

  const lastRequestRef = React.useRef<{ sort: SortChangePayload; page: number; pageSize: number } | null>(null);

  const [liveMessage, setLiveMessage] = React.useState<string>('');

  const totalResults = data.length;

  const rows = React.useMemo(() => {
    const sorted = sortData(data, sort.column, sort.direction);
    return paginateData(sorted, page, pageSize);
  }, [data, sort, page, pageSize]);

  const runFetch = React.useCallback(
    async (next: { sort: SortChangePayload; page: number; pageSize: number }, announce?: { sort?: boolean; page?: boolean }) => {
      lastRequestRef.current = next;
      setIsError(false);
      setIsLoading(true);

      // simulate async fetch
      await new Promise((r) => setTimeout(r, 5));

      if (failNextFetchRef?.current) {
        failNextFetchRef.current = false;
        setIsLoading(false);
        setIsError(true);
        return;
      }

      setIsLoading(false);

      if (announce?.sort) {
        const colLabel =
          next.sort.column === 'date'
            ? 'Date'
            : next.sort.column === 'amount'
              ? 'Amount'
              : next.sort.column === 'status'
                ? 'Status'
                : next.sort.column === 'merchant_name'
                  ? 'Merchant Name'
                  : 'Payment Method';
        setLiveMessage(`Sorted by ${colLabel} ${next.sort.direction}`);
