import { TransactionTableStatusBadge } from '../TransactionTableStatusBadge/TransactionTableStatusBadge';
import { TransactionTablePagination } from '../TransactionTablePagination/TransactionTablePagination';

type TransactionStatus = 'pending' | 'completed' | 'failed' | 'refunded';
type SortDirection = 'ascending' | 'descending';
type TransactionSortColumn = 'date' | 'amount' | 'status' | 'merchant_name' | 'payment_method';

type TransactionRow = {
  id: string;
  date: string;
  amount: string | number;
  status: TransactionStatus;
  merchant_name: string;
  payment_method: string;
};

type SortChangePayload = { column: TransactionSortColumn; direction: SortDirection };
type OpenTransactionDetailsPayload = { id: string } & Record<string, any>;

export type TransactionTableProps = {
  transactions: TransactionRow[];
  is_loading: boolean;
  is_error: boolean;
  sort_column: TransactionSortColumn;
  sort_direction: SortDirection;
  page: number;
  page_size: number;
  total_results: number;
  on_sort_change: (payload: SortChangePayload) => void;
  on_page_change: (page: number) => void;
  on_page_size_change: (page_size: number) => void;
  on_open_details: (payload: OpenTransactionDetailsPayload) => void;
  on_retry: () => void;
};

const COLUMN_LABELS: Record<TransactionSortColumn, string> = {
  date: 'Date',
  amount: 'Amount',
  status: 'Status',
  merchant_name: 'Merchant Name',
  payment_method: 'Payment Method'
};

function nextDirectionForRequest(params: {
  activeColumn: TransactionSortColumn;
  activeDirection: SortDirection;
  requestedColumn: TransactionSortColumn;
}): SortDirection {
  const { activeColumn, activeDirection, requestedColumn } = params;
  if (requestedColumn !== activeColumn) return 'ascending';
  return activeDirection === 'ascending' ? 'descending' : 'ascending';
}

function formatAmount(value: string | number): string {
  if (typeof value === 'number') {
    return value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
  return String(value);
}

function SortIndicator(props: { isActive: boolean; direction: SortDirection }) {
  const { isActive, direction } = props;
  // Keep the indicator simple and deterministic.
  // Use ▲/▼ only when active; otherwise render a placeholder to avoid layout shift.
  return (
    <span aria-hidden="true" style={{ display: 'inline-block', width: '1em', textAlign: 'center' }}>
      {isActive ? (direction === 'ascending' ? '▲' : '▼') : ''}
    </span>
  );
}

export function TransactionTable(props: TransactionTableProps) {
  const {
    transactions,
    is_loading,
    is_error,
    sort_column,
    sort_direction,
    page,
    page_size,
    total_results,
    on_sort_change,
    on_page_change,
    on_page_size_change,
    on_open_details,
    on_retry
  } = props;

  const isDisabled = is_loading || is_error;

  const onHeaderActivate = (column: TransactionSortColumn) => {
    if (isDisabled) return;
    const direction = nextDirectionForRequest({
      activeColumn: sort_column,
      activeDirection: sort_direction,
      requestedColumn: column
    });
    on_sort_change({ column, direction });
  };

  const openDetails = (row: TransactionRow) => {
    on_open_details({ id: row.id });
  };

  const headerCells: { column: TransactionSortColumn; minWidth: number }[] = [
    { column: 'date', minWidth: 120 },
    { column: 'amount', minWidth: 120 },
    { column: 'status', minWidth: 120 },
    { column: 'merchant_name', minWidth: 200 },
    { column: 'payment_method', minWidth: 160 }
  ];

  return (
    <div className="tt-root" data-component="transaction_table">
      <div className="tt-scroll" role="region" aria-label="Transactions table" tabIndex={-1}>
        <table className="tt-table">
          <thead>
            <tr>
              {headerCells.map(({ column, minWidth }) => {
                const isActive = sort_column === column;
                const ariaSort = isActive ? sort_direction : undefined;
                return (
                  <th
                    key={column}
                    scope="col"
                    className="tt-th"
                    style={{ minWidth }}
                    aria-sort={ariaSort as any}
                  >
                    <button
                      type="button"
                      className="tt-sortButton"
                      disabled={isDisabled}
                      onClick={() => onHeaderActivate(column)}
                    >
                      <span className="tt-sortButtonLabel">{COLUMN_LABELS[column]}</span>
                      <SortIndicator isActive={isActive} direction={sort_direction} />
                    </button>
                  </th>
                );
              })}
            </tr>
          </thead>

          <tbody>
            {is_error ? (
              <tr>
                <td className="tt-stateCell" colSpan={headerCells.length}>
                  <div className="tt-errorRow">
                    <div className="tt-errorText">Transactions failed to load</div>
                    <button type="button" className="tt-retryButton" onClick={on_retry}>
                      Retry
                    </button>
                  </div>
                </td>
              </tr>
            ) : is_loading ? (
              Array.from({ length: 10 }).map((_, idx) => (
                <tr key={`sk_${idx}`} className="tt-skeletonRow" aria-hidden="true">
                  {headerCells.map(({ column }) => (
                    <td key={`${idx}_${column}`} className="tt-td">
                      <div className="tt-skeleton" />
                    </td>
                  ))}
                </tr>
              ))
            ) : transactions.length === 0 ? (
              <tr>
                <td className="tt-stateCell" colSpan={headerCells.length}>
                  No transactions to display
                </td>
              </tr>
            ) : (
              transactions.map((row) => {
                const detailsLabel = `View transaction details for ${row.merchant_name} on ${row.date}`;
                return (
                  <tr
                    key={row.id}
                    className="tt-row"
                    onClick={(e) => {
                      if (isDisabled) return;
                      // Avoid double-activating when clicking the dedicated button.
                      const target = e.target as HTMLElement | null;
                      if (target && (target.closest('button') || target.closest('a'))) return;
                      openDetails(row);
                    }}
                  >
                    <td className="tt-td tt-dateCell">
                      <div className="tt-dateCellInner">
                        <button
                          type="button"
                          className="tt-viewDetailsButton"
                          onClick={() => openDetails(row)}
                          aria-label={detailsLabel}
                          disabled={isDisabled}
                        >
                          View details
                        </button>
                        <span className="tt-dateText">{row.date}</span>
                      </div>
                    </td>
                    <td className="tt-td tt-amountCell">{formatAmount(row.amount)}</td>
                    <td className="tt-td">
                      <TransactionTableStatusBadge status={row.status as any} />
                    </td>
                    <td className="tt-td tt-truncate" title={row.merchant_name}>
                      {row.merchant_name}
                    </td>
                    <td className="tt-td tt-truncate" title={row.payment_method}>
                      {row.payment_method}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      <div className="tt-pagination">
        <TransactionTablePagination
          page={page as any}
          page_size={page_size as any}
          total_results={total_results as any}
          is_disabled={isDisabled as any}
          on_page_change={on_page_change as any}
          on_page_size_change={on_page_size_change as any}
        />
      </div>

      <style>{`
        .tt-root {
          color: var(--color-text-primary);
          background: var(--color-surface-default);
          border: 1px solid var(--color-border-subtle);
          border-radius: var(--radius-12);
          box-shadow: var(--shadow-sm);
          overflow: hidden;
        }

        .tt-scroll {
          overflow-x: auto;
        }

        .tt-table {
          width: 100%;
          border-collapse: collapse;
          font-size: var(--font-size-body);
        }

        .tt-th {
          text-align: left;
          background: var(--color-surface-muted);
          padding: var(--spacing-12) var(--spacing-16);
          border-bottom: 1px solid var(--color-border-subtle);
          font-size: var(--font-size-label);
          font-weight: var(--font-weight-medium);
          color: var(--color-text-secondary);
          vertical-align: middle;
          white-space: nowrap;
        }

        .tt-sortButton {
          appearance: none;
          border: 0;
          background: transparent;
          padding: 0;
          margin: 0;
          display: inline-flex;
          align-items: center;
          gap: var(--spacing-8);
          font: inherit;
          color: inherit;
          cursor: pointer;
        }

        .tt-sortButton:disabled {
          cursor: not-allowed;
          opacity: 0.6;
        }

        .tt-sortButton:focus-visible,
        .tt-viewDetailsButton:focus-visible,
        .tt-retryButton:focus-visible {
          outline: 2px solid var(--color-border-subtle);
          outline-offset: 2px;
        }

        .tt-td {
          padding: var(--spacing-12) var(--spacing-16);
          border-bottom: 1px solid var(--color-border-subtle);
          vertical-align: middle;
          color: var(--color-text-primary);
        }

        .tt-row {
          background: var(--color-surface-default);
        }

        .tt-row:hover {
          background: var(--color-surface-muted);
        }

        .tt-stateCell {
          padding: var(--spacing-24);
          text-align: center;
          color: var(--color-text-secondary);
        }

        .tt-dateCellInner {
          display: flex;
          align-items: center;
          gap: var(--spacing-12);
          min-width: 0;
        }

        .tt-viewDetailsButton {
          appearance: none;
          border: 1px solid var(--color-border-subtle);
          background: var(--color-surface-default);
          color: var(--color-text-primary);
          border-radius: var(--radius-8);
          padding: var(--spacing-4) var(--spacing-8);
          font-size: var(--font-size-label);
          font-weight: var(--font-weight-medium);
          cursor: pointer;
          white-space: nowrap;
        }

        .tt-viewDetailsButton:disabled {
          cursor: not-allowed;
          opacity: 0.6;
        }

        .tt-dateText {
          color: var(--color-text-secondary);
          white-space: nowrap;
        }

        .tt-amountCell {
          white-space: nowrap;
        }

        .tt-truncate {
