export type TransactionTablePaginationProps = {
  /** Current 1-based page index being displayed. */
  page: number;
  /** Current selected page size (rows per page). Expected values: 25, 50, or 100. */
  page_size: number;
  /** Total number of results across all pages. */
  total_results: number;
  /** Whether all controls are disabled (e.g., while loading or error). */
  is_disabled: boolean;
  /** Available page size options. */
  page_size_options?: number[];
  /** Callback invoked when user requests a page change via First/Previous/Next/Last controls. */
  on_page_change: (page: number) => void;
  /** Callback invoked when user changes Rows per page. */
  on_page_size_change: (page_size: number) => void;
};

function clampInt(value: number, min: number, max: number) {
  const v = Number.isFinite(value) ? Math.trunc(value) : min;
  return Math.min(max, Math.max(min, v));
}

function computeTotalPages(totalResults: number, pageSize: number) {
  const safeTotal = Math.max(0, Math.trunc(totalResults));
  const safeSize = Math.max(1, Math.trunc(pageSize));
  return Math.max(1, Math.ceil(safeTotal / safeSize));
}

export function TransactionTablePagination(props: TransactionTablePaginationProps) {
  const pageSizeOptions = props.page_size_options ?? [25, 50, 100];

  const totalPages = computeTotalPages(props.total_results, props.page_size);
  const currentPage = clampInt(props.page, 1, totalPages);

  const isOnFirst = currentPage <= 1;
  const isOnLast = currentPage >= totalPages;

  const disableAll = props.is_disabled;
  const disableFirstPrev = disableAll || isOnFirst;
  const disableNextLast = disableAll || isOnLast;

  const onFirst = () => props.on_page_change(1);
  const onPrev = () => props.on_page_change(Math.max(1, currentPage - 1));
  const onNext = () => props.on_page_change(Math.min(totalPages, currentPage + 1));
  const onLast = () => props.on_page_change(totalPages);

  return (
    <nav aria-label="Transaction pagination" style={styles.nav}>
      <div style={styles.summary}>
        <span style={styles.summaryText}>Page {currentPage} of {totalPages}</span>
        <span style={styles.summaryText}>{Math.max(0, Math.trunc(props.total_results))} results</span>
      </div>

      <div style={styles.controls}>
        <div style={styles.buttons}>
          <button
            type="button"
            aria-label="First page"
            onClick={onFirst}
            disabled={disableFirstPrev}
            style={buttonStyle(disableFirstPrev)}
          >
            First
          </button>
          <button
            type="button"
            aria-label="Previous page"
            onClick={onPrev}
            disabled={disableFirstPrev}
            style={buttonStyle(disableFirstPrev)}
          >
            Previous
          </button>
          <button
            type="button"
            aria-label="Next page"
            onClick={onNext}
            disabled={disableNextLast}
            style={buttonStyle(disableNextLast)}
          >
            Next
          </button>
          <button
            type="button"
            aria-label="Last page"
            onClick={onLast}
            disabled={disableNextLast}
            style={buttonStyle(disableNextLast)}
          >
            Last
          </button>
        </div>

        <div style={styles.pageSize}>
          <label style={styles.label}>
            <span style={styles.labelText}>Rows per page</span>
            <select
              aria-label="Rows per page"
              value={String(props.page_size)}
              onChange={(e) => props.on_page_size_change(Number(e.target.value))}
              disabled={disableAll}
              style={selectStyle(disableAll)}
            >
              {pageSizeOptions.map((opt) => (
                <option key={opt} value={String(opt)}>
                  {opt}
                </option>
              ))}
            </select>
          </label>
        </div>
      </div>

      <style>{css}</style>
    </nav>
  );
}

