bled controls","Error state: error message + Retry and disabled controls","Empty state: message "No transactions to display""],"files":[{"filename":"/app/generated/frontend/src/components/TransactionTable/TransactionTable.spec.tsx","content":"import React from 'react';
import { render, screen, within } from '@testing-library/react';
