entCode":"transaction_table_status_badge","description":"Failed status label for a transaction.","kind":"status","name":"Failed","isRequired":true},{"code":"status_refunded","componentCode":"transaction_table_status_badge","description":"Refunded status label for a transaction.","kind":"status","name":"Refunded","isRequired":true}],"interactions":[{"code":"sort_by_column","componentCode":"transaction_table","description":"User sorts the table by any column.","targetComponentCode":null,"type":"sort"},{"code":"paginate_transactions","componentCode":"transaction_table_pagination","description":"User navigates between pages of transactions and changes page size.","targetComponentCode":"transaction_table","type":"paginate"},{"code":"open_transaction_details","componentCode":"transaction_table","description":"User clicks a row to open transaction details.","targetComponentCode":null,"type":"open_details"}],"rootComponentCode":"transaction_table","specifiedStates":[{"code":"state_pending","componentCode":"transaction_table_status_badge","description":"Badge displays pending status styling.","isExplicit":true,"name":"Pending"},{"code":"state_completed","componentCode":"transaction_table_status_badge","description":"Badge displays completed status styling.","isExplicit":true,"name":"Completed"},{"code":"state_failed","componentCode":"transaction_table_status_badge","description":"Badge displays failed status styling.","isExplicit":true,"name":"Failed"},{"code":"state_refunded","componentCode":"transaction_table_status_badge","description":"Badge displays refunded status styling.","isExplicit":true,"name":"Refunded"}],"tokenReferences":[{"componentCode":"transaction_table_status_badge","description":"Colors used to distinguish status values (pending, completed, failed, refunded).","name":"status color","type":"color"},{"componentCode":"transaction_table","description":"Spacing for table cells, rows, and header.","name":"table spacing","type":"spacing"},{"componentCode":"trans